# EMBYFLOW_BETA83_PERFORMANCE_V1
# Normale Diagnose-Logs sind im Release standardmäßig deaktiviert.
# Für eine gezielte Fehlersuche kann dieser Wert vorübergehend auf
# True gesetzt werden. Fehler- und Crashlogs bleiben immer aktiv.
# TEMPORAER AUF True FUER DIE AV1/SCHWARZBILD-DIAGNOSE (Verflucht normal) -
# nach abgeschlossener Fehlersuche wieder auf False zurücksetzen!
EMBYFLOW_DEBUG_LOGS = False
# EMBYFLOW_PUBLIC_LOG_CLEAN_V1: normal diagnostics disabled; error/crash logs remain enabled.


def embyflow_log_path(path):
    try:
        log_path = str(path or "")
        lowered = log_path.lower()

        if (
            EMBYFLOW_DEBUG_LOGS
            or "error" in lowered
            or "crash" in lowered
        ):
            return log_path

    except Exception:
        pass

    return "/dev/null"


# EMBYFLOW_PERFORMANCE_PATCH23_RELEASE_LOG_GATE_V1
# Normale Diagnose-Logs werden bei EMBYFLOW_DEBUG_LOGS=False bereits vor
# dem Datei-Open verworfen. Fehler- und Crashlogs bleiben aktiv.
class _EmbyFlowNullLog(object):
    def write(self, data):
        return 0

    def flush(self):
        return None

    def close(self):
        return None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        return False


EMBYFLOW_NULL_LOG = _EmbyFlowNullLog()


def embyflow_open_log(path, mode="a", *args, **kwargs):
    try:
        log_path = str(path or "")
        lowered = log_path.lower()

        if not (
            EMBYFLOW_DEBUG_LOGS
            or "error" in lowered
            or "crash" in lowered
        ):
            return EMBYFLOW_NULL_LOG

        return io.open(
            log_path,
            mode,
            *args,
            **kwargs
        )

    except Exception:
        return EMBYFLOW_NULL_LOG

