# EMBYFLOW_NEW_WEEKDAY_TAGS_V1
EMBYFLOW_NEW_WEEKDAY_TAGS = (
    ("MO", "#F4D03F"),
    ("DI", "#58D68D"),
    ("MI", "#5DADE2"),
    ("DO", "#F5B041"),
    ("FR", "#EC7063"),
    ("SA", "#AF7AC5"),
    ("SO", "#48C9B0"),
)


def embyflow_parse_emby_datetime(value):
    try:
        raw = str(value or "").strip()

        if not raw:
            return None

        raw = raw.replace("Z", "")
        raw = re.sub(r"([+-]\d{2}:\d{2})$", "", raw)

        if "." in raw:
            raw = raw.split(".", 1)[0]

        for date_format in (
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
        ):
            try:
                return datetime.strptime(
                    raw,
                    date_format
                )
            except Exception:
                pass

    except Exception:
        pass

    return None


def embyflow_new_weekday_tag(date_created, max_age_days=15):
    try:
        created = embyflow_parse_emby_datetime(
            date_created
        )

        if created is None:
            return "", "", None

        now = datetime.now()
        age_seconds = max(
            0,
            int(
                (
                    now - created
                ).total_seconds()
            )
        )

        age_days = int(
            age_seconds / 86400
        )

        if age_days > int(max_age_days):
            return "", "", age_days

        weekday_index = int(
            created.weekday()
        )

        short_name, color = (
            EMBYFLOW_NEW_WEEKDAY_TAGS[
                weekday_index
            ]
        )

        if age_days == 0:
            age_text = "HEUTE"
        elif age_days == 1:
            age_text = "GESTERN"
        else:
            age_text = "vor %d Tagen" % age_days

        return (
            "%s · %s" % (
                short_name,
                age_text,
            ),
            color,
            age_days,
        )

    except Exception:
        return "", "", None

def emby_new_items(include_types, limit=120, genres=None):
    items = []
    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return items
    try:
        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return items

        headers = {"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER}
        genre_list = genres if isinstance(genres, list) else ([genres] if genres else [None])
        seen = set()
        seen_content = set()
        raw_items = []
        for genre in genre_list:
            params = {
                "Recursive": "true",
                "IncludeItemTypes": include_types,
                "SortBy": "DateCreated",
                "SortOrder": "Descending",
                "Limit": str(limit),
                "Fields": "Overview,Genres,ProductionYear,RunTimeTicks,MediaSources,UserData,SeriesName,IndexNumber,ParentIndexNumber,DateCreated",
            }
            if genre:
                params["Genres"] = genre
            r = embyflow_http_get(
                server + "/Users/%s/Items" % user_id,
                headers=headers,
                params=params,
                timeout=10,
                verify=True,
            )
            for item in r.json().get("Items", []) or []:
                item_id = item.get("Id")
                if not item_id or item_id in seen:
                    continue
                seen.add(item_id)

                # EMBYFLOW_NEW_CONTENT_DEDUPE_V1
                # Gleicher Inhalt kann auf dem Server unter mehreren
                # IDs oder Bibliotheken auftauchen. Zusätzlich zur ID
                # nach Typ, normalisiertem Titel und Jahr filtern.
                item_type = str(
                    item.get("Type")
                    or include_types
                    or ""
                ).strip().lower()

                title_key = re.sub(
                    r"[^a-z0-9]+",
                    "",
                    str(
                        item.get("Name")
                        or ""
                    ).strip().lower()
                )

                year_key = str(
                    item.get("ProductionYear")
                    or ""
                ).strip()

                content_key = (
                    item_type,
                    title_key,
                    year_key,
                )

                if item_type == "episode":
                    content_key = (
                        item_type,
                        title_key,
                        year_key,
                        str(
                            item.get("SeriesName")
                            or ""
                        ).strip().lower(),
                        str(
                            item.get("ParentIndexNumber")
                            or ""
                        ),
                        str(
                            item.get("IndexNumber")
                            or ""
                        ),
                    )

                if title_key and content_key in seen_content:
                    continue

                if title_key:
                    seen_content.add(content_key)

                raw_items.append(item)

        for item in raw_items[:limit]:
            title = item.get("Name", "")
            item_type = item.get("Type") or include_types
            if item_type == "Series":
                typ = "Serie"
            elif item_type == "Episode":
                typ = "Episode"
            else:
                typ = "Film"
            year = item.get("ProductionYear") or ""
            genres_text = ", ".join(item.get("Genres") or [])
            meta = typ
            if item_type == "Episode":
                season = item.get("ParentIndexNumber")
                episode = item.get("IndexNumber")
                if season is not None and episode is not None:
                    meta = "S%02dE%02d" % (int(season), int(episode))
                series_name = item.get("SeriesName") or ""
                if series_name:
                    meta += " | %s" % series_name
            # EMBYFLOW_NEW_WEEKDAY_TAGS_COMPACT_V2
            # Im Neu-Grid bleibt die Metazeile bewusst kurz:
            # Wochentag/Alter plus Jahr. Genres würden auf
            # den schmalen Karten häufig abgeschnitten.
            weekday_tag, weekday_color, weekday_age_days = (
                embyflow_new_weekday_tag(
                    item.get("DateCreated"),
                    15
                )
            )

            if weekday_tag:
                compact_parts = [weekday_tag]

                if item_type == "Episode":
                    compact_parts.append(meta)
                elif year:
                    compact_parts.append(str(year))

                meta = " | ".join(compact_parts)

            else:
                if year:
                    meta += " | %s" % year

                if genres_text:
                    meta += " | %s" % genres_text

            items.append({
                "title": title,
                "meta": meta,
                "overview": item.get("Overview", ""),
                "country": "",
                "director": "",
                "search_term": title,
                "id": item.get("Id"),
                "type": item_type,
                "user_data": item.get("UserData", {}),
                "UserData": item.get("UserData", {}),
                "runtime_ticks": item.get("RunTimeTicks"),
                "date_created": item.get("DateCreated"),
                "new_weekday_tag": weekday_tag,
                "new_weekday_color": weekday_color,
                "new_weekday_age_days": weekday_age_days,
                "media_sources": item.get("MediaSources", []),
            })
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_new_items_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return items


def emby_set_favorite(item_id, favorite=True):
    if not requests or not EMBY_SERVER or not EMBY_USERNAME or not item_id:
        return False
    try:
        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return False

        url = "%s/Users/%s/FavoriteItems/%s" % (server, user_id, item_id)
        headers = {"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER}

        if favorite:
            r = embyflow_http_post(url, headers=headers, timeout=10, verify=True)
        else:
            r = embyflow_http_delete(url, headers=headers, timeout=10, verify=True)

        return r.status_code in (200, 204)
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_set_favorite_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return False


LOCAL_FAVORITES_FILE = "/etc/enigma2/embyflow_local_favorites.json"


def load_local_favorites():
    try:
        if not os.path.exists(LOCAL_FAVORITES_FILE):
            return []
        f = open(LOCAL_FAVORITES_FILE, "r")
        data = json.loads(f.read())
        f.close()
        return data if isinstance(data, list) else []
    except:
        return []


def save_local_favorites(items):
    try:
        f = open(LOCAL_FAVORITES_FILE, "w")
        f.write(json.dumps(items))
        f.close()
        return True
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_local_favorites_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return False


def set_local_favorite(item, favorite=True):
    items = load_local_favorites()
    item_id = item.get("id") or item.get("Id") or item.get("item_id")
    if not item_id:
        return False
    item_id = str(item_id)

    new_items = []
    for x in items:
        xid = x.get("id") or x.get("Id") or x.get("item_id")
        if str(xid) != item_id:
            new_items.append(x)

    if favorite:
        copy = dict(item)
        copy["id"] = item_id
        copy["is_favorite"] = True
        new_items.insert(0, copy)

    return save_local_favorites(new_items)



# EMBYFLOW_PERF25_CONTINUE_COLDSTART_V1
# Der erste Klick nach einem Enigma2-/Box-Neustart darf weder Anmeldung noch
# Resume-Abfrage im GUI-Thread ausführen. Der Homescreen wärmt beides direkt
# nach dem Layout in einem Worker vor. Ein sehr früher Klick öffnet sofort den
# Grid-Screen und übernimmt das Ergebnis anschließend über einen eTimer.
EMBYFLOW_CONTINUE_PREFETCH_LOCK = None
EMBYFLOW_CONTINUE_PREFETCH_RUNNING = False
EMBYFLOW_CONTINUE_PREFETCH_READY = False
EMBYFLOW_CONTINUE_PREFETCH_ITEMS = []
EMBYFLOW_CONTINUE_PREFETCH_TS = 0.0
EMBYFLOW_CONTINUE_PREFETCH_ERROR = ""


def embyflow_continue_prefetch_snapshot(max_age=120):
    global EMBYFLOW_CONTINUE_PREFETCH_LOCK

    try:
        import copy
        import threading

        if EMBYFLOW_CONTINUE_PREFETCH_LOCK is None:
            EMBYFLOW_CONTINUE_PREFETCH_LOCK = threading.RLock()

        with EMBYFLOW_CONTINUE_PREFETCH_LOCK:
            age = max(
                0.0,
                time.time() - float(EMBYFLOW_CONTINUE_PREFETCH_TS or 0.0)
            )
            if (
                EMBYFLOW_CONTINUE_PREFETCH_READY
                and age <= max(1, int(max_age or 120))
            ):
                return copy.deepcopy(
                    EMBYFLOW_CONTINUE_PREFETCH_ITEMS or []
                )
    except Exception:
        pass

    return None


def embyflow_start_continue_prefetch(limit=200, force=False):
    global EMBYFLOW_CONTINUE_PREFETCH_LOCK
    global EMBYFLOW_CONTINUE_PREFETCH_RUNNING
    global EMBYFLOW_CONTINUE_PREFETCH_READY
    global EMBYFLOW_CONTINUE_PREFETCH_ITEMS
    global EMBYFLOW_CONTINUE_PREFETCH_TS
    global EMBYFLOW_CONTINUE_PREFETCH_ERROR

    try:
        import threading

        if EMBYFLOW_CONTINUE_PREFETCH_LOCK is None:
            EMBYFLOW_CONTINUE_PREFETCH_LOCK = threading.RLock()

        with EMBYFLOW_CONTINUE_PREFETCH_LOCK:
            age = max(
                0.0,
                time.time() - float(EMBYFLOW_CONTINUE_PREFETCH_TS or 0.0)
            )

            if EMBYFLOW_CONTINUE_PREFETCH_RUNNING:
                return True

            if (
                not force
                and EMBYFLOW_CONTINUE_PREFETCH_READY
                and age <= 60.0
            ):
                return True

            EMBYFLOW_CONTINUE_PREFETCH_RUNNING = True
            EMBYFLOW_CONTINUE_PREFETCH_ERROR = ""

        def worker():
            global EMBYFLOW_CONTINUE_PREFETCH_RUNNING
            global EMBYFLOW_CONTINUE_PREFETCH_READY
            global EMBYFLOW_CONTINUE_PREFETCH_ITEMS
            global EMBYFLOW_CONTINUE_PREFETCH_TS
            global EMBYFLOW_CONTINUE_PREFETCH_ERROR

            loaded = []
            error_text = ""

            try:
                loaded = emby_resume_items(limit=limit) or []
            except Exception as error:
                error_text = str(error)
                loaded = []

            try:
                with EMBYFLOW_CONTINUE_PREFETCH_LOCK:
                    EMBYFLOW_CONTINUE_PREFETCH_ITEMS = list(loaded)
                    EMBYFLOW_CONTINUE_PREFETCH_TS = time.time()
                    EMBYFLOW_CONTINUE_PREFETCH_READY = True
                    EMBYFLOW_CONTINUE_PREFETCH_ERROR = error_text
                    EMBYFLOW_CONTINUE_PREFETCH_RUNNING = False
            except Exception:
                EMBYFLOW_CONTINUE_PREFETCH_ITEMS = list(loaded)
                EMBYFLOW_CONTINUE_PREFETCH_TS = time.time()
                EMBYFLOW_CONTINUE_PREFETCH_READY = True
                EMBYFLOW_CONTINUE_PREFETCH_ERROR = error_text
                EMBYFLOW_CONTINUE_PREFETCH_RUNNING = False

        thread = threading.Thread(
            target=worker,
            name="EmbyFlowContinuePrefetch"
        )
        thread.daemon = True
        thread.start()
        return True

    except Exception:
        EMBYFLOW_CONTINUE_PREFETCH_RUNNING = False
        return False


def embyflow_wait_continue_prefetch(limit=200, timeout=12.0):
    """Nur für einen Hintergrundthread: vorhandenen Preload abwarten."""
    snapshot = embyflow_continue_prefetch_snapshot(max_age=120)
    if snapshot is not None:
        return snapshot

    embyflow_start_continue_prefetch(limit=limit)
    deadline = time.time() + max(1.0, float(timeout or 12.0))

    while time.time() < deadline:
        snapshot = embyflow_continue_prefetch_snapshot(max_age=120)
        if snapshot is not None:
            return snapshot
        time.sleep(0.05)

    # Der GUI-Thread wird hiervon nicht berührt. Falls der Preload wegen eines
    # ungewöhnlich langsamen Servers noch läuft, bleibt die Ansicht bedienbar.
    snapshot = embyflow_continue_prefetch_snapshot(max_age=300)
    return snapshot if snapshot is not None else []


# EMBYFLOW_PERF24_CONTINUE_FAST_OPEN_V1
def emby_resume_items(limit=200):
    """Lädt fortsetzbare Filme/Episoden mit kurzem RAM-Cache.

    Die Listenabfrage enthält absichtlich keine MediaSources mehr. Diese
    umfangreichen Streamdaten werden nur für die sichtbaren Einträge im
    Hintergrund nachgeladen oder spätestens beim Abspielen abgefragt.
    """
    items = []

    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return items

    try:
        server, token, user_id = get_emby_auth()

        if not token or not user_id:
            return items

        headers = {
            "X-Emby-Token": token,
            "X-Emby-Authorization": AUTH_HEADER,
        }

        params = {
            "Recursive": "true",
            "Limit": str(max(1, int(limit or 200))),
            "Fields": (
                "Overview,Genres,ProductionYear,RunTimeTicks,"
                "UserData,SeriesName,SeriesId,SeasonId,ParentId,"
                "IndexNumber,ParentIndexNumber,DatePlayed"
            ),
        }

        data = embyflow_cached_get_json(
            server + "/Users/%s/Items/Resume" % user_id,
            headers=headers,
            params=params,
            ttl=60,
            timeout=10,
            verify=True,
            cache_key="continue-resume",
        )

        raw_items = data.get("Items", []) or []

        # Kompatibilitätsweg für Server, die den Resume-Endpunkt
        # nicht oder nur unvollständig liefern.
        if not raw_items:
            fallback_params = {
                "Recursive": "true",
                "IncludeItemTypes": "Movie,Episode",
                "Filters": "IsResumable",
                "SortBy": "DatePlayed",
                "SortOrder": "Descending",
                "Limit": str(max(1, int(limit or 200))),
                "Fields": params["Fields"],
            }
            fallback_data = embyflow_cached_get_json(
                server + "/Users/%s/Items" % user_id,
                headers=headers,
                params=fallback_params,
                ttl=60,
                timeout=10,
                verify=True,
                cache_key="continue-resume-fallback",
            )
            raw_items = fallback_data.get("Items", []) or []

        seen_ids = set()

        for raw in raw_items:
            item_id = str(raw.get("Id") or "").strip()
            item_type = str(raw.get("Type") or "").strip()

            if not item_id or item_id in seen_ids:
                continue

            if item_type not in ("Movie", "Episode"):
                continue

            seen_ids.add(item_id)

            title = str(raw.get("Name") or "").strip()
            year = raw.get("ProductionYear") or ""
            user_data = dict(raw.get("UserData") or {})

            if item_type == "Episode":
                season = raw.get("ParentIndexNumber")
                episode = raw.get("IndexNumber")
                series_name = str(raw.get("SeriesName") or "").strip()

                if season is not None and episode is not None:
                    try:
                        meta = "S%02dE%02d" % (int(season), int(episode))
                    except Exception:
                        meta = "Episode"
                else:
                    meta = "Episode"

                if series_name:
                    meta += " | %s" % series_name
            else:
                meta = "Film"

                if year:
                    meta += " | %s" % year

            items.append({
                "title": title,
                "meta": meta,
                "overview": raw.get("Overview", ""),
                "country": "",
                "director": "",
                "search_term": title,
                "id": item_id,
                "Id": item_id,
                "type": item_type,
                "Type": item_type,
                # EMBYFLOW_MEDIA_TYPE_GENRES_V1
                "genres": list(raw.get("Genres") or []),
                "Genres": list(raw.get("Genres") or []),
                "production_year": year,
                "ProductionYear": year,
                "user_data": user_data,
                "UserData": user_data,
                "runtime_ticks": raw.get("RunTimeTicks"),
                "RunTimeTicks": raw.get("RunTimeTicks"),
                "media_sources": [],
                "MediaSources": [],
                "series_id": raw.get("SeriesId"),
                "SeriesId": raw.get("SeriesId"),
                "season_id": raw.get("SeasonId"),
                "SeasonId": raw.get("SeasonId"),
                "parent_id": raw.get("ParentId"),
                "ParentId": raw.get("ParentId"),
                "series_name": raw.get("SeriesName"),
                "SeriesName": raw.get("SeriesName"),
                "season_number": raw.get("ParentIndexNumber"),
                "episode_number": raw.get("IndexNumber"),
            })

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_continue_error.log",
                "a"
            ) as log:
                log.write("%s\n" % str(error))
        except Exception:
            pass

    return items

def emby_favorite_items(limit=1000):
    items = []
    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return items
    try:
        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return items

        r = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
            params={
                "Recursive": "true",
                "IncludeItemTypes": "Movie,Series",
                "Filters": "IsFavorite",
                "SortBy": "SortName",
                "SortOrder": "Ascending",
                "Limit": str(limit),
                "Fields": "Overview,Genres,ProductionYear,OfficialRating,RunTimeTicks,MediaSources,UserData,SeriesName,IndexNumber,ParentIndexNumber",
            },
            timeout=10,
            verify=True,
        )

        for item in r.json().get("Items", []) or []:
            title = item.get("Name", "")
            typ = item.get("Type", "")
            year = item.get("ProductionYear") or ""
            genres = ", ".join(item.get("Genres") or [])

            if typ == "Series":
                meta = "Serie"
            elif typ == "Movie":
                meta = "Film"
            elif typ == "Episode":
                season = item.get("ParentIndexNumber")
                episode = item.get("IndexNumber")
                if season is not None and episode is not None:
                    meta = "S%02dE%02d" % (int(season), int(episode))
                else:
                    meta = "Episode"
                if item.get("SeriesName"):
                    meta += " | %s" % item.get("SeriesName")
            else:
                meta = typ or "Favorit"

            if year:
                meta += " | %s" % year
            if genres and typ != "Episode":
                meta += " | %s" % genres

            items.append({
                "title": title,
                "meta": meta,
                "overview": item.get("Overview", ""),
                "country": "",
                "director": "",
                "search_term": title,
                "id": item.get("Id"),
                "type": typ,
                "user_data": item.get("UserData", {}),
                "UserData": item.get("UserData", {}),
                "runtime_ticks": item.get("RunTimeTicks"),
                "RunTimeTicks": item.get("RunTimeTicks"),
                "production_year": item.get("ProductionYear"),
                "ProductionYear": item.get("ProductionYear"),
                "official_rating": item.get("OfficialRating"),
                "OfficialRating": item.get("OfficialRating"),
                "media_sources": item.get("MediaSources", []),
                "MediaSources": item.get("MediaSources", []),
            })
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_favorites_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return items

def emby_search_items(search_term, limit=30, include_types="Movie,Series,Video,Episode"):
    items = []
    try:
        search_term = unicodedata.normalize(
            "NFC",
            str(search_term or "")
        ).strip()
    except Exception:
        search_term = str(search_term or "").strip()

    if not requests or not EMBY_SERVER or not EMBY_USERNAME or not search_term:
        return items
    try:
        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return items

        headers = {"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER}
        r = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers=headers,
            params={
                "SearchTerm": search_term,
                "Recursive": "true",
                "IncludeItemTypes": include_types,
                "Limit": str(limit),
                "Fields": "Overview,Genres,ProductionYear,RunTimeTicks,MediaSources,UserData,SeriesName,IndexNumber,ParentIndexNumber",
            },
            timeout=10,
            verify=True,
        )

        for item in r.json().get("Items", []) or []:
            title = item.get("Name", "")
            typ = item.get("Type", "")
            year = item.get("ProductionYear") or ""
            genres = ", ".join(item.get("Genres") or [])
            meta = typ
            if year:
                meta += " | %s" % year
            if genres:
                meta += " | %s" % genres

            items.append({
                "title": title,
                "meta": meta,
                "overview": item.get("Overview", ""),
                "country": "",
                "director": "",
                "search_term": title,
                "id": item.get("Id"),
                "type": item.get("Type"),
                "user_data": item.get("UserData", {}),
                "UserData": item.get("UserData", {}),
                "runtime_ticks": item.get("RunTimeTicks"),
                "media_sources": item.get("MediaSources", []),
            })
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_search_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return items


# DETAIL_METADATA_ENRICHMENT_V3
def emby_enrich_detail_data(source_data):
    # DETAIL_METADATA_ENRICHMENT_V3
    # DETAIL_METADATA_FALLBACK_V7
    result = dict(source_data or {})

    # EMBYFLOW_REF13_DETAILSAFE_LOCALTEST
    # Items coming from the dynamic server-view loader already contain the
    # metadata needed to construct the detail screen. A synchronous full-item
    # refresh here blocks Enigma2's GUI if the provider/API is slow. Keep the
    # first detail-open strictly local; playback can fetch stream information
    # later only when the user explicitly presses Play.
    if bool(result.get("_embyflow_lazy_library")):
        try:
            with embyflow_open_log(
                "/tmp/embyflow_detailsafe_ref13.log",
                "a"
            ) as _safe_log:
                _safe_log.write(
                    "%s SKIP_SYNC_ENRICH title=%s id=%s parent=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        str(result.get("title") or result.get("Name") or ""),
                        str(result.get("id") or result.get("Id") or ""),
                        str(result.get("_embyflow_parent_id") or ""),
                    )
                )
        except Exception:
            pass
        return result

    item_id = (
        result.get("id")
        or result.get("Id")
        or result.get("item_id")
    )

    if not item_id or not requests:
        return result

    try:
        server, token, user_id = get_emby_auth()

        if not server or not token:
            return result

        server = server.rstrip("/")

        headers = {
            "X-Emby-Token": token,
            "X-Emby-Authorization": AUTH_HEADER,
        }

        fields = (
            "People,Studios,ProductionLocations,ProductionCountries,"
            "ProductionCountry,Country,CountryCode,Genres,"
            "RunTimeTicks,OfficialRating,Overview,ProductionYear,"
            "SeriesId,SeasonId,ParentId,Type"
        )

        def fetch_full(fetch_id):
            if not fetch_id:
                return {}

            urls = []

            if user_id:
                urls.append(
                    "%s/Users/%s/Items/%s"
                    % (server, user_id, fetch_id)
                )

            urls.append(
                "%s/Items/%s"
                % (server, fetch_id)
            )

            for url in urls:
                try:
                    response = embyflow_http_get(
                        url,
                        headers=headers,
                        params={
                            "Fields": fields,
                            "api_key": token,
                        },
                        timeout=10,
                        verify=True,
                    )

                    if response.status_code != 200:
                        continue

                    data = response.json() or {}

                    if isinstance(data, dict) and data:
                        return data
                except:
                    continue

            return {}

        def first_child(parent_id, include_type, recursive):
            if not parent_id or not user_id:
                return {}

            try:
                response = embyflow_http_get(
                    "%s/Users/%s/Items"
                    % (server, user_id),
                    headers=headers,
                    params={
                        "ParentId": str(parent_id),
                        "Recursive": (
                            "true" if recursive else "false"
                        ),
                        "IncludeItemTypes": include_type,
                        "SortBy": (
                            "ParentIndexNumber,IndexNumber"
                            if include_type == "Episode"
                            else "IndexNumber"
                        ),
                        "SortOrder": "Ascending",
                        "Limit": "1",
                        "Fields": fields,
                    },
                    timeout=10,
                    verify=True,
                )

                if response.status_code != 200:
                    return {}

                items = response.json().get("Items", []) or []

                return items[0] if items else {}
            except:
                return {}

        primary = fetch_full(item_id)

        if not primary:
            return result

        source_type = str(
            primary.get("Type")
            or result.get("type")
            or result.get("Type")
            or ""
        )

        source_items = [primary]
        source_labels = ["primary"]

        def add_source(label, item):
            if not item:
                return

            source_item_id = item.get("Id")

            for existing in source_items:
                if (
                    source_item_id
                    and existing.get("Id") == source_item_id
                ):
                    return

            source_items.append(item)
            source_labels.append(label)

        if source_type == "Series":
            season = first_child(
                item_id,
                "Season",
                False
            )
            add_source("first-season", season)

            episode = first_child(
                item_id,
                "Episode",
                True
            )
            add_source("first-episode", episode)

        elif source_type == "Season":
            series_id = (
                primary.get("SeriesId")
                or primary.get("ParentId")
                or result.get("series_id")
            )

            add_source(
                "series",
                fetch_full(series_id)
            )

            episode = first_child(
                series_id or item_id,
                "Episode",
                True
            )
            add_source("first-episode", episode)

        elif source_type == "Episode":
            season_id = (
                primary.get("SeasonId")
                or result.get("season_id")
            )

            series_id = (
                primary.get("SeriesId")
                or result.get("series_id")
            )

            add_source(
                "season",
                fetch_full(season_id)
            )

            add_source(
                "series",
                fetch_full(series_id)
            )

        # SERIES_COUNTRY_RAW_DEBUG_V9
        try:
            import json as _json

            with embyflow_open_log(
                "/tmp/embyflow_series_country_raw_v9.log",
                "a"
            ) as raw_log:
                raw_log.write(
                    "\n=== DETAIL id=%s type=%s ===\n"
                    % (item_id, source_type)
                )

                for source_label, source_item in zip(
                    source_labels,
                    source_items
                ):
                    raw_log.write(
                        "SOURCE=%s ID=%s TYPE=%s\n"
                        % (
                            source_label,
                            source_item.get("Id", ""),
                            source_item.get("Type", ""),
                        )
                    )

                    interesting = {}

                    for key, value in source_item.items():
                        key_lower = str(key).lower()

                        if (
                            "countr" in key_lower
                            or "production" in key_lower
                            or "provider" in key_lower
                            or "external" in key_lower
                            or "origin" in key_lower
                            or key in (
                                "Tags",
                                "Studios",
                                "People",
                                "PremiereDate",
                                "ProductionYear",
                            )
                        ):
                            interesting[key] = value

                    raw_log.write(
                        _json.dumps(
                            interesting,
                            ensure_ascii=False,
                            indent=2
                        )
                        + "\n"
                    )
        except Exception as debug_error:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_series_country_raw_v9_error.log",
                    "a"
                ) as raw_error:
                    raw_error.write(str(debug_error) + "\n")
            except:
                pass

        def unique_append(target, value):
            value = str(value or "").strip()

            if value and value not in target:
                target.append(value)

        genres = []
        countries = []
        studios = []
        directors = []
        actors = []

        runtime_ticks = 0
        official_rating = ""
        overview = ""
        production_year = None

        for item in source_items:
            if not overview and item.get("Overview"):
                overview = item.get("Overview")

            if not production_year and item.get("ProductionYear"):
                production_year = item.get("ProductionYear")

            if not runtime_ticks and item.get("RunTimeTicks"):
                runtime_ticks = item.get("RunTimeTicks")

            if not official_rating and item.get("OfficialRating"):
                official_rating = str(
                    item.get("OfficialRating")
                ).strip()

            for genre in item.get("Genres") or []:
                unique_append(genres, genre)

            # DETAIL_COUNTRY_FIELDS_V8
            # Emby-Server und Metadatenanbieter verwenden hierfür
            # unterschiedliche Feldformen. Es werden ausschließlich
            # tatsächlich vorhandene Werte übernommen.
            def append_country_value(value):
                if value is None:
                    return

                if isinstance(value, (list, tuple)):
                    for entry in value:
                        append_country_value(entry)
                    return

                if isinstance(value, dict):
                    name = (
                        value.get("Name")
                        or value.get("name")
                        or value.get("DisplayName")
                        or value.get("displayName")
                        or value.get("TwoLetterISORegionName")
                        or value.get("ThreeLetterISORegionName")
                        or value.get("Code")
                        or value.get("code")
                        or ""
                    )
                    unique_append(countries, name)
                    return

                text = str(value or "").strip()

                if not text:
                    return

                # Manche Anbieter liefern mehrere Länder als Text.
                if "," in text:
                    for part in text.split(","):
                        unique_append(countries, part)
                elif ";" in text:
                    for part in text.split(";"):
                        unique_append(countries, part)
                else:
                    unique_append(countries, text)

            append_country_value(
                item.get("ProductionLocations")
            )
            append_country_value(
                item.get("ProductionCountries")
            )
            append_country_value(
                item.get("ProductionCountry")
            )
            append_country_value(
                item.get("Country")
            )
            append_country_value(
                item.get("CountryCode")
            )

            for studio in item.get("Studios") or []:
                if isinstance(studio, dict):
                    name = (
                        studio.get("Name")
                        or studio.get("name")
                        or ""
                    )
                else:
                    name = studio

                unique_append(studios, name)

            for person in item.get("People") or []:
                if not isinstance(person, dict):
                    continue

                name = str(
                    person.get("Name") or ""
                ).strip()

                person_type = str(
                    person.get("Type")
                    or person.get("type")
                    or ""
                ).strip().lower()

                if not name:
                    continue

                if person_type == "director":
                    unique_append(directors, name)

                elif person_type in (
                    "actor",
                    "gueststar",
                    "guest star",
                ):
                    unique_append(actors, name)

        if overview:
            result["overview"] = overview

        if production_year:
            result["production_year"] = production_year

        result["genres"] = genres

        try:
            result["runtime_minutes"] = int(
                round(
                    float(runtime_ticks)
                    / 600000000.0
                )
            )
        except:
            result["runtime_minutes"] = 0

        # Einige Server liefern Werte wie "-12".
        # Das Minus wird nur entfernt, wenn danach eine Zahl folgt.
        if (
            official_rating.startswith("-")
            and official_rating[1:].isdigit()
        ):
            official_rating = official_rating[1:]

        result["official_rating"] = official_rating
        result["countries"] = countries
        result["studios"] = studios
        result["directors"] = directors
        result["actors"] = actors[:8]

        try:
            with embyflow_open_log(
                "/tmp/embyflow_detail_metadata_v7.log",
                "a"
            ) as log:
                log.write(
                    "OK id=%s type=%s sources=%s "
                    "countries=%s studios=%s "
                    "directors=%s actors=%s "
                    "rating=%s runtime=%s\n"
                    % (
                        item_id,
                        source_type,
                        ",".join(source_labels),
                        ",".join(countries),
                        ",".join(studios),
                        ",".join(directors),
                        ",".join(actors[:8]),
                        official_rating,
                        result.get(
                            "runtime_minutes",
                            0
                        ),
                    )
                )
        except:
            pass

    except Exception as e:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_detail_metadata_v7_error.log",
                "a"
            ) as log:
                log.write(
                    "id=%s error=%s\n"
                    % (item_id, str(e))
                )
        except:
            pass

    return result



# EMBYFLOW_REF14_SINGLE_ASYNC_DETAIL_REQUEST_LOCALTEST
def embyflow_fetch_detail_metadata_once_ref14(source_data):
    result = dict(source_data or {})
    item_id = (
        result.get("id")
        or result.get("Id")
        or result.get("item_id")
    )

    if not item_id or not requests:
        return result

    try:
        server, token, user_id = get_emby_auth()

        if not server or not token or not user_id:
            return result

        server = str(server).rstrip("/")
        fields = (
            "People,Studios,ProductionLocations,ProductionCountries,"
            "ProductionCountry,Country,CountryCode,Genres,"
            "RunTimeTicks,OfficialRating,Overview,ProductionYear,Type"
        )

        # Exactly one provider request for this detail screen.
        response = requests.get(
            "%s/Users/%s/Items/%s"
            % (
                server,
                user_id,
                item_id,
            ),
            headers={
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            },
            params={
                "Fields": fields,
            },
            timeout=(3.05, 8.0),
            verify=True,
        )

        try:
            with embyflow_open_log(
                "/tmp/embyflow_async_detail_ref14.log",
                "a"
            ) as log:
                log.write(
                    "%s HTTP status=%s id=%s title=%s bytes=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        getattr(response, "status_code", "?"),
                        str(item_id),
                        str(
                            result.get("title")
                            or result.get("Name")
                            or ""
                        ),
                        len(getattr(response, "content", b"") or b""),
                    )
                )
        except Exception:
            pass

        if int(getattr(response, "status_code", 500) or 500) != 200:
            return result

        primary = response.json() or {}

        if not isinstance(primary, dict) or not primary:
            return result

        def unique_append(target, value):
            value = str(value or "").strip()
            if value and value not in target:
                target.append(value)

        def append_country(target, value):
            if value is None:
                return

            if isinstance(value, (list, tuple)):
                for entry in value:
                    append_country(target, entry)
                return

            if isinstance(value, dict):
                unique_append(
                    target,
                    value.get("Name")
                    or value.get("name")
                    or value.get("DisplayName")
                    or value.get("displayName")
                    or value.get("TwoLetterISORegionName")
                    or value.get("ThreeLetterISORegionName")
                    or value.get("Code")
                    or value.get("code")
                    or ""
                )
                return

            raw = str(value or "").strip()
            if not raw:
                return

            if "," in raw:
                for part in raw.split(","):
                    unique_append(target, part)
            elif ";" in raw:
                for part in raw.split(";"):
                    unique_append(target, part)
            else:
                unique_append(target, raw)

        genres = []
        countries = []
        studios = []
        directors = []
        actors = []

        for genre in primary.get("Genres") or []:
            unique_append(genres, genre)

        for key in (
            "ProductionLocations",
            "ProductionCountries",
            "ProductionCountry",
            "Country",
            "CountryCode",
        ):
            append_country(
                countries,
                primary.get(key)
            )

        for studio in primary.get("Studios") or []:
            if isinstance(studio, dict):
                studio = (
                    studio.get("Name")
                    or studio.get("name")
                    or ""
                )
            unique_append(studios, studio)

        for person in primary.get("People") or []:
            if not isinstance(person, dict):
                continue

            name = str(
                person.get("Name") or ""
            ).strip()
            person_type = str(
                person.get("Type")
                or person.get("type")
                or ""
            ).strip().lower()

            if not name:
                continue

            if person_type == "director":
                unique_append(directors, name)
            elif person_type in (
                "actor",
                "gueststar",
                "guest star",
            ):
                unique_append(actors, name)

        if primary.get("Overview"):
            result["overview"] = primary.get("Overview")

        if primary.get("ProductionYear"):
            result["production_year"] = primary.get("ProductionYear")

        if primary.get("Genres") is not None:
            result["genres"] = genres

        try:
            runtime_ticks = int(
                primary.get("RunTimeTicks")
                or 0
            )
            result["runtime_minutes"] = int(
                round(
                    float(runtime_ticks)
                    / 600000000.0
                )
            )
        except Exception:
            result["runtime_minutes"] = 0

        rating = str(
            primary.get("OfficialRating")
            or ""
        ).strip()

        if (
            rating.startswith("-")
            and rating[1:].isdigit()
        ):
            rating = rating[1:]

        result["official_rating"] = rating
        result["countries"] = countries
        result["studios"] = studios
        result["directors"] = directors
        result["actors"] = actors[:8]

        return result

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_async_detail_ref14.log",
                "a"
            ) as log:
                log.write(
                    "%s ERROR id=%s title=%s error=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        str(item_id),
                        str(
                            result.get("title")
                            or result.get("Name")
                            or ""
                        ),
                        str(error),
                    )
                )
        except Exception:
            pass

        return result


def fetch_hero_slides(limit=8):
    # HERO_DIAG_FETCH_V1
    hero_downloads = 0
    try:
        with embyflow_open_log(
            "/tmp/embyflow_hero_diagnose.log",
            "a"
        ) as diag_log:
            diag_log.write(
                "FETCH_HERO_ENTER limit=%s requests=%s "
                "server=%s username=%s\n"
                % (
                    limit,
                    bool(requests),
                    bool(EMBY_SERVER),
                    bool(EMBY_USERNAME),
                )
            )
    except Exception:
        pass

    slides = []
    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return slides
    try:
        # EMBYFLOW_BETA84_CENTRAL_AUTH_HERO_V1
        # Vorhandenen zentralen Token-Cache verwenden,
        # statt für die Hero-Liste erneut anzumelden.
        server, token, user_id = get_emby_auth()

        if not server or not token or not user_id:
            return slides

        r = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
            params={
                "Recursive": "true",
                "IncludeItemTypes": "Movie,Series",
                "SortBy": "DateCreated",
                "SortOrder": "Descending",
                # HERO_RANDOM_POOL_80_V1
                "Limit": str(
                    max(
                        80,
                        int(limit or 8) * 10
                    )
                ),
                "Fields": "Overview,Genres,ProductionYear,RunTimeTicks,MediaSources",
            },
            timeout=10,
            verify=True,
        )

        # HERO_RANDOM_SELECT_8_V1
        hero_candidates = (
            r.json().get("Items", [])
            or []
        )

        unique_candidates = []
        seen_candidate_ids = set()

        for candidate in hero_candidates:
            candidate_id = str(
                candidate.get("Id") or ""
            )

            if (
                not candidate_id
                or candidate_id in seen_candidate_ids
            ):
                continue

            seen_candidate_ids.add(
                candidate_id
            )
            unique_candidates.append(
                candidate
            )

        try:
            random.SystemRandom().shuffle(
                unique_candidates
            )
        except Exception:
            random.shuffle(
                unique_candidates
            )

        try:
            selected_limit = max(
                1,
                int(limit or 8)
            )
        except Exception:
            selected_limit = 8

        selected_candidates = (
            unique_candidates[:selected_limit]
        )

        try:
            with embyflow_open_log(
                "/tmp/embyflow_hero_random_pool.log",
                "a"
            ) as hero_pool_log:
                hero_pool_log.write(
                    "POOL=%s SELECTED=%s IDS=%s\n"
                    % (
                        len(unique_candidates),
                        len(selected_candidates),
                        ",".join(
                            str(
                                item.get("Id") or ""
                            )
                            for item in selected_candidates
                        ),
                    )
                )
        except Exception:
            pass

        for item in selected_candidates:
            name = item.get("Name") or "Unbekannt"
            typ = "Serie" if item.get("Type") == "Series" else "Film"
            year = item.get("ProductionYear") or ""
            genres = ", ".join((item.get("Genres") or [])[:3])
            overview = item.get("Overview") or "Keine Beschreibung vorhanden."

            minutes = ""
            ticks = item.get("RunTimeTicks") or 0
            if ticks:
                try:
                    minutes = "%d min" % int(int(ticks) / 600000000)
                except:
                    minutes = ""

            meta_parts = [typ]
            if year:
                meta_parts.append(str(year))
            if minutes:
                meta_parts.append(minutes)
            if genres:
                meta_parts.append(genres)

            ensure_dir(HERO_CACHE_DIR)
            img_path = HERO_CACHE_DIR + "/hero_%s.jpg" % item.get("Id")
            missing_path = img_path + ".missing"

            if (
                os.path.isfile(img_path)
                and os.path.getsize(img_path) > 1000
            ):
                embyflow_touch_cache_file(img_path)

            elif embyflow_negative_cache_active(missing_path):
                img_path = "/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/hero_bg.png"

            else:
              try:
                  img = embyflow_http_get(
                      server + "/Items/%s/Images/Backdrop/0" % item.get("Id"),
                      headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
                      params={"api_key": token, "maxWidth": "800", "maxHeight": "450", "quality": "90"},
                      timeout=10,
                      verify=True,
                  )
                  if img.status_code == 200 and len(img.content) > 1000:
                      raw_path = HERO_CACHE_DIR + "/hero_raw_%s.jpg" % item.get("Id")
                      f = open(raw_path, "wb")
                      f.write(img.content)
                      f.close()

                      im = Image.open(raw_path).convert("RGB")
                      target_w, target_h = 680, 300
                      iw, ih = im.size
                      scale = max(float(target_w) / float(iw), float(target_h) / float(ih))
                      nw, nh = int(iw * scale), int(ih * scale)
                      im = im.resize((nw, nh), Image.LANCZOS)
                      left = max(0, int((nw - target_w) / 2))
                      top = max(0, int((nh - target_h) / 2))
                      im = im.crop((left, top, left + target_w, top + target_h))
                      im.save(
                          img_path,
                          "JPEG",
                          quality=84,
                          optimize=True
                      )

                      try:
                          os.remove(raw_path)
                      except Exception:
                          pass

                      embyflow_clear_negative_cache(missing_path)
                      embyflow_touch_cache_file(img_path, 0)
                      hero_downloads += 1
                  else:
                      embyflow_mark_negative_cache(
                          missing_path,
                          "http-%s" % getattr(img, "status_code", "?")
                      )
                      img_path = "/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/hero_bg.png"
              except Exception as image_error:
                  embyflow_mark_negative_cache(
                      missing_path,
                      str(image_error)
                  )
                  img_path = "/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/hero_bg.png"
            slides.append({
                "title": name,
                "meta": " | ".join(meta_parts),
                "overview": overview[:160],
                "backdrop": img_path,
                "id": item.get("Id"),
                "type": item.get("Type"),
                "search_term": name,
            })
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_hero_slider_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    if hero_downloads > 0:
        embyflow_request_cache_tune("hero-slides")

    return slides


