    def progress_percent_from_item(self, item):
        try:
            user_data = (item or {}).get("UserData") or {}
            percent = user_data.get("PlayedPercentage")
            if percent is None:
                percent = user_data.get("PlayedPercent")
            if percent is None:
                pos = user_data.get("PlaybackPositionTicks") or (item or {}).get("PlaybackPositionTicks") or 0
                runtime = (item or {}).get("RunTimeTicks") or 0
                if pos and runtime:
                    percent = (float(pos) * 100.0) / float(runtime)
            if percent is None and user_data.get("Played"):
                percent = 100
            if percent is None:
                percent = 0
            percent = int(round(float(percent)))
            if percent < 0:
                percent = 0
            if percent > 100:
                percent = 100
            if percent == 0:
                pos = user_data.get("PlaybackPositionTicks") or 0
                if pos:
                    percent = 1
            return percent
        except:
            return None

    def hide_progress_widget(self, index):
        try:
            for prefix in ("progress_bg", "progress_fill", "progress_text"):
                self["%s%d" % (prefix, index)].hide()
                if self["%s%d" % (prefix, index)].instance:
                    self["%s%d" % (prefix, index)].instance.move(EFP(-500, -500))
                    self["%s%d" % (prefix, index)].instance.resize(EFS(1, 1))
        except:
            pass

    def show_progress_widget(self, index, percent):

        self.hide_progress_widget(index)

    def update_poster_labels(self):
        try:
            for i in range(1, 7):
                item = (self.dynamic_poster_items or {}).get("poster%d" % i) or {}
                title = item.get("title") or item.get("Name") or ""
                if len(title) > 25:
                    title = title[:24] + "..."

                try:
                    fname, area, col, fx, fy, fw, fh = self.current_focus()
                    active_map = {
                        "poster_movie_1": 1,
                        "poster_movie_2": 2,
                        "poster_series_1": 3,
                        "poster_series_2": 4,
                        "poster_doc_1": 5,
                        "poster_doc_2": 6,
                    }
                    if active_map.get(fname, 0) == i and title:
                        title = ">>> " + title
                except:
                    pass

                typ = item.get("type") or item.get("Type") or ""
                if typ == "Movie":
                    typ = "Film"
                elif typ == "Series":
                    typ = "Serie"
                elif typ == "Episode":
                    typ = "Episode"
                elif not typ:
                    typ = "Titel"

                year = item.get("year") or item.get("ProductionYear") or ""
                percent = item.get("progress")
                if percent is None:
                    percent = self.progress_percent_from_item(item)

                # HOME_META_MODERN_COLORS_V1
                # Dieselbe Darstellung wie im Favoriten-Grid:
                # neutral hellgrau, Fortschritt deutlich grün.
                try:
                    percent_value = (
                        None
                        if percent is None
                        else max(
                            0,
                            min(
                                100,
                                int(round(float(percent)))
                            )
                        )
                    )
                except Exception:
                    percent_value = None

                meta_parts = []

                if percent_value is not None and percent_value >= 95:
                    meta_parts.append("Gesehen")
                elif percent_value is not None and percent_value > 0:
                    meta_parts.append(
                        "%s %% gesehen" % percent_value
                    )

                if typ:
                    meta_parts.append(str(typ))

                if year:
                    meta_parts.append(str(year))

                meta = " · ".join(meta_parts)

                self["poster_title%d" % i].setText(
                    title.replace(">>>", "").strip()
                )
                self["poster_meta%d" % i].setText(meta)

                try:
                    if percent_value is not None and percent_value > 0:
                        self[
                            "poster_meta%d" % i
                        ].instance.setForegroundColor(
                            parseColor("#6BCB77")
                        )
                    else:
                        self[
                            "poster_meta%d" % i
                        ].instance.setForegroundColor(
                            parseColor("#B8C0CC")
                        )
                except Exception:
                    pass
        except Exception as e:
            try:
                f=embyflow_open_log("/tmp/embyflow_title_error.log","a")
                f.write("%s\n" % str(e))
                f.close()
            except:
                pass


    def update_progress_widgets(self):
        try:
            for i in range(1, 7):
                self.hide_progress_widget(i)
            self.update_poster_labels()
            for name in ("focus_top","focus_bottom","focus_left","focus_right"):
                try:
                    self[name].hide()
                    self[name].instance.hide()
                    self[name].instance.move(EFP(-500, -500))
                    self[name].instance.resize(EFS(1, 1))
                except:
                    pass
        except:
            pass

    def clear_progress_widgets(self):
        for i in range(1, 7):
            self.hide_progress_widget(i)
            try:
                self["poster_title%d" % i].setText("")
                self["poster_meta%d" % i].setText("")
            except:
                pass

