        # EMBYFLOW_SELECTION_UNPACK_FIX_V1
        label = (
            selection[0]
            if len(selection) > 0
            else ""
        )
        data = (
            selection[1]
            if len(selection) > 1
            else None
        )
        if isinstance(data, dict):
            self.session.open(EmbyFlowDetailScreen, data)

