        # EMBYFLOW_PERF24_ASYNC_GRID_IO_V1
        # Backdrop-Download/PIL sowie sichtbare UserData-Nachladung dürfen
        # den Enigma2-GUI-Thread nicht blockieren.
        self.grid_backdrop_worker_running = False
        self.grid_backdrop_worker_key = ""
        self.grid_backdrop_requested_key = ""
        self.grid_backdrop_ready = None
        self.grid_backdrop_poll_timer = eTimer()
