EMBYFLOW_LIBRARY_HISTORY_FILE = "/etc/enigma2/embyflow_library_history.json"


def embyflow_library_history_key(data):
    if not isinstance(data, dict):
        return ""

    include_types = str(data.get("include_types") or "")

    if data.get("all_items"):
        return "all:%s" % include_types

    if data.get("genres"):
        return "genre:%s:%s" % (
            include_types,
            str(data.get("genre_name") or ""),
        )

    if data.get("library_id") or data.get("library_name"):
        return "library:%s:%s:%s" % (
            include_types,
            str(data.get("library_id") or ""),
            str(data.get("library_name") or ""),
        )

    return ""


def load_embyflow_library_history():
    try:
        if not os.path.exists(EMBYFLOW_LIBRARY_HISTORY_FILE):
            return {}

        f = open(EMBYFLOW_LIBRARY_HISTORY_FILE, "r")
        try:
            payload = json.loads(f.read())
        finally:
            f.close()

        return payload if isinstance(payload, dict) else {}
    except:
        return {}


def save_embyflow_library_opened(data):
    key = embyflow_library_history_key(data)
    if not key:
        return

    try:
        history = load_embyflow_library_history()
        history[key] = __import__("time").strftime(
            "%Y-%m-%dT%H:%M:%S"
        )

        tmp_path = EMBYFLOW_LIBRARY_HISTORY_FILE + ".tmp"

        f = open(tmp_path, "w")
        try:
            f.write(json.dumps(history))
        finally:
            f.close()

        os.rename(tmp_path, EMBYFLOW_LIBRARY_HISTORY_FILE)

    except Exception as error:
        try:
            f = embyflow_open_log(
                "/tmp/embyflow_library_history_error.log",
                "a"
            )
            f.write("save: %s\n" % str(error))
            f.close()
        except:
            pass


def add_embyflow_library_timestamps(entries):
    history = load_embyflow_library_history()
    enriched = []

    for entry in entries or []:
        if not entry:
            enriched.append(entry)
            continue

        label = entry[0]
        data = entry[1] if len(entry) > 1 else None
        key = embyflow_library_history_key(data)
        timestamp = str(history.get(key) or "") if key else ""

        enriched.append((label, data, timestamp))

    return enriched



