    def __init__(self, session, player):
        Screen.__init__(self, session)
        self.player = player
        self.chapters = []
        self.selected = 0
        self.top_index = 0
        self._closing = False
        self._chapter_load_done = False
        self._chapter_load_result = None
        self._chapter_load_error = ""
        self._chapter_thread = None
        self._preview_busy = False
        self._preview_result = None
        self._preview_request = None
        self._preview_generation = 0
        self._preview_process = None

        self["brand_emby"] = Label("EMBY")
        self["brand_flow"] = Label("FLOW")
        self["screen_title"] = Label("KAPITELSPRUNG")
        self["media_title"] = Label(str(getattr(player, "overlay_main_title", "") or getattr(player, "title_text", "") or "EmbyFlow"))
        self["position_text"] = Label("")
        self["header_line"] = Label(" ")
        self["header_line_pink"] = Label(" ")
        self["left_heading"] = Label("KAPITEL")
        self["left_duration_heading"] = Label("DAUER")
        self["right_heading"] = Label("VORSCHAU")

        for row in range(self.VISIBLE_ROWS):
            self["row%d_border" % row] = Label(" ")
            self["row%d_bg" % row] = Label(" ")
            self["row%d_num" % row] = Label("")
            self["row%d_name" % row] = Label("")
            self["row%d_time" % row] = Label("")

        self["preview_frame"] = Label(" ")
        self["preview_border_top"] = Label(" ")
        self["preview_border_bottom"] = Label(" ")
        self["preview_border_left"] = Label(" ")
        self["preview_border_right"] = Label(" ")
        self["preview_image"] = Pixmap()
        self["preview_image"].hide()
        self["preview_status"] = Label("Kapitel werden geladen …")

        for index in range(8):
            self["thumb%d_bg" % index] = Label(" ")
            self["thumb%d" % index] = Pixmap()
            self["thumb%d" % index].hide()

        self["timeline_line"] = Label(" ")
        for index in range(5):
            self["timeline_mark%d" % index] = Label(" ")
            self["timeline_t%d" % index] = Label("")
        self["timeline_selected_mark"] = Label(" ")
        self["timeline_selected_time"] = Label("")

        self["preview_title"] = Label("")
        self["preview_time"] = Label("")
        self["chapter_count"] = Label("")
        self["footer_line"] = Label(" ")
        self["key_red"] = Label("ROT  Zurück")
        self["key_ok"] = Label("OK  Zu Kapitel springen")
        self["key_info"] = Label("INFO  Aktuelles Kapitel")
        self["key_nav"] = Label("▲/▼ Kapitel   ◀/▶ Seite")

        self["actions"] = ActionMap(
            [
                "OkCancelActions",
                "ColorActions",
                "DirectionActions",
                "InfobarEPGActions",
            ],
            {
                "cancel": self.close_screen,
                "red": self.close_screen,
                "blue": self.close_screen,
                "ok": self.jump_selected,
                "green": self.jump_selected,
                "up": self.move_up,
                "down": self.move_down,
                "left": self.page_up,
                "right": self.page_down,
                "showEventInfo": self.focus_current_chapter_v16_4,
            },
            -10,
        )

        self._poll_timer = eTimer()
        try:
            self._poll_timer.callback.append(self._poll_async)
        except Exception:
            try:
                self._poll_timer.timeout.connect(self._poll_async)
            except Exception:
                pass

        self.onLayoutFinish.append(self._layout_ready)
        try:
            self.onClose.append(self._cleanup)
        except Exception:
            pass

    def _layout_ready(self):
        try:
            current = int(self.player.current_position_ticks() or 0)
        except Exception:
            current = 0
        self["position_text"].setText("Aktuelle Position  %s" % self._format_ticks(current))
        try:
            self._poll_timer.start(200, False)
        except Exception:
            pass

        local = []
        try:
            local = self.player.embyflow_extract_local_chapters()
        except Exception:
            local = []

        if local:
            self._apply_chapters(local)
            return

        self["preview_status"].setText("Kapitel werden von Emby geladen …")
        self._start_chapter_load()

    def _cleanup(self):
        self._closing = True
        try:
            self._poll_timer.stop()
        except Exception:
            pass
        try:
            process = self._preview_process
            if process is not None and process.poll() is None:
                process.terminate()
        except Exception:
            pass
        self._preview_process = None

    def close_screen(self):
        self._closing = True
        self.close()

    def _start_chapter_load(self):
        if self._chapter_thread is not None:
            return
        try:
            import threading

            def worker():
                try:
                    result = self.player.embyflow_fetch_chapters_remote()
                    self._chapter_load_result = result or []
                except Exception as error:
                    self._chapter_load_error = str(error)
                    self._chapter_load_result = []
                self._chapter_load_done = True

            self._chapter_thread = threading.Thread(target=worker, name="EmbyFlowChapters")
            self._chapter_thread.daemon = True
            self._chapter_thread.start()
        except Exception as error:
            self._chapter_load_error = str(error)
            self._chapter_load_result = []
            self._chapter_load_done = True

    def _poll_async(self):
        if self._closing:
            return

        try:
            current = int(self.player.current_position_ticks() or 0)
            value = "Aktuelle Position  %s" % self._format_ticks(current)
            if value != str(self["position_text"].getText() or ""):
                self["position_text"].setText(value)
        except Exception:
            pass

        if self._chapter_load_done and not self.chapters:
            result = self._chapter_load_result or []
            self._chapter_load_done = False
            if result:
                self._apply_chapters(result)
            else:
                self["preview_status"].setText("Keine Kapitelinformationen für diesen Titel gefunden.")
                self["chapter_count"].setText("Emby liefert für diesen Titel keine Kapitelmarken.")

        preview = self._preview_result
        if preview is not None:
            self._preview_result = None
            self._preview_busy = False
            generation, index, path, error = preview
            if generation == self._preview_generation and index == self.selected:
                if path and os.path.isfile(path):
                    self._show_preview_path(index, path)
                else:
                    try:
                        self["preview_image"].hide()
                    except Exception:
                        pass
                    self["preview_status"].setText(error or "Kein Vorschaubild verfügbar.")
            self._maybe_start_preview()

    def _normalize_selection(self):
        if not self.chapters:
            self.selected = 0
            self.top_index = 0
            return
        self.selected = max(0, min(int(self.selected), len(self.chapters) - 1))
        if self.selected < self.top_index:
            self.top_index = self.selected
        if self.selected >= self.top_index + self.VISIBLE_ROWS:
            self.top_index = self.selected - self.VISIBLE_ROWS + 1
        max_top = max(0, len(self.chapters) - self.VISIBLE_ROWS)
        self.top_index = max(0, min(self.top_index, max_top))

    def _apply_chapters(self, chapters):
        self.chapters = list(chapters or [])
        if not self.chapters:
            self["preview_status"].setText("Keine Kapitelinformationen für diesen Titel gefunden.")
            return

        try:
            current = int(self.player.current_position_ticks() or 0)
        except Exception:
            current = 0

        active = 0
        for idx, chapter in enumerate(self.chapters):
            try:
                if int(chapter.get("StartPositionTicks") or 0) <= current:
                    active = idx
                else:
                    break
            except Exception:
                pass

        self.selected = active
        self.top_index = max(0, active - 2)
        self._normalize_selection()
        self.refresh_rows()
        self.request_preview()

    def _format_ticks(self, ticks):
        try:
            total = max(0, int(int(ticks or 0) // 10000000))
        except Exception:
            total = 0
        hours = total // 3600
        minutes = (total % 3600) // 60
        seconds = total % 60
        if hours:
            return "%d:%02d:%02d" % (hours, minutes, seconds)
        return "%02d:%02d" % (minutes, seconds)

    # EMBYFLOW_CHAPTER_CINEMATIC_UI_V16_4
    def _timeline_duration_ticks_v16_4(self):
        try:
            duration = int(getattr(self.player, "duration_ticks", 0) or 0)
            if duration > 0:
                return duration
        except Exception:
            pass
        try:
            item = getattr(self.player, "item", None) or {}
            duration = int(
                item.get("RunTimeTicks")
                or item.get("runtime_ticks")
                or 0
            )
            if duration > 0:
                return duration
        except Exception:
            pass
        if self.chapters:
            try:
                last = int(self.chapters[-1].get("StartPositionTicks") or 0)
                return max(last + 3000000000, 1)
            except Exception:
                pass
        return 1

    def _format_timeline_ticks_v16_4(self, ticks):
        try:
            total = max(0, int(int(ticks or 0) // 10000000))
        except Exception:
            total = 0
        hours = total // 3600
        minutes = (total % 3600) // 60
        seconds = total % 60
        return "%d:%02d:%02d" % (hours, minutes, seconds)

    def _timeline_sample_indices_v16_4(self):
        if not self.chapters:
            return []
        count = len(self.chapters)
        if count == 1:
            return [0] * 8
        result = []
        for slot in range(8):
            value = int(round((float(slot) * float(count - 1)) / 7.0))
            result.append(max(0, min(count - 1, value)))
        return result

    def _refresh_filmstrip_v16_4(self, fallback_path=""):
        if not self.chapters or self._closing:
            return

        samples = self._timeline_sample_indices_v16_4()
        for slot in range(8):
            widget = self["thumb%d" % slot]
            path = ""
            chapter_index = samples[slot] if slot < len(samples) else self.selected

            try:
                chapter = self.chapters[chapter_index]
                candidate = self._cache_path(chapter)
                if self._preview_file_valid(candidate):
                    path = candidate
            except Exception:
                path = ""

            if not path and self._preview_file_valid(fallback_path):
                path = fallback_path

            if not path:
                try:
                    widget.hide()
                except Exception:
                    pass
                continue

            token = "chapter-filmstrip-v16-4-%s-%s-%s" % (
                str(getattr(self.player, "item_id", "")),
                slot,
                chapter_index,
            )
            try:
                ok = embyflow_decode_image_to_widget(
                    self,
                    "thumb%d" % slot,
                    path,
                    112,
                    62,
                    token=token,
                    is_current=lambda: not self._closing,
                )
                if not ok:
                    widget.hide()
            except Exception:
                try:
                    widget.hide()
                except Exception:
                    pass

    def _refresh_timeline_v16_4(self):
        if not self.chapters:
            return

        duration = max(1, int(self._timeline_duration_ticks_v16_4()))
        selected_ticks = 0
        try:
            selected_ticks = max(
                0,
                int(self.chapters[self.selected].get("StartPositionTicks") or 0),
            )
        except Exception:
            selected_ticks = 0

        quarter_ticks = [
            0,
            int(duration * 0.25),
            int(duration * 0.50),
            int(duration * 0.75),
            int(duration),
        ]
        for index, value in enumerate(quarter_ticks):
            self["timeline_t%d" % index].setText(
                self._format_timeline_ticks_v16_4(value)
            )

        self["timeline_selected_time"].setText(
            self._format_timeline_ticks_v16_4(selected_ticks)
        )

        fraction = min(
            1.0,
            max(0.0, float(selected_ticks) / float(duration)),
        )
        # Timeline geometry follows the fixed 1920x1080 skin.
        x = int(round(835 + (995 * fraction)))
        x = max(835, min(1822, x - 8))
        label_x = max(835, min(1640, x - 87))
        try:
            instance = getattr(self["timeline_selected_mark"], "instance", None)
            if instance is not None:
                instance.move(ePoint(x, 888))
        except Exception:
            pass
        try:
            instance = getattr(self["timeline_selected_time"], "instance", None)
            if instance is not None:
                instance.move(ePoint(label_x, 909))
        except Exception:
            pass

    def refresh_rows(self):
        self._normalize_selection()

        for row in range(self.VISIBLE_ROWS):
            absolute = self.top_index + row
            names = ("bg", "num", "name", "time")
            if absolute < len(self.chapters):
                chapter = self.chapters[absolute]
                title = str(chapter.get("Name") or "Kapitel %d" % (absolute + 1))
                start = int(chapter.get("StartPositionTicks") or 0)
                self["row%d_num" % row].setText("%02d" % (absolute + 1))
                self["row%d_name" % row].setText(title)
                self["row%d_time" % row].setText(self._format_ticks(start))
                selected = absolute == self.selected
                base = "#10344A" if selected else ("#0A1525" if row % 2 == 0 else "#08111E")
                cell = "#091728" if selected else base
                border = "#F14AAA" if selected else "#030811"
                num_color = "#F14AAA" if selected else "#35D9F3"
                try:
                    border_widget = self["row%d_border" % row]
                    border_instance = getattr(border_widget, "instance", None)
                    if border_instance is not None:
                        border_instance.setBackgroundColor(parseColor(border))
                        try:
                            border_instance.invalidate()
                        except Exception:
                            pass
                    border_widget.setText(" ")

                    for suffix in names:
                        widget = self["row%d_%s" % (row, suffix)]
                        instance = getattr(widget, "instance", None)
                        if instance is not None:
                            background = (
                                cell
                                if selected and suffix in ("num", "time")
                                else base
                            )
                            instance.setBackgroundColor(parseColor(background))
                            try:
                                instance.invalidate()
                            except Exception:
                                pass

                    try:
                        self["row%d_bg" % row].setText(" ")
                    except Exception:
                        pass
                    self["row%d_num" % row].instance.setForegroundColor(parseColor(num_color))
                    self["row%d_name" % row].instance.setForegroundColor(parseColor("#FFFFFF" if selected else "#F5F7FA"))
                    self["row%d_time" % row].instance.setForegroundColor(parseColor("#FFFFFF" if selected else "#AAB7C7"))
                except Exception:
                    pass
            else:
                self["row%d_num" % row].setText("")
                self["row%d_name" % row].setText("")
                self["row%d_time" % row].setText("")

        if self.chapters:
            chapter = self.chapters[self.selected]
            self["preview_title"].setText(str(chapter.get("Name") or "Kapitel %d" % (self.selected + 1)))
            self["preview_time"].setText(self._format_ticks(chapter.get("StartPositionTicks") or 0))
            self["chapter_count"].setText(
                "Kapitel %d von %d  •  OK springt direkt zur gewählten Position"
                % (self.selected + 1, len(self.chapters))
            )
            self._refresh_timeline_v16_4()
            self._refresh_filmstrip_v16_4()

    def focus_current_chapter_v16_4(self):
        if not self.chapters:
            return
        try:
            current = int(self.player.current_position_ticks() or 0)
        except Exception:
            current = 0

        active = 0
        for index, chapter in enumerate(self.chapters):
            try:
                if int(chapter.get("StartPositionTicks") or 0) <= current:
                    active = index
                else:
                    break
            except Exception:
                pass

        self.selected = active
        self._normalize_selection()
        self.refresh_rows()
        self.request_preview()

    def move_up(self):
        if not self.chapters:
            return
        self.selected = max(0, self.selected - 1)
        self.refresh_rows()
        self.request_preview()

    def move_down(self):
        if not self.chapters:
            return
        self.selected = min(len(self.chapters) - 1, self.selected + 1)
        self.refresh_rows()
        self.request_preview()

    def page_up(self):
        if not self.chapters:
            return
        self.selected = max(0, self.selected - self.VISIBLE_ROWS)
        self.refresh_rows()
        self.request_preview()

    def page_down(self):
        if not self.chapters:
            return
        self.selected = min(len(self.chapters) - 1, self.selected + self.VISIBLE_ROWS)
        self.refresh_rows()
        self.request_preview()

    def jump_selected(self):
        if not self.chapters:
            return
        chapter = self.chapters[self.selected]
        try:
            target = int(chapter.get("StartPositionTicks") or 0)
        except Exception:
            target = 0
        try:
            self.player.embyflow_seek_to_chapter(target)
        finally:
            self.close_screen()

    def _cache_path(self, chapter):
        try:
            item_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(getattr(self.player, "item_id", "") or "item"))
            image_index = int(chapter.get("_embyflow_image_index") or 0)
            tag = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(chapter.get("ImageTag") or "notag_v5"))[-60:]
            folder = os.path.join(CACHE_DIR, "chapters", item_id)
            ensure_dir(folder)
            return os.path.join(folder, "chapter_%03d_%s.jpg" % (image_index, tag))
        except Exception:
            return ""

    # EMBYFLOW_CHAPTER_NAV_PREVIEW_V2_FFMPEG_FALLBACK
    # Stufe 1: fertiges Emby-Kapitelbild. Stufe 2: eigenes Standbild aus dem
    # Emby-Stream an der Kapitelposition. Der Fallback läuft niedrig priorisiert
    # im Hintergrund und wird danach lokal gecacht.
    def request_preview(self):
        if not self.chapters:
            return
        chapter = self.chapters[self.selected]
        self._preview_generation += 1
        generation = self._preview_generation
        path = self._cache_path(chapter)

        if self._preview_file_valid(path):
            self._show_preview_path(self.selected, path)
            return

        try:
            self["preview_image"].hide()
        except Exception:
            pass

        if chapter.get("ImageTag"):
            self["preview_status"].setText("Kapitelbild wird von Emby geladen …")
        else:
            self["preview_status"].setText("Kapitelvorschau wird sicher vorbereitet …")

        self._preview_request = (generation, self.selected, dict(chapter), path)
        self._maybe_start_preview()

    def _maybe_start_preview(self):
        if self._preview_busy or not self._preview_request or self._closing:
            return
        request = self._preview_request
        self._preview_request = None
        self._preview_busy = True

        try:
            import threading

            def worker():
                generation, index, chapter, path = request
                result_path = ""
                error_text = ""
                try:
                    result_path = self._obtain_preview(chapter, path)
                    if not result_path:
                        if not os.path.isfile("/usr/bin/ffmpeg"):
                            error_text = "Kein Kapitelbild vorhanden und ffmpeg fehlt auf der Box."
                        else:
                            error_text = "Vorschaubild konnte für dieses Kapitel nicht erzeugt werden."
                except Exception as error:
                    error_text = "Vorschaubild konnte nicht erzeugt werden: %s" % str(error)
                self._preview_result = (generation, index, result_path, error_text)

            thread = threading.Thread(target=worker, name="EmbyFlowChapterPreviewV2")
            thread.daemon = True
            thread.start()
        except Exception as error:
            self._preview_busy = False
            self._preview_result = (request[0], request[1], "", str(error))

    def _preview_file_valid(self, path):
        try:
            candidate = str(path or "")
            if not candidate or not os.path.isfile(candidate) or os.path.getsize(candidate) <= 500:
                return False
            with open(candidate, "rb") as handle:
                head = handle.read(12)
            return head.startswith(b"\xff\xd8") or head.startswith(b"\x89PNG\r\n\x1a\n")
        except Exception:
            return False

    # EMBYFLOW_SAFE_CHAPTER_PREVIEW_V11_6_START
    def _preview_v6_log(self, event, **values):
        try:
            parts = []
            for key in sorted(values):
                if str(key).lower() in (
                    "url",
                    "token",
                    "password",
                    "api_key",
                    "apikey",
                ):
                    continue
                parts.append(
                    "%s=%s"
                    % (
                        str(key),
                        str(values.get(key)),
                    )
                )
            with embyflow_open_log(
                "/tmp/embyflow_chapter_preview_v11_6.log",
                "a",
            ) as log:
                log.write(
                    "%s event=%s %s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        str(event or "unknown"),
                        " ".join(parts),
                    )
                )
        except Exception:
            pass

    def _preview_v6_native_item_marker(self):
        try:
            item_id = re.sub(
                r"[^A-Za-z0-9_.-]+",
                "_",
                str(
                    getattr(
                        self.player,
                        "item_id",
                        "",
                    )
                    or "item"
                ),
            )
            folder = os.path.join(
                CACHE_DIR,
                "chapters",
                item_id,
            )
            ensure_dir(folder)
            return os.path.join(
                folder,
                ".native_untagged_unavailable_v11_6",
            )
        except Exception:
            return ""

    def _preview_v6_native_chapter_marker(self, path):
        try:
            return str(path or "") + ".native_missing_v11_6"
        except Exception:
            return ""

    def _preview_v6_direct_marker(self, path):
        try:
            return str(path or "") + ".safe_direct_missing_v11_6"
        except Exception:
            return ""

    def _preview_v6_placeholder_path(self, chapter):
        try:
            item_id = re.sub(
                r"[^A-Za-z0-9_.-]+",
                "_",
                str(
                    getattr(
                        self.player,
                        "item_id",
                        "",
                    )
                    or "item"
                ),
            )
            index = int(
                chapter.get("_embyflow_image_index")
                or 0
            )
            folder = os.path.join(
                CACHE_DIR,
                "chapters",
                item_id,
            )
            ensure_dir(folder)
            return os.path.join(
                folder,
                "chapter_%03d_placeholder_v11_6.jpg"
                % index,
            )
        except Exception:
            return ""

    def _preview_v6_make_placeholder(self, chapter):
        """
        Last-resort local artwork. No server request.
        preview_title / preview_time already provide the chapter text below it.
        """
        path = self._preview_v6_placeholder_path(
            chapter
        )
        if self._preview_file_valid(path):
            return path

        if Image is None or not path:
            return ""

        temporary = path + ".tmp"
        try:
            from PIL import ImageDraw

            width = 954
            height = 536
            image = Image.new(
                "RGB",
                (width, height),
                (7, 17, 30),
            )
            draw = ImageDraw.Draw(image)

            # EmbyFlow cyan/pink frame and restrained center motif.
            cyan = (53, 217, 243)
            pink = (241, 74, 170)
            navy = (10, 21, 37)
            steel = (34, 52, 75)

            draw.rectangle(
                (0, 0, width - 1, height - 1),
                outline=steel,
                width=3,
            )
            draw.rectangle(
                (0, 0, int(width * 0.72), 5),
                fill=cyan,
            )
            draw.rectangle(
                (int(width * 0.72), 0, width, 5),
                fill=pink,
            )

            center_x = width // 2
            center_y = height // 2
            draw.rectangle(
                (
                    center_x - 128,
                    center_y - 72,
                    center_x + 128,
                    center_y + 72,
                ),
                fill=navy,
                outline=steel,
            )
            draw.rectangle(
                (
                    center_x - 92,
                    center_y - 4,
                    center_x - 8,
                    center_y + 4,
                ),
                fill=cyan,
            )
            draw.rectangle(
                (
                    center_x + 8,
                    center_y - 4,
                    center_x + 92,
                    center_y + 4,
                ),
                fill=pink,
            )

            image.save(
                temporary,
                "JPEG",
                quality=88,
                optimize=True,
            )
            try:
                image.close()
            except Exception:
                pass

            self._preview_atomic_replace(
                temporary,
                path,
            )
            return (
                path
                if self._preview_file_valid(path)
                else ""
            )
        except Exception:
            return ""
        finally:
            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except Exception:
                pass

    def _obtain_preview(self, chapter, path):
        if not path:
            return ""

        if self._preview_file_valid(path):
            return path

        background_prewarm = bool(
            getattr(
                self,
                "_embyflow_preview_background_prewarm_v11_6",
                False,
            )
        )

        # ------------------------------------------------------------------
        # Stage 1: native Emby chapter artwork.
        #
        # Important V11.6 change: a missing ImageTag no longer proves that the
        # REST image endpoint is unavailable. In the foreground we probe
        # /Items/{id}/Images/Chapter/{index} once even without ImageTag.
        # Background prewarm remains conservative and never blind-probes 24
        # chapter indices on a title that has no ImageTags.
        # ------------------------------------------------------------------
        native = self._download_preview(
            chapter,
            path,
            allow_untagged=not background_prewarm,
        )
        if self._preview_file_valid(native):
            return native

        # Background prewarm ends here. It may download known native chapter
        # images, but it may NOT start local ffmpeg extraction or placeholders.
        if background_prewarm:
            return ""

        # ------------------------------------------------------------------
        # Stage 2: local ffmpeg frame from a strictly validated Direct source.
        # The receiver seeks the Static=true stream itself. No Static=false,
        # StartTimeTicks, VideoCodec, TranscodingUrl or new PlaySessionId.
        # ------------------------------------------------------------------
        if EMBYFLOW_ALLOW_SAFE_DIRECT_CHAPTER_FRAME_FALLBACK:
            direct_marker = self._preview_v6_direct_marker(
                path
            )
            direct_blocked = bool(
                direct_marker
                and embyflow_negative_cache_active(
                    direct_marker,
                    EMBYFLOW_CHAPTER_SAFE_DIRECT_NEGATIVE_TTL,
                )
            )

            if not direct_blocked:
                generated = (
                    self._generate_preview_frame_safe_direct_v11_6(
                        chapter,
                        path,
                    )
                )
                if self._preview_file_valid(generated):
                    if direct_marker:
                        embyflow_clear_negative_cache(
                            direct_marker
                        )
                    return generated

                if direct_marker:
                    embyflow_mark_negative_cache(
                        direct_marker,
                        "safe-direct-failed",
                    )

        # ------------------------------------------------------------------
        # Stage 3 (legacy/admin-only): dangerous server transcode fallback.
        # Still OFF by default. This block is deliberately kept separate so
        # enabling safe V11.6 previews can never implicitly enable it.
        # ------------------------------------------------------------------
        if EMBYFLOW_ALLOW_SERVER_CHAPTER_FRAME_FALLBACK:
            generated = self._generate_preview_frame(
                chapter,
                path,
            )
            if self._preview_file_valid(generated):
                return generated

        # ------------------------------------------------------------------
        # Stage 4: local visual placeholder. No network/server activity.
        # ------------------------------------------------------------------
        return self._preview_v6_make_placeholder(
            chapter
        )

    def _download_preview(
        self,
        chapter,
        path,
        allow_untagged=False,
    ):
        if not requests or not path:
            return ""

        image_tag = str(
            chapter.get("ImageTag")
            or ""
        ).strip()

        if not image_tag and not allow_untagged:
            return ""

        server = str(
            (self.player.playback_info or {}).get("server")
            or ""
        ).rstrip("/")
        token = str(
            (self.player.playback_info or {}).get("token")
            or ""
        )
        item_id = str(
            getattr(
                self.player,
                "item_id",
                "",
            )
            or ""
        )
        if not server or not token or not item_id:
            return ""

        image_index = int(
            chapter.get("_embyflow_image_index")
            or 0
        )

        item_marker = (
            self._preview_v6_native_item_marker()
            if not image_tag
            else ""
        )
        chapter_marker = (
            self._preview_v6_native_chapter_marker(
                path
            )
            if image_tag
            else ""
        )

        if (
            item_marker
            and embyflow_negative_cache_active(
                item_marker,
                EMBYFLOW_CHAPTER_NATIVE_UNTAGGED_NEGATIVE_TTL,
            )
        ):
            return ""

        if (
            chapter_marker
            and embyflow_negative_cache_active(
                chapter_marker,
                EMBYFLOW_CHAPTER_NATIVE_TAGGED_NEGATIVE_TTL,
            )
        ):
            return ""

        url = (
            "%s/Items/%s/Images/Chapter/%d"
            % (
                server,
                item_id,
                image_index,
            )
        )
        headers = {
            "X-Emby-Token": token,
            "X-Emby-Authorization": AUTH_HEADER,
        }
        params = {
            "MaxWidth": "955",
            "MaxHeight": "537",
            "Quality": "86",
            "api_key": token,
        }
        if image_tag:
            params["Tag"] = image_tag

        try:
            response = embyflow_http_get(
                url,
                headers=headers,
                params=params,
                timeout=(
                    EMBYFLOW_CHAPTER_NATIVE_FOREGROUND_TIMEOUT
                    if allow_untagged
                    else 3.0
                ),
                verify=True,
            )
        except Exception as error:
            self._preview_v6_log(
                "native_http_error",
                item=item_id,
                chapter=image_index,
                tagged=int(bool(image_tag)),
                error_type=type(error).__name__,
            )
            return ""

        status = int(
            getattr(
                response,
                "status_code",
                0,
            )
            or 0
        )

        if status != 200:
            # 404/400 is useful capability information. Authentication/server
            # errors must not be cached as "no chapter artwork".
            if status in (400, 404):
                if image_tag and chapter_marker:
                    embyflow_mark_negative_cache(
                        chapter_marker,
                        "native-http-%s" % status,
                    )
                elif item_marker:
                    embyflow_mark_negative_cache(
                        item_marker,
                        "native-untagged-http-%s"
                        % status,
                    )

            self._preview_v6_log(
                "native_miss",
                item=item_id,
                chapter=image_index,
                tagged=int(bool(image_tag)),
                status=status,
            )
            return ""

        content = getattr(
            response,
            "content",
            b"",
        ) or b""
        content_type = str(
            response.headers.get(
                "Content-Type",
                "",
            )
            if hasattr(response, "headers")
            else ""
        )

        if (
            len(content) <= 500
            or (
                content_type
                and not content_type.startswith("image/")
            )
        ):
            self._preview_v6_log(
                "native_invalid",
                item=item_id,
                chapter=image_index,
                tagged=int(bool(image_tag)),
                bytes=len(content),
            )
            return ""

        temporary = path + ".native.v11_6.tmp"
        try:
            with open(
                temporary,
                "wb",
            ) as handle:
                handle.write(content)
                handle.flush()
                try:
                    os.fsync(
                        handle.fileno()
                    )
                except Exception:
                    pass

            self._preview_atomic_replace(
                temporary,
                path,
            )

            if self._preview_file_valid(path):
                if item_marker:
                    embyflow_clear_negative_cache(
                        item_marker
                    )
                if chapter_marker:
                    embyflow_clear_negative_cache(
                        chapter_marker
                    )
                self._preview_v6_log(
                    "native_ok",
                    item=item_id,
                    chapter=image_index,
                    tagged=int(bool(image_tag)),
                    bytes=len(content),
                )
                return path

            return ""
        finally:
            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except Exception:
                pass

    def _preview_v6_source_is_safe(self, source):
        """
        Hard safety gate for client-side frame extraction.
        Only local files or Emby Static=true /Videos/.../stream.* URLs pass.
        """
        value = str(source or "").strip()
        if not value:
            return False

        # Local recordings/files are inherently server-safe.
        try:
            if os.path.isfile(value):
                return True
        except Exception:
            pass

        lower = value.lower()
        if not (
            lower.startswith("http://")
            or lower.startswith("https://")
        ):
            return False

        try:
            from urllib.parse import urlparse, parse_qs

            parsed = urlparse(value)
            query = {
                str(key).lower(): [
                    str(item).lower()
                    for item in values
                ]
                for key, values in parse_qs(
                    parsed.query,
                    keep_blank_values=True,
                ).items()
            }
            path_lower = str(
                parsed.path
                or ""
            ).lower()

            if "/videos/" not in path_lower:
                return False
            if "/stream." not in path_lower:
                return False
            if "static" not in query:
                return False
            if "true" not in query.get(
                "static",
                [],
            ):
                return False

            # Any of these would make the URL inappropriate for the safe path.
            forbidden_query_keys = (
                "starttimeticks",
                "playsessionid",
                "videocodec",
                "audiocodec",
                "enableautostreamcopy",
                "allowvideostreamcopy",
                "transcodingurl",
            )
            for forbidden in forbidden_query_keys:
                if forbidden in query:
                    return False

            if "static" in query and "false" in query["static"]:
                return False

            if (
                "/hls/" in path_lower
                or path_lower.endswith(".m3u8")
                or "master.m3u8" in lower
                or "transcodingurl" in lower
            ):
                return False

            return True
        except Exception:
            return False

    def _preview_v6_safe_direct_source(self):
        # Local file candidate first.
        candidates = []

        try:
            ref = getattr(
                self.player,
                "ref",
                None,
            )
            if ref is not None and hasattr(
                ref,
                "getPath",
            ):
                candidates.append(
                    str(
                        ref.getPath()
                        or ""
                    )
                )
        except Exception:
            pass

        try:
            session = getattr(
                self.player,
                "session",
                None,
            )
            nav = getattr(
                session,
                "nav",
                None,
            )
            if nav is not None:
                ref = nav.getCurrentlyPlayingServiceReference()
                if (
                    ref is not None
                    and hasattr(
                        ref,
                        "getPath",
                    )
                ):
                    candidates.append(
                        str(
                            ref.getPath()
                            or ""
                        )
                    )
        except Exception:
            pass

        for candidate in candidates:
            value = str(
                candidate
                or ""
            ).strip()
            if not value:
                continue
            try:
                from urllib.parse import unquote
                value = unquote(value)
            except Exception:
                pass
            if (
                os.path.isfile(value)
                and self._preview_v6_source_is_safe(
                    value
                )
            ):
                self._preview_v6_log(
                    "safe_source",
                    source_kind="local_file",
                    item=str(
                        getattr(
                            self.player,
                            "item_id",
                            "",
                        )
                        or ""
                    ),
                )
                return value

        # For Emby media deliberately construct a NEW *static/direct* URL.
        # Do not reuse the current playback URL because it may be HLS/transcode.
        server, token = self._preview_auth_context_v3()
        item_id = str(
            getattr(
                self.player,
                "item_id",
                "",
            )
            or ""
        )
        media_source_id = str(
            getattr(
                self.player,
                "media_source_id",
                "",
            )
            or ""
        )

        if not server or not token or not item_id:
            return ""

        try:
            source = build_direct_mkv_stream_url(
                server,
                item_id,
                token,
                media_source_id or None,
                None,
                None,
            )
        except Exception as error:
            self._preview_v6_log(
                "safe_source_builder_error",
                item=item_id,
                error_type=type(error).__name__,
            )
            return ""

        if not self._preview_v6_source_is_safe(
            source
        ):
            self._preview_v6_log(
                "safe_source_rejected",
                item=item_id,
                has_media_source=int(
                    bool(media_source_id)
                ),
            )
            return ""

        self._preview_v6_log(
            "safe_source",
            source_kind="static_direct",
            item=item_id,
            has_media_source=int(
                bool(media_source_id)
            ),
        )
        return str(source)

    def _preview_v6_run_ffmpeg_direct(
        self,
        source,
        temporary,
        chapter,
        seek_seconds,
    ):
        ffmpeg = "/usr/bin/ffmpeg"

        if (
            not source
            or not temporary
            or not os.path.isfile(ffmpeg)
            or not self._preview_v6_source_is_safe(
                source
            )
        ):
            return -1

        try:
            import subprocess

            command = [
                ffmpeg,
                "-nostdin",
                "-hide_banner",
                "-loglevel",
                "error",
                "-noaccurate_seek",
            ]

            if str(source).lower().startswith(
                ("http://", "https://")
            ):
                command.extend(
                    [
                        "-rw_timeout",
                        "12000000",
                    ]
                )

            # Input-side seek: receiver/ffmpeg performs the seek. The Emby URL
            # itself contains NO StartTimeTicks and NO replacement PlaySessionId.
            command.extend(
                [
                    "-ss",
                    "%.3f"
                    % max(
                        0.0,
                        float(
                            seek_seconds
                            or 0.0
                        ),
                    ),
                    "-i",
                    source,
                    "-map",
                    "0:v:0",
                    "-frames:v",
                    "1",
                    "-an",
                    "-sn",
                    "-dn",
                    "-threads",
                    "2",
                    "-vf",
                    (
                        "scale=%s:%s:"
                        "force_original_aspect_ratio=decrease,"
                        "pad=%s:%s:(ow-iw)/2:(oh-ih)/2:black"
                        % (
                            EMBYFLOW_CHAPTER_FAST_PREVIEW_WIDTH,
                            EMBYFLOW_CHAPTER_FAST_PREVIEW_HEIGHT,
                            EMBYFLOW_CHAPTER_FAST_PREVIEW_WIDTH,
                            EMBYFLOW_CHAPTER_FAST_PREVIEW_HEIGHT,
                        )
                    ),
                    "-q:v",
                    "5",
                    "-y",
                    temporary,
                ]
            )

            if os.path.isfile(
                "/usr/bin/nice"
            ):
                command = [
                    "/usr/bin/nice",
                    "-n",
                    "15",
                ] + command

            devnull = open(
                os.devnull,
                "wb",
            )
            try:
                process = subprocess.Popen(
                    command,
                    stdout=devnull,
                    stderr=devnull,
                )
                self._preview_process = process
                try:
                    return_code = process.wait(
                        timeout=max(
                            5,
                            int(
                                EMBYFLOW_CHAPTER_SAFE_DIRECT_TIMEOUT
                            ),
                        )
                    )
                except Exception:
                    try:
                        process.terminate()
                    except Exception:
                        pass
                    try:
                        return_code = process.wait(
                            timeout=0.25
                        )
                    except Exception:
                        try:
                            process.kill()
                        except Exception:
                            pass
                        return_code = -9
            finally:
                self._preview_process = None
                try:
                    devnull.close()
                except Exception:
                    pass

            return int(
                return_code
                or 0
            )
        except Exception as error:
            self._preview_v6_log(
                "safe_ffmpeg_exception",
                item=str(
                    getattr(
                        self.player,
                        "item_id",
                        "",
                    )
                    or ""
                ),
                chapter=str(
                    chapter.get(
                        "_embyflow_image_index"
                    )
                    or 0
                ),
                error_type=type(error).__name__,
            )
            return -1

    def _generate_preview_frame_safe_direct_v11_6(
        self,
        chapter,
        path,
    ):
        if (
            self._closing
            or not path
            or not EMBYFLOW_ALLOW_SAFE_DIRECT_CHAPTER_FRAME_FALLBACK
        ):
            return ""

        if not os.path.isfile(
            "/usr/bin/ffmpeg"
        ):
            self._preview_v6_log(
                "safe_generate_skip",
                reason="ffmpeg_missing",
            )
            return ""

        source = self._preview_v6_safe_direct_source()
        if not source:
            return ""

        try:
            start_ticks = max(
                0,
                int(
                    chapter.get("StartPositionTicks")
                    or 0
                ),
            )
        except Exception:
            start_ticks = 0

        # One fast keyframe attempt only. Keep the probe inside short chapters.
        offset_seconds = float(
            EMBYFLOW_CHAPTER_FAST_PREVIEW_OFFSET_SECONDS
        )
        try:
            current_index = -1
            for index, candidate in enumerate(self.chapters):
                if int(candidate.get("StartPositionTicks") or 0) == start_ticks:
                    current_index = index
                    break
            if current_index >= 0 and current_index + 1 < len(self.chapters):
                next_ticks = int(
                    self.chapters[current_index + 1].get(
                        "StartPositionTicks"
                    )
                    or 0
                )
                room = max(
                    0.0,
                    float(next_ticks - start_ticks)
                    / 10000000.0,
                )
                if room > 0.5:
                    offset_seconds = min(
                        offset_seconds,
                        max(0.25, room * 0.35),
                    )
        except Exception:
            pass

        absolute_seconds = (
            float(start_ticks) / 10000000.0
            + max(0.25, float(offset_seconds))
        )

        temporary = (
            path
            + ".safe_direct_v11_6_1.tmp.jpg"
        )

        try:
            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except Exception:
                pass

            started = time.monotonic()
            return_code = self._preview_v6_run_ffmpeg_direct(
                source,
                temporary,
                chapter,
                absolute_seconds,
            )
            elapsed = max(
                0.0,
                time.monotonic() - started,
            )

            if self._closing:
                return ""

            valid = (
                int(return_code or 0) == 0
                and self._preview_file_valid(temporary)
            )
            if not valid:
                self._preview_v6_log(
                    "fast_direct_failed",
                    item=str(
                        getattr(
                            self.player,
                            "item_id",
                            "",
                        )
                        or ""
                    ),
                    chapter=str(
                        chapter.get(
                            "_embyflow_image_index"
                        )
                        or 0
                    ),
                    seek="%.3f" % absolute_seconds,
                    seconds="%.3f" % elapsed,
                    ffmpeg_rc=str(return_code),
                )
                return ""

            # In FAST mode a black keyframe is still preferable to blocking the
            # UI for another 2–6 seconds. There is deliberately no retry loop.
            self._preview_atomic_replace(
                temporary,
                path,
            )

            if self._preview_file_valid(path):
                self._preview_v6_log(
                    "fast_direct_ok",
                    item=str(
                        getattr(
                            self.player,
                            "item_id",
                            "",
                        )
                        or ""
                    ),
                    chapter=str(
                        chapter.get(
                            "_embyflow_image_index"
                        )
                        or 0
                    ),
                    seek="%.3f" % absolute_seconds,
                    seconds="%.3f" % elapsed,
                )
                return path

            return ""
        finally:
            try:
                if os.path.exists(
                    temporary
                ):
                    os.remove(
                        temporary
                    )
            except Exception:
                pass

    # EMBYFLOW_SAFE_CHAPTER_PREVIEW_V11_6_END

    # EMBYFLOW_CHAPTER_NAV_PREVIEW_V3_SOURCE_CONTEXT
    def _preview_log_v3(self, event, **values):
        try:
            parts = []
            for key in sorted(values):
                value = values.get(key)
                # Keine URLs, Tokens, Passwörter oder API-Keys protokollieren.
                if str(key).lower() in ("url", "token", "password", "api_key", "apikey"):
                    continue
                parts.append("%s=%s" % (str(key), str(value)))
            with embyflow_open_log("/tmp/embyflow_chapter_preview_v3.log", "a") as log:
                log.write(
                    "%s event=%s %s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        str(event or "unknown"),
                        " ".join(parts),
                    )
                )
        except Exception:
            pass

    def _preview_auth_context_v3(self):
        info = getattr(self.player, "playback_info", None) or {}
        server = str(info.get("server") or "").rstrip("/")
        token = str(info.get("token") or "")

        try:
            cache = globals().get("EMBY_AUTH_CACHE") or {}
            if not server:
                server = str(cache.get("server") or "").rstrip("/")
            if not token:
                token = str(cache.get("token") or "")
        except Exception:
            pass

        # Zentrale EmbyFlow-Authentifizierung ist die bevorzugte Rückfallebene.
        if not server or not token:
            try:
                auth_func = globals().get("get_emby_auth")
                if callable(auth_func):
                    auth_server, auth_token, _auth_user = auth_func(False)
                    if not server and auth_server:
                        server = str(auth_server).rstrip("/")
                    if not token and auth_token:
                        token = str(auth_token)
            except Exception:
                pass

        if not server:
            try:
                server = str(globals().get("EMBY_SERVER") or "").rstrip("/")
            except Exception:
                server = ""

        # Konfigurationswerte nur als letzte Rückfallebene lesen.
        if not server:
            try:
                server = str(getattr(config.embyflow.server, "value", "") or "").rstrip("/")
            except Exception:
                pass
        if not token:
            try:
                token = str(getattr(config.embyflow.api_key, "value", "") or "")
            except Exception:
                pass

        return server, token

    def _preview_service_url_v3(self):
        candidates = []

        # 1. URL, die dem Player ursprünglich übergeben wurde.
        try:
            info = getattr(self.player, "playback_info", None) or {}
            candidates.append(("playback_info", str(info.get("url") or "")))
        except Exception:
            pass

        # 2. Vom EmbyFlow-Player gespeicherte Stream-URL.
        try:
            candidates.append(("player_stream", str(getattr(self.player, "stream_url", "") or "")))
        except Exception:
            pass

        # 3. Service-Referenz des Players.
        try:
            ref = getattr(self.player, "ref", None)
            if ref is not None and hasattr(ref, "getPath"):
                candidates.append(("player_ref", str(ref.getPath() or "")))
        except Exception:
            pass

        # 4. Tatsächlich aktuell laufende Service-Referenz von Enigma2.
        try:
            session = getattr(self.player, "session", None)
            nav = getattr(session, "nav", None)
            if nav is not None:
                ref = nav.getCurrentlyPlayingServiceReference()
                if ref is not None and hasattr(ref, "getPath"):
                    candidates.append(("current_ref", str(ref.getPath() or "")))
        except Exception:
            pass

        for kind, candidate in candidates:
            value = str(candidate or "").strip()
            if not value:
                continue
            try:
                from urllib.parse import unquote
                decoded = unquote(value)
                if decoded:
                    value = decoded
            except Exception:
                pass
            lower = value.lower()
            if lower.startswith("http://") or lower.startswith("https://"):
                return value, kind

        return "", ""

    def _preview_source_url(self):
        # Bevor wir einen neuen URL-Pfad konstruieren, verwenden wir exakt die
        # Streamquelle, die Enigma2 bereits erfolgreich abspielt.
        source, kind = self._preview_service_url_v3()
        if source:
            self._preview_source_kind_v3 = kind
            self._preview_log_v3(
                "source_ready",
                source_kind=kind,
                item=str(getattr(self.player, "item_id", "") or ""),
            )
            return source

        server, token = self._preview_auth_context_v3()
        item_id = str(getattr(self.player, "item_id", "") or "")
        media_source_id = str(getattr(self.player, "media_source_id", "") or "")

        if server and token and item_id:
            try:
                source = build_direct_mkv_stream_url(
                    server,
                    item_id,
                    token,
                    media_source_id or None,
                    None,
                    None,
                )
                if source:
                    self._preview_source_kind_v3 = "direct_builder"
                    self._preview_log_v3(
                        "source_ready",
                        source_kind="direct_builder",
                        item=item_id,
                        has_media_source=int(bool(media_source_id)),
                    )
                    return str(source)
            except Exception as error:
                self._preview_log_v3(
                    "source_builder_error",
                    item=item_id,
                    error_type=type(error).__name__,
                )

        self._preview_source_kind_v3 = ""
        self._preview_log_v3(
            "source_missing",
            item=item_id,
            has_server=int(bool(server)),
            has_token=int(bool(token)),
            has_media_source=int(bool(media_source_id)),
        )
        return ""

    def _preview_seek_seconds(self, chapter):
        try:
            start_ticks = max(0, int(chapter.get("StartPositionTicks") or 0))
        except Exception:
            start_ticks = 0
        start_seconds = float(start_ticks) / 10000000.0

        # Nicht genau auf einer Schnitt-/Schwarzblende greifen. Wenn genügend
        # Raum bis zum nächsten Kapitel ist, zwei Sekunden hinein gehen.
        offset = 2.0
        try:
            current_index = -1
            for index, candidate in enumerate(self.chapters):
                if int(candidate.get("StartPositionTicks") or 0) == start_ticks:
                    current_index = index
                    break
            if current_index >= 0 and current_index + 1 < len(self.chapters):
                next_ticks = int(self.chapters[current_index + 1].get("StartPositionTicks") or 0)
                room = max(0.0, (float(next_ticks - start_ticks) / 10000000.0))
                if room > 0.5:
                    offset = min(2.0, max(0.25, room * 0.20))
        except Exception:
            pass
        return max(0.0, start_seconds + offset)

    # EMBYFLOW_CHAPTER_NAV_PREVIEW_V5_SERVER_SEEK
    def _preview_v5_error(self, event, **values):
        """Write only failure diagnostics; filename deliberately passes release log gate."""
        try:
            parts = []
            for key in sorted(values):
                if str(key).lower() in ("url", "token", "password", "api_key", "apikey"):
                    continue
                parts.append("%s=%s" % (str(key), str(values.get(key))))
            with embyflow_open_log("/tmp/embyflow_chapter_preview_error.log", "a") as log:
                log.write(
                    "%s event=%s %s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        str(event or "unknown"),
                        " ".join(parts),
                    )
                )
        except Exception:
            pass

    def _preview_v5_black_frame(self, path):
        """Pure/near-black cuts are retried deeper into the chapter."""
        if not self._preview_file_valid(path):
            return False
        try:
            if Image is None:
                return False
            image = Image.open(path).convert("L")
            try:
                extrema = image.getextrema()
            finally:
                try:
                    image.close()
                except Exception:
                    pass
            if not extrema:
                return False
            return int(extrema[1] or 0) <= 4
        except Exception:
            return False

    def _preview_v5_offsets(self, chapter):
        """Prefer +15s; retry +30/+60s when the first frame is a black cut."""
        try:
            start_ticks = max(0, int(chapter.get("StartPositionTicks") or 0))
        except Exception:
            start_ticks = 0

        room = None
        try:
            current_index = -1
            for index, candidate in enumerate(self.chapters):
                if int(candidate.get("StartPositionTicks") or 0) == start_ticks:
                    current_index = index
                    break
            if current_index >= 0 and current_index + 1 < len(self.chapters):
                next_ticks = int(self.chapters[current_index + 1].get("StartPositionTicks") or 0)
                if next_ticks > start_ticks:
                    room = float(next_ticks - start_ticks) / 10000000.0
            elif current_index >= 0:
                try:
                    item = getattr(self.player, "item", None) or {}
                    runtime = int(item.get("RunTimeTicks") or item.get("runtime_ticks") or 0)
                    if runtime > start_ticks:
                        room = float(runtime - start_ticks) / 10000000.0
                except Exception:
                    pass
        except Exception:
            pass

        offsets = []
        max_offset = None
        if room is not None and room > 0.5:
            # Stay safely inside the selected chapter.
            max_offset = max(0.25, room * 0.45)

        for wanted in (15.0, 30.0, 60.0):
            value = wanted if max_offset is None else min(wanted, max_offset)
            value = max(0.25, float(value))
            if not any(abs(value - existing) < 0.05 for existing in offsets):
                offsets.append(value)

        if not offsets:
            offsets = [2.0]
        return start_ticks, offsets

    def _preview_v5_transcode_url(self, start_ticks):
        server, token = self._preview_auth_context_v3()
        item_id = str(getattr(self.player, "item_id", "") or "")
        media_source_id = str(getattr(self.player, "media_source_id", "") or "")
        if not server or not token or not item_id:
            return ""

        try:
            from urllib.parse import urlencode
            params = [
                ("Static", "false"),
                ("VideoCodec", "h264"),
                ("AudioCodec", "aac"),
                ("MaxWidth", "960"),
                ("MaxHeight", "540"),
                ("VideoBitRate", "2000000"),
                ("AudioBitRate", "128000"),
                ("MaxAudioChannels", "2"),
                ("StartTimeTicks", str(int(start_ticks or 0))),
                ("PlaySessionId", uuid4().hex),
            ]
            if media_source_id:
                params.append(("MediaSourceId", media_source_id))
            params.append(("api_key", token))
            return "%s/Videos/%s/stream.mp4?%s" % (
                str(server).rstrip("/"),
                item_id,
                urlencode(params),
            )
        except Exception as error:
            self._preview_v5_error(
                "transcode_url_error",
                item=item_id,
                error_type=type(error).__name__,
            )
            return ""

    def _preview_v5_run_ffmpeg(self, source, temporary, chapter, offset_seconds):
        ffmpeg = "/usr/bin/ffmpeg"
        if not source or not os.path.isfile(ffmpeg):
            return -1

        try:
            import subprocess
            command = [
                ffmpeg,
                "-nostdin",
                "-hide_banner",
                "-loglevel", "error",
                "-rw_timeout", "20000000",
                "-i", source,
                "-map", "0:v:0",
                "-frames:v", "1",
                "-an", "-sn", "-dn",
                "-vf",
                "scale=954:536:force_original_aspect_ratio=decrease,pad=954:536:(ow-iw)/2:(oh-ih)/2:black",
                "-q:v", "4",
                "-y", temporary,
            ]
            if os.path.isfile("/usr/bin/nice"):
                command = ["/usr/bin/nice", "-n", "15"] + command

            devnull = open(os.devnull, "wb")
            try:
                process = subprocess.Popen(command, stdout=devnull, stderr=devnull)
                self._preview_process = process
                try:
                    return_code = process.wait(timeout=20)
                except Exception:
                    try:
                        process.terminate()
                    except Exception:
                        pass
                    try:
                        return_code = process.wait(timeout=4)
                    except Exception:
                        try:
                            process.kill()
                        except Exception:
                            pass
                        return_code = -9
            finally:
                self._preview_process = None
                try:
                    devnull.close()
                except Exception:
                    pass
            return int(return_code or 0)
        except Exception as error:
            self._preview_v5_error(
                "ffmpeg_exception",
                item=str(getattr(self.player, "item_id", "") or ""),
                chapter=str(chapter.get("_embyflow_image_index") or 0),
                offset="%.3f" % float(offset_seconds or 0.0),
                error_type=type(error).__name__,
            )
            return -1

    def _generate_preview_frame(self, chapter, path):
        # EMBYFLOW_ADMIN_SERVER_SAFETY_V1
        if not EMBYFLOW_ALLOW_SERVER_CHAPTER_FRAME_FALLBACK:
            return ""

        ffmpeg = "/usr/bin/ffmpeg"
        if self._closing or not path:
            return ""
        if not os.path.isfile(ffmpeg):
            self._preview_v5_error("generate_skip", reason="ffmpeg_missing")
            return ""

        try:
            start_ticks, offsets = self._preview_v5_offsets(chapter)
        except Exception as error:
            self._preview_v5_error(
                "offset_error",
                error_type=type(error).__name__,
                item=str(getattr(self.player, "item_id", "") or ""),
            )
            return ""

        temporary = path + ".v5.tmp.jpg"
        try:
            for attempt_index, offset_seconds in enumerate(offsets):
                if self._closing:
                    return ""

                target_ticks = int(start_ticks + (float(offset_seconds) * 10000000.0))
                source = self._preview_v5_transcode_url(target_ticks)
                if not source:
                    self._preview_v5_error(
                        "source_missing",
                        item=str(getattr(self.player, "item_id", "") or ""),
                        chapter=str(chapter.get("_embyflow_image_index") or 0),
                    )
                    return ""

                try:
                    if os.path.exists(temporary):
                        os.remove(temporary)
                except Exception:
                    pass

                return_code = self._preview_v5_run_ffmpeg(
                    source,
                    temporary,
                    chapter,
                    offset_seconds,
                )

                if self._closing:
                    return ""

                valid = int(return_code or 0) == 0 and self._preview_file_valid(temporary)
                if not valid:
                    self._preview_v5_error(
                        "ffmpeg_failed",
                        item=str(getattr(self.player, "item_id", "") or ""),
                        chapter=str(chapter.get("_embyflow_image_index") or 0),
                        offset="%.3f" % float(offset_seconds),
                        ffmpeg_rc=str(return_code),
                    )
                    continue

                if self._preview_v5_black_frame(temporary):
                    # Retry deeper into the chapter. If every candidate is black,
                    # keep the final valid frame rather than reporting a failure.
                    if attempt_index + 1 < len(offsets):
                        continue

                self._preview_atomic_replace(temporary, path)
                return path if self._preview_file_valid(path) else ""

        finally:
            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except Exception:
                pass

        return ""

    def _preview_atomic_replace(self, source, destination):
        try:
            os.replace(source, destination)
        except AttributeError:
            try:
                if os.path.exists(destination):
                    os.remove(destination)
            except Exception:
                pass
            os.rename(source, destination)

    def _show_preview_path(self, index, path):
        if index != self.selected or self._closing:
            return
        self["preview_status"].setText("")
        token = "chapter-preview-%s-%s" % (str(getattr(self.player, "item_id", "")), index)
        ok = embyflow_decode_image_to_widget(
            self,
            "preview_image",
            path,
            995,
            560,
            token=token,
            is_current=lambda: (not self._closing and index == self.selected),
        )
        if not ok:
            self["preview_status"].setText("Vorschaubild konnte nicht dargestellt werden.")
        else:
            self._refresh_filmstrip_v16_4(path)



