def _embyflow_neon_panel_edges(x, y, w, h, color):
    return (
        '<eLabel position="%d,%d" size="%d,2" backgroundColor="%s" />'
        '<eLabel position="%d,%d" size="%d,2" backgroundColor="%s" />'
        '<eLabel position="%d,%d" size="2,%d" backgroundColor="%s" />'
        '<eLabel position="%d,%d" size="2,%d" backgroundColor="%s" />'
    ) % (
        x, y, w, color,
        x, y + h - 2, w, color,
        x, y, h, color,
        x + w - 2, y, h, color,
    )


