class EmbyFlowConnectionWizard(Screen):
    skin = scale_skin(_embyflow_neon_login_skin())

    WEEKDAYS_DE = (
        "Montag", "Dienstag", "Mittwoch", "Donnerstag",
        "Freitag", "Samstag", "Sonntag"
    )

    SERVER_CARD_POSITIONS = (
        (322, 174),
        (646, 174),
        (970, 174),
        (1294, 174),
    )

    def __init__(self, session, first_run=False):
        Screen.__init__(self, session)
        self.first_run = bool(first_run)
        self.focus = 0
        self.selected_server_index = 0
        self.connection_ok = False
        self.save_password_enabled = True
        self.server_name = ""
        self._closing = False
        self.server_runtime_states = {}

        self.server = self._cfg(config.embyflow.server).rstrip("/")
        self.username = self._cfg(config.embyflow.username)
        self.password = self._cfg(config.embyflow.password)
        self.server_slots = self._load_server_slots()
        self.selected_server_index = self._find_active_slot()
        self._apply_selected_slot(clear_password=False)

        self["clock_day"] = Label("")
        self["clock_date"] = Label("")
        self["clock_time"] = Label("")
        self["server_focus_border"] = Label(" ")
        self["server_focus_inner"] = Label(" ")
        for i in range(4):
            self["server_icon%d" % i] = Label("▤")
            self["server_name%d" % i] = Label("SERVER %d" % (i + 1))
            self["server_brand%d" % i] = Label("")
            self["server_state%d" % i] = Label("")
        self["server_selected"] = Label("")
        self["server_status"] = Label("")
        self["username_value"] = Label("")
        self["username_hint"] = Label("")
        self["middle_server"] = Label("")
        self["password_hint"] = Label("")
        self["selected_user"] = Label("")
        self["selected_server"] = Label("")
        self["password_value"] = Label("")
        self["save_password"] = Label("")
        self["login_button"] = Label("")
        self["login_status"] = Label("")
        self["secure_text"] = Label("")
        self["focus_marker"] = Label("›")

        self["actions"] = ActionMap(
            ["OkCancelActions", "DirectionActions", "ColorActions"],
            {
                "cancel": self.close_wizard,
                "red": self.close_wizard,
                "green": self.next_step,
                "yellow": self.open_advanced_settings,
                "blue": self.show_help,
                "ok": self.activate,
                "left": self.move_left,
                "right": self.move_right,
                "up": self.move_up,
                "down": self.move_down,
            },
            -1,
        )

        self._clock_timer = eTimer()
        self._bind_timer(self._clock_timer, self.update_clock)
        self.onLayoutFinish.append(self._layout_ready)
        try:
            self.onClose.append(self._stop_timers)
        except Exception:
            pass

    def _cfg(self, item):
        try:
            return str(item.value or "").strip()
        except Exception:
            try:
                return str(item.getValue() or "").strip()
            except Exception:
                return ""

    def _set_cfg(self, item, value):
        try:
            item.setValue(str(value or ""))
        except Exception:
            try:
                item.value = str(value or "")
            except Exception:
                pass

    def _slot_cfg(self, index):
        return getattr(config.embyflow, "server_slot_%d" % (int(index) + 1))

    def _load_server_slots(self):
        slots = []
        for index in range(4):
            try:
                value = self._cfg(self._slot_cfg(index)).rstrip("/")
            except Exception:
                value = ""
            slots.append(value)
        # Bestehende Installation nicht verlieren: aktiven Legacy-Server in Slot 1 übernehmen,
        # falls der Slot leer ist.
        active = self._cfg(config.embyflow.server).rstrip("/")
        if active and not slots[0]:
            slots[0] = active
        return slots

    def _find_active_slot(self):
        active = str(self.server or "").rstrip("/").casefold()
        if active:
            for index, value in enumerate(self.server_slots):
                if str(value or "").rstrip("/").casefold() == active:
                    return index
        for index, value in enumerate(self.server_slots):
            if value:
                return index
        return 0

    def _apply_selected_slot(self, clear_password=True):
        index = max(0, min(3, int(self.selected_server_index)))
        self.selected_server_index = index
        self.server = str(self.server_slots[index] or "").strip().rstrip("/")
        self.protocol, self.port = self._server_parts()
        self.connection_ok = bool(self.server_runtime_states.get(index) == "online")
        self.server_name = self._server_display_name(index)
        if clear_password:
            self.password = ""

    def _save_slot(self, index, value):
        index = max(0, min(3, int(index)))
        normalized = str(value or "").strip().rstrip("/")
        if normalized and not normalized.lower().startswith(("http://", "https://")):
            normalized = "https://" + normalized
        self.server_slots[index] = normalized
        cfg = self._slot_cfg(index)
        self._set_cfg(cfg, normalized)
        try:
            cfg.save()
            configfile.save()
        except Exception:
            pass
        return normalized

    def _bind_timer(self, timer, callback):
        try:
            timer.callback.append(callback)
            return
        except Exception:
            pass
        try:
            timer.timeout.connect(callback)
        except Exception:
            pass

    def _stop_timers(self):
        try:
            self._clock_timer.stop()
        except Exception:
            pass

    def _layout_ready(self):
        self.update_clock()
        try:
            self._clock_timer.start(30000, False)
        except Exception:
            pass
        # Kein automatischer Serverkontakt beim Öffnen des Assistenten.
        self.refresh_all()

    def update_clock(self):
        try:
            now = datetime.now()
            self["clock_day"].setText(self.WEEKDAYS_DE[now.weekday()])
            self["clock_date"].setText(now.strftime("%d.%m.%Y"))
            self["clock_time"].setText(now.strftime("%H:%M"))
        except Exception:
            pass

    def _server_parts(self):
        raw = str(self.server or "").strip()
        low = raw.lower()
        protocol = "HTTPS" if low.startswith("https://") else "HTTP"
        default_port = "443" if protocol == "HTTPS" else "8096"
        authority = raw.split("://", 1)[-1].split("/", 1)[0]
        port = default_port
        if authority.count(":") == 1:
            maybe = authority.rsplit(":", 1)[-1]
            if maybe.isdigit():
                port = maybe
        return protocol, port

    def _server_display_name(self, index):
        try:
            value = str(self.server_slots[int(index)] or "").strip().lower()
        except Exception:
            value = ""
        if value:
            return "Emby Server"
        return ""

    def _selected_server_label(self):
        return "Server %d" % (int(self.selected_server_index) + 1)

    def _candidate_urls(self, suffix):
        base = str(self.server or "").rstrip("/")
        urls = [base + suffix]
        if not base.lower().endswith("/emby"):
            urls.append(base + "/emby" + suffix)
        return urls

    def _get_json(self, suffix):
        last_error = None
        for url in self._candidate_urls(suffix):
            try:
                response = requests.get(
                    url,
                    headers={"X-Emby-Authorization": AUTH_HEADER},
                    timeout=8,
                    verify=True,
                )
                if int(getattr(response, "status_code", 0)) == 200:
                    return response.json(), url
                last_error = "HTTP %s" % getattr(response, "status_code", "?")
            except Exception as error:
                last_error = str(error)
        raise RuntimeError(last_error or "Keine Antwort vom Server")

    def refresh_all(self):
        self._refresh_server_cards()

        username_text = self.username or "Benutzername eingeben"
        self["username_value"].setText(
            "> %s <" % username_text if self.focus == 4 else username_text
        )
        self["username_hint"].setText(
            "OK öffnet die EmbyFlow-Tastatur.\nDer Benutzername wird erst beim Anmelden an den gewählten Server gesendet."
        )
        display_brand = self._server_display_name(self.selected_server_index)
        self["middle_server"].setText(
            "%s%s%s" % (
                display_brand or self._selected_server_label(),
                " · " + self._selected_server_label() if display_brand else "",
                " · Verbindung OK" if self.connection_ok else "",
            )
        )

        chosen_name = str(self.username or "-")
        self["selected_user"].setText(chosen_name)
        self["selected_server"].setText(self._selected_server_label())
        self["password_hint"].setText(
            "Gib das Passwort für „%s“ ein." % chosen_name
            if chosen_name != "-"
            else "Gib zuerst deinen Benutzernamen ein."
        )
        password_text = "•" * len(self.password) if self.password else "Passwort eingeben"
        self["password_value"].setText(
            "> %s <" % password_text if self.focus == 5 else password_text
        )
        self["save_password"].setText(
            ("> " if self.focus == 6 else "")
            + ("[X] Passwort speichern" if self.save_password_enabled else "[ ] Passwort speichern")
            + (" <" if self.focus == 6 else "")
        )
        self["login_button"].setText(
            "> ANMELDEN <" if self.focus == 7 else "ANMELDEN"
        )
        self["secure_text"].setText(
            "Deine Daten werden verschlüsselt übertragen."
            if str(self.protocol).upper() == "HTTPS"
            else "HTTP aktiv – für externen Zugriff wird HTTPS empfohlen."
        )
        self._refresh_focus_marker()

    def _refresh_server_cards(self):
        for index in range(4):
            configured = bool(str(self.server_slots[index] or "").strip())
            state = self.server_runtime_states.get(index)
            if state == "online":
                text = "● Online"
            elif state == "error":
                text = "● Nicht erreichbar"
            elif configured:
                text = "● Bereit"
            else:
                text = "○ Nicht eingerichtet"
            if index == self.selected_server_index and configured:
                if state == "online":
                    text = "✓ Ausgewählt · Online"
                elif state == "error":
                    text = "✓ Ausgewählt · Fehler"
                else:
                    text = "✓ Ausgewählt · Bereit"
            self["server_state%d" % index].setText(text)
            self["server_name%d" % index].setText("SERVER %d" % (index + 1))
            self["server_brand%d" % index].setText(self._server_display_name(index))
            self["server_icon%d" % index].setText("✓" if index == self.selected_server_index and configured else "▤")

        selected = self._selected_server_label()
        brand = self._server_display_name(self.selected_server_index)
        self["server_selected"].setText(
            "%s ausgewählt%s" % (selected, " · " + brand if brand else "")
        )
        if not self.server:
            self["server_status"].setText("Nicht eingerichtet · OK zum Einrichten")
        elif self.connection_ok:
            label = self.server_name or brand or selected
            self["server_status"].setText("● Verbindung OK · %s" % label)
        else:
            self["server_status"].setText("● Bereit · GRÜN prüft die Verbindung")

        try:
            card_index = self.focus if self.focus in (0, 1, 2, 3) else self.selected_server_index
            x, y = self.SERVER_CARD_POSITIONS[card_index]
            self["server_focus_border"].instance.move(EFP(x, y))
            self["server_focus_border"].instance.resize(EFS(308, 198))
            self["server_focus_inner"].instance.move(EFP(x + 4, y + 4))
            self["server_focus_inner"].instance.resize(EFS(300, 190))
            self["server_focus_border"].show()
            self["server_focus_inner"].show()
        except Exception:
            pass

    def _focus_target(self):
        if self.focus == 4:
            return (525, 557)
        if self.focus == 5:
            return (525, 657)
        if self.focus == 6:
            return (535, 718)
        return (525, 763)

    def _refresh_focus_marker(self):
        try:
            if self.focus < 4:
                self["focus_marker"].hide()
                return
            x, y = self._focus_target()
            self["focus_marker"].instance.move(EFP(x, y))
            self["focus_marker"].instance.resize(EFS(28, 38))
            self["focus_marker"].show()
        except Exception:
            pass

    def _select_server(self, index):
        index = max(0, min(3, int(index)))
        if not str(self.server_slots[index] or "").strip():
            self.edit_server_slot(index)
            return False
        self.selected_server_index = index
        self.focus = index
        self._apply_selected_slot(clear_password=True)
        self["login_status"].setText("")
        self.refresh_all()
        return True

    def edit_server_slot(self, index=None):
        if index is None:
            index = self.selected_server_index
        index = max(0, min(3, int(index)))
        current = str(self.server_slots[index] or "")
        try:
            self.session.openWithCallback(
                lambda value, slot=index: self._server_slot_input_done(slot, value),
                EmbyFlowTextInputScreenV19,
                "Server %d Adresse" % (index + 1),
                current,
                False,
            )
        except Exception as error:
            self["server_status"].setText("Server-Eingabe fehlgeschlagen: %s" % str(error))

    def _server_slot_input_done(self, index, value):
        if value is None:
            return
        normalized = self._save_slot(index, value)
        self.selected_server_index = index
        self._apply_selected_slot(clear_password=True)
        self.server_runtime_states.pop(index, None)
        self["server_status"].setText(
            "Server %d gespeichert." % (index + 1) if normalized else "Server %d ist leer." % (index + 1)
        )
        self.refresh_all()

    def move_left(self):
        if self.focus in (1, 2, 3):
            self.focus -= 1
        self.refresh_all()

    def move_right(self):
        if self.focus in (0, 1, 2):
            self.focus += 1
        self.refresh_all()

    def move_up(self):
        if self.focus == 4:
            self.focus = self.selected_server_index
        elif self.focus == 5:
            self.focus = 4
        elif self.focus == 6:
            self.focus = 5
        elif self.focus == 7:
            self.focus = 6
        self.refresh_all()

    def move_down(self):
        if self.focus in (0, 1, 2, 3):
            self.focus = 4
        elif self.focus == 4:
            self.focus = 5
        elif self.focus == 5:
            self.focus = 6
        elif self.focus == 6:
            self.focus = 7
        self.refresh_all()

    def activate(self):
        if self.focus in (0, 1, 2, 3):
            self._select_server(self.focus)
        elif self.focus == 4:
            self.edit_username()
        elif self.focus == 5:
            self.edit_password()
        elif self.focus == 6:
            self.save_password_enabled = not self.save_password_enabled
            self.refresh_all()
        elif self.focus == 7:
            self.login()

    def next_step(self):
        if self.focus in (0, 1, 2, 3):
            if not self._select_server(self.focus):
                return
            if not self.connection_ok:
                if not self.test_connection():
                    return
            self.focus = 4
        elif self.focus == 4:
            if not self.username:
                self.edit_username()
                return
            self.focus = 5
        else:
            self.login()
        self.refresh_all()

    def test_connection(self, automatic=False):
        if not requests:
            self["server_status"].setText("Python-Modul requests fehlt.")
            return False
        if not self.server:
            self["server_status"].setText("Server ist nicht eingerichtet. OK zum Einrichten.")
            self.focus = self.selected_server_index
            self.refresh_all()
            return False

        self["server_status"].setText("Verbindung wird geprüft …")
        self["login_status"].setText("")
        try:
            info, unused_url = self._get_json("/System/Info/Public")
            self.server_name = str((info or {}).get("ServerName") or self._selected_server_label())
            self.connection_ok = True
            self.server_runtime_states[self.selected_server_index] = "online"
            self["server_status"].setText(
                "● Verbindung OK · %s" % self.server_name
            )
            if not automatic:
                self.focus = 4
            self.refresh_all()
            return True
        except Exception as error:
            self.connection_ok = False
            self.server_runtime_states[self.selected_server_index] = "error"
            self["server_status"].setText("Verbindung fehlgeschlagen.\n%s" % str(error))
            self.refresh_all()
            return False

    def edit_username(self):
        try:
            self.session.openWithCallback(
                self._username_input_done,
                EmbyFlowLoginTextInputScreenV21,
                "Emby Benutzername",
                self.username,
                False,
                self._selected_server_label(),
            )
        except Exception as error:
            self["login_status"].setText("Benutzereingabe fehlgeschlagen: %s" % str(error))

    def _username_input_done(self, value):
        if value is None:
            return
        self.username = str(value or "").strip()
        self.password = ""
        self.focus = 5
        self.refresh_all()

    def edit_password(self):
        if not self.username:
            self["login_status"].setText("Bitte zuerst einen Benutzernamen eingeben.")
            self.focus = 4
            self.refresh_all()
            return
        try:
            self.session.openWithCallback(
                self._password_input_done,
                EmbyFlowLoginTextInputScreenV21,
                "Emby Passwort",
                self.password,
                True,
                self._selected_server_label(),
            )
        except Exception as error:
            self["login_status"].setText("Passworteingabe fehlgeschlagen: %s" % str(error))

    def _password_input_done(self, value):
        if value is None:
            return
        self.password = str(value or "")
        self.focus = 7
        self.refresh_all()

    def login(self):
        if not requests:
            self["login_status"].setText("Login nicht möglich: requests fehlt.")
            return
        self.server = str(self.server or "").strip().rstrip("/")
        self.username = str(self.username or "").strip()
        if not self.server or not self.username:
            self["login_status"].setText("Server und Benutzername fehlen.")
            return
        self["login_status"].setText("Anmeldung läuft …")
        try:
            last_error = None
            data = None
            for url in self._candidate_urls("/Users/AuthenticateByName"):
                try:
                    response = requests.post(
                        url,
                        headers={"X-Emby-Authorization": AUTH_HEADER},
                        json={"Username": self.username, "Pw": self.password},
                        timeout=10,
                        verify=True,
                    )
                    if int(getattr(response, "status_code", 0)) == 200:
                        data = response.json() or {}
                        break
                    last_error = "HTTP %s" % getattr(response, "status_code", "?")
                except Exception as error:
                    last_error = str(error)
            if not data:
                raise RuntimeError(last_error or "Keine Login-Antwort")
            token = data.get("AccessToken")
            user = data.get("User") or {}
            user_id = user.get("Id")
            if not token or not user_id:
                raise RuntimeError("Login-Antwort enthält kein Token oder keine User-ID")

            # Aktiven Server erst nach erfolgreichem Login umschalten.
            self._set_cfg(config.embyflow.server, self.server)
            self._set_cfg(config.embyflow.username, self.username)
            self._set_cfg(config.embyflow.password, self.password if self.save_password_enabled else "")
            config.embyflow.server.save()
            config.embyflow.username.save()
            config.embyflow.password.save()
            configfile.save()

            apply_emby_runtime_config()
            clear_emby_auth_cache()
            EMBY_AUTH_CACHE["server"] = self.server
            EMBY_AUTH_CACHE["token"] = token
            EMBY_AUTH_CACHE["user_id"] = user_id
            EMBY_AUTH_CACHE["ts"] = int(time.time())

            name = str(user.get("Name") or self.username)
            self["login_status"].setText("[OK] Angemeldet als %s" % name)
            self._closing = True
            try:
                self.session.openWithCallback(
                    lambda *args: self.close(True),
                    MessageBox,
                    "Login erfolgreich\n\nWillkommen %s" % name,
                    MessageBox.TYPE_INFO,
                    timeout=3,
                )
            except Exception:
                self.close(True)
        except Exception as error:
            self["login_status"].setText("Login fehlgeschlagen: %s" % str(error))

    def open_advanced_settings(self):
        self.session.openWithCallback(
            self._advanced_closed,
            EmbyFlowAdvancedSettingsNeon,
        )

    def _advanced_closed(self, result=None):
        self.server = self._cfg(config.embyflow.server).rstrip("/")
        self.username = self._cfg(config.embyflow.username)
        self.password = self._cfg(config.embyflow.password)
        self.server_slots = self._load_server_slots()
        self.selected_server_index = self._find_active_slot()
        self._apply_selected_slot(clear_password=False)
        if result == "logout":
            self["server_status"].setText("Ausgeloggt – Server bleibt gespeichert.")
            self["login_status"].setText("Bitte erneut anmelden.")
        elif result == "saved":
            self["server_status"].setText("Erweiterte Einstellungen gespeichert.")
        else:
            self["server_status"].setText("Zur Verbindung zurückgekehrt.")
        self.refresh_all()

    def show_help(self):
        text = (
            "EmbyFlow Verbindung einrichten\n\n"
            "Links: Server 1 bis Server 4 auswählen.\n"
            "OK wählt einen Server. Ist der Slot leer, öffnet OK die Server-Adresse.\n"
            "GRÜN prüft nur den ausgewählten Server und geht anschließend weiter.\n"
            "Es werden beim Öffnen des Assistenten keine Server automatisch abgefragt.\n\n"
            "Mitte: Benutzername manuell eingeben.\n"
            "Rechts: Passwort, Speichern und Anmelden.\n\n"
            "ROT  Zurück\nGRÜN  Weiter\nGELB  Erweiterte Einstellungen\nBLAU  Hilfe"
        )
        self.session.open(MessageBox, text, MessageBox.TYPE_INFO, timeout=12)

    def close_wizard(self):
        if self._closing:
            return
        self.close(False if self.first_run else None)

