class EmbyFlowAdvancedSettingsNeon(Screen):
    skin = scale_skin(_embyflow_neon_advanced_skin())

    def __init__(self, session):
        Screen.__init__(self, session)
        self.focus = 0
        self.cache_enabled = bool(getattr(config.embyflow.cache_enabled, "value", True))
        self.sync_mode = str(getattr(config.embyflow.sync_mode, "value", "startup") or "startup")
        self.adaptive_osd = bool(getattr(getattr(config.embyflow, "adaptive_osd", None), "value", False))
        self.debug_enabled = bool(getattr(config.embyflow.debug, "value", False))
        self.api_key = str(getattr(config.embyflow.api_key, "value", "") or "")
        self.server = str(getattr(config.embyflow.server, "value", "") or "").strip()
        self.username = str(getattr(config.embyflow.username, "value", "") or "").strip()
        self._clock_timer = eTimer()
        self._closing = False

        self["clock_day"] = Label("")
        self["clock_date"] = Label("")
        self["clock_time"] = Label("")
        self["cache_value"] = Label("")
        self["sync_value"] = Label("")
        self["left_help"] = Label("")
        self["adaptive_value"] = Label("")
        self["debug_value"] = Label("")
        self["api_value"] = Label("")
        self["middle_help"] = Label("")
        self["account_server"] = Label("")
        self["account_user"] = Label("")
        self["logout_button"] = Label("")
        self["account_status"] = Label("")
        self["focus_marker"] = Label("›")

        self["actions"] = ActionMap(
            ["OkCancelActions", "DirectionActions", "ColorActions"],
            {
                "cancel": self.close_without_save,
                "red": self.close_without_save,
                "green": self.save_settings,
                "yellow": self.back_to_connection,
                "blue": self.show_help,
                "ok": self.activate,
                "up": self.move_up,
                "down": self.move_down,
                "left": self.move_left,
                "right": self.move_right,
            },
            -1,
        )

        try:
            self._clock_timer.callback.append(self.update_clock)
        except Exception:
            try:
                self._clock_timer.timeout.connect(self.update_clock)
            except Exception:
                pass
        self.onLayoutFinish.append(self._layout_ready)
        try:
            self.onClose.append(self._stop_timer)
        except Exception:
            pass

    def _layout_ready(self):
        self.update_clock()
        try:
            self._clock_timer.start(1000, False)
        except Exception:
            pass
        self.refresh_all()

    def _stop_timer(self):
        try:
            self._clock_timer.stop()
        except Exception:
            pass

    def update_clock(self):
        try:
            now = time.localtime()
            days = ("Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag", "Sonntag")
            self["clock_day"].setText(days[now.tm_wday])
            self["clock_date"].setText(time.strftime("%d.%m.%Y", now))
            self["clock_time"].setText(time.strftime("%H:%M", now))
        except Exception:
            pass

    def _onoff(self, value):
        return "AN" if bool(value) else "AUS"

    def _sync_label(self):
        if self.sync_mode == "daily":
            return "Täglich um 06:00 Uhr"
        return "Bei jedem Pluginstart (empfohlen)"

    def _api_label(self):
        if not self.api_key:
            return "Nicht gesetzt · OK zum Bearbeiten"
        return "•••••••••••• · gesetzt · OK zum Bearbeiten"

    def refresh_all(self):
        self["cache_value"].setText(("> " if self.focus == 0 else "") + self._onoff(self.cache_enabled) + (" <" if self.focus == 0 else ""))
        self["sync_value"].setText(("> " if self.focus == 1 else "") + self._sync_label() + (" <" if self.focus == 1 else ""))
        self["adaptive_value"].setText(("> " if self.focus == 2 else "") + self._onoff(self.adaptive_osd) + (" <" if self.focus == 2 else ""))
        self["debug_value"].setText(("> " if self.focus == 3 else "") + self._onoff(self.debug_enabled) + (" <" if self.focus == 3 else ""))
        self["api_value"].setText(("> " if self.focus == 4 else "") + self._api_label() + (" <" if self.focus == 4 else ""))
        self["logout_button"].setText("> AUSLOGGEN <" if self.focus == 5 else "AUSLOGGEN")
        self["account_server"].setText(self.server or "Kein Server gespeichert")
        self["account_user"].setText(self.username or "Nicht angemeldet")

        if self.focus == 0:
            self["left_help"].setText("Posterbilder lokal puffern. LINKS/RECHTS oder OK schaltet die Option um.")
        elif self.focus == 1:
            self["left_help"].setText("Zeitpunkt der Bibliothekssynchronisation. LINKS/RECHTS oder OK wechselt den Modus.")
        else:
            self["left_help"].setText("Cache und Synchronisation beeinflussen nur Medien-/Bilddaten, nicht Player oder Untertitel.")

        if self.focus == 2:
            self["middle_help"].setText("Adaptive OSD-Helligkeit ist eine Beta-Option. LINKS/RECHTS oder OK schaltet sie um.")
        elif self.focus == 3:
            self["middle_help"].setText("Debug-Log nur bei Fehlersuche aktivieren. LINKS/RECHTS oder OK schaltet es um.")
        elif self.focus == 4:
            self["middle_help"].setText("OK öffnet die eigene EmbyFlow-Tastatur. Der API-Key wird hier nicht im Klartext angezeigt.")
        else:
            self["middle_help"].setText("Erweiterte Optionen im gleichen EmbyFlow-Design – ohne native OpenATV-Einstellungsseite.")

        self._refresh_focus_marker()

    def _focus_target(self):
        targets = (
            (48, 415),
            (48, 566),
            (688, 393),
            (688, 528),
            (688, 665),
            (1328, 655),
        )
        return targets[max(0, min(len(targets) - 1, int(self.focus)))]

    def _refresh_focus_marker(self):
        try:
            x, y = self._focus_target()
            self["focus_marker"].instance.move(EFP(x, y))
            self["focus_marker"].instance.resize(EFS(28, 38))
            self["focus_marker"].show()
        except Exception:
            pass

    def move_up(self):
        self.focus = (self.focus - 1) % 6
        self.refresh_all()

    def move_down(self):
        self.focus = (self.focus + 1) % 6
        self.refresh_all()

    def move_left(self):
        if self.focus in (0, 2, 3):
            self._toggle_current()
        elif self.focus == 1:
            self.sync_mode = "startup" if self.sync_mode == "daily" else "daily"
            self.refresh_all()
        elif self.focus > 1:
            self.focus -= 1
            self.refresh_all()

    def move_right(self):
        if self.focus in (0, 2, 3):
            self._toggle_current()
        elif self.focus == 1:
            self.sync_mode = "daily" if self.sync_mode == "startup" else "startup"
            self.refresh_all()
        elif self.focus < 5:
            self.focus += 1
            self.refresh_all()

    def _toggle_current(self):
        if self.focus == 0:
            self.cache_enabled = not self.cache_enabled
        elif self.focus == 2:
            self.adaptive_osd = not self.adaptive_osd
        elif self.focus == 3:
            self.debug_enabled = not self.debug_enabled
        self.refresh_all()

    def activate(self):
        if self.focus in (0, 2, 3):
            self._toggle_current()
        elif self.focus == 1:
            self.sync_mode = "daily" if self.sync_mode == "startup" else "startup"
            self.refresh_all()
        elif self.focus == 4:
            self.edit_api_key()
        elif self.focus == 5:
            self.request_logout()

    def edit_api_key(self):
        try:
            self.session.openWithCallback(
                self._api_key_done,
                EmbyFlowTextInputScreenV19,
                "Emby API Key",
                self.api_key,
                True,
            )
        except Exception as e:
            self["account_status"].setText("API-Key-Eingabe fehlgeschlagen: %s" % str(e))

    def _api_key_done(self, value):
        if value is None:
            return
        self.api_key = str(value or "")
        self["account_status"].setText("API-Key geändert · mit Grün speichern.")
        self.refresh_all()

    def _set_value(self, item, value):
        try:
            item.setValue(value)
        except Exception:
            try:
                item.value = value
            except Exception:
                pass

    def save_settings(self, close_after=False):
        try:
            self._set_value(config.embyflow.cache_enabled, bool(self.cache_enabled))
            self._set_value(config.embyflow.sync_mode, str(self.sync_mode))
            if hasattr(config.embyflow, "adaptive_osd"):
                self._set_value(config.embyflow.adaptive_osd, bool(self.adaptive_osd))
            self._set_value(config.embyflow.debug, bool(self.debug_enabled))
            self._set_value(config.embyflow.api_key, str(self.api_key))

            items = [config.embyflow.cache_enabled, config.embyflow.sync_mode, config.embyflow.debug, config.embyflow.api_key]
            if hasattr(config.embyflow, "adaptive_osd"):
                items.append(config.embyflow.adaptive_osd)
            for item in items:
                try:
                    item.save()
                except Exception:
                    pass
            configfile.save()
            apply_emby_runtime_config()
            clear_emby_auth_cache()
            self["account_status"].setText("[OK] Erweiterte Einstellungen gespeichert.")
            if close_after:
                self.close("saved")
        except Exception as e:
            self["account_status"].setText("Speichern fehlgeschlagen: %s" % str(e))

    def request_logout(self):
        if not self.username and not EMBY_AUTH_CACHE.get("token"):
            self["account_status"].setText("Es ist aktuell kein Benutzer angemeldet.")
            return
        try:
            self.session.openWithCallback(
                self._logout_confirmed,
                MessageBox,
                "EmbyFlow Benutzer wirklich ausloggen?\n\nDer Server bleibt gespeichert.",
                MessageBox.TYPE_YESNO,
            )
        except Exception:
            self._logout_confirmed(True)

    def _logout_confirmed(self, answer):
        if not answer:
            return
        try:
            clear_emby_auth_cache()
            for item in (config.embyflow.username, config.embyflow.password, config.embyflow.api_key):
                self._set_value(item, "")
                try:
                    item.save()
                except Exception:
                    pass
            configfile.save()
            apply_emby_runtime_config()
            self.username = ""
            self.api_key = ""
            self["account_status"].setText("[OK] Ausgeloggt · Server bleibt gespeichert.")
            self.close("logout")
        except Exception as e:
            self["account_status"].setText("Ausloggen fehlgeschlagen: %s" % str(e))

    def back_to_connection(self):
        self.close("connection")

    def close_without_save(self):
        self.close(None)

    def show_help(self):
        text = (
            "EmbyFlow · Erweiterte Einstellungen\n\n"
            "HOCH/RUNTER  Option auswählen\n"
            "LINKS/RECHTS  Schalter oder Auswahl ändern\n"
            "OK  Schalten / API-Key bearbeiten / Ausloggen\n\n"
            "ROT  Zurück ohne Speichern\n"
            "GRÜN  Speichern\n"
            "GELB  Zur Verbindung zurück\n"
            "BLAU  Hilfe\n\n"
            "Server, Benutzer und Passwort werden ausschließlich im Neon-Verbindungsassistenten verwaltet."
        )
        self.session.open(MessageBox, text, MessageBox.TYPE_INFO, timeout=10)


# EMBYFLOW_NEON_LOGIN_WIZARD_V4_END





def main(session, **kwargs):
    # Keymap muss vor Erzeugung der ActionMap registriert sein.
    load_embyflow_remote_keymap()

    server, username, password = apply_emby_runtime_config()

    if not server or not username:
        def first_login_closed(result=None):
            runtime_server, runtime_username, runtime_password = (
                apply_emby_runtime_config()
            )

            if result is True and runtime_server and runtime_username:
                session.open(EmbyFlowE2Screen)

        session.openWithCallback(
            first_login_closed,
            EmbyFlowConnectionWizard,
            True
        )
        return

    session.open(EmbyFlowE2Screen)


