_EMBYFLOW_SRT_V2_ORIGINAL_INIT = EmbyFlowMoviePlayer.__init__


def _embyflow_srt_v2_connect_timer(owner, timer, callback, connection_name):
    try:
        timer.callback.append(callback)
        return True
    except Exception:
        try:
            connection = timer.timeout.connect(callback)
            setattr(owner, connection_name, connection)
            return True
        except Exception:
            return False


def _embyflow_srt_v2_init(self, *args, **kwargs):
    _EMBYFLOW_SRT_V2_ORIGINAL_INIT(self, *args, **kwargs)

    self.embyflow_srt_v2_generation = 0
    self.embyflow_srt_v2_download_result = None
    self.embyflow_srt_v2_download_poll_count = 0
    self.embyflow_srt_v2_loading = False
    self.embyflow_srt_v2_cues = []
    self.embyflow_srt_v2_starts = []
    self.embyflow_srt_v2_visible_index = None
    self.embyflow_srt_v2_overlay = None
    self.embyflow_srt_v2_download_timer = eTimer()
    self.embyflow_srt_v2_render_timer = eTimer()

    _embyflow_srt_v2_connect_timer(
        self,
        self.embyflow_srt_v2_download_timer,
        lambda: _embyflow_srt_v2_poll_download(self),
        "embyflow_srt_v2_download_connection",
    )
    _embyflow_srt_v2_connect_timer(
        self,
        self.embyflow_srt_v2_render_timer,
        lambda: _embyflow_srt_v2_render_tick(self),
        "embyflow_srt_v2_render_connection",
    )


def _embyflow_srt_v2_overlay(self, create=True):
    window = getattr(self, "embyflow_srt_v2_overlay", None)

    if window is not None:
        return window

    if not create:
        return None

    window = self.session.instantiateDialog(
        _EmbyFlowExternalSrtOverlay
    )
    window.hide()
    self.embyflow_srt_v2_overlay = window
    return window


def _embyflow_srt_v2_hide_overlay(self):
    window = _embyflow_srt_v2_overlay(self, False)

    if window is None:
        return

    try:
        window["subtitle_text"].setText("")
    except Exception:
        pass

    try:
        window.hide()
    except Exception:
        pass


def _embyflow_srt_v2_stop(self, invalidate=True):
    if invalidate:
        self.embyflow_srt_v2_generation += 1

    self.embyflow_srt_v2_download_result = None
    self.embyflow_srt_v2_loading = False
    self.embyflow_srt_v2_cues = []
    self.embyflow_srt_v2_starts = []
    self.embyflow_srt_v2_visible_index = None

    try:
        self.embyflow_srt_v2_download_timer.stop()
    except Exception:
        pass

    try:
        self.embyflow_srt_v2_render_timer.stop()
    except Exception:
        pass

    _embyflow_srt_v2_hide_overlay(self)


def _embyflow_srt_v2_is_text_stream(stream):
    try:
        codec = str(stream.get("Codec") or "").strip().lower()
        path = str(stream.get("Path") or "").strip().lower()
        delivery = str(
            stream.get("DeliveryMethod") or ""
        ).strip().lower()

        unsupported = (
            "pgs",
            "hdmv_pgs_subtitle",
            "dvdsub",
            "dvbsub",
            "vobsub",
            "xsub",
        )

        if codec in unsupported:
            return False

        if codec in (
            "srt",
            "subrip",
            "webvtt",
            "vtt",
            "ass",
            "ssa",
            "text",
            "mov_text",
        ):
            return True

        if path.endswith((".srt", ".vtt", ".ass", ".ssa")):
            return True

        value = stream.get("IsExternal")
        if isinstance(value, str):
            value = value.strip().lower() in (
                "1",
                "true",
                "yes",
                "ja",
            )

        return bool(value) or delivery == "external"

    except Exception:
        return False


def _embyflow_srt_v2_streams(self):
    try:
        return self.embyflow_media_streams_by_type("Subtitle")
    except Exception:
        return []


def _embyflow_srt_v2_stream_at(self, position):
    streams = _embyflow_srt_v2_streams(self)

    try:
        position = int(position)
    except Exception:
        position = -1

    if 0 <= position < len(streams):
        return streams[position]

    return None


def _embyflow_srt_v2_language(self, stream, position):
    fallback = "Untertitel %d" % (int(position) + 1)

    try:
        value = (
            stream.get("Language")
            or stream.get("DisplayLanguage")
            or fallback
        )
        return self.embyflow_track_language_name(value, fallback)
    except Exception:
        return fallback


def _embyflow_srt_v2_open_selection(self):
    try:
        streams = _embyflow_srt_v2_streams(self)

        entries = [{
            "primary": "Untertitel aus",
            "secondary": "",
            "tertiary": "",
            "active": self.embyflow_active_subtitle_index is None,
            "payload": ("subtitle_off", None, "Aus", None),
        }]

        for position, stream in enumerate(streams):
            if not _embyflow_srt_v2_is_text_stream(stream):
                continue

            language = _embyflow_srt_v2_language(
                self,
                stream,
                position,
            )

            try:
                codec = self.embyflow_track_codec_name(
                    stream.get("Codec")
                )
            except Exception:
                codec = str(stream.get("Codec") or "SRT").upper()

            flags = []
            title_text = " ".join((
                str(stream.get("Title") or ""),
                str(stream.get("DisplayTitle") or ""),
            )).lower()

            if stream.get("IsForced") or "forced" in title_text or "erzw" in title_text:
                flags.append("Erzw.")

            if stream.get("IsHearingImpaired") or "sdh" in title_text or "hearing" in title_text:
                flags.append("SDH")

            entries.append({
                "primary": language,
                "secondary": codec or "SRT",
                "tertiary": "/".join(flags),
                "active": self.embyflow_active_subtitle_index == position,
                "payload": ("subtitle", None, language, position),
            })

        if len(entries) == 1:
            raise RuntimeError(
                "Keine unterstützten Textuntertitel gefunden"
            )

        active_index = 0
        for index, entry in enumerate(entries):
            if entry.get("active"):
                active_index = index
                break

        self.session.openWithCallback(
            self.subtitle_selection_finished,
            EmbyFlowTrackSelectionScreen,
            title="Untertitel auswählen",
            entries=entries,
            active_index=active_index,
        )

    except Exception as error:
        self.session.open(
            MessageBox,
            "Untertitelauswahl nicht verfügbar: %s" % str(error),
            MessageBox.TYPE_INFO,
            timeout=4,
        )


def _embyflow_srt_v2_timestamp_ms(value):
    match = re.match(
        r"^\s*(?:(\d+):)?(\d{1,2}):(\d{2})[,.](\d{1,3})\s*$",
        str(value or ""),
    )

    if not match:
        raise ValueError("Ungültiger SRT-Zeitstempel: %s" % value)

    hours = int(match.group(1) or 0)
    minutes = int(match.group(2) or 0)
    seconds = int(match.group(3) or 0)
    milliseconds_text = str(match.group(4) or "0")[:3].ljust(3, "0")
    milliseconds = int(milliseconds_text)

    return (
        ((hours * 60 + minutes) * 60 + seconds) * 1000
        + milliseconds
    )


def _embyflow_srt_v2_clean_text(value):
    text = str(value or "").replace("\x00", "")
    text = re.sub(r"(?i)<br\s*/?>", "\n", text)
    text = re.sub(r"\{\\[^}]+\}", "", text)
    text = re.sub(r"<[^>]+>", "", text)

    try:
        import html
        text = html.unescape(text)
    except Exception:
        pass

    lines = []
    for line in text.split("\n"):
        cleaned = re.sub(r"[ \t]+", " ", line).strip()
        if cleaned:
            lines.append(cleaned)

    return "\n".join(lines)


def _embyflow_srt_v2_parse(text):
    normalized = str(text or "").replace("\r\n", "\n").replace("\r", "\n")
    normalized = normalized.lstrip("\ufeff")
    cues = []

    for block in re.split(r"\n\s*\n", normalized.strip()):
        lines = block.split("\n")
        timing_index = None

        for index, line in enumerate(lines):
            if "-->" in line:
                timing_index = index
                break

        if timing_index is None:
            continue

        timing = lines[timing_index].split("-->", 1)
        if len(timing) != 2:
            continue

        right = timing[1].strip().split()[0]

        try:
            start_ms = _embyflow_srt_v2_timestamp_ms(timing[0])
            end_ms = _embyflow_srt_v2_timestamp_ms(right)
        except Exception:
            continue

        if end_ms <= start_ms:
            continue

        cue_text = _embyflow_srt_v2_clean_text(
            "\n".join(lines[timing_index + 1:])
        )

        if cue_text:
            cues.append((start_ms, end_ms, cue_text))

    cues.sort(key=lambda cue: (cue[0], cue[1]))

    if not cues:
        raise RuntimeError("SRT-Datei enthält keine lesbaren Einträge")

    return cues


def _embyflow_srt_v2_urls(self, stream):
    server = str(
        (self.playback_info or {}).get("server")
        or EMBY_AUTH_CACHE.get("server")
        or EMBY_SERVER
        or ""
    ).rstrip("/")

    token = str(
        (self.playback_info or {}).get("token")
        or EMBY_AUTH_CACHE.get("token")
        or ""
    )

    item_id = str(self.item_id or "")
    source_id = str(self.media_source_id or "")
    stream_index = int(stream.get("Index"))

    if not server or not token or not item_id or not source_id:
        raise RuntimeError(
            "Emby-Zugangsdaten oder Medien-ID fehlen"
        )

    roots = [server]
    if not server.lower().endswith("/emby"):
        roots.insert(0, server + "/emby")

    urls = []
    for root in roots:
        url = "%s/Items/%s/%s/Subtitles/%s/stream.srt" % (
            root,
            item_id,
            source_id,
            stream_index,
        )
        if url not in urls:
            urls.append(url)

    return urls, token, stream_index


def _embyflow_srt_v2_start(self, stream, label, position, announce=True):
    if not requests:
        raise RuntimeError("Python-Modul requests fehlt")

    if not stream or not _embyflow_srt_v2_is_text_stream(stream):
        raise RuntimeError("Diese Untertitelspur ist kein Textuntertitel")

    urls, token, stream_index = _embyflow_srt_v2_urls(self, stream)

    self.embyflow_srt_v2_generation += 1
    generation = self.embyflow_srt_v2_generation

    _embyflow_srt_v2_stop(self, False)

    self.embyflow_srt_v2_download_poll_count = 0
    self.embyflow_srt_v2_loading = True
    self["state_label"].setText(
        "Untertitel werden geladen: %s" % str(label)
    )

    import threading

    def worker():
        result = {
            "generation": generation,
            "ok": False,
            "error": "Untertitel konnten nicht geladen werden",
            "cues": [],
            "label": str(label),
            "position": int(position),
            "stream_index": int(stream_index),
        }
        errors = []

        for url in urls:
            try:
                response = embyflow_http_get(
                    url,
                    headers={
                        "X-Emby-Token": token,
                        "X-Emby-Authorization": AUTH_HEADER,
                        "Accept-Encoding": "identity",
                    },
                    params={"api_key": token},
                    timeout=(3, 8),
                    verify=True,
                )

                if int(getattr(response, "status_code", 0) or 0) != 200:
                    errors.append("HTTP %s" % getattr(response, "status_code", "?"))
                    continue

                raw = response.content or b""
                if not raw:
                    errors.append("Leere Untertiteldatei")
                    continue
                if len(raw) > 8 * 1024 * 1024:
                    errors.append("Untertiteldatei ist größer als 8 MiB")
                    continue

                decoded = None
                for encoding in ("utf-8-sig", "utf-8", "cp1252", "latin-1"):
                    try:
                        decoded = raw.decode(encoding)
                        break
                    except Exception:
                        pass

                cues = _embyflow_srt_v2_parse(decoded or "")
                result["ok"] = True
                result["error"] = ""
                result["cues"] = cues
                break

            except Exception as error:
                errors.append(str(error))

        if not result["ok"] and errors:
            result["error"] = "; ".join(errors[-2:])

        if generation == getattr(self, "embyflow_srt_v2_generation", -1):
            self.embyflow_srt_v2_download_result = result

    thread = threading.Thread(
        target=worker,
        name="EmbyFlowSrtV2Download",
    )
    thread.daemon = True
    thread.start()

    self.embyflow_srt_v2_download_timer.start(100, False)

    if announce:
        self.show_overlay()


def _embyflow_srt_v2_poll_download(self):
    try:
        self.embyflow_srt_v2_download_poll_count += 1
        result = self.embyflow_srt_v2_download_result

        if result is None:
            if self.embyflow_srt_v2_download_poll_count < 1500:
                return

            self.embyflow_srt_v2_download_timer.stop()
            self.embyflow_srt_v2_loading = False
            self.embyflow_srt_v2_generation += 1
            self.embyflow_srt_v2_download_result = None

            # EMBYFLOW_SUBTITLE_DOWNLOAD_TIMEOUT_V5_DIAG
            try:
                with open(
                    "/tmp/embyflow_external_subtitle_error.log",
                    "a",
                    encoding="utf-8",
                ) as log:
                    log.write(
                        "%s item=%s download_timeout poll=%s generation=%s\\n"
                        % (
                            time.strftime("%Y-%m-%d %H:%M:%S"),
                            self.item_id,
                            self.embyflow_srt_v2_download_poll_count,
                            self.embyflow_srt_v2_generation,
                        )
                    )
            except Exception:
                pass

            self.session.open(
                MessageBox,
                "Untertitel konnten nicht rechtzeitig geladen werden.",
                MessageBox.TYPE_ERROR,
                timeout=5,
            )
            return

        self.embyflow_srt_v2_download_timer.stop()
        self.embyflow_srt_v2_download_result = None
        self.embyflow_srt_v2_loading = False

        if not result.get("ok"):
            error_text = str(result.get("error") or "Unbekannter Fehler")

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_external_subtitle_error.log",
                    "a",
                ) as log:
                    log.write(
                        "%s item=%s stream=%s error=%s\n" % (
                            time.strftime("%Y-%m-%d %H:%M:%S"),
                            self.item_id,
                            result.get("stream_index"),
                            error_text,
                        )
                    )
            except Exception:
                pass

            self.session.open(
                MessageBox,
                "Untertitel konnten nicht geladen werden: %s" % error_text,
                MessageBox.TYPE_ERROR,
                timeout=6,
            )
            return

        self.embyflow_srt_v2_cues = list(result.get("cues") or [])
        self.embyflow_srt_v2_starts = [cue[0] for cue in self.embyflow_srt_v2_cues]
        self.embyflow_srt_v2_visible_index = None
        self.embyflow_active_subtitle_index = int(result.get("position"))
        self.embyflow_active_subtitle_stream_index = int(result.get("stream_index"))

        sources = self.item.get("MediaSources") or self.item.get("media_sources") or []
        if sources:
            sources[0]["DefaultSubtitleStreamIndex"] = int(result.get("stream_index"))

        _embyflow_srt_v2_overlay(self, True)
        self.embyflow_srt_v2_render_timer.start(100, False)
        _embyflow_srt_v2_render_tick(self)

        self["state_label"].setText(
            "Untertitel: %s" % str(result.get("label") or "")
        )
        self.show_overlay()

    except Exception as error:
        _embyflow_srt_v2_stop(self, False)
        self.session.open(
            MessageBox,
            "Untertitel konnten nicht aktiviert werden: %s" % str(error),
            MessageBox.TYPE_ERROR,
            timeout=6,
        )


def _embyflow_srt_v2_render_tick(self):
    try:
        cues = self.embyflow_srt_v2_cues
        starts = self.embyflow_srt_v2_starts

        if not cues or not starts:
            _embyflow_srt_v2_hide_overlay(self)
            return

        # EMBYFLOW_UT_SYNC_V16_1_SRT_CONTENT_CLOCK
        position_ms = int(
            self.embyflow_v10_content_position_ticks() or 0
        ) // 10000

        import bisect
        index = bisect.bisect_right(starts, position_ms) - 1
        visible_index = None
        text = ""

        if 0 <= index < len(cues):
            start_ms, end_ms, cue_text = cues[index]
            if start_ms <= position_ms < end_ms:
                visible_index = index
                text = cue_text

        if visible_index == self.embyflow_srt_v2_visible_index:
            return

        self.embyflow_srt_v2_visible_index = visible_index
        window = _embyflow_srt_v2_overlay(self, True)

        if visible_index is None:
            window["subtitle_text"].setText("")
            window.hide()
        else:
            window["subtitle_text"].setText(text)
            window.show()

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_external_subtitle_error.log",
                "a",
            ) as log:
                log.write(
                    "%s item=%s render_error=%s\n" % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        self.item_id,
                        str(error),
                    )
                )
        except Exception:
            pass


def _embyflow_srt_v2_selection_finished(self, result):
    if not result:
        return

    try:
        action, _native_entry, label, position = result

        if action == "subtitle_off":
            _embyflow_srt_v2_stop(self, True)
            self.embyflow_active_subtitle_index = None
            self.embyflow_active_subtitle_stream_index = None

            sources = self.item.get("MediaSources") or self.item.get("media_sources") or []
            if sources:
                sources[0]["DefaultSubtitleStreamIndex"] = -1

            self["state_label"].setText("Untertitel: Aus")
            self.show_overlay()
            return

        if action != "subtitle":
            return

        stream = _embyflow_srt_v2_stream_at(self, position)
        if stream is None:
            raise RuntimeError("Ausgewählte Emby-Untertitelspur fehlt")

        _embyflow_srt_v2_start(
            self,
            stream,
            label,
            position,
            True,
        )

    except Exception as error:
        self.session.open(
            MessageBox,
            "Untertitel konnten nicht gewechselt werden: %s" % str(error),
            MessageBox.TYPE_ERROR,
            timeout=5,
        )


def _embyflow_srt_v2_auto_select(self):
    try:
        if self.embyflow_srt_v2_loading or self.embyflow_active_subtitle_index is not None:
            return

        sources = self.item.get("MediaSources") or self.item.get("media_sources") or []
        if not sources:
            return

        desired = int(
            sources[0].get("DefaultSubtitleStreamIndex")
            if sources[0].get("DefaultSubtitleStreamIndex") is not None
            else -1
        )

        if desired < 0:
            return

        for position, stream in enumerate(_embyflow_srt_v2_streams(self)):
            try:
                stream_index = int(stream.get("Index"))
            except Exception:
                continue

            if stream_index != desired or not _embyflow_srt_v2_is_text_stream(stream):
                continue

            _embyflow_srt_v2_start(
                self,
                stream,
                _embyflow_srt_v2_language(self, stream, position),
                position,
                False,
            )
            return

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_external_subtitle_error.log",
                "a",
            ) as log:
                log.write(
                    "%s item=%s auto_error=%s\n" % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        self.item_id,
                        str(error),
                    )
                )
        except Exception:
            pass


def _embyflow_srt_v2_block_native(self, selected_subtitle):
    if selected_subtitle is None:
        _embyflow_srt_v2_stop(self, True)
        return

    raise RuntimeError(
        "Native Enigma2-Untertitel sind für diesen Player deaktiviert"
    )


def _embyflow_srt_v2_close(self):
    _embyflow_srt_v2_stop(self, True)
    window = _embyflow_srt_v2_overlay(self, False)

    if window is not None:
        try:
            self.session.deleteDialog(window)
        except Exception:
            try:
                window.close()
            except Exception:
                pass

    self.embyflow_srt_v2_overlay = None

    # Ein eventuell von älteren Playerpfaden erzeugtes natives Fenster
    # nur gefahrlos schließen; enableSubtitles() wird nie aufgerufen.
    old_window = getattr(self, "embyflow_subtitle_window", None)
    if old_window is not None:
        try:
            old_window.hide()
        except Exception:
            pass
        try:
            self.session.deleteDialog(old_window)
        except Exception:
            try:
                old_window.close()
            except Exception:
                pass
        self.embyflow_subtitle_window = None

    self.embyflow_selected_subtitle = None


EmbyFlowMoviePlayer.open_subtitle_selection = _embyflow_srt_v2_open_selection
EmbyFlowMoviePlayer.subtitle_selection_finished = _embyflow_srt_v2_selection_finished
EmbyFlowMoviePlayer.set_preferred_subtitle_track = _embyflow_srt_v2_auto_select
EmbyFlowMoviePlayer.embyflow_close_subtitle_window = _embyflow_srt_v2_close
EmbyFlowMoviePlayer.embyflow_set_embedded_subtitle = _embyflow_srt_v2_block_native
EmbyFlowMoviePlayer.__init__ = _embyflow_srt_v2_init
# EMBYFLOW_EXTERNAL_SRT_NATIVELESS_V2_END

# EMBYFLOW_SUBTITLE_DIALOG_SINGLE_OPEN_V3_START
_EMBYFLOW_SUBTITLE_DIALOG_V3_OPEN = (
    EmbyFlowMoviePlayer.open_subtitle_selection
)


def _embyflow_subtitle_dialog_v3_open(self):
    now = time.time()
    last_open = float(
        getattr(
            self,
            "embyflow_subtitle_dialog_v3_last_open",
            0.0,
        )
        or 0.0
    )

    # Manche OpenATV-Keymaps melden Gelb gleichzeitig als
    # "yellow" und "subtitleSelection". Der zweite Aufruf erzeugt
    # sonst ein unsichtbares zweites Auswahlfenster im Dialogstapel.
    if now - last_open < 1.5:
        return

    self.embyflow_subtitle_dialog_v3_last_open = now
    return _EMBYFLOW_SUBTITLE_DIALOG_V3_OPEN(self)


EmbyFlowMoviePlayer.open_subtitle_selection = (
    _embyflow_subtitle_dialog_v3_open
)
# EMBYFLOW_SUBTITLE_DIALOG_SINGLE_OPEN_V3_END

# EMBYFLOW_SUBTITLE_IN_PLAYER_V4_START
# V2 nutzte für den SRT-Text einen separaten Screen-Dialog. Auf diesem
# OpenATV-Stand kehrt dadurch beim zeitgesteuerten Ein-/Ausblenden die
# zuvor geschlossene Untertitelauswahl aus dem Dialogstapel zurück.
# V4 zeichnet den Text direkt im bereits geöffneten Player-Screen.


def _embyflow_srt_v4_overlay(self, create=True):
    try:
        return self["external_subtitle_text"]
    except Exception:
        return None


def _embyflow_srt_v4_hide_overlay(self):
    widget = _embyflow_srt_v4_overlay(self, False)

    if widget is None:
        return

    try:
        widget.setText("")
    except Exception:
        pass

    try:
        widget.hide()
    except Exception:
        pass


def _embyflow_srt_v4_render_tick(self):
    try:
        cues = self.embyflow_srt_v2_cues
        starts = self.embyflow_srt_v2_starts
        widget = _embyflow_srt_v4_overlay(self, True)

        if widget is None:
            raise RuntimeError("Player-Untertitelwidget fehlt")

        if not cues or not starts:
            _embyflow_srt_v4_hide_overlay(self)
            return

        # EMBYFLOW_UT_SYNC_V16_1_SRT_CONTENT_CLOCK
        position_ms = int(
            self.embyflow_v10_content_position_ticks() or 0
        ) // 10000

        import bisect
        index = bisect.bisect_right(starts, position_ms) - 1
        visible_index = None
        subtitle_text = ""

        if 0 <= index < len(cues):
            start_ms, end_ms, cue_text = cues[index]

            if start_ms <= position_ms < end_ms:
                visible_index = index
                subtitle_text = cue_text

        if visible_index == self.embyflow_srt_v2_visible_index:
            return

        self.embyflow_srt_v2_visible_index = visible_index

        if visible_index is None:
            widget.setText("")
            widget.hide()
        else:
            widget.setText(subtitle_text)
            widget.show()

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_external_subtitle_error.log",
                "a",
            ) as log:
                log.write(
                    "%s item=%s render_v4_error=%s\n" % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        self.item_id,
                        str(error),
                    )
                )
        except Exception:
            pass


def _embyflow_srt_v4_close(self):
    _embyflow_srt_v2_stop(self, True)
    _embyflow_srt_v4_hide_overlay(self)

    old_window = getattr(self, "embyflow_srt_v2_overlay", None)

    if old_window is not None:
        try:
            old_window.hide()
        except Exception:
            pass

        try:
            self.session.deleteDialog(old_window)
        except Exception:
            try:
                old_window.close()
            except Exception:
                pass

    self.embyflow_srt_v2_overlay = None
    self.embyflow_selected_subtitle = None


# Die vorhandenen V2-Timer-Lambdas lösen diese Namen erst beim Ausführen
# auf und verwenden dadurch den playerinternen V4-Renderer.
_embyflow_srt_v2_overlay = _embyflow_srt_v4_overlay
_embyflow_srt_v2_hide_overlay = _embyflow_srt_v4_hide_overlay
_embyflow_srt_v2_render_tick = _embyflow_srt_v4_render_tick

EmbyFlowMoviePlayer.embyflow_close_subtitle_window = (
    _embyflow_srt_v4_close
)
# EMBYFLOW_SUBTITLE_IN_PLAYER_V4_END

# EMBYFLOW_SUBTITLE_DOWNLOAD_TIMEOUT_V5_START
# Der normale Emby-Basisendpunkt wird zuerst versucht. Der alternative
# /emby-Pfad bleibt als Fallback erhalten. Zwei HTTP-Versuche können
# zusammen länger als der bisherige 15-Sekunden-Wächter dauern; V5 lässt
# dem Hintergrunddownload deshalb bis zu 60 Sekunden Zeit.
# EMBYFLOW_SUBTITLE_DOWNLOAD_TIMEOUT_V5_END

# EMBYFLOW_SUBTITLE_EMBY_ENDPOINT_V6_START
# Diagnose vom 05.08.2026: Der direkte Pfad /Items/... lief in einen
# Timeout, während /emby/Items/... nach rund 24 Sekunden HTTP 200 und
# SRT-Daten lieferte. Deshalb wird /emby wieder zuerst versucht.
# RCDEV4: Das Lesezeitlimit beträgt 120 Sekunden; der GUI-Wächter 150 Sekunden.
# Große 4K-MKVs bekommen damit genug Zeit für ffmpeg-subtitle_extract.
# EMBYFLOW_SUBTITLE_EMBY_ENDPOINT_V6_END

# EMBYFLOW_LOCAL_MEDIA_PROTOTYPE_V1_START
EMBYFLOW_LOCAL_MEDIA_ROOT = "/media/usb"
EMBYFLOW_LOCAL_VIDEO_EXTENSIONS = set((
    ".mkv",
    ".mp4",
    ".avi",
    ".ts",
    ".m2ts",
    ".mov",
    ".mpg",
    ".mpeg",
    ".wmv",
    ".flv",
    ".webm",
))


def embyflow_local_human_size(value):
    try:
        size = float(value or 0)
        units = ("B", "KB", "MB", "GB", "TB")
        unit_index = 0

        while size >= 1024.0 and unit_index < len(units) - 1:
            size /= 1024.0
            unit_index += 1

        if unit_index == 0:
            return "%d %s" % (int(size), units[unit_index])

        return "%.1f %s" % (size, units[unit_index])
    except Exception:
        return ""


def embyflow_local_clean_title(path):
    try:
        base = os.path.basename(str(path or ""))
        title = os.path.splitext(base)[0]
        return title.replace("_", " ").strip() or base
    except Exception:
        return str(path or "")


_EMBYFLOW_LOCAL_ROWS_SKIN = "".join(
    '<widget name="row%d" position="190,%d" size="1160,48" '
    'font="Regular;27" foregroundColor="#E8EDF3" '
    'backgroundColor="#151311" transparent="1" valign="center" zPosition="2" />'
    '<widget name="meta%d" position="1390,%d" size="350,48" '
    'font="Regular;21" foregroundColor="#AEB8C5" '
    'backgroundColor="#151311" transparent="1" halign="right" valign="center" zPosition="2" />'
    % (
        index,
        190 + index * 54,
        index,
        190 + index * 54,
    )
    for index in range(14)
)


class EmbyFlowLocalMediaScreen(Screen):
    VISIBLE_ROWS = 14

    skin = scale_skin(
        '''
        <screen name="EmbyFlowLocalMediaScreen"
                position="0,0" size="1920,1080"
                flags="wfNoBorder"
                backgroundColor="#151311">
            <eLabel position="0,0" size="1920,1080" backgroundColor="#151311" />
            <eLabel position="0,0" size="1920,5" backgroundColor="#1689FF" />
            <eLabel text="EmbyFlow E2" position="110,52" size="420,48"
                    font="Regular;38" foregroundColor="#F2F5F8"
                    backgroundColor="#151311" transparent="1" />
            <widget name="title" position="110,108" size="1050,52"
                    font="Regular;40" foregroundColor="#F2C94C"
                    backgroundColor="#151311" transparent="1" />
            <widget name="path" position="110,158" size="1630,32"
                    font="Regular;21" foregroundColor="#AEB8C5"
                    backgroundColor="#151311" transparent="1" />
            <widget name="focus_bg" position="175,186" size="1580,50" zPosition="1"
                    backgroundColor="#173A5E" transparent="0"
                    cornerRadius="8" widgetBorderWidth="2"
                    widgetBorderColor="#1689FF" />
        '''
        + _EMBYFLOW_LOCAL_ROWS_SKIN
        + '''
            <widget name="status" position="110,958" size="950,34"
                    font="Regular;22" foregroundColor="#AEB8C5"
                    backgroundColor="#151311" transparent="1" />
            <eLabel position="1130,970" size="18,18" backgroundColor="red" />
            <eLabel text="Zurück" position="1160,960" size="120,34"
                    font="Regular;22" foregroundColor="#F2F5F8"
                    backgroundColor="#151311" transparent="1" />
            <eLabel position="1300,970" size="18,18" backgroundColor="green" />
            <eLabel text="Öffnen / Abspielen" position="1330,960" size="230,34"
                    font="Regular;22" foregroundColor="#F2F5F8"
                    backgroundColor="#151311" transparent="1" />
            <eLabel position="1590,970" size="18,18" backgroundColor="blue" />
            <eLabel text="Neu laden" position="1620,960" size="150,34"
                    font="Regular;22" foregroundColor="#F2F5F8"
                    backgroundColor="#151311" transparent="1" />
        </screen>
        '''
    )

    def __init__(self, session, root_path, title="Eigene Medien"):
        Screen.__init__(self, session)

        self.root_path = os.path.realpath(str(root_path or EMBYFLOW_LOCAL_MEDIA_ROOT))
        self.current_path = self.root_path
        self.title_text = str(title or "Eigene Medien")
        self.entries = []
        self.selected_index = 0
        self.offset = 0
        self.scan_generation = 0
        self.scan_result = None
        self.scan_loading = False
        self.closed_local_screen = False

        self["title"] = Label(self.title_text)
        self["path"] = Label(self.current_path)
        self["status"] = Label("")
        self["focus_bg"] = Label(" ")

        for index in range(self.VISIBLE_ROWS):
            self["row%d" % index] = Label("")
            self["meta%d" % index] = Label("")

        self["actions"] = ActionMap(
            [
                "OkCancelActions",
                "DirectionActions",
                "ColorActions",
            ],
            {
                "ok": self.open_selected,
                "cancel": self.go_back,
                "red": self.go_back,
                "green": self.open_selected,
                "blue": self.start_scan,
                "up": self.move_up,
                "down": self.move_down,
                "left": self.page_up,
                "right": self.page_down,
            },
            -1,
        )

        self.scan_timer = eTimer()

        try:
            self.scan_timer.callback.append(self.poll_scan)
        except Exception:
            try:
                self.scan_timer_connection = self.scan_timer.timeout.connect(
                    self.poll_scan
                )
            except Exception:
                self.scan_timer_connection = None

        self.onLayoutFinish.append(self.start_scan)
        self.onClose.append(self.cleanup)

    def cleanup(self):
        self.closed_local_screen = True
        self.scan_generation += 1

        try:
            self.scan_timer.stop()
        except Exception:
            pass

    def safe_within_root(self, candidate):
        try:
            candidate_real = os.path.realpath(str(candidate or ""))
            root_real = os.path.realpath(self.root_path)

            return (
                candidate_real == root_real
                or candidate_real.startswith(root_real + os.sep)
            )
        except Exception:
            return False

    def start_scan(self):
        if self.closed_local_screen:
            return

        current = os.path.realpath(self.current_path)

        if not self.safe_within_root(current):
            current = self.root_path
            self.current_path = current

        self.scan_generation += 1
        generation = self.scan_generation
        self.scan_result = None
        self.scan_loading = True
        self.entries = []
        self.selected_index = 0
        self.offset = 0
        self["path"].setText(current)
        self["status"].setText("Ordner wird im Hintergrund gelesen …")
        self.refresh()

        import threading

        def worker():
            directories = []
            files = []
            error_text = ""
            truncated = False

            try:
                with os.scandir(current) as iterator:
                    for entry in iterator:
                        if self.closed_local_screen:
                            return

                        name = str(entry.name or "")

                        if not name or name.startswith("."):
                            continue

                        full_path = os.path.join(current, name)

                        try:
                            if entry.is_dir(follow_symlinks=False):
                                directories.append({
                                    "kind": "dir",
                                    "name": name,
                                    "path": full_path,
                                    "meta": "Ordner",
                                })
                                continue

                            if not entry.is_file(follow_symlinks=False):
                                continue

                            extension = os.path.splitext(name)[1].lower()

                            if extension not in EMBYFLOW_LOCAL_VIDEO_EXTENSIONS:
                                continue

                            try:
                                stat_info = entry.stat(follow_symlinks=False)
                                file_size = int(stat_info.st_size or 0)
                            except Exception:
                                file_size = 0

                            files.append({
                                "kind": "file",
                                "name": name,
                                "path": full_path,
                                "extension": extension,
                                "size": file_size,
                                "meta": "%s  •  %s" % (
                                    extension.lstrip(".").upper(),
                                    embyflow_local_human_size(file_size),
                                ),
                            })

                            if len(directories) + len(files) >= 5000:
                                truncated = True
                                break

                        except Exception:
                            continue

                directories.sort(
                    key=lambda item: str(item.get("name") or "").casefold()
                )
                files.sort(
                    key=lambda item: str(item.get("name") or "").casefold()
                )

            except Exception as error:
                error_text = str(error)

            if generation == self.scan_generation and not self.closed_local_screen:
                self.scan_result = {
                    "generation": generation,
                    "entries": directories + files,
                    "error": error_text,
                    "truncated": truncated,
                }

        thread = threading.Thread(
            target=worker,
            name="EmbyFlowLocalMediaScan",
        )
        thread.daemon = True
        thread.start()

        try:
            self.scan_timer.stop()
        except Exception:
            pass

        self.scan_timer.start(100, False)

    def poll_scan(self):
        result = self.scan_result

        if result is None:
            return

        try:
            self.scan_timer.stop()
        except Exception:
            pass

        self.scan_result = None
        self.scan_loading = False

        if result.get("generation") != self.scan_generation:
            return

        error_text = str(result.get("error") or "")

        if error_text:
            self.entries = []
            self["status"].setText("Ordner konnte nicht gelesen werden")
            self.refresh()
            self.session.open(
                MessageBox,
                "Eigene Mediathek konnte den Ordner nicht lesen:\n\n%s"
                % error_text,
                MessageBox.TYPE_ERROR,
                timeout=7,
            )
            return

        self.entries = list(result.get("entries") or [])
        self.selected_index = 0
        self.offset = 0

        directory_count = sum(
            1 for entry in self.entries if entry.get("kind") == "dir"
        )
        file_count = sum(
            1 for entry in self.entries if entry.get("kind") == "file"
        )

        status = "%d Ordner  •  %d Videos" % (
            directory_count,
            file_count,
        )

        if result.get("truncated"):
            status += "  •  Anzeige auf 5000 Einträge begrenzt"

        self["status"].setText(status)
        self.refresh()

    def selected_entry(self):
        if not self.entries:
            return None

        self.selected_index = max(
            0,
            min(self.selected_index, len(self.entries) - 1),
        )

        return self.entries[self.selected_index]

    def refresh(self):
        total = len(self.entries)

        if total:
            self.selected_index = max(
                0,
                min(self.selected_index, total - 1),
            )

            if self.selected_index < self.offset:
                self.offset = self.selected_index

            if self.selected_index >= self.offset + self.VISIBLE_ROWS:
                self.offset = self.selected_index - self.VISIBLE_ROWS + 1

            self.offset = max(
                0,
                min(self.offset, max(0, total - self.VISIBLE_ROWS)),
            )

        else:
            self.selected_index = 0
            self.offset = 0

        for slot in range(self.VISIBLE_ROWS):
            actual = self.offset + slot

            if actual < total:
                entry = self.entries[actual]
                prefix = "[Ordner]  " if entry.get("kind") == "dir" else "[Video]   "
                self["row%d" % slot].setText(
                    prefix + str(entry.get("name") or "")
                )
                self["meta%d" % slot].setText(
                    str(entry.get("meta") or "")
                )
            else:
                self["row%d" % slot].setText("")
                self["meta%d" % slot].setText("")

        try:
            instance = self["focus_bg"].instance

            if total and instance is not None:
                visible_slot = self.selected_index - self.offset
                instance.move(EFP(175, 188 + visible_slot * 54))
                instance.resize(EFS(1580, 50))
                instance.show()
            elif instance is not None:
                instance.hide()
        except Exception:
            pass

        self["path"].setText(self.current_path)

    def move_up(self):
        if self.entries and self.selected_index > 0:
            self.selected_index -= 1
            self.refresh()

    def move_down(self):
        if self.entries and self.selected_index < len(self.entries) - 1:
            self.selected_index += 1
            self.refresh()

    def page_up(self):
        if self.entries:
            self.selected_index = max(
                0,
                self.selected_index - self.VISIBLE_ROWS,
            )
            self.refresh()

    def page_down(self):
        if self.entries:
            self.selected_index = min(
                len(self.entries) - 1,
                self.selected_index + self.VISIBLE_ROWS,
            )
            self.refresh()

    def go_back(self):
        current_real = os.path.realpath(self.current_path)
        root_real = os.path.realpath(self.root_path)

        if current_real == root_real:
            self.close()
            return

        parent = os.path.dirname(current_real)

        if not self.safe_within_root(parent):
            parent = root_real

        self.current_path = parent
        self.start_scan()

    def open_selected(self):
        if self.scan_loading:
            return

        entry = self.selected_entry()

        if not entry:
            return

        path = str(entry.get("path") or "")

        if entry.get("kind") == "dir":
            if self.safe_within_root(path) and os.path.isdir(path):
                self.current_path = os.path.realpath(path)
                self.start_scan()
            return

        if entry.get("kind") == "file":
            self.play_file(path)

    def play_file(self, file_path):
        path = os.path.realpath(str(file_path or ""))

        if not self.safe_within_root(path) or not os.path.isfile(path):
            self.session.open(
                MessageBox,
                "Die Videodatei ist nicht mehr vorhanden.",
                MessageBox.TYPE_ERROR,
                timeout=5,
            )
            return

        title = embyflow_local_clean_title(path)
        is_series_root = "serien" in self.root_path.casefold()
        item_type = "Episode" if is_series_root else "Movie"
        local_id = "local:" + path

        item = {
            "Id": local_id,
            "id": local_id,
            "Name": title,
            "title": title,
            "Type": item_type,
            "type": item_type,
            "Path": path,
            "MediaSources": [{
                "Id": local_id,
                "Path": path,
                "MediaStreams": [],
                "DefaultSubtitleStreamIndex": -1,
            }],
        }

        # EMBYFLOW_LOCAL_EPISODE_LIST_V6_RESUME
        try:
            local_position_ticks, local_runtime_ticks = (
                get_embyflow_local_resume(local_id)
            )

            if local_position_ticks > 0:
                item["PlaybackPositionTicks"] = int(
                    local_position_ticks
                )
                item["UserData"] = {
                    "PlaybackPositionTicks": int(
                        local_position_ticks
                    )
                }

            if local_runtime_ticks > 0:
                item["RunTimeTicks"] = int(
                    local_runtime_ticks
                )
        except Exception:
            pass

        if item_type == "Episode":
            item["SeriesName"] = os.path.basename(
                os.path.dirname(path)
            ) or self.title_text

        playback_info = {
            "url": path,
            "item": item,
            "local_file": True,
            "play_session_id": "local-" + str(uuid4()),
        }

        try:
            extension = os.path.splitext(path)[1].lower()

            # Lokale Enigma2-/Receiver-Aufnahmen benötigen den nativen
            # Dateidienst (Typ 1). Servicetyp 4097 ist für HTTP-/Dateistreams
            # gedacht und blieb bei lokalen TS-Dateien auf dem ersten Bild
            # mit unbekannter Laufzeit stehen.
            local_service_type = (
                1
                if extension in (".ts", ".m2ts", ".mts", ".trp")
                else STREAM_SERVICE_TYPE
            )

            playback_info["local_service_type"] = local_service_type
            playback_info["local_extension"] = extension

            ref = eServiceReference(
                local_service_type,
                0,
                path,
            )
            ref.setName(title)

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_local_media.log",
                    "a",
                ) as log:
                    log.write(
                        "%s PLAY path=%s extension=%s service_type=%s\n"
                        % (
                            time.strftime("%Y-%m-%d %H:%M:%S"),
                            path,
                            extension,
                            local_service_type,
                        )
                    )
            except Exception:
                pass

            _open_embyflow_player_now(
                self.session,
                ref,
                title,
                path,
                playback_info,
            )

        except Exception as error:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_local_media_error.log",
                    "a",
                ) as log:
                    log.write(
                        "%s PLAY path=%s error=%s\n"
                        % (
                            time.strftime("%Y-%m-%d %H:%M:%S"),
                            path,
                            str(error),
                        )
                    )
            except Exception:
                pass

            self.session.open(
                MessageBox,
                "Lokales Video konnte nicht gestartet werden:\n\n%s"
                % str(error),
                MessageBox.TYPE_ERROR,
                timeout=7,
            )


def _embyflow_local_media_open_menu(self):
    candidates = (
        ("Filme auf USB", "/media/usb/Filme"),
        ("Serien auf USB", "/media/usb/Serien"),
        ("USB-Festplatte durchsuchen", "/media/usb"),
    )

    entries = []

    for label, media_path in candidates:
        if os.path.isdir(media_path):
            entries.append((
                label,
                {
                    "title": label,
                    "path": media_path,
                },
            ))

    if not entries:
        self.session.open(
            MessageBox,
            "Unter /media/usb wurden keine lesbaren Medienordner gefunden.",
            MessageBox.TYPE_INFO,
            timeout=6,
        )
        return

    self.session.openWithCallback(
        self.local_media_menu_callback,
        EmbyFlowChoiceScreen,
        "Eigene Mediathek",
        entries,
    )


def _embyflow_local_media_menu_callback(self, selection):
    if not selection:
        return

    data = selection[1] if len(selection) > 1 else None

    if not isinstance(data, dict):
        return

    media_path = os.path.realpath(
        str(data.get("path") or "")
    )

    if not (
        media_path == "/media/usb"
        or media_path.startswith("/media/usb/")
    ):
        return

    if not os.path.isdir(media_path):
        self.session.open(
            MessageBox,
            "Der Medienordner ist nicht verfügbar:\n\n%s"
            % media_path,
            MessageBox.TYPE_ERROR,
            timeout=6,
        )
        return

    self.session.open(
        EmbyFlowLocalMediaScreen,
        media_path,
        str(data.get("title") or "Eigene Medien"),
    )


EmbyFlowE2Screen.open_local_media_menu = (
    _embyflow_local_media_open_menu
)
EmbyFlowE2Screen.local_media_menu_callback = (
    _embyflow_local_media_menu_callback
)
# EMBYFLOW_LOCAL_MEDIA_PROTOTYPE_V1_END

# EMBYFLOW_LOCAL_TS_PLAYBACK_V2_START
_EMBYFLOW_LOCAL_TS_V2_UPDATE_OVERLAY = (
    EmbyFlowMoviePlayer.update_playback_overlay
)


def _embyflow_local_ts_v2_update_overlay(self):
    try:
        if (
            (self.playback_info or {}).get("local_file")
            and not int(getattr(self, "duration_ticks", 0) or 0)
        ):
            service = self.session.nav.getCurrentService()
            seek = service and service.seek()
            length = seek and seek.getLength()

            if (
                isinstance(length, (tuple, list))
                and len(length) >= 2
                and int(length[0]) == 0
                and int(length[1]) > 0
            ):
                self.duration_ticks = int(
                    (int(length[1]) * 10000000) / 90000
                )
    except Exception:
        pass

    return _EMBYFLOW_LOCAL_TS_V2_UPDATE_OVERLAY(self)


EmbyFlowMoviePlayer.update_playback_overlay = (
    _embyflow_local_ts_v2_update_overlay
)
