# EMBYFLOW_LOCAL_LIBRARY_CARDS_V3_START
EMBYFLOW_LOCAL_LIBRARY_PAGE_SIZE_V3 = 10
EMBYFLOW_LOCAL_LIBRARY_SCAN_LIMIT_V3 = 5000
EMBYFLOW_LOCAL_LIBRARY_SKIP_DIRS_V3 = set((
    ".trash",
    ".trash-1000",
    "lost+found",
    "@eadir",
))


def embyflow_local_v3_recording_parts(path):
    try:
        base = os.path.splitext(os.path.basename(str(path or "")))[0]
        base = base.replace("_", " ").strip()

        match = re.match(
            r"^(\d{8})\s+(\d{4})\s*-\s*[^-]+\s*-\s*(.+)$",
            base,
        )

        if match:
            date_value = match.group(1)
            time_value = match.group(2)
            title = re.sub(r"\s+", " ", match.group(3)).strip()
            title = re.sub(r"\s+\d{3}$", "", title).strip()

            date_text = "%s.%s.%s" % (
                date_value[6:8],
                date_value[4:6],
                date_value[0:4],
            )
            time_text = "%s:%s" % (
                time_value[0:2],
                time_value[2:4],
            )

            return title or base, date_text, time_text

        title = re.sub(r"\s+", " ", base).strip()
        title = re.sub(r"\s+\d{3}$", "", title).strip()
        return title or base, "", ""

    except Exception:
        return embyflow_local_clean_title(path), "", ""


def embyflow_local_v3_display_title(path):
    title, _date_text, _time_text = embyflow_local_v3_recording_parts(path)
    return title


def embyflow_local_v3_episode_title(path):
    title, date_text, time_text = embyflow_local_v3_recording_parts(path)

    if date_text and time_text:
        return "%s · %s Uhr" % (date_text, time_text)

    if date_text:
        return date_text

    return title


def embyflow_local_v3_series_name(root_path, file_path):
    try:
        root_real = os.path.realpath(str(root_path or ""))
        path_real = os.path.realpath(str(file_path or ""))
        relative = os.path.relpath(path_real, root_real)
        parts = relative.split(os.sep)

        if len(parts) > 1:
            folder_name = str(parts[0] or "").strip()

            if folder_name and not folder_name.startswith("."):
                return folder_name.replace("_", " ").strip()

        title, _date_text, _time_text = embyflow_local_v3_recording_parts(
            file_path
        )
        return title

    except Exception:
        return embyflow_local_v3_display_title(file_path)


def embyflow_local_v3_image_index(directory):
    result = {}

    try:
        if not os.path.isdir(directory):
            return result

        for filename in os.listdir(directory):
            extension = os.path.splitext(filename)[1].lower()

            if extension not in (".jpg", ".jpeg", ".png", ".webp"):
                continue

            key = os.path.splitext(filename)[0].replace("_", " ").strip().casefold()

            if key and key not in result:
                result[key] = os.path.join(directory, filename)

    except Exception:
        pass

    return result


def embyflow_local_v3_find_poster(path, title, poster_index=None):
    try:
        file_path = os.path.realpath(str(path or ""))
        directory = file_path if os.path.isdir(file_path) else os.path.dirname(file_path)
        base_without_extension = os.path.splitext(file_path)[0]

        candidates = []

        if not os.path.isdir(file_path):
            for extension in (".jpg", ".jpeg", ".png", ".webp"):
                candidates.append(base_without_extension + extension)

        for name in (
            "poster.jpg",
            "poster.png",
            "folder.jpg",
            "folder.png",
            "cover.jpg",
            "cover.png",
        ):
            candidates.append(os.path.join(directory, name))

        for candidate in candidates:
            if os.path.isfile(candidate) and os.path.getsize(candidate) > 500:
                return candidate

        title_key = str(title or "").replace("_", " ").strip().casefold()

        if title_key and isinstance(poster_index, dict):
            indexed = poster_index.get(title_key)

            if indexed and os.path.isfile(indexed):
                return indexed

    except Exception:
        pass

    return ""


def embyflow_local_v3_video_files(root_path):
    files = []
    root_real = os.path.realpath(str(root_path or ""))

    for current_root, directories, filenames in os.walk(root_real):
        directories[:] = sorted(
            directory
            for directory in directories
            if (
                not directory.startswith(".")
                and directory.casefold() not in EMBYFLOW_LOCAL_LIBRARY_SKIP_DIRS_V3
            )
        )

        for filename in sorted(filenames):
            extension = os.path.splitext(filename)[1].lower()

            if extension not in EMBYFLOW_LOCAL_VIDEO_EXTENSIONS:
                continue

            full_path = os.path.realpath(os.path.join(current_root, filename))

            if not full_path.startswith(root_real + os.sep):
                continue

            try:
                stat_result = os.stat(full_path)
            except Exception:
                continue

            files.append({
                "path": full_path,
                "mtime": float(stat_result.st_mtime or 0.0),
                "size": int(stat_result.st_size or 0),
                "extension": extension,
            })

            if len(files) >= EMBYFLOW_LOCAL_LIBRARY_SCAN_LIMIT_V3:
                return files

    return files


def embyflow_local_v3_scan(root_path, mode):
    root_real = os.path.realpath(str(root_path or ""))
    mode_value = str(mode or "movies")
    poster_index = embyflow_local_v3_image_index("/media/usb/poster")
    files = embyflow_local_v3_video_files(root_real)

    if mode_value == "series":
        groups = {}

        for file_entry in files:
            series_name = embyflow_local_v3_series_name(
                root_real,
                file_entry.get("path"),
            )
            key = series_name.casefold()
            group = groups.get(key)

            if group is None:
                group = {
                    "kind": "series",
                    "title": series_name,
                    "path": file_entry.get("path"),
                    "mtime": 0.0,
                    "episodes": [],
                    "poster": "",
                }
                groups[key] = group

            episode_title = embyflow_local_v3_episode_title(
                file_entry.get("path")
            )
            episode_meta = embyflow_local_human_size(
                file_entry.get("size")
            )
            group["episodes"].append({
                "kind": "episode",
                "title": episode_title,
                "meta": episode_meta,
                "path": file_entry.get("path"),
                "mtime": file_entry.get("mtime"),
                "size": file_entry.get("size"),
            })
            group["mtime"] = max(
                float(group.get("mtime") or 0.0),
                float(file_entry.get("mtime") or 0.0),
            )

        result = []

        for group in groups.values():
            episodes = sorted(
                group.get("episodes") or [],
                key=lambda entry: float(entry.get("mtime") or 0.0),
                reverse=True,
            )
            group["episodes"] = episodes
            count = len(episodes)
            group["meta"] = "%d Aufnahme%s" % (
                count,
                "" if count == 1 else "n",
            )

            poster_path = os.path.dirname(str(group.get("path") or ""))
            group["poster"] = embyflow_local_v3_find_poster(
                poster_path,
                group.get("title"),
                poster_index,
            )
            result.append(group)

        return sorted(
            result,
            key=lambda entry: (
                -float(entry.get("mtime") or 0.0),
                str(entry.get("title") or "").casefold(),
            ),
        )

    result = []

    for file_entry in files:
        file_path = file_entry.get("path")
        title = embyflow_local_v3_display_title(file_path)
        date_text = ""

        try:
            date_text = time.strftime(
                "%d.%m.%Y",
                time.localtime(float(file_entry.get("mtime") or 0.0)),
            )
        except Exception:
            date_text = ""

        meta_parts = [
            value
            for value in (
                date_text,
                embyflow_local_human_size(file_entry.get("size")),
            )
            if value
        ]

        result.append({
            "kind": "movie",
            "title": title,
            "meta": " · ".join(meta_parts),
            "path": file_path,
            "mtime": file_entry.get("mtime"),
            "size": file_entry.get("size"),
            "poster": embyflow_local_v3_find_poster(
                file_path,
                title,
                poster_index,
            ),
        })

    return sorted(
        result,
        key=lambda entry: (
            -float(entry.get("mtime") or 0.0),
            str(entry.get("title") or "").casefold(),
        ),
    )


