def embyflow_local_v5_query_variants(value):
    raw = re.sub(r"\s+", " ", str(value or "")).strip()
    variants = []

    def add(candidate):
        candidate = re.sub(r"\s+", " ", str(candidate or "")).strip()
        if candidate and candidate.casefold() not in [
            item.casefold() for item in variants
        ]:
            variants.append(candidate)

    add(raw)

    for separator in (" - ", " – ", " — ", ": "):
        if separator in raw:
            add(raw.split(separator, 1)[0])

    normalized = embyflow_local_v4_normalize_title(raw)

    aliases = {
        "unter uns": ("Unter uns",),
        "expedition unknown mythen auf der spur": (
            "Expedition Unknown",
            "Expedition Unknown: Mythen auf der Spur",
        ),
        "goldrausch in alaska": (
            "Gold Rush",
            "Goldrausch in Alaska",
        ),
    }

    for alias in aliases.get(normalized, ()):
        add(alias)

    return variants


def embyflow_local_v5_search_item(
    session,
    server,
    token,
    user_id,
    title,
    mode,
):
    include_types = (
        "Series"
        if str(mode or "") == "series"
        else "Movie,Video"
    )

    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
        "Accept-Encoding": "identity",
    }

    roots = [str(server or "").rstrip("/")]

    if roots[0] and not roots[0].lower().endswith("/emby"):
        roots.append(roots[0] + "/emby")

    best = None

    for query in embyflow_local_v5_query_variants(title):
        for root in roots:
            try:
                response = session.get(
                    root + "/Users/%s/Items" % str(user_id),
                    headers=headers,
                    params={
                        "SearchTerm": query,
                        "Recursive": "true",
                        "Limit": "40",
                        "IncludeItemTypes": include_types,
                        "Fields": (
                            "ImageTags,PrimaryImageAspectRatio,"
                            "ProductionYear"
                        ),
                    },
                    timeout=(5, 18),
                    verify=True,
                )

                if int(response.status_code or 0) != 200:
                    continue

                for item in (
                    (response.json() or {}).get("Items", [])
                    or []
                ):
                    item_id = str(item.get("Id") or "").strip()

                    if not item_id:
                        continue

                    score = embyflow_local_v4_candidate_score(
                        title,
                        item,
                    )

                    if (
                        best is None
                        or int(score) > int(best[0])
                    ):
                        best = (
                            int(score),
                            item,
                            root,
                        )

            except Exception:
                continue

        if best is not None and int(best[0]) >= 95:
            break

    if best is None or int(best[0]) < 72:
        return None

    return {
        "score": int(best[0]),
        "item": best[1],
        "root": best[2],
    }


def embyflow_local_v5_normalize_poster(path):
    try:
        if (
            Image is None
            or not path
            or not os.path.isfile(path)
        ):
            return path

        image = Image.open(path)
        image.load()

        if image.mode not in ("RGB", "L"):
            image = image.convert("RGB")
        elif image.mode == "L":
            image = image.convert("RGB")

        width, height = image.size

        if width <= 0 or height <= 0:
            return path

        target_ratio = 2.0 / 3.0
        current_ratio = float(width) / float(height)

        if current_ratio > target_ratio:
            crop_width = int(round(height * target_ratio))
            left = max(0, int((width - crop_width) / 2))
            image = image.crop(
                (left, 0, left + crop_width, height)
            )
        elif current_ratio < target_ratio:
            crop_height = int(round(width / target_ratio))
            top = max(0, int((height - crop_height) / 2))
            image = image.crop(
                (0, top, width, top + crop_height)
            )

        try:
            resample = Image.Resampling.LANCZOS
        except Exception:
            resample = Image.LANCZOS

        image = image.resize(
            (440, 660),
            resample,
        )

        temporary = path + ".normalize"

        image.save(
            temporary,
            "JPEG",
            quality=90,
            optimize=True,
        )

        try:
            os.replace(temporary, path)
        except AttributeError:
            try:
                os.remove(path)
            except Exception:
                pass
            os.rename(temporary, path)

        return path

    except Exception:
        try:
            temporary = str(path or "") + ".normalize"
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass

        return path


def embyflow_local_v5_tvmaze_poster(
    session,
    title,
    cache_path,
):
    best = None

    for query in embyflow_local_v5_query_variants(title):
        try:
            response = session.get(
                "https://api.tvmaze.com/search/shows",
                params={"q": query},
                headers={
                    "User-Agent": (
                        "EmbyFlowE2-LocalPoster/5"
                    ),
                    "Accept-Encoding": "identity",
                },
                timeout=(5, 15),
                verify=True,
            )

            if int(response.status_code or 0) != 200:
                continue

            for result in response.json() or []:
                show = result.get("show") or {}
                show_name = str(show.get("name") or "")

                if not show_name:
                    continue

                score = embyflow_local_v4_candidate_score(
                    title,
                    {
                        "Name": show_name,
                        "ImageTags": {
                            "Primary": (
                                "tvmaze"
                                if show.get("image")
                                else ""
                            )
                        },
                    },
                )

                if (
                    best is None
                    or int(score) > int(best[0])
                ):
                    best = (
                        int(score),
                        show,
                    )

        except Exception:
            continue

        if best is not None and int(best[0]) >= 95:
            break

    if best is None or int(best[0]) < 78:
        return ""

    image_data = best[1].get("image") or {}
    image_url = str(
        image_data.get("original")
        or image_data.get("medium")
        or ""
    ).strip()

    if not image_url.startswith("https://"):
        return ""

    temporary = cache_path + ".download"

    try:
        response = session.get(
            image_url,
            headers={
                "User-Agent": (
                    "EmbyFlowE2-LocalPoster/5"
                ),
                "Accept-Encoding": "identity",
            },
            timeout=(5, 25),
            verify=True,
        )

        content_type = str(
            response.headers.get("Content-Type", "")
            if hasattr(response, "headers")
            else ""
        )

        if (
            int(response.status_code or 0) != 200
            or not response.content
            or len(response.content) <= 500
            or (
                content_type
                and not content_type.startswith("image/")
            )
        ):
            return ""

        with open(temporary, "wb") as handle:
            handle.write(response.content)
            handle.flush()

            try:
                os.fsync(handle.fileno())
            except Exception:
                pass

        if not embyflow_local_v4_file_valid(temporary):
            return ""

        try:
            os.replace(temporary, cache_path)
        except AttributeError:
            try:
                os.remove(cache_path)
            except Exception:
                pass
            os.rename(temporary, cache_path)

        embyflow_local_v5_normalize_poster(cache_path)
        embyflow_touch_cache_file(cache_path, 0)
        embyflow_request_cache_tune(
            "local-posters-tvmaze"
        )
        return cache_path

    except Exception:
        return ""

    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


_EMBYFLOW_LOCAL_V5_ORIGINAL_DOWNLOAD = (
    embyflow_local_v4_download_poster
)


def embyflow_local_v5_download_poster(
    session,
    server,
    token,
    user_id,
    mode,
    title,
):
    cache_path = embyflow_local_v4_cache_path(
        mode,
        title,
    )
    missing_path = embyflow_local_v4_missing_path(
        mode,
        title,
    )

    result = _EMBYFLOW_LOCAL_V5_ORIGINAL_DOWNLOAD(
        session,
        server,
        token,
        user_id,
        mode,
        title,
    )

    if result:
        embyflow_local_v5_normalize_poster(result)
        embyflow_clear_negative_cache(missing_path)
        return result

    embyflow_clear_negative_cache(missing_path)

    if str(mode or "") == "series":
        result = embyflow_local_v5_tvmaze_poster(
            session,
            title,
            cache_path,
        )

        if result:
            embyflow_clear_negative_cache(missing_path)
            return result

    embyflow_mark_negative_cache(
        missing_path,
        "no-emby-or-tvmaze-poster",
    )
    return ""


