def embyflow_local_v6_format_duration(seconds):
    try:
        value = max(0, int(seconds or 0))

        if value <= 0:
            return "–"

        hours = value // 3600
        minutes = (value % 3600) // 60
        remaining = value % 60

        if hours:
            return "%d:%02d:%02d" % (
                hours,
                minutes,
                remaining,
            )

        return "%d:%02d" % (
            minutes,
            remaining,
        )

    except Exception:
        return "–"


def embyflow_local_v6_read_meta(path):
    result = {
        "title": "",
        "description": "",
        "runtime_seconds": 0,
    }

    try:
        meta_path = str(path or "") + ".meta"

        if not os.path.isfile(meta_path):
            return result

        with open(
            meta_path,
            "r",
            encoding="utf-8",
            errors="replace",
        ) as handle:
            lines = [
                line.rstrip("\r\n")
                for line in handle.readlines()
            ]

        if len(lines) > 1:
            result["title"] = str(lines[1] or "").strip()

        if len(lines) > 2:
            result["description"] = str(
                lines[2] or ""
            ).strip()

        if len(lines) > 5:
            try:
                runtime_value = int(
                    str(lines[5] or "0").strip()
                    or 0
                )

                if 0 < runtime_value < 86400:
                    result["runtime_seconds"] = runtime_value
            except Exception:
                pass

    except Exception:
        pass

    return result


def embyflow_local_v6_read_cuts_resume(path):
    try:
        import struct

        cuts_path = str(path or "") + ".cuts"

        if not os.path.isfile(cuts_path):
            return 0

        resume_pts = 0

        with open(cuts_path, "rb") as handle:
            while True:
                chunk = handle.read(12)

                if len(chunk) < 12:
                    break

                pts, cut_type = struct.unpack(
                    ">QI",
                    chunk,
                )

                if int(cut_type) == 3:
                    resume_pts = max(
                        resume_pts,
                        int(pts or 0),
                    )

        if resume_pts <= 0:
            return 0

        return int(
            (resume_pts * 10000000) / 90000
        )

    except Exception:
        return 0


def embyflow_local_v6_episode_art(
    poster_path,
    series_title,
):
    try:
        poster = os.path.realpath(
            str(poster_path or "")
        )

        if (
            not poster
            or not os.path.isfile(poster)
            or os.path.getsize(poster) <= 500
        ):
            return ""

        if Image is None:
            return poster

        import hashlib

        ensure_dir(
            EMBYFLOW_LOCAL_EPISODE_ART_DIR_V6
        )

        stat_result = os.stat(poster)
        key_source = "%s|%s|%s|%s" % (
            poster,
            int(stat_result.st_mtime or 0),
            int(stat_result.st_size or 0),
            str(series_title or ""),
        )
        key = hashlib.sha1(
            key_source.encode(
                "utf-8",
                "ignore",
            )
        ).hexdigest()
        target = os.path.join(
            EMBYFLOW_LOCAL_EPISODE_ART_DIR_V6,
            key + ".jpg",
        )

        if (
            os.path.isfile(target)
            and os.path.getsize(target) > 500
        ):
            embyflow_touch_cache_file(target)
            return target

        image = Image.open(poster)
        image.load()
        image = image.convert("RGB")
        width, height = image.size

        if width <= 0 or height <= 0:
            return ""

        target_ratio = 16.0 / 9.0
        current_ratio = float(width) / float(height)

        if current_ratio > target_ratio:
            crop_width = int(
                round(height * target_ratio)
            )
            left = max(
                0,
                int((width - crop_width) / 2),
            )
            image = image.crop(
                (
                    left,
                    0,
                    left + crop_width,
                    height,
                )
            )
        elif current_ratio < target_ratio:
            crop_height = int(
                round(width / target_ratio)
            )
            top = max(
                0,
                int((height - crop_height) / 2),
            )
            image = image.crop(
                (
                    0,
                    top,
                    width,
                    top + crop_height,
                )
            )

        try:
            resample = Image.Resampling.LANCZOS
        except Exception:
            resample = Image.LANCZOS

        image = image.resize(
            (320, 180),
            resample,
        )

        temporary = target + ".tmp"
        image.save(
            temporary,
            "JPEG",
            quality=88,
            optimize=True,
        )

        try:
            os.replace(temporary, target)
        except AttributeError:
            try:
                os.remove(target)
            except Exception:
                pass
            os.rename(temporary, target)

        embyflow_touch_cache_file(target, 0)
        embyflow_request_cache_tune(
            "local-episode-art"
        )
        return target

    except Exception:
        try:
            temporary = str(target or "") + ".tmp"

            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass

        return ""


def embyflow_local_v6_prepare_episode(
    raw_entry,
    series_title,
    resume_map,
):
    entry = dict(raw_entry or {})
    path = os.path.realpath(
        str(entry.get("path") or "")
    )

    title_from_name, date_text, time_text = (
        embyflow_local_v3_recording_parts(path)
    )
    meta = embyflow_local_v6_read_meta(path)
    item_id = "local:" + path
    resume_data = (
        (resume_map or {}).get(item_id)
        or {}
    )

    try:
        position_ticks = int(
            resume_data.get("position_ticks")
            or 0
        )
    except Exception:
        position_ticks = 0

    try:
        runtime_ticks = int(
            resume_data.get("runtime_ticks")
            or 0
        )
    except Exception:
        runtime_ticks = 0

    if position_ticks <= 0:
        position_ticks = (
            embyflow_local_v6_read_cuts_resume(
                path
            )
        )

    if (
        runtime_ticks <= 0
        and int(
            meta.get("runtime_seconds")
            or 0
        ) > 0
    ):
        runtime_ticks = int(
            meta.get("runtime_seconds")
        ) * 10000000

    runtime_seconds = int(
        runtime_ticks / 10000000
    ) if runtime_ticks > 0 else 0
    position_seconds = int(
        position_ticks / 10000000
    ) if position_ticks > 0 else 0

    progress = 0

    if runtime_ticks > 0 and position_ticks > 0:
        progress = max(
            0,
            min(
                100,
                int(
                    round(
                        100.0
                        * float(position_ticks)
                        / float(runtime_ticks)
                    )
                ),
            ),
        )

    if (
        position_ticks >= 300000000
        and (
            (
                runtime_ticks > 0
                and position_ticks >= max(
                    0,
                    runtime_ticks - 600000000,
                )
            )
            or progress >= 95
        )
    ):
        state = "seen"
        progress = 100
    elif position_ticks >= 300000000:
        state = "started"
    else:
        state = "unseen"
        progress = 0

    if not date_text:
        try:
            date_text = time.strftime(
                "%d.%m.%Y",
                time.localtime(
                    float(entry.get("mtime") or 0.0)
                ),
            )
        except Exception:
            date_text = ""

    if not time_text:
        try:
            time_text = time.strftime(
                "%H:%M",
                time.localtime(
                    float(entry.get("mtime") or 0.0)
                ),
            )
        except Exception:
            time_text = ""

    display_title = str(
        meta.get("title")
        or title_from_name
        or series_title
        or "Aufnahme"
    ).strip()

    description = str(
        meta.get("description")
        or ""
    ).strip()

    if (
        description.casefold()
        == display_title.casefold()
    ):
        description = ""

    entry.update({
        "kind": "episode",
        "path": path,
        "item_id": item_id,
        "display_title": display_title,
        "description": description,
        "date_text": date_text,
        "time_text": time_text,
        "runtime_ticks": runtime_ticks,
        "runtime_seconds": runtime_seconds,
        "position_ticks": position_ticks,
        "position_seconds": position_seconds,
        "duration_text": (
            embyflow_local_v6_format_duration(
                runtime_seconds
            )
        ),
        "size_text": embyflow_local_human_size(
            entry.get("size")
        ),
        "progress": progress,
        "state": state,
    })

    return entry


