# EMBYFLOW_LOCAL_EPISODE_CARDS_V7_START
# Eigenständige EmbyFlow-Aufnahmenansicht ohne Episodenbilder.
# Es werden ausschließlich lokale .meta/.eit/.cuts-Daten und der
# EmbyFlow-Fortschritt verwendet. Kein EMC-Code und keine EMC-Grafiken.
EMBYFLOW_LOCAL_EPISODE_PAGE_SIZE_V7 = 8
EMBYFLOW_LOCAL_EPISODE_SORTS_V7 = EMBYFLOW_LOCAL_EPISODE_SORTS_V6
EMBYFLOW_LOCAL_EPISODE_FILTERS_V7 = EMBYFLOW_LOCAL_EPISODE_FILTERS_V6


def embyflow_local_v7_clean_text(value):
    try:
        text = str(value or "").replace("\r", "\n")
        lines = []

        for line in text.split("\n"):
            cleaned = re.sub(r"\s+", " ", line).strip()

            if cleaned:
                lines.append(cleaned)

        return "\n".join(lines).strip()
    except Exception:
        return str(value or "").strip()


def embyflow_local_v7_decode_dvb_text(data):
    try:
        raw = bytes(data or b"")

        if not raw:
            return ""

        encoding = "cp1252"
        payload = raw
        first = raw[0]

        iso_map = {
            0x01: "iso8859_5",
            0x02: "iso8859_6",
            0x03: "iso8859_7",
            0x04: "iso8859_8",
            0x05: "iso8859_9",
            0x06: "iso8859_10",
            0x07: "iso8859_11",
            0x09: "iso8859_13",
            0x0A: "iso8859_14",
            0x0B: "iso8859_15",
        }

        if first in iso_map:
            encoding = iso_map[first]
            payload = raw[1:]
        elif first == 0x10 and len(raw) >= 3 and raw[1] == 0x00:
            table = int(raw[2] or 0)
            encoding = "iso8859_%d" % table if 1 <= table <= 16 else "cp1252"
            payload = raw[3:]
        elif first == 0x11:
            encoding = "utf_16_be"
            payload = raw[1:]
        elif first == 0x13:
            encoding = "gb2312"
            payload = raw[1:]
        elif first == 0x14:
            encoding = "big5"
            payload = raw[1:]
        elif first == 0x15:
            encoding = "utf_8"
            payload = raw[1:]

        try:
            text = payload.decode(encoding, "replace")
        except Exception:
            text = payload.decode("cp1252", "replace")

        text = text.replace("\x8a", "\n")
        text = "".join(
            character
            if character in ("\n", "\t") or ord(character) >= 32
            else " "
            for character in text
        )
        return embyflow_local_v7_clean_text(text)

    except Exception:
        return ""


def embyflow_local_v7_bcd(value):
    try:
        number = int(value or 0)
        return ((number >> 4) * 10) + (number & 0x0F)
    except Exception:
        return 0


def embyflow_local_v7_content_label(code):
    labels = {
        0x10: "Film / Drama",
        0x11: "Krimi / Thriller",
        0x12: "Abenteuer / Western / Krieg",
        0x13: "Science-Fiction / Fantasy / Horror",
        0x14: "Komödie",
        0x15: "Soap / Melodram",
        0x16: "Romanze",
        0x17: "Historisch / Religion",
        0x18: "Erwachsenenfilm",
        0x20: "Nachrichten",
        0x21: "Nachrichten / Wetter",
        0x22: "Magazin",
        0x23: "Dokumentation",
        0x30: "Show",
        0x31: "Gameshow / Quiz",
        0x32: "Varieté",
        0x33: "Talkshow",
        0x40: "Sport",
        0x50: "Kinder / Jugend",
        0x60: "Musik / Tanz",
        0x70: "Kultur",
        0x80: "Gesellschaft / Politik",
        0x90: "Bildung / Wissenschaft",
        0xA0: "Freizeit / Hobby",
    }

    try:
        value = int(code or 0) & 0xFF

        if value in labels:
            return labels[value]

        return labels.get(value & 0xF0, "")
    except Exception:
        return ""


def embyflow_local_v7_eit_candidates(path):
    file_path = str(path or "")
    stem, _extension = os.path.splitext(file_path)
    values = []

    for candidate in (
        file_path + ".eit",
        stem + ".eit",
    ):
        if candidate and candidate not in values:
            values.append(candidate)

    return values


def embyflow_local_v7_read_eit(path):
    result = {
        "event_name": "",
        "short_text": "",
        "extended_text": "",
        "runtime_seconds": 0,
        "genre": "",
        "genre_level1": -1,
        "genre_level2": -1,
        "parental_age": 0,
        "path": "",
    }

    try:
        eit_path = ""

        for candidate in embyflow_local_v7_eit_candidates(path):
            if os.path.isfile(candidate) and os.path.getsize(candidate) >= 12:
                eit_path = candidate
                break

        if not eit_path:
            return result

        with open(eit_path, "rb") as handle:
            data = handle.read(1024 * 1024)

        if len(data) < 12:
            return result

        result["path"] = eit_path
        duration = data[7:10]

        if len(duration) == 3:
            result["runtime_seconds"] = (
                embyflow_local_v7_bcd(duration[0]) * 3600
                + embyflow_local_v7_bcd(duration[1]) * 60
                + embyflow_local_v7_bcd(duration[2])
            )

        descriptor_length = (
            ((int(data[10]) & 0x0F) << 8)
            | int(data[11])
        )
        end = min(len(data), 12 + descriptor_length)
        position = 12
        extended_parts = {}
        genre = ""
        genre_level1 = -1
        genre_level2 = -1
        parental_age = 0

        while position + 2 <= end:
            tag = int(data[position])
            length = int(data[position + 1])
            payload_start = position + 2
            payload_end = min(end, payload_start + length)
            payload = data[payload_start:payload_end]
            position = payload_end

            if len(payload) < length:
                break

            if tag == 0x4D and len(payload) >= 5:
                name_length = int(payload[3])
                name_start = 4
                name_end = min(len(payload), name_start + name_length)
                event_name = embyflow_local_v7_decode_dvb_text(
                    payload[name_start:name_end]
                )
                text_length_position = name_end
                short_text = ""

                if text_length_position < len(payload):
                    text_length = int(payload[text_length_position])
                    text_start = text_length_position + 1
                    text_end = min(len(payload), text_start + text_length)
                    short_text = embyflow_local_v7_decode_dvb_text(
                        payload[text_start:text_end]
                    )

                if event_name:
                    result["event_name"] = event_name

                if short_text:
                    result["short_text"] = short_text

            elif tag == 0x4E and len(payload) >= 6:
                descriptor_number = (int(payload[0]) >> 4) & 0x0F
                items_length = int(payload[4])
                text_length_position = 5 + items_length

                if text_length_position < len(payload):
                    text_length = int(payload[text_length_position])
                    text_start = text_length_position + 1
                    text_end = min(len(payload), text_start + text_length)
                    text_value = embyflow_local_v7_decode_dvb_text(
                        payload[text_start:text_end]
                    )

                    if text_value:
                        extended_parts[descriptor_number] = text_value

            elif tag == 0x54:
                for index in range(0, len(payload) - 1, 2):
                    content_byte = int(payload[index])
                    candidate_level1 = (content_byte >> 4) & 0x0F
                    candidate_level2 = content_byte & 0x0F
                    candidate_genre = embyflow_local_v7_content_label(
                        content_byte
                    )

                    if genre_level1 < 0 or candidate_level1 == 0x01:
                        genre_level1 = candidate_level1
                        genre_level2 = candidate_level2

                    if candidate_genre:
                        genre = candidate_genre

                    if candidate_level1 == 0x01:
                        break

            elif tag == 0x55:
                for index in range(0, len(payload) - 3, 4):
                    rating = int(payload[index + 3])

                    if 0x01 <= rating <= 0x0F:
                        parental_age = max(parental_age, rating + 3)

        if extended_parts:
            result["extended_text"] = embyflow_local_v7_clean_text(
                " ".join(
                    extended_parts[index]
                    for index in sorted(extended_parts)
                )
            )

        result["genre"] = genre
        result["genre_level1"] = genre_level1
        result["genre_level2"] = genre_level2
        result["parental_age"] = parental_age

    except Exception:
        pass

    return result


def embyflow_local_v7_read_meta(path):
    result = {
        "service_reference": "",
        "title": "",
        "description": "",
        "tags": "",
        "runtime_seconds": 0,
        "service_name": "",
    }

    try:
        meta_path = str(path or "") + ".meta"

        if not os.path.isfile(meta_path):
            return result

        with open(
            meta_path,
            "r",
            encoding="utf-8",
            errors="replace",
        ) as handle:
            lines = [line.rstrip("\r\n") for line in handle]

        names = (
            "service_reference",
            "title",
            "description",
        )

        for index, name in enumerate(names):
            if index < len(lines):
                result[name] = str(lines[index] or "").strip()

        if len(lines) > 4:
            result["tags"] = str(lines[4] or "").strip()

        if len(lines) > 5:
            try:
                runtime = int(str(lines[5] or "0").strip() or 0)

                if 0 < runtime < 86400:
                    result["runtime_seconds"] = runtime
            except Exception:
                pass

        if len(lines) > 6:
            result["service_name"] = str(lines[6] or "").strip()

    except Exception:
        pass

    return result


def embyflow_local_v7_prepare_episode(raw_entry, series_title, resume_map):
    entry = embyflow_local_v6_prepare_episode(
        raw_entry,
        series_title,
        resume_map,
    )
    path = str(entry.get("path") or "")
    meta = embyflow_local_v7_read_meta(path)
    eit = embyflow_local_v7_read_eit(path)
    event_name = embyflow_local_v7_clean_text(
        eit.get("event_name") or meta.get("title") or series_title
    )
    short_text = embyflow_local_v7_clean_text(
        eit.get("short_text") or meta.get("description")
    )
    extended_text = embyflow_local_v7_clean_text(
        eit.get("extended_text")
    )

    if short_text and short_text.casefold() != event_name.casefold():
        episode_title = short_text
    else:
        episode_title = event_name or str(entry.get("display_title") or "Aufnahme")

    runtime_seconds = int(entry.get("runtime_seconds") or 0)

    if runtime_seconds <= 0:
        runtime_seconds = int(
            eit.get("runtime_seconds")
            or meta.get("runtime_seconds")
            or 0
        )

    runtime_ticks = int(entry.get("runtime_ticks") or 0)

    if runtime_ticks <= 0 and runtime_seconds > 0:
        runtime_ticks = runtime_seconds * 10000000

    position_ticks = int(entry.get("position_ticks") or 0)
    progress = int(entry.get("progress") or 0)
    state = str(entry.get("state") or "unseen")

    if runtime_ticks > 0 and position_ticks > 0:
        progress = max(
            0,
            min(100, int(round(100.0 * float(position_ticks) / float(runtime_ticks))))
        )

        if progress >= 95 or position_ticks >= max(0, runtime_ticks - 600000000):
            state = "seen"
            progress = 100
        elif position_ticks >= 300000000:
            state = "started"

    source = ""

    if eit.get("path"):
        source = "EIT"
    elif meta.get("title") or meta.get("description"):
        source = "META"
    else:
        source = "Dateiname"

    summary = extended_text

    if not summary:
        summary = "Keine ausführliche EPG-Beschreibung gespeichert."

    entry.update({
        "display_title": episode_title,
        "series_name": event_name or str(series_title or ""),
        "description": summary,
        "epg_description": extended_text,
        "epg_source": source,
        "service_name": str(meta.get("service_name") or "").strip(),
        "service_reference": str(meta.get("service_reference") or "").strip(),
        "tags": str(meta.get("tags") or "").strip(),
        "genre": str(eit.get("genre") or "").strip(),
        "parental_age": int(eit.get("parental_age") or 0),
        "runtime_seconds": runtime_seconds,
        "runtime_ticks": runtime_ticks,
        "duration_text": embyflow_local_v6_format_duration(runtime_seconds),
        "progress": progress,
        "state": state,
    })
    return entry


