def _embyflow_local_v8_set_label(owner, name, value):
    try:
        widget = owner[name]
        widget.setText(str(value or ""))
        widget.show()

        try:
            if widget.instance is not None:
                widget.instance.show()
                widget.instance.invalidate()
        except Exception:
            pass

        return True
    except Exception:
        return False


def _embyflow_local_v8_update_header(self):
    _sort_key, sort_label = self.current_sort()
    _filter_key, filter_label = self.current_filter()
    _embyflow_local_v8_set_label(self, "title", self.title_text)
    _embyflow_local_v8_set_label(
        self,
        "subtitle",
        "%d Aufnahmen · %s · %s" % (
            len(self.entries),
            sort_label,
            filter_label,
        ),
    )


def _embyflow_local_v8_update_detail(self):
    entry = self.selected_entry()

    if not entry:
        for name in (
            "detail_title",
            "detail_series",
            "detail_meta",
            "detail_description",
            "detail_info",
        ):
            _embyflow_local_v8_set_label(self, name, "")
        return

    title = str(entry.get("display_title") or "Aufnahme")
    series_name = str(entry.get("series_name") or self.title_text)
    detail_meta = " · ".join(
        value
        for value in (
            str(entry.get("date_text") or ""),
            str(entry.get("time_text") or ""),
            str(entry.get("duration_text") or "–"),
            str(entry.get("size_text") or ""),
        )
        if value
    )
    description = str(entry.get("description") or "").strip()

    if not description:
        description = "Keine ausführliche EPG-Beschreibung gespeichert."

    state_text, _state_color = self.state_style(entry)
    position_text = embyflow_local_v6_format_duration(
        int(entry.get("position_seconds") or 0)
    )
    runtime_text = str(entry.get("duration_text") or "–")
    service_name = str(entry.get("service_name") or "–")
    genre = str(entry.get("genre") or entry.get("tags") or "–")
    source = str(entry.get("epg_source") or "Dateiname")
    info = (
        "Status: %s · Gesehen: %s von %s\n"
        "Sender: %s · Genre: %s · Quelle: %s"
        % (
            state_text,
            position_text,
            runtime_text,
            service_name,
            genre,
            source,
        )
    )

    _embyflow_local_v8_set_label(self, "detail_title", title)
    _embyflow_local_v8_set_label(self, "detail_series", series_name)
    _embyflow_local_v8_set_label(self, "detail_meta", detail_meta)
    _embyflow_local_v8_set_label(self, "detail_description", description)
    _embyflow_local_v8_set_label(self, "detail_info", info)


def _embyflow_local_v8_refresh(self):
    total = len(self.entries)

    if total:
        self.selected_index = max(0, min(self.selected_index, total - 1))
    else:
        self.selected_index = 0

    page_start = (self.selected_index // self.PAGE_SIZE) * self.PAGE_SIZE

    for slot in range(self.PAGE_SIZE):
        actual_index = page_start + slot
        widgets = {
            "bg": self["v7_card%d_bg" % slot],
            "date": self["v7_card%d_date" % slot],
            "title": self["v7_card%d_title" % slot],
            "series": self["v7_card%d_series" % slot],
            "summary": self["v7_card%d_summary" % slot],
            "meta": self["v7_card%d_meta" % slot],
            "progress_bg": self["v7_card%d_progress_bg" % slot],
            "progress_fill": self["v7_card%d_progress_fill" % slot],
            "status": self["v7_card%d_status" % slot],
        }

        if actual_index >= total:
            for widget in widgets.values():
                try:
                    widget.hide()
                except Exception:
                    pass
            continue

        entry = self.entries[actual_index]

        for name, widget in widgets.items():
            try:
                if name == "summary":
                    widget.setText("")
                    widget.hide()
                elif name != "progress_fill":
                    widget.show()
            except Exception:
                pass

        date_text = " · ".join(
            value
            for value in (
                str(entry.get("date_text") or ""),
                str(entry.get("time_text") or ""),
            )
            if value
        )
        widgets["date"].setText(date_text)
        widgets["title"].setText(str(entry.get("display_title") or "Aufnahme")[:86])
        widgets["series"].setText(str(entry.get("series_name") or self.title_text)[:70])
        widgets["meta"].setText(
            " · ".join(
                value
                for value in (
                    str(entry.get("duration_text") or "–"),
                    str(entry.get("size_text") or ""),
                )
                if value
            )
        )
        status_text, status_color = self.state_style(entry)
        widgets["status"].setText(status_text)

        try:
            widgets["status"].instance.setForegroundColor(parseColor(status_color))
        except Exception:
            pass

        progress = max(0, min(100, int(entry.get("progress") or 0)))

        if progress > 0:
            widgets["progress_bg"].show()
            widgets["progress_fill"].show()

            try:
                widgets["progress_fill"].instance.resize(
                    EFS(max(1, int(round(205.0 * float(progress) / 100.0))), 10)
                )
                widgets["progress_fill"].instance.setBackgroundColor(
                    parseColor(status_color)
                )
            except Exception:
                pass
        else:
            widgets["progress_bg"].hide()
            widgets["progress_fill"].hide()

    try:
        focus_slot = self.selected_index - page_start
        x, y = _EMBYFLOW_LOCAL_EPISODE_CARD_POSITIONS_V8[focus_slot]
        parts = (
            ("focus_top", x - 4, y - 4, 294, 4),
            ("focus_bottom", x - 4, y + 252, 294, 4),
            ("focus_left", x - 4, y - 4, 4, 260),
            ("focus_right", x + 286, y - 4, 4, 260),
        )

        for name, x_value, y_value, width, height in parts:
            instance = self[name].instance

            if total and instance is not None:
                instance.move(EFP(x_value, y_value))
                instance.resize(EFS(width, height))
                instance.show()
            elif instance is not None:
                instance.hide()
    except Exception:
        pass

    if total:
        current_page = (page_start // self.PAGE_SIZE) + 1
        page_count = ((total - 1) // self.PAGE_SIZE) + 1
        _embyflow_local_v8_set_label(
            self,
            "page",
            "Seite %d/%d" % (current_page, page_count),
        )
        self["status"].setText("")
    else:
        _embyflow_local_v8_set_label(self, "page", "Seite 0/0")
        self["status"].setText("Keine Aufnahmen in diesem Filter")

    _embyflow_local_v8_update_header(self)
    # EMBYFLOW_LOCAL_RECORDING_SOURCE_REFRESH_V13
    # Späte Methodenauflösung, damit V12 die Senderquelle einsetzen kann.
    self.update_detail()


