def embyflow_local_v9_resolve_series_poster(owner):
    try:
        candidates = [str(getattr(owner, "poster_path", "") or "")]

        try:
            candidates.append(
                embyflow_local_v4_cached_poster(
                    "series",
                    getattr(owner, "title_text", ""),
                )
            )
        except Exception:
            pass

        try:
            poster_index = embyflow_local_v3_image_index("/media/usb/poster")
            candidates.append(
                embyflow_local_v3_find_poster(
                    getattr(owner, "root_path", "/media/usb/Serien"),
                    getattr(owner, "title_text", ""),
                    poster_index,
                )
            )
        except Exception:
            pass

        for candidate in candidates:
            path = str(candidate or "")

            if (
                path
                and os.path.isfile(path)
                and os.path.getsize(path) > 500
            ):
                return path
    except Exception:
        pass

    return ""


def _embyflow_local_v9_init(self, *args, **kwargs):
    _EMBYFLOW_LOCAL_V9_ORIGINAL_INIT(self, *args, **kwargs)
    self["detail_poster"] = Pixmap()
    self["detail_poster_fallback"] = Label("SERIE")

    for index in range(self.PAGE_SIZE):
        self["v9_card%d_poster" % index] = Pixmap()
        self["v9_card%d_poster_fallback" % index] = Label("SERIE")

    self.embyflow_local_v9_poster_requests = set()
    self.embyflow_local_v9_poster_path = ""


def _embyflow_local_v9_show_fallback(owner, pixmap_name, fallback_name, visible=True):
    try:
        owner[pixmap_name].hide()
    except Exception:
        pass

    try:
        if visible:
            owner[fallback_name].setText("SERIE")
            owner[fallback_name].show()
        else:
            owner[fallback_name].hide()
    except Exception:
        pass


def _embyflow_local_v9_decode(owner, widget_name, path, width, height):
    key = "%s|%s|%sx%s" % (widget_name, path, width, height)

    if key in owner.embyflow_local_v9_poster_requests:
        try:
            owner[widget_name].show()
        except Exception:
            pass
        return True

    accepted = embyflow_decode_image_to_widget(
        owner,
        widget_name,
        path,
        width,
        height,
        token="local-v9-%s" % key,
        is_current=lambda: (
            not getattr(owner, "closed_v7", False)
            and str(getattr(owner, "embyflow_local_v9_poster_path", "") or "") == path
        ),
    )

    if accepted:
        owner.embyflow_local_v9_poster_requests.add(key)

    return bool(accepted)


def _embyflow_local_v9_apply_posters(self):
    poster_path = embyflow_local_v9_resolve_series_poster(self)
    self.embyflow_local_v9_poster_path = poster_path
    total = len(self.entries)
    page_start = (self.selected_index // self.PAGE_SIZE) * self.PAGE_SIZE if total else 0

    if poster_path:
        try:
            self["detail_poster_fallback"].hide()
            self["detail_poster"].show()
        except Exception:
            pass

        _embyflow_local_v9_decode(
            self,
            "detail_poster",
            poster_path,
            EMBYFLOW_LOCAL_EPISODE_POSTER_DETAIL_W_V9,
            EMBYFLOW_LOCAL_EPISODE_POSTER_DETAIL_H_V9,
        )
    else:
        _embyflow_local_v9_show_fallback(
            self,
            "detail_poster",
            "detail_poster_fallback",
            True,
        )

    for slot in range(self.PAGE_SIZE):
        actual_index = page_start + slot
        pixmap_name = "v9_card%d_poster" % slot
        fallback_name = "v9_card%d_poster_fallback" % slot

        if actual_index >= total:
            _embyflow_local_v9_show_fallback(
                self,
                pixmap_name,
                fallback_name,
                False,
            )
            continue

        if poster_path:
            try:
                self[fallback_name].hide()
                self[pixmap_name].show()
            except Exception:
                pass

            _embyflow_local_v9_decode(
                self,
                pixmap_name,
                poster_path,
                EMBYFLOW_LOCAL_EPISODE_POSTER_CARD_W_V9,
                EMBYFLOW_LOCAL_EPISODE_POSTER_CARD_H_V9,
            )
        else:
            _embyflow_local_v9_show_fallback(
                self,
                pixmap_name,
                fallback_name,
                True,
            )


def _embyflow_local_v9_refresh(self):
    _EMBYFLOW_LOCAL_V9_ORIGINAL_REFRESH(self)
    _embyflow_local_v9_apply_posters(self)


def _embyflow_local_v9_update_detail(self):
    _EMBYFLOW_LOCAL_V9_ORIGINAL_UPDATE_DETAIL(self)
    _embyflow_local_v9_apply_posters(self)


