def embyflow_local_v10_thumb_key(entry):
    try:
        path = os.path.realpath(str((entry or {}).get("path") or ""))
        stat_result = os.stat(path)
        raw = "%s|%s|%s" % (
            path,
            int(stat_result.st_size or 0),
            int(stat_result.st_mtime or 0),
        )
        import hashlib
        return hashlib.sha1(
            raw.encode("utf-8", "ignore")
        ).hexdigest()
    except Exception:
        return ""


def embyflow_local_v10_thumb_path(entry):
    key = embyflow_local_v10_thumb_key(entry)

    if not key:
        return ""

    return os.path.join(
        EMBYFLOW_LOCAL_EPISODE_THUMB_CACHE_DIR_V10,
        key + ".jpg",
    )


def embyflow_local_v10_thumb_missing_path(entry):
    path = embyflow_local_v10_thumb_path(entry)
    return path + ".missing" if path else ""


def embyflow_local_v10_thumb_valid(path):
    try:
        candidate = str(path or "")

        if (
            not candidate
            or not os.path.isfile(candidate)
            or os.path.getsize(candidate) <= 500
        ):
            return False

        with open(candidate, "rb") as handle:
            return handle.read(2) == b"\xff\xd8"
    except Exception:
        return False


def embyflow_local_v10_cached_thumb(entry):
    path = embyflow_local_v10_thumb_path(entry)

    if embyflow_local_v10_thumb_valid(path):
        embyflow_touch_cache_file(path)
        return path

    return ""


def embyflow_local_v10_generate_thumb(owner, entry):
    path = os.path.realpath(str((entry or {}).get("path") or ""))
    cache_path = embyflow_local_v10_thumb_path(entry)
    missing_path = embyflow_local_v10_thumb_missing_path(entry)

    if not path or not os.path.isfile(path) or not cache_path:
        return ""

    if embyflow_local_v10_thumb_valid(cache_path):
        return cache_path

    if embyflow_negative_cache_active(
        missing_path,
        EMBYFLOW_LOCAL_EPISODE_THUMB_NEGATIVE_TTL_V10,
    ):
        return ""

    ffmpeg_path = "/usr/bin/ffmpeg"

    if not os.path.isfile(ffmpeg_path):
        embyflow_mark_negative_cache(
            missing_path,
            "ffmpeg-fehlt",
        )
        return ""

    ensure_dir(EMBYFLOW_LOCAL_EPISODE_THUMB_CACHE_DIR_V10)
    temporary = cache_path + ".tmp.jpg"
    attempts = (90, 60, 20)
    last_return_code = -1

    try:
        import subprocess

        for seek_seconds in attempts:
            if getattr(owner, "embyflow_local_v10_closed", False):
                break

            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except Exception:
                pass

            command = [
                "/usr/bin/nice",
                "-n",
                "15",
                ffmpeg_path,
                "-nostdin",
                "-hide_banner",
                "-loglevel",
                "error",
                "-ss",
                str(int(seek_seconds)),
                "-i",
                path,
                "-map",
                "0:v:0",
                "-frames:v",
                "1",
                "-an",
                "-sn",
                "-dn",
                "-vf",
                (
                    "scale=%d:%d:force_original_aspect_ratio=decrease,"
                    "pad=%d:%d:(ow-iw)/2:(oh-ih)/2:black"
                    % (
                        EMBYFLOW_LOCAL_EPISODE_THUMB_W_V10,
                        EMBYFLOW_LOCAL_EPISODE_THUMB_H_V10,
                        EMBYFLOW_LOCAL_EPISODE_THUMB_W_V10,
                        EMBYFLOW_LOCAL_EPISODE_THUMB_H_V10,
                    )
                ),
                "-q:v",
                "4",
                "-y",
                temporary,
            ]

            if not os.path.isfile(command[0]):
                command = [ffmpeg_path] + command[4:]

            devnull = open(os.devnull, "wb")

            try:
                process = subprocess.Popen(
                    command,
                    stdout=devnull,
                    stderr=devnull,
                )
                owner.embyflow_local_v10_process = process

                try:
                    last_return_code = process.wait(timeout=45)
                except Exception:
                    try:
                        process.terminate()
                    except Exception:
                        pass

                    try:
                        last_return_code = process.wait(timeout=5)
                    except Exception:
                        try:
                            process.kill()
                        except Exception:
                            pass
                        last_return_code = -9
            finally:
                try:
                    devnull.close()
                except Exception:
                    pass

                owner.embyflow_local_v10_process = None

            if (
                int(last_return_code or 0) == 0
                and embyflow_local_v10_thumb_valid(temporary)
            ):
                try:
                    os.replace(temporary, cache_path)
                except AttributeError:
                    try:
                        os.remove(cache_path)
                    except Exception:
                        pass
                    os.rename(temporary, cache_path)

                embyflow_clear_negative_cache(missing_path)
                embyflow_touch_cache_file(cache_path, 0)
                embyflow_request_cache_tune(
                    "local-episode-thumbs"
                )
                return cache_path

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_episode_thumb_error.log",
                "a",
            ) as log:
                log.write(
                    "%s path=%s error=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        path,
                        str(error),
                    )
                )
        except Exception:
            pass

    try:
        if os.path.exists(temporary):
            os.remove(temporary)
    except Exception:
        pass

    embyflow_mark_negative_cache(
        missing_path,
        "ffmpeg-rc-%s" % str(last_return_code),
    )
    return ""


_EMBYFLOW_LOCAL_V10_ORIGINAL_INIT = (
    EmbyFlowLocalEpisodesScreenV7.__init__
)
_EMBYFLOW_LOCAL_V10_BASE_REFRESH = (
    _EMBYFLOW_LOCAL_V9_ORIGINAL_REFRESH
)
_EMBYFLOW_LOCAL_V10_BASE_UPDATE_DETAIL = (
    _EMBYFLOW_LOCAL_V9_ORIGINAL_UPDATE_DETAIL
)


def _embyflow_local_v10_init(self, *args, **kwargs):
    _EMBYFLOW_LOCAL_V10_ORIGINAL_INIT(
        self,
        *args,
        **kwargs
    )

    for index in range(self.PAGE_SIZE):
        self["v10_card%d_thumb" % index] = Pixmap()
        self["v10_card%d_thumb_fallback" % index] = Label(
            "VORSCHAU"
        )

    self.embyflow_local_v10_closed = False
    self.embyflow_local_v10_pending = []
    self.embyflow_local_v10_results = []
    self.embyflow_local_v10_fetching = set()
    self.embyflow_local_v10_worker_running = False
    self.embyflow_local_v10_process = None
    self.embyflow_local_v10_loaded_slots = {}
    self.embyflow_local_v10_lock = None
    self.embyflow_local_v10_timer = eTimer()

    try:
        import threading
        self.embyflow_local_v10_lock = threading.RLock()
    except Exception:
        self.embyflow_local_v10_lock = None

    try:
        self.embyflow_local_v10_timer.callback.append(
            self.embyflow_local_v10_poll
        )
    except Exception:
        try:
            self.embyflow_local_v10_timer_connection = (
                self.embyflow_local_v10_timer.timeout.connect(
                    self.embyflow_local_v10_poll
                )
            )
        except Exception:
            self.embyflow_local_v10_timer_connection = None

    self.onClose.append(
        self.embyflow_local_v10_cleanup
    )


def _embyflow_local_v10_cleanup(self):
    self.embyflow_local_v10_closed = True

    try:
        self.embyflow_local_v10_timer.stop()
    except Exception:
        pass

    try:
        if self.embyflow_local_v10_lock:
            with self.embyflow_local_v10_lock:
                self.embyflow_local_v10_pending[:] = []
        else:
            self.embyflow_local_v10_pending[:] = []
    except Exception:
        pass

    process = getattr(
        self,
        "embyflow_local_v10_process",
        None,
    )

    if process is not None:
        try:
            process.terminate()
        except Exception:
            pass


def _embyflow_local_v10_apply_detail_poster(self):
    poster_path = embyflow_local_v9_resolve_series_poster(self)
    self.embyflow_local_v9_poster_path = poster_path

    if poster_path:
        try:
            self["detail_poster_fallback"].hide()
            self["detail_poster"].show()
        except Exception:
            pass

        _embyflow_local_v9_decode(
            self,
            "detail_poster",
            poster_path,
            EMBYFLOW_LOCAL_EPISODE_POSTER_DETAIL_W_V9,
            EMBYFLOW_LOCAL_EPISODE_POSTER_DETAIL_H_V9,
        )
    else:
        _embyflow_local_v9_show_fallback(
            self,
            "detail_poster",
            "detail_poster_fallback",
            True,
        )


def _embyflow_local_v10_show_thumb_fallback(
    owner,
    slot,
    visible=True,
):
    pixmap_name = "v10_card%d_thumb" % slot
    fallback_name = "v10_card%d_thumb_fallback" % slot

    try:
        owner[pixmap_name].hide()
    except Exception:
        pass

    try:
        if visible:
            owner[fallback_name].setText("VORSCHAU")
            owner[fallback_name].show()
        else:
            owner[fallback_name].hide()
    except Exception:
        pass


def _embyflow_local_v10_apply_thumbs(self):
    total = len(self.entries)
    page_start = (
        (self.selected_index // self.PAGE_SIZE) * self.PAGE_SIZE
        if total
        else 0
    )

    for slot in range(self.PAGE_SIZE):
        actual_index = page_start + slot
        pixmap_name = "v10_card%d_thumb" % slot
        fallback_name = "v10_card%d_thumb_fallback" % slot

        try:
            self["v7_card%d_series" % slot].hide()
            self["v7_card%d_summary" % slot].hide()
        except Exception:
            pass

        try:
            self["v9_card%d_poster" % slot].hide()
            self["v9_card%d_poster_fallback" % slot].hide()
        except Exception:
            pass

        if actual_index >= total:
            _embyflow_local_v10_show_thumb_fallback(
                self,
                slot,
                False,
            )
            self.embyflow_local_v10_loaded_slots.pop(
                slot,
                None,
            )
            continue

        entry = self.entries[actual_index]
        thumb_path = str(
            entry.get("local_episode_thumb")
            or embyflow_local_v10_cached_thumb(entry)
            or ""
        )

        if thumb_path:
            entry["local_episode_thumb"] = thumb_path

            try:
                self[fallback_name].hide()
                self[pixmap_name].show()
            except Exception:
                pass

            loaded = self.embyflow_local_v10_loaded_slots.get(
                slot
            )

            if loaded != thumb_path:
                entry_key = embyflow_local_v10_thumb_key(entry)
                accepted = embyflow_decode_image_to_widget(
                    self,
                    pixmap_name,
                    thumb_path,
                    EMBYFLOW_LOCAL_EPISODE_THUMB_CARD_W_V10,
                    EMBYFLOW_LOCAL_EPISODE_THUMB_CARD_H_V10,
                    token=(
                        "local-v10-thumb-%d-%s"
                        % (slot, entry_key)
                    ),
                    is_current=lambda s=slot, k=entry_key: (
                        not getattr(
                            self,
                            "embyflow_local_v10_closed",
                            False,
                        )
                        and (
                            (
                                self.selected_index
                                // self.PAGE_SIZE
                            )
                            * self.PAGE_SIZE
                            + s
                        )
                        < len(self.entries)
                        and embyflow_local_v10_thumb_key(
                            self.entries[
                                (
                                    self.selected_index
                                    // self.PAGE_SIZE
                                )
                                * self.PAGE_SIZE
                                + s
                            ]
                        )
                        == k
                    ),
                )

                if accepted:
                    self.embyflow_local_v10_loaded_slots[
                        slot
                    ] = thumb_path
        else:
            _embyflow_local_v10_show_thumb_fallback(
                self,
                slot,
                True,
            )
            self.embyflow_local_v10_loaded_slots.pop(
                slot,
                None,
            )

        progress = max(
            0,
            min(
                100,
                int(entry.get("progress") or 0),
            ),
        )

        try:
            if progress > 0:
                self["v7_card%d_progress_fill" % slot].instance.resize(
                    EFS(
                        max(
                            1,
                            int(
                                round(
                                    260.0
                                    * float(progress)
                                    / 100.0
                                )
                            ),
                        ),
                        7,
                    )
                )
        except Exception:
            pass

    try:
        focus_slot = self.selected_index - page_start
        x, y = _EMBYFLOW_LOCAL_EPISODE_CARD_POSITIONS_V10[
            focus_slot
        ]
        parts = (
            ("focus_top", x - 4, y - 4, 294, 4),
            ("focus_bottom", x - 4, y + 310, 294, 4),
            ("focus_left", x - 4, y - 4, 4, 318),
            ("focus_right", x + 286, y - 4, 4, 318),
        )

        for name, x_value, y_value, width, height in parts:
            instance = self[name].instance

            if total and instance is not None:
                instance.move(EFP(x_value, y_value))
                instance.resize(EFS(width, height))
                instance.show()
            elif instance is not None:
                instance.hide()
    except Exception:
        pass


def _embyflow_local_v10_worker(self):
    try:
        while not self.embyflow_local_v10_closed:
            candidate = None

            try:
                if self.embyflow_local_v10_lock:
                    with self.embyflow_local_v10_lock:
                        if self.embyflow_local_v10_pending:
                            candidate = (
                                self.embyflow_local_v10_pending.pop(0)
                            )
                elif self.embyflow_local_v10_pending:
                    candidate = self.embyflow_local_v10_pending.pop(0)
            except Exception:
                candidate = None

            if not candidate:
                break

            entry = candidate.get("entry") or {}
            thumb_path = embyflow_local_v10_generate_thumb(
                self,
                entry,
            )
            result = {
                "key": candidate.get("key"),
                "path": str(entry.get("path") or ""),
                "thumb": thumb_path,
            }

            try:
                if self.embyflow_local_v10_lock:
                    with self.embyflow_local_v10_lock:
                        self.embyflow_local_v10_results.append(
                            result
                        )
                else:
                    self.embyflow_local_v10_results.append(
                        result
                    )
            except Exception:
                pass

    finally:
        self.embyflow_local_v10_worker_running = False


def _embyflow_local_v10_start_worker(self):
    if (
        self.embyflow_local_v10_closed
        or self.embyflow_local_v10_worker_running
    ):
        return

    try:
        import threading

        self.embyflow_local_v10_worker_running = True
        worker = threading.Thread(
            target=self.embyflow_local_v10_worker,
            name="EmbyFlowLocalEpisodeThumbV10",
        )
        worker.daemon = True
        worker.start()
        self.embyflow_local_v10_timer.start(
            250,
            False,
        )
    except Exception:
        self.embyflow_local_v10_worker_running = False


def _embyflow_local_v10_request_visible(self):
    if (
        self.embyflow_local_v10_closed
        or not self.entries
    ):
        return

    total = len(self.entries)
    page_start = (
        self.selected_index // self.PAGE_SIZE
    ) * self.PAGE_SIZE
    added = False

    for entry in self.entries[
        page_start:page_start + self.PAGE_SIZE
    ]:
        cached = embyflow_local_v10_cached_thumb(entry)

        if cached:
            entry["local_episode_thumb"] = cached
            continue

        key = embyflow_local_v10_thumb_key(entry)

        if not key:
            continue

        if embyflow_negative_cache_active(
            embyflow_local_v10_thumb_missing_path(entry),
            EMBYFLOW_LOCAL_EPISODE_THUMB_NEGATIVE_TTL_V10,
        ):
            continue

        try:
            if self.embyflow_local_v10_lock:
                with self.embyflow_local_v10_lock:
                    if key in self.embyflow_local_v10_fetching:
                        continue

                    self.embyflow_local_v10_fetching.add(key)
                    self.embyflow_local_v10_pending.append({
                        "key": key,
                        "entry": dict(entry),
                    })
                    added = True
            else:
                if key in self.embyflow_local_v10_fetching:
                    continue

                self.embyflow_local_v10_fetching.add(key)
                self.embyflow_local_v10_pending.append({
                    "key": key,
                    "entry": dict(entry),
                })
                added = True
        except Exception:
            pass

    if added or self.embyflow_local_v10_pending:
        _embyflow_local_v10_start_worker(self)


def _embyflow_local_v10_poll(self):
    results = []

    try:
        if self.embyflow_local_v10_lock:
            with self.embyflow_local_v10_lock:
                results = list(
                    self.embyflow_local_v10_results
                )
                self.embyflow_local_v10_results[:] = []
        else:
            results = list(
                self.embyflow_local_v10_results
            )
            self.embyflow_local_v10_results[:] = []
    except Exception:
        results = []

    changed = False

    for result in results:
        key = str(result.get("key") or "")
        source_path = str(result.get("path") or "")
        thumb_path = str(result.get("thumb") or "")
        self.embyflow_local_v10_fetching.discard(key)

        if not thumb_path:
            continue

        for entry in self.entries:
            if (
                str(entry.get("path") or "")
                == source_path
            ):
                entry["local_episode_thumb"] = thumb_path
                changed = True

        for entry in self.all_entries:
            if (
                str(entry.get("path") or "")
                == source_path
            ):
                entry["local_episode_thumb"] = thumb_path

    if changed and not self.embyflow_local_v10_closed:
        _embyflow_local_v10_apply_thumbs(self)

    if (
        self.embyflow_local_v10_pending
        and not self.embyflow_local_v10_worker_running
        and not self.embyflow_local_v10_closed
    ):
        _embyflow_local_v10_start_worker(self)

    if (
        not self.embyflow_local_v10_worker_running
        and not self.embyflow_local_v10_pending
        and not self.embyflow_local_v10_results
    ):
        try:
            self.embyflow_local_v10_timer.stop()
        except Exception:
            pass
    else:
        try:
            self.embyflow_local_v10_timer.start(
                250,
                False,
            )
        except Exception:
            pass


def _embyflow_local_v10_refresh(self):
    _EMBYFLOW_LOCAL_V10_BASE_REFRESH(self)
    _embyflow_local_v10_apply_detail_poster(self)
    _embyflow_local_v10_apply_thumbs(self)
    _embyflow_local_v10_request_visible(self)


