# EMBYFLOW_LOCAL_RECORDING_SOURCE_V12_START
# Zeigt im lokalen Episodendetail die tatsächliche Aufnahmequelle an.
# Reihenfolge:
# 1. bereits gespeicherter Sendername
# 2. Auflösung der Enigma2-Servicereferenz
# 3. Sendername aus dem Aufnahmedateinamen
#
# Beispiel:
# 20260805 1729 - RTL HD - Unter uns.ts
# wird zu:
# Aufgenommen von: RTL HD


def _embyflow_local_v12_clean_source_name(value):
    try:
        text = str(value or "")
        text = text.replace("\x86", "").replace("\x87", "")
        text = " ".join(text.split()).strip()
        lowered = text.casefold()

        if (
            not text
            or lowered in (
                "-",
                "–",
                "0",
                "unbekannt",
                "unknown",
                "none",
            )
            or text.isdigit()
            or text.startswith("1:0:")
        ):
            return ""

        return text

    except Exception:
        return ""


def embyflow_local_v12_recording_source(entry):
    try:
        data = entry if isinstance(entry, dict) else {}

        cached = _embyflow_local_v12_clean_source_name(
            data.get("recording_source")
        )

        if cached:
            return cached

        direct = _embyflow_local_v12_clean_source_name(
            data.get("service_name")
        )

        if direct:
            data["recording_source"] = direct
            return direct

        service_reference = str(
            data.get("service_reference") or ""
        ).strip()

        if service_reference:
            try:
                from ServiceReference import ServiceReference

                resolved = _embyflow_local_v12_clean_source_name(
                    ServiceReference(
                        service_reference
                    ).getServiceName()
                )

                if resolved:
                    data["recording_source"] = resolved
                    return resolved

            except Exception:
                pass

        path = str(data.get("path") or "")
        base = os.path.splitext(
            os.path.basename(path)
        )[0]

        parts = re.split(
            r"\s+-\s+",
            base,
        )

        if len(parts) >= 3:
            filename_source = (
                _embyflow_local_v12_clean_source_name(
                    parts[1]
                )
            )

            if filename_source:
                data["recording_source"] = filename_source
                return filename_source

    except Exception:
        pass

    return "Unbekannt"


