# EMBYFLOW_LOCAL_LIVE_RECORDING_TAG_V17_START
# Erkennt laufende lokale Aufnahmen über:
# 1. Enigma2 RecordTimer
# 2. aktuell zum Schreiben geöffnete TS-Dateien
# 3. Dateiwachstum als Fallback
#
# Anzeige:
# Karte:  ● LÄUFT
# Details: AUFNAHME LÄUFT, bisherige Dauer und aktuelle Dateigröße

import os as _embyflow_v17_os
import re as _embyflow_v17_re
import time as _embyflow_v17_time

try:
    from enigma import eTimer as _EmbyFlowLocalV17Timer
except Exception:
    _EmbyFlowLocalV17Timer = eTimer

try:
    from skin import parseColor as _embyflow_v17_parse_color
except Exception:
    _embyflow_v17_parse_color = parseColor


_EMBYFLOW_LOCAL_V17_ORIGINAL_INIT = (
    EmbyFlowLocalEpisodesScreenV7.__init__
)

_EMBYFLOW_LOCAL_V17_ORIGINAL_REFRESH = (
    EmbyFlowLocalEpisodesScreenV7.refresh
)

_EMBYFLOW_LOCAL_V17_ORIGINAL_UPDATE_DETAIL = (
    EmbyFlowLocalEpisodesScreenV7.update_detail
)


def _embyflow_local_v17_path_keys(path):
    value = str(path or "").strip()

    if value.endswith(" (deleted)"):
        value = value[:-10]

    if not value:
        return set()

    try:
        value = _embyflow_v17_os.path.realpath(value)
    except Exception:
        pass

    keys = {value}

    if value.casefold().endswith(".ts"):
        keys.add(value[:-3])
    else:
        keys.add(value + ".ts")

    return keys


def _embyflow_local_v17_parse_begin(path):
    try:
        filename = _embyflow_v17_os.path.basename(
            str(path or "")
        )

        match = _embyflow_v17_re.match(
            r"^(\d{8})\s+(\d{4})\b",
            filename,
        )

        if not match:
            return 0

        parsed = _embyflow_v17_time.strptime(
            match.group(1) + match.group(2),
            "%Y%m%d%H%M",
        )

        return int(
            _embyflow_v17_time.mktime(parsed)
        )

    except Exception:
        return 0


def _embyflow_local_v17_timer_running(timer, now_value):
    try:
        if bool(getattr(timer, "justplay", False)):
            return False
    except Exception:
        pass

    try:
        method = getattr(timer, "isRunning", None)

        if callable(method) and bool(method()):
            return True
    except Exception:
        pass

    try:
        state = int(
            getattr(timer, "state", -999)
        )

        running_state = int(
            getattr(timer, "StateRunning", 2)
        )

        if state == running_state:
            return True
    except Exception:
        pass

    try:
        begin = int(
            getattr(timer, "begin", 0) or 0
        )

        end = int(
            getattr(timer, "end", 0) or 0
        )

        if (
            begin > 0
            and begin <= now_value
            and (
                end <= 0
                or now_value < end
            )
        ):
            return True
    except Exception:
        pass

    return False


def _embyflow_local_v17_running_timer_paths(now_value):
    result = {}

    try:
        import NavigationInstance

        navigation = getattr(
            NavigationInstance,
            "instance",
            None,
        )

        record_timer = getattr(
            navigation,
            "RecordTimer",
            None,
        )

        timers = list(
            getattr(
                record_timer,
                "timer_list",
                [],
            )
            or []
        )

        for timer in timers:
            if not _embyflow_local_v17_timer_running(
                timer,
                now_value,
            ):
                continue

            begin = int(
                getattr(timer, "begin", 0)
                or 0
            )

            timer_path = ""

            for attribute in (
                "Filename",
                "filename",
                "recordingFilename",
            ):
                try:
                    candidate = getattr(
                        timer,
                        attribute,
                        "",
                    )

                    if callable(candidate):
                        candidate = candidate()

                    candidate = str(
                        candidate or ""
                    ).strip()

                    if candidate:
                        timer_path = candidate
                        break
                except Exception:
                    pass

            if not timer_path:
                continue

            for key in _embyflow_local_v17_path_keys(
                timer_path
            ):
                result[key] = {
                    "begin": begin,
                    "reason": "RecordTimer",
                }

    except Exception:
        pass

    return result


def _embyflow_local_v17_writable_fd_paths():
    result = {}
    fd_root = "/proc/self/fd"

    try:
        fd_names = _embyflow_v17_os.listdir(
            fd_root
        )
    except Exception:
        return result

    for fd_name in fd_names:
        if not str(fd_name).isdigit():
            continue

        try:
            target = _embyflow_v17_os.readlink(
                _embyflow_v17_os.path.join(
                    fd_root,
                    fd_name,
                )
            )
        except Exception:
            continue

        if not str(target).casefold().endswith(
            (
                ".ts",
                ".ts (deleted)",
            )
        ):
            continue

        writable = False

        try:
            info_path = (
                "/proc/self/fdinfo/%s"
                % fd_name
            )

            with open(
                info_path,
                "r",
                encoding="ascii",
                errors="ignore",
            ) as handle:
                for line in handle:
                    if not line.startswith("flags:"):
                        continue

                    flags = int(
                        line.split(
                            ":",
                            1,
                        )[1].strip(),
                        8,
                    )

                    writable = (
                        flags & 3
                    ) in (
                        1,
                        2,
                    )

                    break

        except Exception:
            writable = False

        if not writable:
            continue

        begin = _embyflow_local_v17_parse_begin(
            target
        )

        for key in _embyflow_local_v17_path_keys(
            target
        ):
            result[key] = {
                "begin": begin,
                "reason": "WritableFD",
            }

    return result


def _embyflow_local_v17_all_entries(self):
    result = []
    seen = set()

    for collection_name in (
        "entries",
        "all_entries",
    ):
        try:
            collection = list(
                getattr(
                    self,
                    collection_name,
                    [],
                )
                or []
            )
        except Exception:
            collection = []

        for entry in collection:
            if not isinstance(entry, dict):
                continue

            identity = id(entry)

            if identity in seen:
                continue

            seen.add(identity)
            result.append(entry)

    return result


def _embyflow_local_v17_update_file_data(entry):
    path = str(
        entry.get("path") or ""
    )

    if (
        not path
        or not _embyflow_v17_os.path.isfile(path)
    ):
        return None

    try:
        stat_result = _embyflow_v17_os.stat(
            path
        )

        size_value = int(
            stat_result.st_size or 0
        )

        mtime_value = float(
            stat_result.st_mtime or 0
        )

        entry["size_bytes"] = size_value

        try:
            entry["size_text"] = (
                embyflow_local_human_size(
                    size_value
                )
            )
        except Exception:
            pass

        return (
            size_value,
            mtime_value,
        )

    except Exception:
        return None


def _embyflow_local_v17_scan(self):
    now_value = int(
        _embyflow_v17_time.time()
    )

    detected = {}

    detected.update(
        _embyflow_local_v17_running_timer_paths(
            now_value
        )
    )

    detected.update(
        _embyflow_local_v17_writable_fd_paths()
    )

    previous_state = getattr(
        self,
        "embyflow_local_v17_file_state",
        {},
    )

    next_state = {}

    for entry in _embyflow_local_v17_all_entries(
        self
    ):
        path = str(
            entry.get("path") or ""
        )

        path_keys = (
            _embyflow_local_v17_path_keys(path)
        )

        live_info = None

        for key in path_keys:
            if key in detected:
                live_info = detected[key]
                break

        file_data = (
            _embyflow_local_v17_update_file_data(
                entry
            )
        )

        if file_data is not None:
            size_value, mtime_value = file_data

            try:
                normalized_path = (
                    _embyflow_v17_os.path.realpath(
                        path
                    )
                )
            except Exception:
                normalized_path = path

            old_value = previous_state.get(
                normalized_path
            )

            next_state[normalized_path] = (
                size_value,
                mtime_value,
                now_value,
            )

            if (
                live_info is None
                and old_value
            ):
                old_size = int(
                    old_value[0] or 0
                )

                old_mtime = float(
                    old_value[1] or 0
                )

                if (
                    size_value > old_size
                    and mtime_value >= old_mtime
                    and (
                        now_value - mtime_value
                    ) < 120
                ):
                    live_info = {
                        "begin": (
                            _embyflow_local_v17_parse_begin(
                                path
                            )
                        ),
                        "reason": "Dateiwachstum",
                    }

        is_live = bool(live_info)

        entry[
            "embyflow_local_v17_live"
        ] = is_live

        if is_live:
            begin_value = int(
                (
                    live_info
                    or {}
                ).get("begin")
                or 0
            )

            if begin_value <= 0:
                begin_value = (
                    _embyflow_local_v17_parse_begin(
                        path
                    )
                )

            entry[
                "embyflow_local_v17_begin"
            ] = begin_value

            entry[
                "embyflow_local_v17_reason"
            ] = str(
                (
                    live_info
                    or {}
                ).get("reason")
                or ""
            )

        else:
            entry.pop(
                "embyflow_local_v17_begin",
                None,
            )

            entry.pop(
                "embyflow_local_v17_reason",
                None,
            )

    self.embyflow_local_v17_file_state = (
        next_state
    )


def _embyflow_local_v17_elapsed_text(entry):
    begin_value = int(
        (
            entry
            or {}
        ).get(
            "embyflow_local_v17_begin"
        )
        or 0
    )

    if begin_value <= 0:
        return "läuft"

    elapsed = max(
        0,
        int(
            _embyflow_v17_time.time()
        )
        - begin_value,
    )

    try:
        return (
            embyflow_local_v6_format_duration(
                elapsed
            )
        )
    except Exception:
        hours = elapsed // 3600
        minutes = (
            elapsed % 3600
        ) // 60

        if hours:
            return "%d:%02d" % (
                hours,
                minutes,
            )

        return "%d Min." % minutes


def _embyflow_local_v17_apply_card_tags(self):
    total = len(
        getattr(
            self,
            "entries",
            [],
        )
        or []
    )

    if total <= 0:
        return

    page_size = int(
        getattr(
            self,
            "PAGE_SIZE",
            8,
        )
        or 8
    )

    selected_index = int(
        getattr(
            self,
            "selected_index",
            0,
        )
        or 0
    )

    page_start = (
        selected_index
        // page_size
    ) * page_size

    for slot in range(page_size):
        actual_index = page_start + slot

        if actual_index >= total:
            continue

        entry = self.entries[
            actual_index
        ]

        if not entry.get(
            "embyflow_local_v17_live"
        ):
            continue

        try:
            widget = self[
                "v7_card%d_status"
                % slot
            ]

            widget.setText(
                "● LÄUFT"
            )

            widget.show()

            try:
                if widget.instance is not None:
                    widget.instance.setForegroundColor(
                        _embyflow_v17_parse_color(
                            "#FF4D3D"
                        )
                    )

                    widget.instance.show()
                    widget.instance.invalidate()

            except Exception:
                pass

        except Exception:
            pass


def _embyflow_local_v17_update_live_detail(self):
    try:
        entry = self.selected_entry()
    except Exception:
        entry = None

    if (
        not entry
        or not entry.get(
            "embyflow_local_v17_live"
        )
    ):
        return

    recording_source = str(
        entry.get("service_name")
        or "Unbekannt"
    )

    try:
        recording_source = (
            embyflow_local_v12_recording_source(
                entry
            )
        )
    except Exception:
        pass

    genre = str(
        entry.get("genre")
        or entry.get("tags")
        or "–"
    )

    epg_source = str(
        entry.get("epg_source")
        or "Dateiname"
    )

    size_text = str(
        entry.get("size_text")
        or ""
    )

    elapsed_text = (
        _embyflow_local_v17_elapsed_text(
            entry
        )
    )

    first_line = (
        "Status: ● AUFNAHME LÄUFT · Seit: %s"
        % elapsed_text
    )

    if size_text:
        first_line += (
            " · %s"
            % size_text
        )

    info = (
        first_line
        + "\n"
        + (
            "Aufgenommen von: %s · Genre: %s · EPG: %s"
            % (
                recording_source,
                genre,
                epg_source,
            )
        )
    )

    try:
        _embyflow_local_v8_set_label(
            self,
            "detail_info",
            info,
        )
    except Exception:
        try:
            self[
                "detail_info"
            ].setText(info)
        except Exception:
            pass


def _embyflow_local_v17_refresh(self):
    _embyflow_local_v17_scan(self)

    _EMBYFLOW_LOCAL_V17_ORIGINAL_REFRESH(
        self
    )

    _embyflow_local_v17_apply_card_tags(
        self
    )

    _embyflow_local_v17_update_live_detail(
        self
    )


def _embyflow_local_v17_update_detail(self):
    _EMBYFLOW_LOCAL_V17_ORIGINAL_UPDATE_DETAIL(
        self
    )

    _embyflow_local_v17_update_live_detail(
        self
    )


def _embyflow_local_v17_tick(self):
    if getattr(
        self,
        "embyflow_local_v17_closed",
        False,
    ):
        return

    try:
        self.refresh()

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_local_live_recording_v17.log",
                "a",
            ) as log:
                log.write(
                    "%s error=%s\n"
                    % (
                        _embyflow_v17_time.strftime(
                            "%Y-%m-%d %H:%M:%S"
                        ),
                        str(error),
                    )
                )
        except Exception:
            pass

    try:
        self.embyflow_local_v17_timer.start(
            10000,
            True,
        )
    except Exception:
        pass


def _embyflow_local_v17_start(self):
    try:
        self.embyflow_local_v17_timer.start(
            750,
            True,
        )
    except Exception:
        pass


def _embyflow_local_v17_stop(self):
    self.embyflow_local_v17_closed = True

    try:
        self.embyflow_local_v17_timer.stop()
    except Exception:
        pass


def _embyflow_local_v17_init(
    self,
    *args,
    **kwargs
):
    _EMBYFLOW_LOCAL_V17_ORIGINAL_INIT(
        self,
        *args,
        **kwargs
    )

    self.embyflow_local_v17_closed = False
    self.embyflow_local_v17_file_state = {}

    self.embyflow_local_v17_timer = (
        _EmbyFlowLocalV17Timer()
    )

    try:
        self.embyflow_local_v17_timer.callback.append(
            self.embyflow_local_v17_tick
        )

    except Exception:
        try:
            self.embyflow_local_v17_timer_connection = (
                self.embyflow_local_v17_timer.timeout.connect(
                    self.embyflow_local_v17_tick
                )
            )
        except Exception:
            self.embyflow_local_v17_timer_connection = None

    self.onLayoutFinish.append(
        self.embyflow_local_v17_start
    )

    self.onClose.append(
        self.embyflow_local_v17_stop
    )


EmbyFlowLocalEpisodesScreenV7.__init__ = (
    _embyflow_local_v17_init
)

EmbyFlowLocalEpisodesScreenV7.refresh = (
    _embyflow_local_v17_refresh
)

EmbyFlowLocalEpisodesScreenV7.update_detail = (
    _embyflow_local_v17_update_detail
)

EmbyFlowLocalEpisodesScreenV7.embyflow_local_v17_tick = (
    _embyflow_local_v17_tick
)

EmbyFlowLocalEpisodesScreenV7.embyflow_local_v17_start = (
    _embyflow_local_v17_start
)

EmbyFlowLocalEpisodesScreenV7.embyflow_local_v17_stop = (
    _embyflow_local_v17_stop
)

# EMBYFLOW_LOCAL_LIVE_RECORDING_TAG_V17_END


# EMBYFLOW_NETWORK_PERFORMANCE_V18_START
# Netzwerk-Performance:
# - vier wiederverwendbare HTTP-Sessions mit Connection-Pooling
# - Single-Flight für identische parallele GET-Anfragen
# - kleiner Endpunkt-spezifischer Antwortcache
# - serialisierte Authentifizierung gegen Mehrfach-Login
# - Cache-Invalidierung nach schreibenden Emby-Aufrufen

try:
    import threading as _embyflow_v18_threading
except Exception:
    _embyflow_v18_threading = None

try:
    import copy as _embyflow_v18_copy
except Exception:
    _embyflow_v18_copy = None

try:
    from requests.adapters import HTTPAdapter as _EmbyFlowV18HTTPAdapter
except Exception:
    _EmbyFlowV18HTTPAdapter = None


EMBYFLOW_V18_HTTP_POOL_SIZE = 4
EMBYFLOW_V18_HTTP_CACHE_MAX = 96
EMBYFLOW_V18_HTTP_CACHE_MAX_ITEM_BYTES = 1024 * 1024
EMBYFLOW_V18_HTTP_POOL = []
EMBYFLOW_V18_HTTP_POOL_LOCK = (
    _embyflow_v18_threading.RLock()
    if _embyflow_v18_threading is not None
    else None
)
EMBYFLOW_V18_HTTP_STATE_LOCK = (
    _embyflow_v18_threading.RLock()
    if _embyflow_v18_threading is not None
    else None
)
EMBYFLOW_V18_HTTP_CACHE = {}
EMBYFLOW_V18_HTTP_INFLIGHT = {}
EMBYFLOW_V18_AUTH_LOCK = (
    _embyflow_v18_threading.RLock()
    if _embyflow_v18_threading is not None
    else None
)


def _embyflow_v18_freeze(value):
    try:
        if isinstance(value, dict):
            return tuple(
                sorted(
                    (
                        str(key),
                        _embyflow_v18_freeze(item),
                    )
                    for key, item in value.items()
                )
            )

        if isinstance(value, (list, tuple, set)):
            return tuple(
                _embyflow_v18_freeze(item)
                for item in value
            )

        if value is None:
            return ""

        return str(value)

    except Exception:
        return repr(value)


def _embyflow_v18_build_session():
    if not requests:
        return None

    session = requests.Session()

    try:
        session.headers.update({
            "Connection": "keep-alive",
        })
    except Exception:
        pass

    if _EmbyFlowV18HTTPAdapter is not None:
        try:
            adapter = _EmbyFlowV18HTTPAdapter(
                pool_connections=8,
                pool_maxsize=8,
                max_retries=0,
                pool_block=False,
            )
            session.mount("http://", adapter)
            session.mount("https://", adapter)
        except Exception:
            pass

    return session


def _embyflow_v18_ensure_pool():
    if not requests:
        return []

    lock = EMBYFLOW_V18_HTTP_POOL_LOCK

    try:
        if lock is not None:
            with lock:
                while len(EMBYFLOW_V18_HTTP_POOL) < EMBYFLOW_V18_HTTP_POOL_SIZE:
                    EMBYFLOW_V18_HTTP_POOL.append({
                        "session": _embyflow_v18_build_session(),
                        "lock": _embyflow_v18_threading.RLock(),
                    })
        else:
            while len(EMBYFLOW_V18_HTTP_POOL) < EMBYFLOW_V18_HTTP_POOL_SIZE:
                EMBYFLOW_V18_HTTP_POOL.append({
                    "session": _embyflow_v18_build_session(),
                    "lock": None,
                })
    except Exception:
        pass

    return EMBYFLOW_V18_HTTP_POOL


def _embyflow_v18_pool_slot():
    pool = _embyflow_v18_ensure_pool()

    if not pool:
        return None

    try:
        ident = int(
            getattr(
                _embyflow_v18_threading.current_thread(),
                "ident",
                0,
            )
            or 0
        )
    except Exception:
        ident = 0

    return pool[abs(ident) % len(pool)]


def _embyflow_v18_raw_request(method, url, *args, **kwargs):
    # EMBYFLOW_HTTP_POOL_NONBLOCK_V1
    # A slow background Stopped/ActiveEncodings request must never hold the
    # shared session-slot lock and freeze a foreground playback click.  Reuse
    # the pooled keep-alive session only when its slot is immediately free.
    # Under contention use a private one-shot requests call instead of waiting.
    if not requests:
        raise RuntimeError("requests ist nicht verfügbar")

    request_method = str(method or "GET").upper()
    slot = _embyflow_v18_pool_slot()

    if not slot or slot.get("session") is None:
        return requests.request(
            request_method,
            url,
            *args,
            **kwargs
        )

    session = slot["session"]
    lock = slot.get("lock")

    if lock is not None:
        acquired = False
        try:
            acquired = bool(lock.acquire(False))
        except Exception:
            acquired = False

        if acquired:
            try:
                return session.request(
                    request_method,
                    url,
                    *args,
                    **kwargs
                )
            finally:
                try:
                    lock.release()
                except Exception:
                    pass

        # Never log URL/token/credentials.  This local diagnostic records only
        # that a busy pooled connection was bypassed.
        try:
            with embyflow_open_log(
                "/tmp/embyflow_http_pool_nonblock_v1.log",
                "a",
            ) as handle:
                handle.write(
                    "%s BYPASS method=%s reason=slot-busy\n"
                    % (time.strftime("%H:%M:%S"), request_method)
                )
        except Exception:
            pass

        return requests.request(
            request_method,
            url,
            *args,
            **kwargs
        )

    return session.request(
        request_method,
        url,
        *args,
        **kwargs
    )


def _embyflow_v18_request_key(method, url, args, kwargs):
    headers = kwargs.get("headers") or {}
    selected_headers = {}

    for header_name in (
        "X-Emby-Token",
        "X-Emby-Authorization",
        "Cache-Control",
        "Pragma",
        "Accept-Encoding",
        "Range",
    ):
        try:
            value = headers.get(header_name)
        except Exception:
            value = None

        if value is not None:
            selected_headers[header_name] = value

    return (
        str(method or "GET").upper(),
        str(url or ""),
        _embyflow_v18_freeze(args),
        _embyflow_v18_freeze(kwargs.get("params")),
        _embyflow_v18_freeze(selected_headers),
    )


def _embyflow_v18_response_ttl(url, kwargs):
    try:
        lowered_url = str(url or "").lower()
        params = kwargs.get("params") or {}
        headers = kwargs.get("headers") or {}

        if kwargs.get("stream"):
            return 0

        if "/images/" in lowered_url:
            return 0

        if (
            str(headers.get("Cache-Control") or "").lower() == "no-cache"
            or str(headers.get("Pragma") or "").lower() == "no-cache"
            or "_embyflow_ts" in params
        ):
            return 0

        if "/system/info/public" in lowered_url:
            return 30

        if lowered_url.endswith("/views"):
            return 300

        if "/shows/" in lowered_url:
            return 180

        if "/items" in lowered_url:
            filters = str(params.get("Filters") or "").lower()
            sort_by = str(params.get("SortBy") or "").lower()
            include_types = str(
                params.get("IncludeItemTypes")
                or ""
            ).lower()
            limit_value = str(params.get("Limit") or "")
            search_term = str(params.get("SearchTerm") or "")
            ids_value = str(params.get("Ids") or "")
            recursive_value = str(params.get("Recursive") or "").lower()

            if ids_value:
                return 3

            if (
                "isresumable" in filters
                or str(params.get("IsResumable") or "").lower()
                == "true"
            ):
                return 15

            if "isfavorite" in filters:
                return 30

            if "datecreated" in sort_by:
                return 20

            if search_term:
                return 30

            if limit_value == "1":
                return 120

            if (
                params.get("ParentId")
                and (
                    "episode" in include_types
                    or "season" in include_types
                )
            ):
                return 180

            if recursive_value in ("true", "false"):
                return 30

            return 20

        return 0

    except Exception:
        return 0


def _embyflow_v18_response_snapshot(response):
    try:
        content = bytes(
            getattr(response, "content", b"")
            or b""
        )
    except Exception:
        content = b""

    try:
        headers = dict(
            getattr(response, "headers", {})
            or {}
        )
    except Exception:
        headers = {}

    return {
        "status_code": int(
            getattr(response, "status_code", 0)
            or 0
        ),
        "headers": headers,
        "content": content,
        "url": str(
            getattr(response, "url", "")
            or ""
        ),
        "reason": str(
            getattr(response, "reason", "")
            or ""
        ),
        "encoding": getattr(
            response,
            "encoding",
            None,
        ),
    }


def _embyflow_v18_response_from_snapshot(snapshot):
    response = requests.Response()
    response.status_code = int(
        snapshot.get("status_code", 0)
        or 0
    )
    response._content = bytes(
        snapshot.get("content", b"")
        or b""
    )
    response.headers.update(
        snapshot.get("headers", {})
        or {}
    )
    response.url = str(
        snapshot.get("url", "")
        or ""
    )
    response.reason = str(
        snapshot.get("reason", "")
        or ""
    )
    response.encoding = snapshot.get("encoding")
    return response


def _embyflow_v18_wait_seconds(kwargs):
    timeout_value = kwargs.get("timeout", 10)

    try:
        if isinstance(timeout_value, (tuple, list)):
            seconds = sum(
                float(value or 0)
                for value in timeout_value
            )
        else:
            seconds = float(timeout_value or 10)
    except Exception:
        seconds = 10.0

    return max(3.0, min(90.0, seconds + 5.0))


def _embyflow_v18_cache_put(key, snapshot, ttl):
    if ttl <= 0:
        return

    content_size = len(
        snapshot.get("content", b"")
        or b""
    )

    if content_size > EMBYFLOW_V18_HTTP_CACHE_MAX_ITEM_BYTES:
        return

    now_value = time.time()

    EMBYFLOW_V18_HTTP_CACHE[key] = {
        "snapshot": snapshot,
        "ts": now_value,
        "access": now_value,
        "ttl": int(ttl),
    }

    while len(EMBYFLOW_V18_HTTP_CACHE) > EMBYFLOW_V18_HTTP_CACHE_MAX:
        oldest_key = min(
            EMBYFLOW_V18_HTTP_CACHE,
            key=lambda candidate: float(
                EMBYFLOW_V18_HTTP_CACHE[candidate].get(
                    "access",
                    0.0
                )
                or 0.0
            )
        )
        EMBYFLOW_V18_HTTP_CACHE.pop(
            oldest_key,
            None
        )


def _embyflow_v18_clear_response_caches():
    lock = EMBYFLOW_V18_HTTP_STATE_LOCK

    try:
        if lock is not None:
            with lock:
                EMBYFLOW_V18_HTTP_CACHE.clear()
        else:
            EMBYFLOW_V18_HTTP_CACHE.clear()
    except Exception:
        pass

    try:
        api_lock = globals().get(
            "EMBYFLOW_API_RAM_CACHE_LOCK"
        )

        if api_lock is not None:
            with api_lock:
                EMBYFLOW_API_RAM_CACHE.clear()
        else:
            EMBYFLOW_API_RAM_CACHE.clear()
    except Exception:
        pass


def _embyflow_v18_get(url, *args, **kwargs):
    method = "GET"
    key = _embyflow_v18_request_key(
        method,
        url,
        args,
        kwargs,
    )
    ttl = _embyflow_v18_response_ttl(
        url,
        kwargs,
    )
    lock = EMBYFLOW_V18_HTTP_STATE_LOCK
    now_value = time.time()
    waiter_state = None
    owner_state = None

    if lock is not None:
        with lock:
            cache_entry = EMBYFLOW_V18_HTTP_CACHE.get(
                key
            )

            if cache_entry:
                age = now_value - float(
                    cache_entry.get("ts", 0.0)
                    or 0.0
                )

                if age < max(
                    1,
                    int(cache_entry.get("ttl", 0) or 0)
                ):
                    cache_entry["access"] = now_value
                    return _embyflow_v18_response_from_snapshot(
                        cache_entry["snapshot"]
                    )

                EMBYFLOW_V18_HTTP_CACHE.pop(
                    key,
                    None
                )

            waiter_state = EMBYFLOW_V18_HTTP_INFLIGHT.get(
                key
            )

            if waiter_state is None:
                owner_state = {
                    "event": _embyflow_v18_threading.Event(),
                    "snapshot": None,
                    "error": "",
                }
                EMBYFLOW_V18_HTTP_INFLIGHT[key] = (
                    owner_state
                )
    else:
        return _embyflow_v18_raw_request(
            method,
            url,
            *args,
            **kwargs
        )

    if waiter_state is not None:
        finished = waiter_state["event"].wait(
            _embyflow_v18_wait_seconds(kwargs)
        )

        if finished and waiter_state.get("snapshot") is not None:
            return _embyflow_v18_response_from_snapshot(
                waiter_state["snapshot"]
            )

        if finished and waiter_state.get("error"):
            raise RuntimeError(
                waiter_state.get("error")
            )

        return _embyflow_v18_raw_request(
            method,
            url,
            *args,
            **kwargs
        )

    try:
        response = _embyflow_v18_raw_request(
            method,
            url,
            *args,
            **kwargs
        )
        snapshot = _embyflow_v18_response_snapshot(
            response
        )

        with lock:
            owner_state["snapshot"] = snapshot
            _embyflow_v18_cache_put(
                key,
                snapshot,
                ttl,
            )

        return response

    except Exception as error:
        with lock:
            owner_state["error"] = str(error)
        raise

    finally:
        with lock:
            try:
                owner_state["event"].set()
            except Exception:
                pass

            EMBYFLOW_V18_HTTP_INFLIGHT.pop(
                key,
                None
            )


def embyflow_http_get(url, *args, **kwargs):
    return _embyflow_v18_get(
        url,
        *args,
        **kwargs
    )


def embyflow_http_post(url, *args, **kwargs):
    response = _embyflow_v18_raw_request(
        "POST",
        url,
        *args,
        **kwargs
    )

    if int(
        getattr(response, "status_code", 500)
        or 500
    ) < 400:
        _embyflow_v18_clear_response_caches()

    return response


def embyflow_http_delete(url, *args, **kwargs):
    response = _embyflow_v18_raw_request(
        "DELETE",
        url,
        *args,
        **kwargs
    )

    if int(
        getattr(response, "status_code", 500)
        or 500
    ) < 400:
        _embyflow_v18_clear_response_caches()

    return response


_EMBYFLOW_V18_ORIGINAL_GET_EMBY_AUTH = get_emby_auth


def _embyflow_v18_get_emby_auth(force=False):
    lock = EMBYFLOW_V18_AUTH_LOCK

    if lock is None:
        return _EMBYFLOW_V18_ORIGINAL_GET_EMBY_AUTH(
            force
        )

    with lock:
        return _EMBYFLOW_V18_ORIGINAL_GET_EMBY_AUTH(
            force
        )


get_emby_auth = _embyflow_v18_get_emby_auth

# Der bestehende JSON-RAM-Cache darf mehr kleine Metadatenantworten halten.
EMBYFLOW_API_RAM_CACHE_MAX = max(
    int(EMBYFLOW_API_RAM_CACHE_MAX or 0),
    96,
)

# EMBYFLOW_NETWORK_PERFORMANCE_V18_END


# EMBYFLOW_PERFORMANCE_MONITOR_V19_START
# Leichter 5-Minuten-Monitor für den EmbyFlow-Kaltstart.
# Startet beim Öffnen des Plugins, nicht beim Booten der Box.
# Ausgabe: /tmp/embyflow_performance_v19.log

try:
    import queue as _embyflow_v19_queue
except Exception:
    import Queue as _embyflow_v19_queue

try:
    import threading as _embyflow_v19_threading
except Exception:
    _embyflow_v19_threading = None

try:
    from urllib.parse import urlsplit as _embyflow_v19_urlsplit
except Exception:
    try:
        from urlparse import urlsplit as _embyflow_v19_urlsplit
    except Exception:
        _embyflow_v19_urlsplit = None

EMBYFLOW_V19_LOG_PATH = "/tmp/embyflow_performance_v19.log"
EMBYFLOW_V19_DURATION_SECONDS = 300.0
EMBYFLOW_V19_SAMPLE_SECONDS = 2.0
EMBYFLOW_V19_HEARTBEAT_MS = 500
EMBYFLOW_V19_GUI_GAP_SECONDS = 1.25
EMBYFLOW_V19_STATE = None
EMBYFLOW_V19_HEARTBEAT_TIMER = None
EMBYFLOW_V19_HEARTBEAT_CONNECTION = None


def _embyflow_v19_mono():
    try:
        return time.monotonic()
    except Exception:
        return time.time()


def _embyflow_v19_safe_text(value, limit=220):
    try:
        text = str(value or "")
    except Exception:
        text = "?"

    text = text.replace("\r", " ").replace("\n", " ")

    if len(text) > int(limit):
        text = text[: max(0, int(limit) - 3)] + "..."

    return text


def _embyflow_v19_state_active(state=None):
    current = state or EMBYFLOW_V19_STATE

    if not isinstance(current, dict):
        return False

    if not current.get("active"):
        return False

    return _embyflow_v19_mono() <= float(
        current.get("deadline", 0.0) or 0.0
    )


def _embyflow_v19_emit(category, message="", state=None, force=False):
    current = state or EMBYFLOW_V19_STATE

    if not isinstance(current, dict):
        return False

    now_value = _embyflow_v19_mono()

    if not force and (
        not current.get("active")
        or now_value > float(current.get("deadline", 0.0) or 0.0)
    ):
        return False

    elapsed = max(
        0.0,
        now_value - float(current.get("start_mono", now_value) or now_value),
    )

    line = "%08.3f | %-13s | %s" % (
        elapsed,
        _embyflow_v19_safe_text(category, 13),
        _embyflow_v19_safe_text(message, 700),
    )

    try:
        current["queue"].put_nowait(line)
        return True
    except Exception:
        try:
            lock = current.get("lock")

            if lock is not None:
                with lock:
                    current["dropped"] = int(
                        current.get("dropped", 0) or 0
                    ) + 1
            else:
                current["dropped"] = int(
                    current.get("dropped", 0) or 0
                ) + 1
        except Exception:
            pass

    return False


def _embyflow_v19_count(name, amount=1, state=None):
    current = state or EMBYFLOW_V19_STATE

    if not isinstance(current, dict):
        return

    try:
        lock = current.get("lock")

        if lock is not None:
            with lock:
                counters = current.setdefault("counters", {})
                counters[name] = float(counters.get(name, 0) or 0) + float(amount)
        else:
            counters = current.setdefault("counters", {})
            counters[name] = float(counters.get(name, 0) or 0) + float(amount)
    except Exception:
        pass


def _embyflow_v19_snapshot_summary(state):
    counters = {}
    slowest = []
    dropped = 0

    try:
        lock = state.get("lock")

        if lock is not None:
            with lock:
                counters = dict(state.get("counters", {}) or {})
                slowest = list(state.get("slowest", []) or [])
                dropped = int(state.get("dropped", 0) or 0)
        else:
            counters = dict(state.get("counters", {}) or {})
            slowest = list(state.get("slowest", []) or [])
            dropped = int(state.get("dropped", 0) or 0)
    except Exception:
        pass

    total = int(counters.get("http_total", 0) or 0)
    total_ms = float(counters.get("http_ms", 0.0) or 0.0)
    avg_ms = (total_ms / total) if total else 0.0

    lines = [
        "MONITOR SUMMARY",
        "HTTP total=%d hit=%d miss=%d join=%d bypass=%d errors=%d slow=%d avg_ms=%.1f" % (
            total,
            int(counters.get("http_hit", 0) or 0),
            int(counters.get("http_miss", 0) or 0),
            int(counters.get("http_join", 0) or 0),
            int(counters.get("http_bypass", 0) or 0),
            int(counters.get("http_error", 0) or 0),
            int(counters.get("http_slow", 0) or 0),
            avg_ms,
        ),
        "AUTH calls=%d errors=%d | GUI gaps=%d max_gap_ms=%.1f | samples=%d dropped=%d" % (
            int(counters.get("auth_calls", 0) or 0),
            int(counters.get("auth_errors", 0) or 0),
            int(counters.get("gui_gaps", 0) or 0),
            float(counters.get("gui_max_gap_ms", 0.0) or 0.0),
            int(counters.get("samples", 0) or 0),
            dropped,
        ),
    ]

    for index, item in enumerate(
        sorted(slowest, key=lambda value: float(value[0]), reverse=True)[:10],
        1,
    ):
        lines.append(
            "SLOW #%d ms=%.1f mode=%s status=%s endpoint=%s" % (
                index,
                float(item[0]),
                _embyflow_v19_safe_text(item[1], 12),
                _embyflow_v19_safe_text(item[2], 12),
                _embyflow_v19_safe_text(item[3], 260),
            )
        )

    return lines


def _embyflow_v19_writer(state):
    try:
        with open(EMBYFLOW_V19_LOG_PATH, "a", buffering=1) as log:
            while True:
                now_value = _embyflow_v19_mono()
                deadline = float(state.get("deadline", 0.0) or 0.0)

                try:
                    line = state["queue"].get(timeout=0.5)
                    log.write(line + "\n")
                except Exception:
                    line = None

                if now_value > deadline and state["queue"].empty():
                    break

            for summary_line in _embyflow_v19_snapshot_summary(state):
                log.write(summary_line + "\n")

            log.write(
                "%08.3f | %-13s | %s\n"
                % (
                    max(
                        0.0,
                        _embyflow_v19_mono()
                        - float(state.get("start_mono", 0.0) or 0.0),
                    ),
                    "MONITOR_END",
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                )
            )
    except Exception:
        pass
    finally:
        state["active"] = False


def _embyflow_v19_read_proc_stat():
    result = {
        "ticks": 0,
        "rss_kb": 0,
        "threads": 0,
        "read_bytes": 0,
        "write_bytes": 0,
        "mem_available_kb": 0,
        "net_rx": 0,
        "net_tx": 0,
        "load1": 0.0,
    }

    try:
        with open("/proc/self/stat", "r") as handle:
            raw = handle.read().strip()

        closing = raw.rfind(")")
        rest = raw[closing + 2 :].split()
        result["ticks"] = int(rest[11]) + int(rest[12])
    except Exception:
        pass

    try:
        with open("/proc/self/status", "r") as handle:
            for line in handle:
                if line.startswith("VmRSS:"):
                    result["rss_kb"] = int(line.split()[1])
                elif line.startswith("Threads:"):
                    result["threads"] = int(line.split()[1])
    except Exception:
        pass

    try:
        with open("/proc/self/io", "r") as handle:
            for line in handle:
                if line.startswith("read_bytes:"):
                    result["read_bytes"] = int(line.split(":", 1)[1].strip())
                elif line.startswith("write_bytes:"):
                    result["write_bytes"] = int(line.split(":", 1)[1].strip())
    except Exception:
        pass

    try:
        with open("/proc/meminfo", "r") as handle:
            for line in handle:
                if line.startswith("MemAvailable:"):
                    result["mem_available_kb"] = int(line.split()[1])
                    break
    except Exception:
        pass

    try:
        with open("/proc/net/dev", "r") as handle:
            for line in handle:
                if ":" not in line:
                    continue

                interface, values = line.split(":", 1)

                if interface.strip() == "lo":
                    continue

                fields = values.split()

                if len(fields) >= 9:
                    result["net_rx"] += int(fields[0])
                    result["net_tx"] += int(fields[8])
    except Exception:
        pass

    try:
        with open("/proc/loadavg", "r") as handle:
            result["load1"] = float(handle.read().split()[0])
    except Exception:
        pass

    return result


def _embyflow_v19_sampler(state):
    previous = None
    previous_mono = None

    try:
        hz = float(os.sysconf("SC_CLK_TCK"))
    except Exception:
        hz = 100.0

    while _embyflow_v19_state_active(state):
        now_value = _embyflow_v19_mono()
        sample = _embyflow_v19_read_proc_stat()
        cpu_percent = 0.0
        read_kbps = 0.0
        write_kbps = 0.0
        rx_kbps = 0.0
        tx_kbps = 0.0

        if previous is not None and previous_mono is not None:
            delta = max(0.001, now_value - previous_mono)
            cpu_percent = max(
                0.0,
                (
                    float(sample["ticks"] - previous["ticks"])
                    / max(1.0, hz)
                    / delta
                )
                * 100.0,
            )
            read_kbps = max(
                0.0,
                float(sample["read_bytes"] - previous["read_bytes"])
                / 1024.0
                / delta,
            )
            write_kbps = max(
                0.0,
                float(sample["write_bytes"] - previous["write_bytes"])
                / 1024.0
                / delta,
            )
            rx_kbps = max(
                0.0,
                float(sample["net_rx"] - previous["net_rx"])
                / 1024.0
                / delta,
            )
            tx_kbps = max(
                0.0,
                float(sample["net_tx"] - previous["net_tx"])
                / 1024.0
                / delta,
            )

        _embyflow_v19_count("samples", 1, state)
        _embyflow_v19_emit(
            "SYSTEM",
            (
                "cpu=%.1f%% rss=%.1fMB threads=%d load1=%.2f "
                "mem_free=%.1fMB net_rx=%.1fKB/s net_tx=%.1fKB/s "
                "io_read=%.1fKB/s io_write=%.1fKB/s"
            )
            % (
                cpu_percent,
                float(sample["rss_kb"]) / 1024.0,
                int(sample["threads"]),
                float(sample["load1"]),
                float(sample["mem_available_kb"]) / 1024.0,
                rx_kbps,
                tx_kbps,
                read_kbps,
                write_kbps,
            ),
            state,
        )

        previous = sample
        previous_mono = now_value

        end_sleep = _embyflow_v19_mono() + EMBYFLOW_V19_SAMPLE_SECONDS

        while (
            _embyflow_v19_state_active(state)
            and _embyflow_v19_mono() < end_sleep
        ):
            time.sleep(0.2)

    _embyflow_v19_emit(
        "SAMPLER_DONE",
        "Systemmessung beendet",
        state,
        force=True,
    )


def _embyflow_v19_start_heartbeat():
    global EMBYFLOW_V19_HEARTBEAT_TIMER
    global EMBYFLOW_V19_HEARTBEAT_CONNECTION

    state = EMBYFLOW_V19_STATE

    if not _embyflow_v19_state_active(state):
        return

    try:
        if EMBYFLOW_V19_HEARTBEAT_TIMER is not None:
            EMBYFLOW_V19_HEARTBEAT_TIMER.stop()
    except Exception:
        pass

    try:
        timer = eTimer()
        EMBYFLOW_V19_HEARTBEAT_TIMER = timer
        EMBYFLOW_V19_HEARTBEAT_CONNECTION = None

        try:
            timer.callback.append(_embyflow_v19_heartbeat_tick)
        except Exception:
            EMBYFLOW_V19_HEARTBEAT_CONNECTION = timer.timeout.connect(
                _embyflow_v19_heartbeat_tick
            )

        state["heartbeat_last"] = _embyflow_v19_mono()
        timer.start(EMBYFLOW_V19_HEARTBEAT_MS, True)
        _embyflow_v19_emit("HEARTBEAT", "GUI-Wächter aktiv", state)
    except Exception as error:
        _embyflow_v19_emit(
            "HEARTBEAT_ERR",
            _embyflow_v19_safe_text(error),
            state,
        )


def _embyflow_v19_heartbeat_tick():
    state = EMBYFLOW_V19_STATE

    if not _embyflow_v19_state_active(state):
        try:
            if EMBYFLOW_V19_HEARTBEAT_TIMER is not None:
                EMBYFLOW_V19_HEARTBEAT_TIMER.stop()
        except Exception:
            pass
        return

    now_value = _embyflow_v19_mono()
    previous = float(state.get("heartbeat_last", now_value) or now_value)
    gap = max(0.0, now_value - previous)
    state["heartbeat_last"] = now_value

    if gap >= EMBYFLOW_V19_GUI_GAP_SECONDS:
        gap_ms = gap * 1000.0
        _embyflow_v19_count("gui_gaps", 1, state)

        try:
            lock = state.get("lock")

            if lock is not None:
                with lock:
                    counters = state.setdefault("counters", {})
                    counters["gui_max_gap_ms"] = max(
                        float(counters.get("gui_max_gap_ms", 0.0) or 0.0),
                        gap_ms,
                    )
        except Exception:
            pass

        _embyflow_v19_emit(
            "GUI_GAP",
            "gap_ms=%.1f expected_ms=%d"
            % (gap_ms, EMBYFLOW_V19_HEARTBEAT_MS),
            state,
        )

    try:
        EMBYFLOW_V19_HEARTBEAT_TIMER.start(
            EMBYFLOW_V19_HEARTBEAT_MS,
            True,
        )
    except Exception:
        pass


def _embyflow_v19_start_monitor(reason="plugin-open"):
    global EMBYFLOW_V19_STATE

    now_mono = _embyflow_v19_mono()
    current = EMBYFLOW_V19_STATE

    if (
        isinstance(current, dict)
        and current.get("active")
        and now_mono <= float(current.get("deadline", 0.0) or 0.0)
    ):
        _embyflow_v19_emit(
            "START_IGNORED",
            "Monitor läuft bereits",
            current,
        )
        return current

    lock = (
        _embyflow_v19_threading.RLock()
        if _embyflow_v19_threading is not None
        else None
    )

    state = {
        "active": True,
        "start_mono": now_mono,
        "start_wall": time.time(),
        "deadline": now_mono + EMBYFLOW_V19_DURATION_SECONDS,
        "queue": _embyflow_v19_queue.Queue(maxsize=4096),
        "lock": lock,
        "counters": {},
        "slowest": [],
        "dropped": 0,
        "home_visible": False,
        "home_closed": False,
    }

    EMBYFLOW_V19_STATE = state

    try:
        with open(EMBYFLOW_V19_LOG_PATH, "w") as log:
            log.write("EmbyFlow Performance Monitor V19\n")
            log.write(
                "Start: %s | Dauer: %d Sekunden | Grund: %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    int(EMBYFLOW_V19_DURATION_SECONDS),
                    _embyflow_v19_safe_text(reason),
                )
            )
            log.write(
                "Format: Sekunden | Kategorie | Messwert\n"
            )
    except Exception:
        pass

    if _embyflow_v19_threading is not None:
        try:
            writer = _embyflow_v19_threading.Thread(
                target=_embyflow_v19_writer,
                args=(state,),
                name="EmbyFlowPerfWriterV19",
            )
            writer.daemon = True
            state["writer"] = writer
            writer.start()
        except Exception:
            pass

        try:
            sampler = _embyflow_v19_threading.Thread(
                target=_embyflow_v19_sampler,
                args=(state,),
                name="EmbyFlowPerfSamplerV19",
            )
            sampler.daemon = True
            state["sampler"] = sampler
            sampler.start()
        except Exception as error:
            _embyflow_v19_emit(
                "SAMPLER_ERR",
                _embyflow_v19_safe_text(error),
                state,
            )

    _embyflow_v19_emit(
        "MONITOR_START",
        "duration=%ds pid=%s"
        % (
            int(EMBYFLOW_V19_DURATION_SECONDS),
            str(os.getpid()),
        ),
        state,
    )
    _embyflow_v19_start_heartbeat()
    return state


def _embyflow_v19_endpoint(url, kwargs=None):
    text = _embyflow_v19_safe_text(url, 1000)
    path = text.split("?", 1)[0]

    try:
        if _embyflow_v19_urlsplit is not None:
            parsed = _embyflow_v19_urlsplit(text)
            path = parsed.path or "/"
    except Exception:
        pass

    try:
        path = re.sub(
            r"/(?=[^/]*(?:[0-9a-fA-F]{12,}|\d{7,})[^/]*)[^/]+",
            "/:id",
            path,
        )
    except Exception:
        pass

    params = (kwargs or {}).get("params") or {}
    details = []

    for key in (
        "IncludeItemTypes",
        "Filters",
        "SortBy",
        "Limit",
        "StartIndex",
        "Recursive",
    ):
        value = params.get(key)

        if value not in (None, ""):
            details.append(
                "%s=%s"
                % (
                    key,
                    _embyflow_v19_safe_text(value, 60),
                )
            )

    if params.get("ParentId"):
        details.append("ParentId=yes")

    if params.get("Ids"):
        try:
            details.append(
                "Ids=%d"
                % len(str(params.get("Ids") or "").split(","))
            )
        except Exception:
            details.append("Ids=yes")

    if params.get("SearchTerm"):
        details.append("SearchTerm=yes")

    if details:
        return "%s [%s]" % (path, " ".join(details))

    return path


def _embyflow_v19_cache_mode(url, args, kwargs):
    try:
        ttl = int(_embyflow_v18_response_ttl(url, kwargs) or 0)

        if ttl <= 0:
            return "BYPASS"

        key = _embyflow_v18_request_key(
            "GET",
            url,
            args,
            kwargs,
        )
        lock = EMBYFLOW_V18_HTTP_STATE_LOCK
        now_value = time.time()

        if lock is None:
            return "MISS"

        with lock:
            cache_entry = EMBYFLOW_V18_HTTP_CACHE.get(key)

            if cache_entry:
                age = now_value - float(cache_entry.get("ts", 0.0) or 0.0)
                entry_ttl = max(
                    1,
                    int(cache_entry.get("ttl", 0) or 0),
                )

                if age < entry_ttl:
                    return "HIT"

            if key in EMBYFLOW_V18_HTTP_INFLIGHT:
                return "JOIN"

        return "MISS"

    except Exception:
        return "UNKNOWN"


def _embyflow_v19_record_http(
    mode,
    duration_ms,
    endpoint,
    status="?",
    byte_count=0,
    error="",
):
    state = EMBYFLOW_V19_STATE

    if not _embyflow_v19_state_active(state):
        return

    normalized_mode = str(mode or "UNKNOWN").upper()
    _embyflow_v19_count("http_total", 1, state)
    _embyflow_v19_count("http_ms", float(duration_ms), state)
    _embyflow_v19_count(
        "http_%s" % normalized_mode.lower(),
        1,
        state,
    )

    if error:
        _embyflow_v19_count("http_error", 1, state)

    if float(duration_ms) >= 500.0:
        _embyflow_v19_count("http_slow", 1, state)

        try:
            lock = state.get("lock")
            item = (
                float(duration_ms),
                normalized_mode,
                _embyflow_v19_safe_text(status, 20),
                _embyflow_v19_safe_text(endpoint, 300),
            )

            if lock is not None:
                with lock:
                    slowest = state.setdefault("slowest", [])
                    slowest.append(item)
                    slowest.sort(key=lambda value: float(value[0]), reverse=True)
                    del slowest[20:]
        except Exception:
            pass

    message = "mode=%s ms=%.1f status=%s bytes=%d endpoint=%s" % (
        normalized_mode,
        float(duration_ms),
        _embyflow_v19_safe_text(status, 20),
        int(byte_count or 0),
        _embyflow_v19_safe_text(endpoint, 360),
    )

    if error:
        message += " error=%s" % _embyflow_v19_safe_text(error, 180)

    _embyflow_v19_emit("HTTP", message, state)


_EMBYFLOW_V19_ORIGINAL_HTTP_GET = embyflow_http_get
_EMBYFLOW_V19_ORIGINAL_HTTP_POST = embyflow_http_post
_EMBYFLOW_V19_ORIGINAL_HTTP_DELETE = embyflow_http_delete
_EMBYFLOW_V19_ORIGINAL_AUTH = get_emby_auth
_EMBYFLOW_V19_ORIGINAL_PERF_LOG = embyflow_perf_log
_EMBYFLOW_V19_ORIGINAL_HOME_INIT = EmbyFlowE2Screen.__init__
_EMBYFLOW_V19_ORIGINAL_MAIN = main


def _embyflow_v19_http_get(url, *args, **kwargs):
    mode = _embyflow_v19_cache_mode(url, args, kwargs)
    endpoint = _embyflow_v19_endpoint(url, kwargs)
    started = _embyflow_v19_mono()

    try:
        response = _EMBYFLOW_V19_ORIGINAL_HTTP_GET(
            url,
            *args,
            **kwargs
        )
        duration_ms = (_embyflow_v19_mono() - started) * 1000.0

        try:
            byte_count = len(getattr(response, "content", b"") or b"")
        except Exception:
            byte_count = 0

        _embyflow_v19_record_http(
            mode,
            duration_ms,
            endpoint,
            getattr(response, "status_code", "?"),
            byte_count,
        )
        return response

    except Exception as error:
        duration_ms = (_embyflow_v19_mono() - started) * 1000.0
        _embyflow_v19_record_http(
            mode,
            duration_ms,
            endpoint,
            "ERR",
            0,
            str(error),
        )
        raise


def _embyflow_v19_http_write(method, original, url, args, kwargs):
    endpoint = _embyflow_v19_endpoint(url, kwargs)
    started = _embyflow_v19_mono()

    try:
        response = original(url, *args, **kwargs)
        duration_ms = (_embyflow_v19_mono() - started) * 1000.0

        try:
            byte_count = len(getattr(response, "content", b"") or b"")
        except Exception:
            byte_count = 0

        _embyflow_v19_record_http(
            method,
            duration_ms,
            endpoint,
            getattr(response, "status_code", "?"),
            byte_count,
        )
        return response

    except Exception as error:
        duration_ms = (_embyflow_v19_mono() - started) * 1000.0
        _embyflow_v19_record_http(
            method,
            duration_ms,
            endpoint,
            "ERR",
            0,
            str(error),
        )
        raise


def _embyflow_v19_http_post(url, *args, **kwargs):
    return _embyflow_v19_http_write(
        "POST",
        _EMBYFLOW_V19_ORIGINAL_HTTP_POST,
        url,
        args,
        kwargs,
    )


def _embyflow_v19_http_delete(url, *args, **kwargs):
    return _embyflow_v19_http_write(
        "DELETE",
        _EMBYFLOW_V19_ORIGINAL_HTTP_DELETE,
        url,
        args,
        kwargs,
    )


def _embyflow_v19_auth(force=False):
    state = EMBYFLOW_V19_STATE
    started = _embyflow_v19_mono()
    _embyflow_v19_count("auth_calls", 1, state)

    try:
        result = _EMBYFLOW_V19_ORIGINAL_AUTH(force)
        duration_ms = (_embyflow_v19_mono() - started) * 1000.0

        try:
            token_present = int(bool(result[1]))
            user_present = int(bool(result[2]))
        except Exception:
            token_present = 0
            user_present = 0

        _embyflow_v19_emit(
            "AUTH",
            "ms=%.1f force=%d token=%d user=%d"
            % (
                duration_ms,
                int(bool(force)),
                token_present,
                user_present,
            ),
            state,
        )
        return result

    except Exception as error:
        _embyflow_v19_count("auth_errors", 1, state)
        _embyflow_v19_emit(
            "AUTH_ERR",
            "ms=%.1f force=%d error=%s"
            % (
                (_embyflow_v19_mono() - started) * 1000.0,
                int(bool(force)),
                _embyflow_v19_safe_text(error, 220),
            ),
            state,
        )
        raise


def _embyflow_v19_perf_log(stage, started=None, **fields):
    try:
        message_parts = []

        if started is not None:
            message_parts.append(
                "ms=%.1f"
                % ((time.time() - float(started)) * 1000.0)
            )

        for key in sorted(fields):
            message_parts.append(
                "%s=%s"
                % (
                    key,
                    _embyflow_v19_safe_text(fields[key], 120),
                )
            )

        _embyflow_v19_emit(
            "STAGE",
            "%s%s"
            % (
                _embyflow_v19_safe_text(stage, 120),
                (" | " + " ".join(message_parts))
                if message_parts
                else "",
            ),
        )
    except Exception:
        pass

    return _EMBYFLOW_V19_ORIGINAL_PERF_LOG(
        stage,
        started,
        **fields
    )


def _embyflow_v19_home_layout_visible(self):
    state = EMBYFLOW_V19_STATE

    if not isinstance(state, dict):
        return

    if state.get("home_visible"):
        return

    state["home_visible"] = True
    _embyflow_v19_emit(
        "HOME_VISIBLE",
        "Homescreen-Layout sichtbar",
        state,
    )


def _embyflow_v19_home_closed(self):
    state = EMBYFLOW_V19_STATE

    if not isinstance(state, dict):
        return

    if state.get("home_closed"):
        return

    state["home_closed"] = True
    _embyflow_v19_emit(
        "HOME_CLOSED",
        "Homescreen geschlossen",
        state,
    )


def _embyflow_v19_home_init(self, *args, **kwargs):
    _embyflow_v19_emit("HOME_INIT", "Homescreen wird erzeugt")
    started = _embyflow_v19_mono()

    _EMBYFLOW_V19_ORIGINAL_HOME_INIT(
        self,
        *args,
        **kwargs
    )

    _embyflow_v19_emit(
        "HOME_INIT_DONE",
        "ms=%.1f"
        % ((_embyflow_v19_mono() - started) * 1000.0),
    )

    try:
        self.onLayoutFinish.append(
            self.embyflow_v19_layout_visible
        )
    except Exception:
        pass

    try:
        self.onClose.append(
            self.embyflow_v19_home_closed
        )
    except Exception:
        pass


def _embyflow_v19_main(session, **kwargs):
    _embyflow_v19_start_monitor("plugin-open")
    _embyflow_v19_emit("MAIN", "EmbyFlow main() aufgerufen")
    return _EMBYFLOW_V19_ORIGINAL_MAIN(
        session,
        **kwargs
    )


def _embyflow_v19_wrap_home_method(method_name):
    original = getattr(EmbyFlowE2Screen, method_name, None)

    if not callable(original):
        return False

    marker_name = "_embyflow_v19_original_%s" % method_name

    if hasattr(EmbyFlowE2Screen, marker_name):
        return True

    setattr(EmbyFlowE2Screen, marker_name, original)

    def wrapped(self, *args, **kwargs):
        state = EMBYFLOW_V19_STATE
        started = _embyflow_v19_mono()
        _embyflow_v19_emit(
            "HOME_CALL",
            "%s start" % method_name,
            state,
        )

        try:
            result = original(self, *args, **kwargs)
            _embyflow_v19_emit(
                "HOME_CALL",
                "%s done ms=%.1f"
                % (
                    method_name,
                    (_embyflow_v19_mono() - started) * 1000.0,
                ),
                state,
            )
            return result
        except Exception as error:
            _embyflow_v19_emit(
                "HOME_ERROR",
                "%s ms=%.1f error=%s"
                % (
                    method_name,
                    (_embyflow_v19_mono() - started) * 1000.0,
                    _embyflow_v19_safe_text(error, 220),
                ),
                state,
            )
            raise

    wrapped.__name__ = str(method_name)
    setattr(EmbyFlowE2Screen, method_name, wrapped)
    return True


def _embyflow_v19_wrap_startup_apply():
    method_name = "_apply_startup_sync_result"
    original = getattr(EmbyFlowE2Screen, method_name, None)

    if not callable(original):
        return False

    marker_name = "_embyflow_v19_original_apply_startup_sync_result"

    if hasattr(EmbyFlowE2Screen, marker_name):
        return True

    setattr(EmbyFlowE2Screen, marker_name, original)

    def wrapped(self, *args, **kwargs):
        was_done = bool(
            getattr(self, "_startup_sync_worker_done", False)
        )
        result_snapshot = dict(
            getattr(self, "_startup_sync_worker_result", None)
            or {}
        )
        started = _embyflow_v19_mono()
        result = original(self, *args, **kwargs)

        if was_done:
            _embyflow_v19_emit(
                "SYNC_APPLIED",
                "ms=%.1f success=%d counts=%d error=%s"
                % (
                    (_embyflow_v19_mono() - started) * 1000.0,
                    int(bool(result_snapshot.get("success"))),
                    len(result_snapshot.get("counts", {}) or {}),
                    _embyflow_v19_safe_text(
                        result_snapshot.get("error", ""),
                        180,
                    ),
                ),
            )

        return result

    wrapped.__name__ = method_name
    setattr(EmbyFlowE2Screen, method_name, wrapped)
    return True


embyflow_http_get = _embyflow_v19_http_get
embyflow_http_post = _embyflow_v19_http_post
embyflow_http_delete = _embyflow_v19_http_delete
get_emby_auth = _embyflow_v19_auth
