# EMBYFLOW_PERFORMANCE_MONITOR_V19_END

# EMBYFLOW_PERFORMANCE_STORM_CONTROL_V20_START
# V20: gezielte Entlastung nach dem Homescreen.
# - kein kompletter Metadaten-Prewarm direkt nach Pluginstart
# - V11-Vollscan (Limit 5000) frühestens nach 10 Minuten und nur bei stale Cache
# - Startup-Zähler erst nach 8 Sekunden
# - force=True verursacht keinen zweiten Login, solange der zentrale Token gültig ist
# - Playback-POSTs leeren nicht länger den kompletten GET-Cache
# - Favoriten-/sonstige Mutationen invalidieren weiterhin sicher
# - V19-Monitor bleibt aktiv und misst den Vorher/Nachher-Lauf

try:
    import threading as _embyflow_v20_threading
except Exception:
    _embyflow_v20_threading = None

try:
    _embyflow_v20_mono = time.monotonic
except Exception:
    _embyflow_v20_mono = time.time

EMBYFLOW_V20_LOADED_MONO = _embyflow_v20_mono()
EMBYFLOW_V20_SESSION_OPEN_MONO = EMBYFLOW_V20_LOADED_MONO
EMBYFLOW_V20_LIBRARY_REFRESH_DELAY = 600.0
EMBYFLOW_V20_LIBRARY_REFRESH_AFTER = 21600.0
EMBYFLOW_V20_STARTUP_SYNC_DELAY_MS = 250
EMBYFLOW_V20_LIBRARY_REFRESH_LOCK = (
    _embyflow_v20_threading.RLock()
    if _embyflow_v20_threading is not None
    else None
)
EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE = set()

# V18 darf mehr kleine/mittlere Metadatenantworten behalten.
try:
    EMBYFLOW_V18_HTTP_CACHE_MAX = max(
        int(EMBYFLOW_V18_HTTP_CACHE_MAX or 0),
        160,
    )
    EMBYFLOW_V18_HTTP_CACHE_MAX_ITEM_BYTES = max(
        int(EMBYFLOW_V18_HTTP_CACHE_MAX_ITEM_BYTES or 0),
        2 * 1024 * 1024,
    )
    EMBYFLOW_API_RAM_CACHE_MAX = max(
        int(EMBYFLOW_API_RAM_CACHE_MAX or 0),
        160,
    )
except Exception:
    pass


def _embyflow_v20_monitor(stage, text=""):
    try:
        emitter = globals().get("_embyflow_v19_emit")
        if callable(emitter):
            emitter(str(stage), str(text or ""))
    except Exception:
        pass


def _embyflow_v20_cached_auth_valid():
    try:
        server = str(EMBY_SERVER or "").rstrip("/")
        if not server:
            return False

        cached_server = str(
            EMBY_AUTH_CACHE.get("server") or ""
        ).rstrip("/")
        token = str(EMBY_AUTH_CACHE.get("token") or "")
        user_id = str(EMBY_AUTH_CACHE.get("user_id") or "")
        stamp = int(EMBY_AUTH_CACHE.get("ts") or 0)

        return bool(
            cached_server == server
            and token
            and user_id
            and (int(time.time()) - stamp) < 21600
        )
    except Exception:
        return False


_EMBYFLOW_V20_PREVIOUS_AUTH = get_emby_auth


def _embyflow_v20_get_emby_auth(force=False):
    # Ein Startup-Sync darf einen gerade erfolgreich geholten Token nicht
    # unmittelbar durch einen zweiten AuthenticateByName-POST ersetzen.
    if force and _embyflow_v20_cached_auth_valid():
        force = False

    return _EMBYFLOW_V20_PREVIOUS_AUTH(bool(force))


get_emby_auth = _embyflow_v20_get_emby_auth


def _embyflow_v20_clear_http_cache_matching(predicate):
    lock = globals().get("EMBYFLOW_V18_HTTP_STATE_LOCK")

    try:
        if lock is not None:
            with lock:
                keys = list(EMBYFLOW_V18_HTTP_CACHE.keys())
                for key in keys:
                    try:
                        if predicate(key):
                            EMBYFLOW_V18_HTTP_CACHE.pop(key, None)
                    except Exception:
                        pass
        else:
            keys = list(EMBYFLOW_V18_HTTP_CACHE.keys())
            for key in keys:
                try:
                    if predicate(key):
                        EMBYFLOW_V18_HTTP_CACHE.pop(key, None)
                except Exception:
                    pass
    except Exception:
        pass


def _embyflow_v20_clear_ram_cache_matching(predicate):
    try:
        lock = globals().get("EMBYFLOW_API_RAM_CACHE_LOCK")

        def _clear():
            keys = list(EMBYFLOW_API_RAM_CACHE.keys())
            for key in keys:
                try:
                    if predicate(key):
                        EMBYFLOW_API_RAM_CACHE.pop(key, None)
                except Exception:
                    pass

        if lock is not None:
            with lock:
                _clear()
        else:
            _clear()
    except Exception:
        pass


def _embyflow_v20_invalidate_resume_only():
    def http_match(key):
        text = repr(key).lower()
        return (
            "/items/resume" in text
            or "isresumable" in text
        )

    def ram_match(key):
        text = repr(key).lower()
        return (
            "resume" in text
            or "continue" in text
            or "isresumable" in text
        )

    _embyflow_v20_clear_http_cache_matching(http_match)
    _embyflow_v20_clear_ram_cache_matching(ram_match)



def _embyflow_v20_should_full_invalidate(url):
    lowered = str(url or "").lower()

    if "/users/authenticatebyname" in lowered:
        return False

    if "/sessions/playing/progress" in lowered:
        return False

    if lowered.endswith("/sessions/playing") or "/sessions/playing?" in lowered:
        return False

    if "/sessions/playing/stopped" in lowered:
        return False

    if "/favoriteitems/" in lowered:
        return True

    # Unbekannte schreibende Endpunkte bleiben aus Sicherheitsgründen
    # konservativ: Cache leeren statt möglicherweise veraltete Daten zeigen.
    return True



def _embyflow_v20_post_core(url, *args, **kwargs):
    response = _embyflow_v18_raw_request(
        "POST",
        url,
        *args,
        **kwargs
    )

    status = int(
        getattr(response, "status_code", 500)
        or 500
    )

    if status < 400:
        lowered = str(url or "").lower()

        if "/sessions/playing/stopped" in lowered:
            _embyflow_v20_invalidate_resume_only()
        elif _embyflow_v20_should_full_invalidate(url):
            _embyflow_v18_clear_response_caches()

    return response



def _embyflow_v20_delete_core(url, *args, **kwargs):
    response = _embyflow_v18_raw_request(
        "DELETE",
        url,
        *args,
        **kwargs
    )

    if int(getattr(response, "status_code", 500) or 500) < 400:
        _embyflow_v18_clear_response_caches()

    return response



def _embyflow_v20_http_post(url, *args, **kwargs):
    monitor_write = globals().get("_embyflow_v19_http_write")

    if callable(monitor_write):
        return monitor_write(
            "POST",
            _embyflow_v20_post_core,
            url,
            args,
            kwargs,
        )

    return _embyflow_v20_post_core(
        url,
        *args,
        **kwargs
    )



def _embyflow_v20_http_delete(url, *args, **kwargs):
    monitor_write = globals().get("_embyflow_v19_http_write")

    if callable(monitor_write):
        return monitor_write(
            "DELETE",
            _embyflow_v20_delete_core,
            url,
            args,
            kwargs,
        )

    return _embyflow_v20_delete_core(
        url,
        *args,
        **kwargs
    )


embyflow_http_post = _embyflow_v20_http_post
embyflow_http_delete = _embyflow_v20_http_delete


# Beginn der 10-Minuten-Sperrfrist ist das tatsächliche Öffnen von EmbyFlow,
# nicht der GUI-/Modulstart der Box.
_EMBYFLOW_V20_PREVIOUS_HOME_INIT = EmbyFlowE2Screen.__init__


def _embyflow_v20_home_init(self, *args, **kwargs):
    global EMBYFLOW_V20_SESSION_OPEN_MONO
    EMBYFLOW_V20_SESSION_OPEN_MONO = _embyflow_v20_mono()
    return _EMBYFLOW_V20_PREVIOUS_HOME_INIT(
        self,
        *args,
        **kwargs
    )


EmbyFlowE2Screen.__init__ = _embyflow_v20_home_init


# Heavy Prewarm war der Hauptverursacher des Request-Sturms: neben Movie/Series
# Limit=5000 wurden sofort Kategorien, Genres und Views vorab geladen. V20 lädt
# diese Daten ausschließlich on demand; vorhandene persistente Caches bleiben.
_EMBYFLOW_V20_ORIGINAL_METADATA_PREWARM = (
    EmbyFlowE2Screen._run_metadata_prewarm
)


def _embyflow_v20_metadata_prewarm(self):
    _embyflow_v20_monitor(
        "V20_PREWARM",
        "remote-prewarm=skipped on-demand=1"
    )


EmbyFlowE2Screen._run_metadata_prewarm = (
    _embyflow_v20_metadata_prewarm
)


# V11-Snapshot darf weiter benutzt werden, aber der Vollscan mit Limit=5000
# startet nicht mehr beim Homescreen bzw. bei jedem frühen Kategorieaufruf.
_EMBYFLOW_V20_ORIGINAL_V11_REFRESH_WORKER = (
    EmbyFlowInMemoryLibraryCache._refresh_worker
)


def _embyflow_v20_v11_refresh_async(self, include_types, force=False):
    include_types = str(include_types or "")

    if include_types not in ("Movie", "Series"):
        return

    now_mono = _embyflow_v20_mono()
    now_wall = time.time()
    session_started = float(
        globals().get("EMBYFLOW_V20_SESSION_OPEN_MONO")
        or EMBYFLOW_V20_LOADED_MONO
    )

    if (
        not force
        and now_mono - session_started
        < EMBYFLOW_V20_LIBRARY_REFRESH_DELAY
    ):
        return

    try:
        with self.lock:
            if include_types in self.loading:
                return

            values = self.items.get(include_types) or []
            age = now_wall - float(
                self.loaded_at.get(include_types) or 0.0
            )

            if (
                not force
                and values
                and age < EMBYFLOW_V20_LIBRARY_REFRESH_AFTER
            ):
                return
    except Exception:
        pass

    lock = EMBYFLOW_V20_LIBRARY_REFRESH_LOCK

    try:
        if lock is not None:
            with lock:
                if EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE:
                    return
                EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE.add(include_types)
        else:
            if EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE:
                return
            EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE.add(include_types)

        with self.lock:
            if include_types in self.loading:
                EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE.discard(include_types)
                return
            self.loading.add(include_types)

        def worker():
            try:
                _embyflow_v20_monitor(
                    "V20_V11_SCAN",
                    "start type=%s" % include_types
                )
                _EMBYFLOW_V20_ORIGINAL_V11_REFRESH_WORKER(
                    self,
                    include_types
                )
            finally:
                try:
                    if lock is not None:
                        with lock:
                            EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE.discard(
                                include_types
                            )
                    else:
                        EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE.discard(
                            include_types
                        )
                except Exception:
                    pass

        thread = _embyflow_v20_threading.Thread(
            target=worker,
            name="EmbyFlowLibraryV20%s" % include_types,
        )
        thread.daemon = True
        thread.start()

    except Exception:
        try:
            with self.lock:
                self.loading.discard(include_types)
        except Exception:
            pass
        try:
            EMBYFLOW_V20_LIBRARY_REFRESH_ACTIVE.discard(include_types)
        except Exception:
            pass


EmbyFlowInMemoryLibraryCache.refresh_async = (
    _embyflow_v20_v11_refresh_async
)
EMBYFLOW_LIBRARY_CACHE_V11.REFRESH_AFTER = int(
    EMBYFLOW_V20_LIBRARY_REFRESH_AFTER
)


# Startup-Zähler bleiben asynchron, konkurrieren aber nicht mehr direkt mit
# Login, Continue-Prefetch und den ersten Benutzereingaben.
_EMBYFLOW_V20_ORIGINAL_START_SYNC = (
    EmbyFlowE2Screen.start_library_sync_by_mode
)


def _embyflow_v20_start_library_sync_by_mode(self):
    if getattr(self, "_embyflow_sync_mode_started", False):
        return

    if embyflow_sync_mode_value() == "daily":
        return _EMBYFLOW_V20_ORIGINAL_START_SYNC(self)

    self._embyflow_sync_mode_started = True
    self.startup_library_sync_timer = eTimer()

    try:
        self.startup_library_sync_timer.callback.append(
            self.run_startup_library_sync
        )
    except Exception:
        try:
            self.startup_library_sync_timer.timeout.connect(
                self.run_startup_library_sync
            )
        except Exception:
            pass

    try:
        self.startup_library_sync_timer.start(
            EMBYFLOW_V20_STARTUP_SYNC_DELAY_MS,
            True
        )
        _embyflow_v20_monitor(
            "V20_SYNC_DELAY",
            "ms=%d" % EMBYFLOW_V20_STARTUP_SYNC_DELAY_MS
        )
    except Exception:
        self.run_startup_library_sync()


EmbyFlowE2Screen.start_library_sync_by_mode = (
    _embyflow_v20_start_library_sync_by_mode
)

# EMBYFLOW_PERFORMANCE_STORM_CONTROL_V20_END

# EMBYFLOW_IMAGE_PIPELINE_CONTROL_V21_START
# V21: begrenzt die Bildpipeline auf wenige wiederverwendete Decoder und
# dedupliziert identische Bild-HTTP-Aufrufe. Ziel: keine ePicLoad-/Thread-
# Explosion beim schnellen Navigieren, ohne Layout oder Datenlogik zu ändern.

try:
    import threading as _embyflow_v21_threading
except Exception:
    _embyflow_v21_threading = None

try:
    import weakref as _embyflow_v21_weakref
except Exception:
    _embyflow_v21_weakref = None

try:
    from collections import deque as _embyflow_v21_deque
    from collections import OrderedDict as _embyflow_v21_ordered_dict
except Exception:
    _embyflow_v21_deque = None
    _embyflow_v21_ordered_dict = dict

try:
    _embyflow_v21_mono = time.monotonic
except Exception:
    _embyflow_v21_mono = time.time

EMBYFLOW_V21_IMAGE_HTTP_PARALLEL = 4
EMBYFLOW_V21_IMAGE_SUCCESS_TTL = 5.0
EMBYFLOW_V21_IMAGE_NEGATIVE_TTL = 600.0
EMBYFLOW_V21_IMAGE_CACHE_MAX = 16
EMBYFLOW_V21_PICLOAD_POOL_SIZE = 3
EMBYFLOW_V21_PICLOAD_QUEUE_MAX = 96

EMBYFLOW_V21_IMAGE_HTTP_LOCK = (
    _embyflow_v21_threading.RLock()
    if _embyflow_v21_threading is not None
    else None
)
EMBYFLOW_V21_IMAGE_HTTP_SEMAPHORE = (
    _embyflow_v21_threading.BoundedSemaphore(
        EMBYFLOW_V21_IMAGE_HTTP_PARALLEL
    )
    if _embyflow_v21_threading is not None
    else None
)
EMBYFLOW_V21_IMAGE_HTTP_CACHE = _embyflow_v21_ordered_dict()
EMBYFLOW_V21_IMAGE_HTTP_INFLIGHT = {}

EMBYFLOW_V21_PICLOAD_LOCK = (
    _embyflow_v21_threading.RLock()
    if _embyflow_v21_threading is not None
    else None
)
EMBYFLOW_V21_PICLOAD_QUEUE = (
    _embyflow_v21_deque()
    if _embyflow_v21_deque is not None
    else []
)
EMBYFLOW_V21_PICLOAD_LOADERS = []
EMBYFLOW_V21_PICLOAD_CONNECTIONS = []
EMBYFLOW_V21_PICLOAD_ACTIVE = []
EMBYFLOW_V21_PICLOAD_CURRENT = {}
EMBYFLOW_V21_PICLOAD_PENDING = {}
EMBYFLOW_V21_PICLOAD_READY = False
EMBYFLOW_V21_PICLOAD_SEQUENCE = 0

EMBYFLOW_V21_FILE_VALID_CACHE = _embyflow_v21_ordered_dict()
EMBYFLOW_V21_FILE_VALID_CACHE_MAX = 512


def _embyflow_v21_monitor(stage, text=""):
    try:
        emitter = globals().get("_embyflow_v19_emit")
        if callable(emitter):
            emitter(str(stage), str(text or ""))
    except Exception:
        pass


class _EmbyFlowV21ImageResponse(object):
    def __init__(self, status_code=599, content=b"", headers=None, url=""):
        self.status_code = int(status_code or 0)
        self.content = content if isinstance(content, bytes) else bytes(content or b"")
        self.headers = dict(headers or {})
        self.url = str(url or "")

    @property
    def ok(self):
        return 200 <= int(self.status_code) < 400

    def raise_for_status(self):
        if int(self.status_code) >= 400:
            raise RuntimeError(
                "HTTP %s for %s" % (
                    self.status_code,
                    self.url,
                )
            )


def _embyflow_v21_image_url(url):
    lowered = str(url or "").lower()
    return (
        "/images/" in lowered
        or lowered.endswith("/images")
    )


def _embyflow_v21_response_snapshot(response, url):
    try:
        status = int(getattr(response, "status_code", 599) or 599)
    except Exception:
        status = 599

    try:
        content = getattr(response, "content", b"") or b""
        if not isinstance(content, bytes):
            content = bytes(content)
    except Exception:
        content = b""

    try:
        headers = dict(getattr(response, "headers", {}) or {})
    except Exception:
        headers = {}

    return (
        status,
        content,
        headers,
        str(url or ""),
    )


def _embyflow_v21_response_from_snapshot(snapshot):
    try:
        status, content, headers, url = snapshot
        return _EmbyFlowV21ImageResponse(
            status,
            content,
            headers,
            url,
        )
    except Exception:
        return _EmbyFlowV21ImageResponse()


def _embyflow_v21_image_cache_get(key):
    now_value = _embyflow_v21_mono()

    try:
        entry = EMBYFLOW_V21_IMAGE_HTTP_CACHE.get(key)
        if not entry:
            return None

        expires, snapshot = entry
        if float(expires or 0.0) <= now_value:
            EMBYFLOW_V21_IMAGE_HTTP_CACHE.pop(key, None)
            return None

        try:
            EMBYFLOW_V21_IMAGE_HTTP_CACHE.move_to_end(key)
        except Exception:
            pass

        return snapshot
    except Exception:
        return None


def _embyflow_v21_image_cache_put(key, snapshot):
    try:
        status = int(snapshot[0] or 0)
        content = snapshot[1] or b""

        if status == 200 and len(content) > 500:
            ttl = EMBYFLOW_V21_IMAGE_SUCCESS_TTL
        elif status in (404, 410):
            ttl = EMBYFLOW_V21_IMAGE_NEGATIVE_TTL
        else:
            ttl = 2.0

        EMBYFLOW_V21_IMAGE_HTTP_CACHE[key] = (
            _embyflow_v21_mono() + float(ttl),
            snapshot,
        )

        try:
            EMBYFLOW_V21_IMAGE_HTTP_CACHE.move_to_end(key)
        except Exception:
            pass

        while len(EMBYFLOW_V21_IMAGE_HTTP_CACHE) > EMBYFLOW_V21_IMAGE_CACHE_MAX:
            try:
                EMBYFLOW_V21_IMAGE_HTTP_CACHE.popitem(last=False)
            except TypeError:
                first = next(iter(EMBYFLOW_V21_IMAGE_HTTP_CACHE))
                EMBYFLOW_V21_IMAGE_HTTP_CACHE.pop(first, None)
            except Exception:
                break
    except Exception:
        pass


_EMBYFLOW_V21_PREVIOUS_HTTP_GET = embyflow_http_get


def _embyflow_v21_http_get(url, *args, **kwargs):
    if not _embyflow_v21_image_url(url):
        return _EMBYFLOW_V21_PREVIOUS_HTTP_GET(
            url,
            *args,
            **kwargs
        )

    key = str(url or "")

    if EMBYFLOW_V21_IMAGE_HTTP_LOCK is None:
        return _EMBYFLOW_V21_PREVIOUS_HTTP_GET(
            url,
            *args,
            **kwargs
        )

    leader = False
    event = None

    with EMBYFLOW_V21_IMAGE_HTTP_LOCK:
        snapshot = _embyflow_v21_image_cache_get(key)
        if snapshot is not None:
            _embyflow_v21_monitor(
                "V21_IMG_HIT",
                "status=%s" % snapshot[0]
            )
            return _embyflow_v21_response_from_snapshot(snapshot)

        event = EMBYFLOW_V21_IMAGE_HTTP_INFLIGHT.get(key)

        if event is None:
            event = _embyflow_v21_threading.Event()
            EMBYFLOW_V21_IMAGE_HTTP_INFLIGHT[key] = event
            leader = True

    if not leader:
        _embyflow_v21_monitor("V21_IMG_JOIN", "wait=1")

        try:
            timeout_value = float(kwargs.get("timeout", 10) or 10)
        except Exception:
            timeout_value = 10.0

        try:
            event.wait(max(2.0, timeout_value + 2.0))
        except Exception:
            pass

        with EMBYFLOW_V21_IMAGE_HTTP_LOCK:
            snapshot = _embyflow_v21_image_cache_get(key)

        if snapshot is not None:
            return _embyflow_v21_response_from_snapshot(snapshot)

        # Der Leader ist fehlgeschlagen. Nicht sofort einen neuen Sturm erzeugen.
        return _EmbyFlowV21ImageResponse(
            599,
            b"",
            {},
            key,
        )

    response = None
    snapshot = None

    try:
        semaphore = EMBYFLOW_V21_IMAGE_HTTP_SEMAPHORE

        if semaphore is not None:
            semaphore.acquire()

        try:
            response = _EMBYFLOW_V21_PREVIOUS_HTTP_GET(
                url,
                *args,
                **kwargs
            )
        finally:
            if semaphore is not None:
                semaphore.release()

        snapshot = _embyflow_v21_response_snapshot(
            response,
            key,
        )

        with EMBYFLOW_V21_IMAGE_HTTP_LOCK:
            _embyflow_v21_image_cache_put(key, snapshot)

        return response

    except Exception:
        snapshot = (599, b"", {}, key)

        with EMBYFLOW_V21_IMAGE_HTTP_LOCK:
            _embyflow_v21_image_cache_put(key, snapshot)

        raise

    finally:
        with EMBYFLOW_V21_IMAGE_HTTP_LOCK:
            waiter = EMBYFLOW_V21_IMAGE_HTTP_INFLIGHT.pop(
                key,
                None,
            )

        if waiter is not None:
            try:
                waiter.set()
            except Exception:
                pass


embyflow_http_get = _embyflow_v21_http_get


# Cache-Dateien wurden bereits beim Schreiben validiert. Die bisherige
# _grid_cache_valid()-Variante dekodierte jedes Bild zusätzlich synchron mit
# LoadPixmap, bevor anschließend ePicLoad noch einmal dekodierte.
_EMBYFLOW_V21_ORIGINAL_GRID_FILE_VALID = _grid_cache_file_valid


def _embyflow_v21_grid_file_valid(path):
    try:
        stat_value = os.stat(path)
        signature = (
            str(path),
            int(stat_value.st_size or 0),
            int(stat_value.st_mtime or 0),
        )
    except Exception:
        return False

    try:
        cached = EMBYFLOW_V21_FILE_VALID_CACHE.get(signature)
        if cached is not None:
            try:
                EMBYFLOW_V21_FILE_VALID_CACHE.move_to_end(signature)
            except Exception:
                pass
            return bool(cached)
    except Exception:
        pass

    valid = bool(
        _EMBYFLOW_V21_ORIGINAL_GRID_FILE_VALID(path)
    )

    try:
        EMBYFLOW_V21_FILE_VALID_CACHE[signature] = valid
        while len(EMBYFLOW_V21_FILE_VALID_CACHE) > EMBYFLOW_V21_FILE_VALID_CACHE_MAX:
            try:
                EMBYFLOW_V21_FILE_VALID_CACHE.popitem(last=False)
            except TypeError:
                first = next(iter(EMBYFLOW_V21_FILE_VALID_CACHE))
                EMBYFLOW_V21_FILE_VALID_CACHE.pop(first, None)
            except Exception:
                break
    except Exception:
        pass

    return valid


def _embyflow_v21_grid_cache_valid(path):
    valid = _embyflow_v21_grid_file_valid(path)

    if valid:
        try:
            embyflow_touch_cache_file(path)
        except Exception:
            pass

    return bool(valid)


_grid_cache_file_valid = _embyflow_v21_grid_file_valid
_grid_cache_valid = _embyflow_v21_grid_cache_valid


def _embyflow_v21_owner_ref(owner):
    if _embyflow_v21_weakref is not None:
        try:
            return _embyflow_v21_weakref.ref(owner)
        except Exception:
            pass

    return lambda: owner


def _embyflow_v21_apply_pixmap(job, data):
    try:
        owner = job["owner_ref"]()
        if owner is None or data is None:
            return False

        current_test = job.get("is_current")
        if callable(current_test) and not current_test():
            return False

        key = job["key"]
        request_id = job["request_id"]

        if EMBYFLOW_V21_PICLOAD_CURRENT.get(key) != request_id:
            return False

        widget = owner[job["widget_name"]]
        instance = getattr(widget, "instance", None)

        if instance is None:
            return False

        try:
            instance.setPixmap(None)
        except Exception:
            pass

        instance.setPixmap(data)

        try:
            instance.setScale(1)
        except Exception:
            pass

        try:
            widget.show()
            instance.show()
            instance.invalidate()
        except Exception:
            pass

        try:
            embyflow_touch_cache_file(job["path"])
        except Exception:
            pass

        return True

    except Exception:
        return False


def _embyflow_v21_picload_ready(index):
    try:
        with EMBYFLOW_V21_PICLOAD_LOCK:
            job = EMBYFLOW_V21_PICLOAD_ACTIVE[index]
            EMBYFLOW_V21_PICLOAD_ACTIVE[index] = None

        if job is not None:
            try:
                loader = EMBYFLOW_V21_PICLOAD_LOADERS[index]
                data = loader.getData()
                _embyflow_v21_apply_pixmap(job, data)
            except Exception:
                pass

            try:
                with EMBYFLOW_V21_PICLOAD_LOCK:
                    key = job["key"]
                    if EMBYFLOW_V21_PICLOAD_PENDING.get(key) == job["request_id"]:
                        EMBYFLOW_V21_PICLOAD_PENDING.pop(key, None)
            except Exception:
                pass

    finally:
        _embyflow_v21_picload_pump()


def _embyflow_v21_init_picload_pool():
    global EMBYFLOW_V21_PICLOAD_READY

    if EMBYFLOW_V21_PICLOAD_READY:
        return True

    if ePicLoad is None:
        return False

    with EMBYFLOW_V21_PICLOAD_LOCK:
        if EMBYFLOW_V21_PICLOAD_READY:
            return True

        created_loaders = []
        created_connections = []

        try:
            for index in range(EMBYFLOW_V21_PICLOAD_POOL_SIZE):
                loader = ePicLoad()

                def ready_callback(*_args, _index=index):
                    _embyflow_v21_picload_ready(_index)

                connection = None
                connected = False

                try:
                    loader.PictureData.get().append(ready_callback)
                    connected = True
                except Exception:
                    try:
                        connection = loader.PictureData.connect(
                            ready_callback
                        )
                        connected = True
                    except Exception:
                        connected = False

                if not connected:
                    raise RuntimeError(
                        "ePicLoad callback konnte nicht verbunden werden"
                    )

                created_loaders.append(loader)
                created_connections.append(connection)

            EMBYFLOW_V21_PICLOAD_LOADERS[:] = created_loaders
            EMBYFLOW_V21_PICLOAD_CONNECTIONS[:] = created_connections
            EMBYFLOW_V21_PICLOAD_ACTIVE[:] = [
                None
                for _unused in created_loaders
            ]
            EMBYFLOW_V21_PICLOAD_READY = True

            _embyflow_v21_monitor(
                "V21_PICLOAD_POOL",
                "size=%d" % len(created_loaders)
            )
            return True

        except Exception:
            EMBYFLOW_V21_PICLOAD_LOADERS[:] = []
            EMBYFLOW_V21_PICLOAD_CONNECTIONS[:] = []
            EMBYFLOW_V21_PICLOAD_ACTIVE[:] = []
            EMBYFLOW_V21_PICLOAD_READY = False
            return False


def _embyflow_v21_queue_popleft():
    try:
        return EMBYFLOW_V21_PICLOAD_QUEUE.popleft()
    except AttributeError:
        if EMBYFLOW_V21_PICLOAD_QUEUE:
            return EMBYFLOW_V21_PICLOAD_QUEUE.pop(0)
    except Exception:
        pass
    return None


def _embyflow_v21_queue_append(job):
    try:
        EMBYFLOW_V21_PICLOAD_QUEUE.append(job)
    except Exception:
        return False

    try:
        while len(EMBYFLOW_V21_PICLOAD_QUEUE) > EMBYFLOW_V21_PICLOAD_QUEUE_MAX:
            old_job = _embyflow_v21_queue_popleft()
            if old_job is None:
                break
            key = old_job.get("key")
            request_id = old_job.get("request_id")
            if EMBYFLOW_V21_PICLOAD_PENDING.get(key) == request_id:
                EMBYFLOW_V21_PICLOAD_PENDING.pop(key, None)
    except Exception:
        pass

    return True


def _embyflow_v21_picload_pump():
    if not _embyflow_v21_init_picload_pool():
        return

    while True:
        slot_index = None
        job = None

        with EMBYFLOW_V21_PICLOAD_LOCK:
            for index, active in enumerate(EMBYFLOW_V21_PICLOAD_ACTIVE):
                if active is None:
                    slot_index = index
                    break

            if slot_index is None:
                return

            while True:
                candidate = _embyflow_v21_queue_popleft()

                if candidate is None:
                    return

                key = candidate.get("key")
                request_id = candidate.get("request_id")

                if EMBYFLOW_V21_PICLOAD_CURRENT.get(key) != request_id:
                    if EMBYFLOW_V21_PICLOAD_PENDING.get(key) == request_id:
                        EMBYFLOW_V21_PICLOAD_PENDING.pop(key, None)
                    continue

                owner = candidate["owner_ref"]()
                if owner is None:
                    EMBYFLOW_V21_PICLOAD_PENDING.pop(key, None)
                    continue

                current_test = candidate.get("is_current")
                if callable(current_test):
                    try:
                        if not current_test():
                            EMBYFLOW_V21_PICLOAD_PENDING.pop(key, None)
                            continue
                    except Exception:
                        EMBYFLOW_V21_PICLOAD_PENDING.pop(key, None)
                        continue

                job = candidate
                EMBYFLOW_V21_PICLOAD_ACTIVE[slot_index] = job
                break

        loader = EMBYFLOW_V21_PICLOAD_LOADERS[slot_index]

        try:
            loader.setPara((
                int(job["width"]),
                int(job["height"]),
                1,
                1,
                False,
                1,
                "#00000000",
            ))

            result = loader.startDecode(job["path"])

            if result in (0, None):
                # Dieser Slot bleibt bis zum PictureData-Callback belegt.
                continue

        except Exception:
            pass

        with EMBYFLOW_V21_PICLOAD_LOCK:
            EMBYFLOW_V21_PICLOAD_ACTIVE[slot_index] = None
            key = job["key"]
            if EMBYFLOW_V21_PICLOAD_PENDING.get(key) == job["request_id"]:
                EMBYFLOW_V21_PICLOAD_PENDING.pop(key, None)


def _embyflow_v21_decode_image_to_widget(
    owner,
    widget_name,
    path,
    width,
    height,
    token="",
    is_current=None,
):
    global EMBYFLOW_V21_PICLOAD_SEQUENCE

    try:
        image_path = str(path or "")

        if (
            not image_path
            or not os.path.isfile(image_path)
            or os.path.getsize(image_path) <= 500
        ):
            return False

        target_w = max(1, int(width or 1))
        target_h = max(1, int(height or 1))
        request_token = str(
            token
            or widget_name
            or image_path
        )
        key = (
            id(owner),
            request_token,
        )
        signature = (
            image_path,
            target_w,
            target_h,
        )

        if ePicLoad is None or EMBYFLOW_V21_PICLOAD_LOCK is None:
            try:
                if callable(is_current) and not is_current():
                    return False
                data = LoadPixmap(image_path)
                widget = owner[widget_name]
                instance = getattr(widget, "instance", None)
                if instance is None or data is None:
                    return False
                try:
                    instance.setPixmap(None)
                except Exception:
                    pass
                instance.setPixmap(data)
                try:
                    instance.setScale(1)
                except Exception:
                    pass
                try:
                    widget.show()
                    instance.show()
                    instance.invalidate()
                except Exception:
                    pass
                embyflow_touch_cache_file(image_path)
                return True
            except Exception:
                return False

        with EMBYFLOW_V21_PICLOAD_LOCK:
            pending_id = EMBYFLOW_V21_PICLOAD_PENDING.get(key)

            if pending_id is not None:
                current_id = EMBYFLOW_V21_PICLOAD_CURRENT.get(key)
                if current_id == pending_id:
                    for active in EMBYFLOW_V21_PICLOAD_ACTIVE:
                        if (
                            active is not None
                            and active.get("key") == key
                            and active.get("request_id") == pending_id
                            and active.get("signature") == signature
                        ):
                            return True

                    try:
                        for queued_job in EMBYFLOW_V21_PICLOAD_QUEUE:
                            if (
                                queued_job.get("key") == key
                                and queued_job.get("request_id") == pending_id
                                and queued_job.get("signature") == signature
                            ):
                                return True
                    except Exception:
                        pass

            EMBYFLOW_V21_PICLOAD_SEQUENCE += 1
            request_id = EMBYFLOW_V21_PICLOAD_SEQUENCE
            EMBYFLOW_V21_PICLOAD_CURRENT[key] = request_id
            EMBYFLOW_V21_PICLOAD_PENDING[key] = request_id

            job = {
                "owner_ref": _embyflow_v21_owner_ref(owner),
                "key": key,
                "request_id": request_id,
                "signature": signature,
                "widget_name": str(widget_name),
                "path": image_path,
                "width": target_w,
                "height": target_h,
                "is_current": is_current,
            }

            _embyflow_v21_queue_append(job)

        _embyflow_v21_picload_pump()
        return True

    except Exception:
        return False


embyflow_decode_image_to_widget = _embyflow_v21_decode_image_to_widget


# Der Player hatte noch einen zweiten, direkten ePicLoad-Pfad außerhalb der
# zentralen Hilfsfunktion. Auch dieser nutzt ab V21 denselben Pool.
def _embyflow_v21_player_decode_poster(self, path):
    path = str(path or "")

    if (
        getattr(self, "player_poster_closed", False)
        or not path
        or not _grid_cache_file_valid(path)
    ):
        return False

    if self.player_poster_loaded_path == path:
        if self.overlay_visible:
            try:
                self["player_poster"].show()
            except Exception:
                pass
        return True

    accepted = embyflow_decode_image_to_widget(
        self,
        "player_poster",
        path,
        sx(170),
        sy(255),
        token="player-poster",
        is_current=lambda: (
            not getattr(self, "player_poster_closed", False)
            and str(path) == str(getattr(self, "player_poster_ready_path", "") or path)
        ),
    )

    if accepted:
        self.player_poster_loaded_path = path

    return bool(accepted)


EmbyFlowMoviePlayer.decode_player_poster = (
    _embyflow_v21_player_decode_poster
)

# EMBYFLOW_IMAGE_PIPELINE_CONTROL_V21_END

# EMBYFLOW_LOCAL_EPISODE_SAFE_ROOT_V21A_START
# Hotfix: EmbyFlowLocalEpisodesScreenV7 nutzt den gemeinsamen lokalen Player,
# besaß aber keine safe_within_root()-Methode. Dadurch crashte OK/Abspielen.
def _embyflow_v21a_local_episode_safe_within_root(self, candidate):
    return EmbyFlowLocalMediaScreen.safe_within_root(self, candidate)

EmbyFlowLocalEpisodesScreenV7.safe_within_root = (
    _embyflow_v21a_local_episode_safe_within_root
)
# EMBYFLOW_LOCAL_EPISODE_SAFE_ROOT_V21A_END


# EMBYFLOW_LOCAL_MEDIA_PROBE_AV1_GUARD_V21B_START
# V21b: lokale Dateien vor dem Start einmal mit ffprobe einlesen. Dadurch
# bekommt der eigene Player echte Video-/Audio-Metadaten statt der alten
# H264/AAC-Fallback-Badges. AV1 wird auf diesem Receiver vor dem Start sauber
# abgefangen, statt einen schwarzen Player ohne Bild/Ton zu öffnen.
try:
    import subprocess as _embyflow_v21b_subprocess
except Exception:
    _embyflow_v21b_subprocess = None

EMBYFLOW_V21B_PROBE_CACHE = {}
EMBYFLOW_V21B_PROBE_CACHE_MAX = 64
EMBYFLOW_V21B_PROBE_TIMEOUT = 4


def _embyflow_v21b_int(value, default=0):
    try:
        if value in (None, "", "N/A"):
            return int(default)
        return int(value)
    except Exception:
        return int(default)


def _embyflow_v21b_float(value, default=0.0):
    try:
        if value in (None, "", "N/A"):
            return float(default)
        return float(value)
    except Exception:
        return float(default)


def _embyflow_v21b_bit_depth(stream):
    value = _embyflow_v21b_int(
        (stream or {}).get("bits_per_raw_sample"),
        0,
    )
    if value > 0:
        return value

    pix_fmt = str((stream or {}).get("pix_fmt") or "").lower()
    match = re.search(r"(?:p|gbrp|gray|yuv\d+p)(10|12|16)(?:le|be)?$", pix_fmt)
    if match:
        return _embyflow_v21b_int(match.group(1), 0)

    match = re.search(r"(?:p0|p)(10|12)(?:le|be)?", pix_fmt)
    if match:
        return _embyflow_v21b_int(match.group(1), 0)

    if "10" in pix_fmt:
        return 10
    if "12" in pix_fmt:
        return 12
    return 8 if pix_fmt else 0


def _embyflow_v21b_probe_cache_key(path):
    try:
        info = os.stat(path)
        mtime_ns = getattr(info, "st_mtime_ns", None)
        if mtime_ns is None:
            mtime_ns = int(float(info.st_mtime) * 1000000000.0)
        return (
            os.path.realpath(path),
            int(info.st_size or 0),
            int(mtime_ns or 0),
        )
    except Exception:
        return (os.path.realpath(str(path or "")), 0, 0)


def _embyflow_v21b_probe_local_file(path):
    real_path = os.path.realpath(str(path or ""))
    key = _embyflow_v21b_probe_cache_key(real_path)
    cached = EMBYFLOW_V21B_PROBE_CACHE.get(key)
    if isinstance(cached, dict):
        return dict(cached)

    result = {
        "ok": False,
        "path": real_path,
        "format_name": "",
        "duration": 0.0,
        "runtime_ticks": 0,
        "media_streams": [],
        "default_audio_index": None,
        "error": "",
    }

    ffprobe = "/usr/bin/ffprobe"
    if _embyflow_v21b_subprocess is None or not os.path.isfile(ffprobe):
        result["error"] = "ffprobe nicht verfügbar"
        return result

    command = [
        ffprobe,
        "-v", "error",
        "-print_format", "json",
        "-show_entries",
        "format=format_name,duration,size:"
        "stream=index,codec_type,codec_name,profile,pix_fmt,width,height,"
        "sample_rate,channels,bits_per_raw_sample:"
        "stream_tags=language,title",
        real_path,
    ]

    try:
        # EMBYFLOW_LOCAL_MEDIA_PROBE_JSON_FIX_V21C_START
        # ffprobe/decoder warnings (notably libdav1d with AV1) must never be
        # merged into stdout, otherwise the JSON document becomes invalid.
        raw = _embyflow_v21b_subprocess.check_output(
            command,
            stderr=_embyflow_v21b_subprocess.DEVNULL,
            timeout=EMBYFLOW_V21B_PROBE_TIMEOUT,
        )
        raw_text = raw.decode("utf-8", "replace").strip()
        json_start = raw_text.find("{")
        json_end = raw_text.rfind("}")
        if json_start < 0 or json_end < json_start:
            raise ValueError("ffprobe lieferte kein JSON")
        data = json.loads(raw_text[json_start:json_end + 1])
        # EMBYFLOW_LOCAL_MEDIA_PROBE_JSON_FIX_V21C_END
        format_data = data.get("format") or {}
        duration = _embyflow_v21b_float(format_data.get("duration"), 0.0)
        mapped_streams = []
        first_audio_index = None

        for raw_stream in data.get("streams") or []:
            stream_type = str(raw_stream.get("codec_type") or "").lower()
            if stream_type not in ("video", "audio", "subtitle"):
                continue

            mapped_type = {
                "video": "Video",
                "audio": "Audio",
                "subtitle": "Subtitle",
            }[stream_type]
            codec = str(raw_stream.get("codec_name") or "").strip().lower()
            profile = str(raw_stream.get("profile") or "").strip()
            tags = raw_stream.get("tags") or {}
            stream_index = _embyflow_v21b_int(raw_stream.get("index"), 0)
            mapped = {
                "Index": stream_index,
                "Type": mapped_type,
                "Codec": codec,
            }

            if profile and profile.lower() not in ("unknown", "n/a"):
                mapped["Profile"] = profile

            language = str(tags.get("language") or "").strip()
            if language:
                mapped["Language"] = language

            title = str(tags.get("title") or "").strip()
            if title:
                mapped["Title"] = title

            if stream_type == "video":
                width = _embyflow_v21b_int(raw_stream.get("width"), 0)
                height = _embyflow_v21b_int(raw_stream.get("height"), 0)
                bit_depth = _embyflow_v21b_bit_depth(raw_stream)
                pix_fmt = str(raw_stream.get("pix_fmt") or "").strip()
                if width:
                    mapped["Width"] = width
                if height:
                    mapped["Height"] = height
                if bit_depth:
                    mapped["BitDepth"] = bit_depth
                if pix_fmt:
                    mapped["PixelFormat"] = pix_fmt

            elif stream_type == "audio":
                channels = _embyflow_v21b_int(raw_stream.get("channels"), 0)
                sample_rate = _embyflow_v21b_int(raw_stream.get("sample_rate"), 0)
                if channels:
                    mapped["Channels"] = channels
                if sample_rate:
                    mapped["SampleRate"] = sample_rate
                if first_audio_index is None:
                    first_audio_index = stream_index

            mapped_streams.append(mapped)

        result.update({
            "ok": True,
            "format_name": str(format_data.get("format_name") or ""),
            "duration": duration,
            "runtime_ticks": int(max(0.0, duration) * 10000000.0),
            "media_streams": mapped_streams,
            "default_audio_index": first_audio_index,
            "error": "",
        })

        if len(EMBYFLOW_V21B_PROBE_CACHE) >= EMBYFLOW_V21B_PROBE_CACHE_MAX:
            try:
                first_key = next(iter(EMBYFLOW_V21B_PROBE_CACHE))
                EMBYFLOW_V21B_PROBE_CACHE.pop(first_key, None)
            except Exception:
                EMBYFLOW_V21B_PROBE_CACHE.clear()

        EMBYFLOW_V21B_PROBE_CACHE[key] = dict(result)
        return result

    except Exception as error:
        result["error"] = str(error)
        try:
            with embyflow_open_log(
                "/tmp/embyflow_local_probe_error.log",
                "a",
            ) as log:
                log.write(
                    "%s PROBE path=%s error=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        real_path,
                        str(error),
                    )
                )
        except Exception:
            pass
        return result


def _embyflow_v21b_first_stream(probe, stream_type):
    wanted = str(stream_type or "").lower()
    for stream in (probe or {}).get("media_streams") or []:
        if str(stream.get("Type") or "").lower() == wanted:
            return stream
    return {}


def _embyflow_v21b_resolution_label(video):
    width = _embyflow_v21b_int((video or {}).get("Width"), 0)
    height = _embyflow_v21b_int((video or {}).get("Height"), 0)
    if width >= 3800 or height >= 2100:
        return "4K"
    if width >= 1900 or height >= 1000:
        return "1080p"
    if height >= 700:
        return "720p"
    if height:
        return "%dp" % height
    return ""


def _embyflow_v21b_codec_label(codec):
    value = str(codec or "").strip().lower()
    return {
        "av1": "AV1",
        "h264": "H.264",
        "avc": "H.264",
        "hevc": "HEVC",
        "h265": "HEVC",
        "eac3": "E-AC3",
        "ac3": "AC3",
        "aac": "AAC",
        "dts": "DTS",
        "dca": "DTS",
        "truehd": "TrueHD",
    }.get(value, value.upper() if value else "")


def _embyflow_v21b_av1_message(probe):
    video = _embyflow_v21b_first_stream(probe, "video")
    audio = _embyflow_v21b_first_stream(probe, "audio")
    video_parts = []
    audio_parts = []

    codec = _embyflow_v21b_codec_label(video.get("Codec"))
    if codec:
        video_parts.append(codec)
    resolution = _embyflow_v21b_resolution_label(video)
    if resolution:
        video_parts.append(resolution)
    bit_depth = _embyflow_v21b_int(video.get("BitDepth"), 0)
    if bit_depth:
        video_parts.append("%d-Bit" % bit_depth)
    profile = str(video.get("Profile") or "").strip()
    if profile:
        video_parts.append(profile)

    audio_codec = _embyflow_v21b_codec_label(audio.get("Codec"))
    if audio_codec:
        audio_parts.append(audio_codec)
    channels = _embyflow_v21b_int(audio.get("Channels"), 0)
    if channels:
        audio_parts.append(
            "%s.0" % channels
            if channels <= 2
            else "%s.1" % max(1, channels - 1)
        )

    return (
        "Diese Datei kann auf diesem Receiver nicht direkt wiedergegeben werden.\n\n"
        "Video: %s\n"
        "Audio: %s\n\n"
        "AV1 wird auf der VU+ Duo 4K SE nicht hardwareseitig dekodiert. "
        "Die Datei wurde deshalb nicht gestartet."
        % (
            " · ".join(video_parts) or "AV1",
            " ".join(audio_parts) or "–",
        )
    )


_EMBYFLOW_V21B_ORIGINAL_LOCAL_PLAY_FILE = EmbyFlowLocalMediaScreen.play_file


def _embyflow_v21b_local_play_file(self, file_path):
    path = os.path.realpath(str(file_path or ""))

    if not self.safe_within_root(path) or not os.path.isfile(path):
        self.session.open(
            MessageBox,
            "Die Videodatei ist nicht mehr vorhanden.",
            MessageBox.TYPE_ERROR,
            timeout=5,
        )
        return

    probe = _embyflow_v21b_probe_local_file(path)
    video_stream = _embyflow_v21b_first_stream(probe, "video")
    video_codec = str(video_stream.get("Codec") or "").strip().lower()

    if video_codec == "av1":
        self.session.open(
            MessageBox,
            _embyflow_v21b_av1_message(probe),
            MessageBox.TYPE_INFO,
            timeout=10,
        )
        return

    title = embyflow_local_clean_title(path)
    is_series_root = "serien" in self.root_path.casefold()
    item_type = "Episode" if is_series_root else "Movie"
    local_id = "local:" + path
    streams = list((probe or {}).get("media_streams") or [])
    media_source = {
        "Id": local_id,
        "Path": path,
        "MediaStreams": streams,
        "DefaultSubtitleStreamIndex": -1,
    }

    default_audio_index = (probe or {}).get("default_audio_index")
    if default_audio_index is not None:
        media_source["DefaultAudioStreamIndex"] = default_audio_index

    format_name = str((probe or {}).get("format_name") or "").strip()
    if format_name:
        media_source["Container"] = format_name.split(",", 1)[0]

    item = {
        "Id": local_id,
        "id": local_id,
        "Name": title,
        "title": title,
        "Type": item_type,
        "type": item_type,
        "Path": path,
        "MediaSources": [media_source],
    }

    probe_runtime_ticks = _embyflow_v21b_int(
        (probe or {}).get("runtime_ticks"),
        0,
    )
    if probe_runtime_ticks > 0:
        item["RunTimeTicks"] = probe_runtime_ticks

    try:
        local_position_ticks, local_runtime_ticks = (
            get_embyflow_local_resume(local_id)
        )

        if local_position_ticks > 0:
            item["PlaybackPositionTicks"] = int(local_position_ticks)
            item["UserData"] = {
                "PlaybackPositionTicks": int(local_position_ticks)
            }

        if local_runtime_ticks > 0 and probe_runtime_ticks <= 0:
            item["RunTimeTicks"] = int(local_runtime_ticks)
    except Exception:
        pass

    if item_type == "Episode":
        item["SeriesName"] = os.path.basename(
            os.path.dirname(path)
        ) or self.title_text

    playback_info = {
        "url": path,
        "item": item,
        "local_file": True,
        "local_probe": dict(probe or {}),
        "play_session_id": "local-" + str(uuid4()),
    }

    try:
        extension = os.path.splitext(path)[1].lower()
        local_service_type = (
            1
            if extension in (".ts", ".m2ts", ".mts", ".trp")
            else STREAM_SERVICE_TYPE
        )
        playback_info["local_service_type"] = local_service_type
        playback_info["local_extension"] = extension

        ref = eServiceReference(local_service_type, 0, path)
        ref.setName(title)

        try:
            with embyflow_open_log(
                "/tmp/embyflow_local_media.log",
                "a",
            ) as log:
                log.write(
                    "%s PLAY path=%s extension=%s service_type=%s "
                    "video=%s audio=%s probe=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        path,
                        extension,
                        local_service_type,
                        str(video_stream.get("Codec") or ""),
                        str(_embyflow_v21b_first_stream(probe, "audio").get("Codec") or ""),
                        int(bool((probe or {}).get("ok"))),
                    )
                )
        except Exception:
            pass

        _open_embyflow_player_now(
            self.session,
            ref,
            title,
            path,
            playback_info,
        )

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_local_media_error.log",
                "a",
            ) as log:
                log.write(
                    "%s PLAY path=%s error=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        path,
                        str(error),
                    )
                )
        except Exception:
            pass

        self.session.open(
            MessageBox,
            "Lokales Video konnte nicht gestartet werden:\n\n%s"
            % str(error),
            MessageBox.TYPE_ERROR,
            timeout=7,
        )


EmbyFlowLocalMediaScreen.play_file = _embyflow_v21b_local_play_file
# EMBYFLOW_LOCAL_MEDIA_PROBE_AV1_GUARD_V21B_END

# EMBYFLOW_LOCAL_AV1_EMBY_FALLBACK_V22_START
# V22: AV1-Dateien aus der lokalen Mediathek werden nicht auf der Box
# software-dekodiert. Wenn derselbe Titel auf dem konfigurierten Emby-Server
# vorhanden ist, wird automatisch der bestehende H.264/AAC-Transcode-Pfad
# benutzt. Lokale H.264/HEVC-Dateien bleiben unverändert Direct Play.
EMBYFLOW_V22_MATCH_CACHE = {}
EMBYFLOW_V22_MATCH_CACHE_MAX = 64
EMBYFLOW_V22_MATCH_CACHE_TTL = 1800


def _embyflow_v22_norm(value):
    try:
        text = unicodedata.normalize("NFKD", str(value or ""))
        text = "".join(ch for ch in text if not unicodedata.combining(ch))
        text = text.casefold().replace("&", " and ")
        return " ".join(re.findall(r"[a-z0-9]+", text))
    except Exception:
        return str(value or "").casefold().strip()


def _embyflow_v22_compact(value):
    return _embyflow_v22_norm(value).replace(" ", "")


def _embyflow_v22_title_score(candidate, wanted):
    a = _embyflow_v22_norm(candidate)
    b = _embyflow_v22_norm(wanted)
    if not a or not b:
        return 0
    if a == b:
        return 1000
    ac = a.replace(" ", "")
    bc = b.replace(" ", "")
    if ac == bc:
        return 950
    if ac.startswith(bc) or bc.startswith(ac):
        return 800
    if bc in ac or ac in bc:
        return 700
    aset = set(a.split())
    bset = set(b.split())
    overlap = len(aset & bset)
    if overlap:
        return 300 + overlap * 80
    return 0


def _embyflow_v22_source_basename_score(item, local_path):
    try:
        local_name = _embyflow_v22_compact(os.path.basename(str(local_path or "")))
        if not local_name:
            return 0
        for source in (item or {}).get("media_sources") or (item or {}).get("MediaSources") or []:
            remote_path = source.get("Path") or ""
            if not remote_path:
                continue
            remote_name = _embyflow_v22_compact(os.path.basename(str(remote_path)))
            if remote_name and remote_name == local_name:
                return 2000
        return 0
    except Exception:
        return 0


def _embyflow_v22_local_identity(screen, path):
    stem = os.path.splitext(os.path.basename(str(path or "")))[0]
    readable = re.sub(r"[._-]+", " ", stem).strip()
    series_hint = ""
    episode_title = ""
    season_number = None
    episode_number = None

    try:
        selected = screen.selected_entry() if callable(getattr(screen, "selected_entry", None)) else None
        if isinstance(selected, dict):
            series_hint = str(selected.get("series_name") or "").strip()
            episode_title = str(selected.get("display_title") or selected.get("title") or "").strip()
    except Exception:
        pass

    try:
        title_text = str(getattr(screen, "title_text", "") or "").strip()
        if title_text and title_text.casefold() not in ("aufnahmen", "eigene mediathek"):
            series_hint = title_text
    except Exception:
        pass

    match = re.search(
        r"(?i)(?:^|[\s._-])s(\d{1,2})e(\d{1,3})(?:$|[\s._-])",
        stem,
    )
    if match:
        try:
            season_number = int(match.group(1))
            episode_number = int(match.group(2))
        except Exception:
            season_number = None
            episode_number = None
        prefix = stem[:match.start()].strip(" ._-")
        if prefix and not series_hint:
            series_hint = re.sub(r"[._-]+", " ", prefix).strip()

    if season_number is None or episode_number is None:
        match = re.search(
            r"(?i)(?:^|[\s._-])(\d{1,2})x(\d{1,3})(?:$|[\s._-])",
            stem,
        )
        if match:
            try:
                season_number = int(match.group(1))
                episode_number = int(match.group(2))
            except Exception:
                season_number = None
                episode_number = None
            prefix = stem[:match.start()].strip(" ._-")
            if prefix and not series_hint:
                series_hint = re.sub(r"[._-]+", " ", prefix).strip()

    is_episode = bool(
        season_number is not None
        and episode_number is not None
    ) or "serien" in str(getattr(screen, "root_path", "") or "").casefold()

    return {
        "is_episode": is_episode,
        "series_hint": series_hint,
        "episode_title": episode_title,
        "season_number": season_number,
        "episode_number": episode_number,
        "movie_title": embyflow_local_clean_title(path) or readable,
    }


def _embyflow_v22_match_episode(path, identity):
    series_hint = str(identity.get("series_hint") or "").strip()
    season_number = identity.get("season_number")
    episode_number = identity.get("episode_number")
    episode_title = str(identity.get("episode_title") or "").strip()

    if not series_hint or season_number is None or episode_number is None:
        return None

    series_items = emby_search_items(
        series_hint,
        limit=20,
        include_types="Series",
    )
    ranked_series = []
    for series in series_items:
        score = _embyflow_v22_title_score(series.get("title"), series_hint)
        if score > 0:
            ranked_series.append((score, series))
    ranked_series.sort(key=lambda value: value[0], reverse=True)

    for _score, series in ranked_series[:4]:
        series_id = series.get("id") or series.get("Id")
        if not series_id:
            continue
        episodes = emby_series_episodes_for_season(
            series_id,
            season_number,
            600,
        )
        matches = []
        for episode in episodes:
            if _int_or_none(episode.get("episode_number")) != int(episode_number):
                continue
            score = 1000
            score += _embyflow_v22_source_basename_score(episode, path)
            if episode_title:
                score += _embyflow_v22_title_score(
                    episode.get("title"),
                    episode_title,
                )
            matches.append((score, episode))
        if matches:
            matches.sort(key=lambda value: value[0], reverse=True)
            return matches[0][1]
    return None


def _embyflow_v22_match_movie(path, identity):
    title = str(identity.get("movie_title") or "").strip()
    if not title:
        return None
    items = emby_search_items(
        title,
        limit=30,
        include_types="Movie,Video",
    )
    ranked = []
    for item in items:
        score = _embyflow_v22_source_basename_score(item, path)
        score += _embyflow_v22_title_score(item.get("title"), title)
        if score > 0:
            ranked.append((score, item))
    if not ranked:
        return None
    ranked.sort(key=lambda value: value[0], reverse=True)
    return ranked[0][1]


def _embyflow_v22_match_remote_item(screen, path, identity=None):
    try:
        stat_info = os.stat(path)
        cache_key = (
            os.path.realpath(path),
            int(stat_info.st_mtime or 0),
            int(stat_info.st_size or 0),
        )
    except Exception:
        cache_key = (os.path.realpath(path), 0, 0)

    cached = EMBYFLOW_V22_MATCH_CACHE.get(cache_key)
    if cached:
        cached_ts, cached_item = cached
        if time.time() - float(cached_ts or 0.0) < EMBYFLOW_V22_MATCH_CACHE_TTL:
            return dict(cached_item) if isinstance(cached_item, dict) else None

    identity = dict(identity or _embyflow_v22_local_identity(screen, path))
    if identity.get("is_episode"):
        item = _embyflow_v22_match_episode(path, identity)
    else:
        item = _embyflow_v22_match_movie(path, identity)

    if item:
        if len(EMBYFLOW_V22_MATCH_CACHE) >= EMBYFLOW_V22_MATCH_CACHE_MAX:
            try:
                EMBYFLOW_V22_MATCH_CACHE.pop(next(iter(EMBYFLOW_V22_MATCH_CACHE)), None)
            except Exception:
                EMBYFLOW_V22_MATCH_CACHE.clear()
        EMBYFLOW_V22_MATCH_CACHE[cache_key] = (time.time(), dict(item))
    return item


def _embyflow_v22_resolve_av1_fallback(screen, path, identity=None):
    result = {
        "ok": False,
        "error": "",
        "stream_info": None,
        "title": "",
    }
    try:
        if not requests or not EMBY_SERVER or not EMBY_USERNAME:
            result["error"] = "Kein Emby-Server konfiguriert."
            return result

        remote_item = _embyflow_v22_match_remote_item(screen, path, identity)
        if not remote_item:
            result["error"] = (
                "Keine passende Version dieses Titels wurde auf dem Emby-Server gefunden."
            )
            return result

        item_id = remote_item.get("id") or remote_item.get("Id")
        title = remote_item.get("title") or remote_item.get("Name") or embyflow_local_clean_title(path)
        if not item_id:
            result["error"] = "Emby-Treffer hat keine Item-ID."
            return result

        stream_info = fetch_stream_info(
            title,
            "aac",
            item_id=item_id,
            item_data=remote_item,
        )
        if not stream_info or not stream_info.get("url"):
            result["error"] = "Emby konnte keinen H.264-Transcode bereitstellen."
            return result

        stream_info["embyflow_local_av1_fallback"] = True
        stream_info["embyflow_local_source_path"] = path
        result.update({
            "ok": True,
            "stream_info": stream_info,
            "title": title,
        })
        return result
    except Exception as error:
        result["error"] = str(error)
        return result


def _embyflow_v22_set_status(screen, text):
    try:
        screen["status"].setText(str(text or ""))
    except Exception:
        pass


def _embyflow_v22_screen_closed(screen):
    return bool(
        getattr(screen, "closed_local_screen", False)
        or getattr(screen, "closed_v7", False)
    )


def _embyflow_v22_poll_av1_fallback(screen):
    result = getattr(screen, "_embyflow_v22_fallback_result", None)
    if result is None:
        if _embyflow_v22_screen_closed(screen):
            try:
                screen._embyflow_v22_fallback_timer.stop()
            except Exception:
                pass
            screen._embyflow_v22_fallback_running = False
        return

    try:
        screen._embyflow_v22_fallback_timer.stop()
    except Exception:
        pass
    screen._embyflow_v22_fallback_result = None
    screen._embyflow_v22_fallback_running = False
    _embyflow_v22_set_status(screen, "")

    if _embyflow_v22_screen_closed(screen):
        return

    if not result.get("ok"):
        try:
            screen.session.open(
                MessageBox,
                "AV1 kann auf diesem Receiver nicht direkt abgespielt werden.\n\n%s"
                % str(result.get("error") or "Emby-Fallback fehlgeschlagen."),
                MessageBox.TYPE_INFO,
                timeout=8,
            )
        except Exception:
            pass
        return

    stream_info = result.get("stream_info") or {}
    stream_url = stream_info.get("url")
    title = str(result.get("title") or embyflow_local_clean_title(
        stream_info.get("embyflow_local_source_path") or ""
    ))
    if not stream_url:
        return

    try:
        with embyflow_open_log("/tmp/embyflow_av1_fallback.log", "a") as log:
            log.write(
                "%s OK path=%s item=%s title=%s mode=emby-h264-aac\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(stream_info.get("embyflow_local_source_path") or ""),
                    str((stream_info.get("item") or {}).get("Id") or (stream_info.get("item") or {}).get("id") or ""),
                    title,
                )
            )
    except Exception:
        pass

    ref = eServiceReference(STREAM_SERVICE_TYPE, 0, stream_url)
    try:
        with embyflow_open_log("/tmp/embyflow_universal_ref_trace.log", "a") as _urt:
            _urt.write("%s site=local_av1_fallback url=%s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), embyflow_sanitize_url_for_log(str(ref.getPath() if hasattr(ref, "getPath") else ""))))
    except Exception:
        pass
    ref.setName(title)
    open_embyflow_player(
        screen.session,
        ref,
        title,
        stream_url,
        stream_info,
    )


def _embyflow_v22_start_av1_fallback(screen, path):
    if getattr(screen, "_embyflow_v22_fallback_running", False):
        return

    screen._embyflow_v22_fallback_running = True
    screen._embyflow_v22_fallback_result = None
    screen._embyflow_v22_fallback_path = path
    identity = _embyflow_v22_local_identity(screen, path)
    _embyflow_v22_set_status(
        screen,
        "AV1 erkannt · Emby-Transcoding wird vorbereitet …",
    )

    timer = getattr(screen, "_embyflow_v22_fallback_timer", None)
    if timer is None:
        timer = eTimer()
        screen._embyflow_v22_fallback_timer = timer
        try:
            timer.callback.append(
                lambda: _embyflow_v22_poll_av1_fallback(screen)
            )
        except Exception:
            try:
                screen._embyflow_v22_fallback_timer_connection = timer.timeout.connect(
                    lambda: _embyflow_v22_poll_av1_fallback(screen)
                )
            except Exception:
                screen._embyflow_v22_fallback_timer_connection = None

    def worker():
        result = _embyflow_v22_resolve_av1_fallback(screen, path, identity)
        if not _embyflow_v22_screen_closed(screen):
            screen._embyflow_v22_fallback_result = result
        try:
            with embyflow_open_log("/tmp/embyflow_av1_fallback.log", "a") as log:
                log.write(
                    "%s RESOLVE path=%s ok=%s error=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        path,
                        int(bool(result.get("ok"))),
                        str(result.get("error") or ""),
                    )
                )
        except Exception:
            pass

    try:
        import threading
        thread = threading.Thread(
            target=worker,
            name="EmbyFlowAV1Fallback",
        )
        thread.daemon = True
        thread.start()
        timer.start(150, False)
    except Exception as error:
        screen._embyflow_v22_fallback_running = False
        _embyflow_v22_set_status(screen, "")
        screen.session.open(
            MessageBox,
            "Emby-Transcoding konnte nicht gestartet werden:\n\n%s" % str(error),
            MessageBox.TYPE_ERROR,
            timeout=7,
        )


_EMBYFLOW_V22_ORIGINAL_LOCAL_PLAY_FILE = EmbyFlowLocalMediaScreen.play_file


def _embyflow_v22_local_play_file(screen, file_path):
    path = os.path.realpath(str(file_path or ""))
    if not os.path.isfile(path):
        return _EMBYFLOW_V22_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)
    try:
        if not screen.safe_within_root(path):
            return _EMBYFLOW_V22_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)
    except Exception:
        return _EMBYFLOW_V22_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)

    probe = _embyflow_v21b_probe_local_file(path)
    video = _embyflow_v21b_first_stream(probe, "video")
    codec = str(video.get("Codec") or "").strip().lower()

    if codec == "av1":
        return _embyflow_v22_start_av1_fallback(screen, path)

    return _EMBYFLOW_V22_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)


EmbyFlowLocalMediaScreen.play_file = _embyflow_v22_local_play_file
# EMBYFLOW_LOCAL_AV1_EMBY_FALLBACK_V22_END

# EMBYFLOW_LOCAL_AV1_AUTO_CONVERT_V23_START
# V23: Lokale AV1-Dateien werden einmalig im Hintergrund nach H.264/MKV
# konvertiert. Die Quelldatei bleibt unangetastet. Das Ergebnis liegt in
# einem versteckten .embyflow_transcode-Ordner innerhalb der lokalen
# Bibliothek, wird bei spaeteren Starts wiederverwendet und nach Abschluss
# automatisch abgespielt. Pro Receiver laeuft maximal eine Konvertierung.
try:
    import hashlib as _embyflow_v23_hashlib
    import shutil as _embyflow_v23_shutil
    import subprocess as _embyflow_v23_subprocess
    import shlex as _embyflow_v23_shlex
except Exception:
    _embyflow_v23_hashlib = None
    _embyflow_v23_shutil = None
    _embyflow_v23_subprocess = None
    _embyflow_v23_shlex = None

EMBYFLOW_V23_TRANSCODE_DIR = ".embyflow_transcode"
EMBYFLOW_V23_FFMPEG = "/usr/bin/ffmpeg"
EMBYFLOW_V23_MIN_FREE_BYTES = 512 * 1024 * 1024
EMBYFLOW_V23_OUTPUT_FACTOR = 2.2
EMBYFLOW_V23_POLL_MS = 1000
EMBYFLOW_V23_JOBS = {}


def _embyflow_v23_log(text):
    try:
        with embyflow_open_log("/tmp/embyflow_av1_convert_v23.log", "a") as log:
            log.write(
                "%s %s\n" % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(text or ""),
                )
            )
    except Exception:
        pass


def _embyflow_v23_pid_alive(pid):
    try:
        pid = int(pid or 0)
        if pid <= 1:
            return False
        os.kill(pid, 0)
        return True
    except Exception:
        return False


def _embyflow_v23_read_pid(path):
    try:
        with open(path, "r") as handle:
            return int((handle.read() or "0").strip())
    except Exception:
        return 0


def _embyflow_v23_source_signature(path):
    info = os.stat(path)
    mtime_ns = getattr(info, "st_mtime_ns", None)
    if mtime_ns is None:
        mtime_ns = int(float(info.st_mtime or 0.0) * 1000000000.0)
    raw = "%s|%s|%s" % (
        os.path.realpath(path),
        int(info.st_size or 0),
        int(mtime_ns or 0),
    )
    digest = _embyflow_v23_hashlib.sha1(
        raw.encode("utf-8", "replace")
    ).hexdigest()[:16]
    return digest, int(info.st_size or 0)


def _embyflow_v23_paths(screen, source_path):
    root = os.path.realpath(
        str(getattr(screen, "root_path", "") or EMBYFLOW_LOCAL_MEDIA_ROOT)
    )
    digest, source_size = _embyflow_v23_source_signature(source_path)
    job_dir = os.path.join(root, EMBYFLOW_V23_TRANSCODE_DIR, digest)
    stem = os.path.splitext(os.path.basename(source_path))[0] or "video"
    final_path = os.path.join(job_dir, stem + ".mkv")
    return {
        "source": os.path.realpath(source_path),
        "source_size": source_size,
        "root": root,
        "dir": job_dir,
        "final": final_path,
        "temp": final_path + ".part",
        "progress": os.path.join(job_dir, "progress.txt"),
        "pid": os.path.join(job_dir, "job.pid"),
        "rc": os.path.join(job_dir, "job.rc"),
        "log": os.path.join(job_dir, "ffmpeg.log"),
        "script": os.path.join(job_dir, "convert.sh"),
    }


def _embyflow_v23_ready_output(job):
    final_path = str((job or {}).get("final") or "")
    try:
        if not os.path.isfile(final_path) or os.path.getsize(final_path) < 1024 * 1024:
            return False
        probe = _embyflow_v21b_probe_local_file(final_path)
        video = _embyflow_v21b_first_stream(probe, "video")
        codec = str(video.get("Codec") or "").strip().lower()
        return bool((probe or {}).get("ok")) and codec == "h264"
    except Exception:
        return False


def _embyflow_v23_job_running(job):
    pid = _embyflow_v23_read_pid(str((job or {}).get("pid") or ""))
    return _embyflow_v23_pid_alive(pid)


def _embyflow_v23_find_other_running(root, own_dir=""):
    base = os.path.join(os.path.realpath(root), EMBYFLOW_V23_TRANSCODE_DIR)
    if not os.path.isdir(base):
        return ""
    try:
        for name in os.listdir(base):
            job_dir = os.path.join(base, name)
            if not os.path.isdir(job_dir):
                continue
            if own_dir and os.path.realpath(job_dir) == os.path.realpath(own_dir):
                continue
            pid_path = os.path.join(job_dir, "job.pid")
            if _embyflow_v23_pid_alive(_embyflow_v23_read_pid(pid_path)):
                return job_dir
    except Exception:
        pass
    return ""


def _embyflow_v23_progress(job, duration):
    percent = 0
    speed = ""
    progress_path = str((job or {}).get("progress") or "")
    try:
        with open(progress_path, "rb") as handle:
            handle.seek(0, 2)
            size = handle.tell()
            handle.seek(max(0, size - 65536), 0)
            text = handle.read().decode("utf-8", "replace")
        values = re.findall(r"(?:out_time_us|out_time_ms)=(\d+)", text)
        if values and float(duration or 0.0) > 0.0:
            elapsed_us = float(values[-1])
            percent = int(
                max(0.0, min(99.0, elapsed_us / (float(duration) * 1000000.0) * 100.0))
            )
        speeds = re.findall(r"^speed=([^\r\n]+)", text, re.M)
        if speeds:
            speed = str(speeds[-1] or "").strip()
    except Exception:
        pass
    return percent, speed


def _embyflow_v23_status(screen, text):
    try:
        screen["status"].setText(str(text or ""))
    except Exception:
        pass


def _embyflow_v23_screen_closed(screen):
    return bool(
        getattr(screen, "closed_local_screen", False)
        or getattr(screen, "closed_v7", False)
    )


def _embyflow_v23_stop_timer(screen):
    try:
        screen._embyflow_v23_timer.stop()
    except Exception:
        pass


def _embyflow_v23_play_converted(screen, job):
    final_path = str((job or {}).get("final") or "")
    if not _embyflow_v23_ready_output(job):
        return False
    _embyflow_v23_log(
        "READY source=%s output=%s" % (
            str((job or {}).get("source") or ""),
            final_path,
        )
    )
    try:
        return _EMBYFLOW_V23_ORIGINAL_LOCAL_PLAY_FILE(screen, final_path)
    except Exception as error:
        _embyflow_v23_log("PLAY_ERROR output=%s error=%s" % (final_path, error))
        try:
            screen.session.open(
                MessageBox,
                "Die konvertierte Datei konnte nicht gestartet werden:\n\n%s" % str(error),
                MessageBox.TYPE_ERROR,
                timeout=7,
            )
        except Exception:
            pass
        return False


def _embyflow_v23_poll(screen):
    job = getattr(screen, "_embyflow_v23_job", None)
    if not isinstance(job, dict):
        _embyflow_v23_stop_timer(screen)
        return

    if _embyflow_v23_screen_closed(screen):
        _embyflow_v23_stop_timer(screen)
        return

    if _embyflow_v23_ready_output(job):
        _embyflow_v23_stop_timer(screen)
        _embyflow_v23_status(screen, "Konvertierung fertig · Wiedergabe startet …")
        try:
            EMBYFLOW_V23_JOBS.pop(str(job.get("source") or ""), None)
        except Exception:
            pass
        return _embyflow_v23_play_converted(screen, job)

    if _embyflow_v23_job_running(job):
        percent, speed = _embyflow_v23_progress(
            job,
            float(job.get("duration") or 0.0),
        )
        suffix = " · %s" % speed if speed else ""
        _embyflow_v23_status(
            screen,
            "AV1 → H.264 wird einmalig konvertiert · %d%%%s" % (percent, suffix),
        )
        return

    _embyflow_v23_stop_timer(screen)
    _embyflow_v23_status(screen, "")
    rc = ""
    try:
        with open(str(job.get("rc") or ""), "r") as handle:
            rc = (handle.read() or "").strip()
    except Exception:
        pass
    _embyflow_v23_log(
        "FAILED source=%s rc=%s log=%s" % (
            str(job.get("source") or ""),
            rc,
            str(job.get("log") or ""),
        )
    )
    try:
        screen.session.open(
            MessageBox,
            "AV1-Konvertierung ist fehlgeschlagen%s.\n\nDie Originaldatei wurde nicht verändert."
            % ((" (Code %s)" % rc) if rc else ""),
            MessageBox.TYPE_ERROR,
            timeout=8,
        )
    except Exception:
        pass


def _embyflow_v23_attach_timer(screen, job):
    screen._embyflow_v23_job = dict(job)
    timer = getattr(screen, "_embyflow_v23_timer", None)
    if timer is None:
        timer = eTimer()
        screen._embyflow_v23_timer = timer
        try:
            timer.callback.append(lambda: _embyflow_v23_poll(screen))
        except Exception:
            try:
                screen._embyflow_v23_timer_connection = timer.timeout.connect(
                    lambda: _embyflow_v23_poll(screen)
                )
            except Exception:
                screen._embyflow_v23_timer_connection = None
    try:
        timer.stop()
    except Exception:
        pass
    timer.start(EMBYFLOW_V23_POLL_MS, False)


def _embyflow_v23_shell_script(job, probe):
    quote = _embyflow_v23_shlex.quote
    source = quote(job["source"])
    temp = quote(job["temp"])
    final = quote(job["final"])
    progress = quote(job["progress"])
    pidfile = quote(job["pid"])
    rcfile = quote(job["rc"])
    logfile = quote(job["log"])

    video = _embyflow_v21b_first_stream(probe, "video")
    width = _embyflow_v21b_int(video.get("Width"), 0)
    height = _embyflow_v21b_int(video.get("Height"), 0)
    scale = ""
    if width > 1920 or height > 1080:
        if height >= width:
            scale = " -vf " + quote("scale=-2:1080")
        else:
            scale = " -vf " + quote("scale=1920:-2")

    ffmpeg = quote(EMBYFLOW_V23_FFMPEG)
    return """#!/bin/sh
set +e
echo $$ > {pid}
rm -f {rc} {progress} {temp}
{ffmpeg} -hide_banner -nostdin -y -threads 2 -i {source} -map 0:v? -map 0:a? -map 0:s? -map_metadata 0 -map_chapters 0 -c copy -c:v libx264 -preset ultrafast -crf 23 -pix_fmt yuv420p -threads 2{scale} -max_muxing_queue_size 4096 -progress {progress} -nostats -f matroska {temp} >> {log} 2>&1
RC=$?
if [ "$RC" -eq 0 ] && [ -s {temp} ]; then
    mv -f {temp} {final}
fi
echo "$RC" > {rc}
rm -f {pid}
exit "$RC"
""".format(
        pid=pidfile,
        rc=rcfile,
        progress=progress,
        temp=temp,
        ffmpeg=ffmpeg,
        source=source,
        scale=scale,
        log=logfile,
        final=final,
    )


def _embyflow_v23_start_convert(screen, path, probe):
    if (
        _embyflow_v23_hashlib is None
        or _embyflow_v23_shutil is None
        or _embyflow_v23_subprocess is None
        or _embyflow_v23_shlex is None
        or not os.path.isfile(EMBYFLOW_V23_FFMPEG)
    ):
        screen.session.open(
            MessageBox,
            "AV1-Konvertierung ist auf diesem Image nicht verfügbar.",
            MessageBox.TYPE_ERROR,
            timeout=7,
        )
        return

    try:
        job = _embyflow_v23_paths(screen, path)
        os.makedirs(job["dir"], exist_ok=True)
    except Exception as error:
        screen.session.open(
            MessageBox,
            "Konvertierungsordner konnte nicht erstellt werden:\n\n%s" % str(error),
            MessageBox.TYPE_ERROR,
            timeout=7,
        )
        return

    job["duration"] = float((probe or {}).get("duration") or 0.0)

    if _embyflow_v23_ready_output(job):
        return _embyflow_v23_play_converted(screen, job)

    if _embyflow_v23_job_running(job):
        EMBYFLOW_V23_JOBS[path] = dict(job)
        _embyflow_v23_attach_timer(screen, job)
        _embyflow_v23_poll(screen)
        return

    other = _embyflow_v23_find_other_running(job["root"], job["dir"])
    if other:
        screen.session.open(
            MessageBox,
            "Es läuft bereits eine AV1-Konvertierung.\n\nBitte diese zuerst fertig werden lassen.",
            MessageBox.TYPE_INFO,
            timeout=7,
        )
        return

    try:
        free_bytes = int(_embyflow_v23_shutil.disk_usage(job["dir"]).free or 0)
        needed = max(
            EMBYFLOW_V23_MIN_FREE_BYTES,
            int(float(job["source_size"] or 0) * EMBYFLOW_V23_OUTPUT_FACTOR),
        )
        if free_bytes < needed:
            screen.session.open(
                MessageBox,
                "Für die einmalige AV1-Konvertierung ist nicht genug freier Speicher vorhanden.\n\nBenötigt: ca. %s\nFrei: %s"
                % (
                    embyflow_local_human_size(needed),
                    embyflow_local_human_size(free_bytes),
                ),
                MessageBox.TYPE_ERROR,
                timeout=9,
            )
            return
    except Exception:
        pass

    try:
        for stale in (job["temp"], job["progress"], job["pid"], job["rc"]):
            try:
                os.unlink(stale)
            except Exception:
                pass
        script_text = _embyflow_v23_shell_script(job, probe)
        with open(job["script"], "w") as handle:
            handle.write(script_text)
        os.chmod(job["script"], 0o700)

        process = _embyflow_v23_subprocess.Popen(
            ["/bin/sh", job["script"]],
            stdin=_embyflow_v23_subprocess.DEVNULL,
            stdout=_embyflow_v23_subprocess.DEVNULL,
            stderr=_embyflow_v23_subprocess.DEVNULL,
            close_fds=True,
            start_new_session=True,
        )
        try:
            with open(job["pid"], "w") as handle:
                handle.write(str(int(process.pid)))
        except Exception:
            pass

        EMBYFLOW_V23_JOBS[path] = dict(job)
        _embyflow_v23_log(
            "START source=%s output=%s pid=%s" % (
                path,
                job["final"],
                int(process.pid),
            )
        )
        _embyflow_v23_attach_timer(screen, job)
        _embyflow_v23_status(screen, "AV1 → H.264 wird einmalig konvertiert · 0%")
        screen.session.open(
            MessageBox,
            "AV1 erkannt.\n\nDie Datei wird einmalig im Hintergrund nach H.264 konvertiert. Danach startet sie automatisch.\n\nDie Originaldatei bleibt unverändert.",
            MessageBox.TYPE_INFO,
            timeout=7,
        )
    except Exception as error:
        _embyflow_v23_log("START_ERROR source=%s error=%s" % (path, error))
        _embyflow_v23_status(screen, "")
        screen.session.open(
            MessageBox,
            "AV1-Konvertierung konnte nicht gestartet werden:\n\n%s" % str(error),
            MessageBox.TYPE_ERROR,
            timeout=8,
        )


_EMBYFLOW_V23_ORIGINAL_LOCAL_PLAY_FILE = EmbyFlowLocalMediaScreen.play_file


def _embyflow_v23_local_play_file(screen, file_path):
    path = os.path.realpath(str(file_path or ""))
    if not os.path.isfile(path):
        return _EMBYFLOW_V23_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)
    try:
        if not screen.safe_within_root(path):
            return _EMBYFLOW_V23_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)
    except Exception:
        return _EMBYFLOW_V23_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)

    probe = _embyflow_v21b_probe_local_file(path)
    video = _embyflow_v21b_first_stream(probe, "video")
    codec = str(video.get("Codec") or "").strip().lower()

    if codec == "av1":
        return _embyflow_v23_start_convert(screen, path, probe)

    return _EMBYFLOW_V23_ORIGINAL_LOCAL_PLAY_FILE(screen, file_path)


EmbyFlowLocalMediaScreen.play_file = _embyflow_v23_local_play_file
# EMBYFLOW_LOCAL_AV1_AUTO_CONVERT_V23_END

# EMBYFLOW_SERVER_SYNC_LATENCY_FIX_V24_START
# V24: Startup-Zähler wieder auf den ursprünglichen 900-ms-Start setzen.
# Heavy V11-Library-Refresh (Limit=5000) und Remote-Metadaten-Prewarm bleiben
# durch V20 weiterhin gebremst/deaktiviert.
# EMBYFLOW_SERVER_SYNC_LATENCY_FIX_V24_END

# EMBYFLOW_SERVER_SYNC_FAST_START_V25_START
# V25: Gemessenen Startup-Zähler von 900 ms auf 250 ms reduzieren.
# Der 10-Minuten-Schutz vor dem V11-Limit=5000-Vollscan und der deaktivierte
# Remote-Metadaten-Prewarm aus V20 bleiben unverändert erhalten.
# EMBYFLOW_SERVER_SYNC_FAST_START_V25_END

# EMBYFLOW_SERVER_SYNC_PARALLEL_V26_START
# V26: schneller echter Server-Sync nach dem Prinzip kleiner Zählerantworten.
# - Filme/Serien/Episoden über Emby /Items/Counts in EINER Anfrage.
# - Doku und Doku-Serien nur als TotalRecordCount mit Limit=0.
# - Die drei unabhängigen Abfragen laufen parallel im bestehenden Worker.
# - Bei fehlendem /Items/Counts-Endpunkt fallen die drei Kernzähler auf die
#   bewährten /Users/{UserId}/Items-Abfragen zurück.
# - Vorhandene Cachewerte werden nur als Fehler-Fallback benutzt.
# - Messlog: /tmp/embyflow_server_sync_v26.log
try:
    import threading as _embyflow_v26_threading
except Exception:
    _embyflow_v26_threading = None

try:
    _embyflow_v26_mono = time.monotonic
except Exception:
    _embyflow_v26_mono = time.time

EMBYFLOW_V26_SYNC_LOG = "/tmp/embyflow_server_sync_v26.log"


def _embyflow_v26_log(message, reset=False):
    try:
        mode = "w" if reset else "a"
        with open(EMBYFLOW_V26_SYNC_LOG, mode) as handle:
            handle.write(
                "%s | %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_v26_run_startup_library_sync(self):
    """Aktualisiert die fünf Home-Zähler mit minimalen, parallelen Emby-Abfragen."""
    if getattr(self, "_startup_sync_worker_running", False):
        return

    self._startup_sync_worker_running = True
    self._startup_sync_worker_done = False
    self._startup_sync_worker_error = ""
    self._startup_sync_worker_result = None

    try:
        if not hasattr(self, "_startup_sync_apply_timer"):
            self._startup_sync_apply_timer = eTimer()
            try:
                self._startup_sync_apply_timer.callback.append(
                    self._apply_startup_sync_result
                )
            except Exception:
                try:
                    self._startup_sync_apply_timer.timeout.connect(
                        self._apply_startup_sync_result
                    )
                except Exception:
                    pass
        self._startup_sync_apply_timer.start(200, True)
    except Exception:
        self._startup_sync_worker_running = False
        return

    def startup_sync_worker():
        total_started = _embyflow_v26_mono()
        result = {
            "success": False,
            "counts": {},
            "username": EMBY_USERNAME or "User",
            "server": EMBY_SERVER.rstrip("/") if EMBY_SERVER else "",
            "last_sync": time.strftime("%H:%M"),
            "error": "",
        }

        _embyflow_v26_log("START", reset=True)

        try:
            if not requests or not EMBY_SERVER or not EMBY_USERNAME:
                raise RuntimeError("Emby Server nicht konfiguriert")

            auth_started = _embyflow_v26_mono()
            server, token, user_id = get_emby_auth(force=True)
            auth_ms = (_embyflow_v26_mono() - auth_started) * 1000.0
            _embyflow_v26_log(
                "AUTH ms=%.1f token=%d user=%d"
                % (auth_ms, int(bool(token)), int(bool(user_id)))
            )

            if not server or not token or not user_id:
                raise RuntimeError("Emby Login ohne Token oder User-ID")

            headers = {
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            }

            cached_payload = read_json_file(
                CACHE_DIR + "/library_counts.json",
                {}
            ) or {}
            cached_counts = dict(
                cached_payload.get("counts", cached_payload) or {}
            )

            fresh_counts = {}
            errors = {}
            timings = {}
            lock = (
                _embyflow_v26_threading.RLock()
                if _embyflow_v26_threading is not None
                else None
            )

            def store_count(label, value, elapsed_ms):
                try:
                    value = max(0, int(value or 0))
                except Exception:
                    value = 0
                if lock is not None:
                    with lock:
                        fresh_counts[label] = value
                        timings[label] = float(elapsed_ms)
                else:
                    fresh_counts[label] = value
                    timings[label] = float(elapsed_ms)

            def store_error(label, error, elapsed_ms):
                if lock is not None:
                    with lock:
                        errors[label] = str(error)
                        timings[label] = float(elapsed_ms)
                else:
                    errors[label] = str(error)
                    timings[label] = float(elapsed_ms)

            def fetch_core_counts():
                started = _embyflow_v26_mono()
                try:
                    response = embyflow_http_get(
                        server + "/Items/Counts",
                        headers=headers,
                        params={"UserId": user_id},
                        timeout=8,
                        verify=True,
                    )
                    if int(getattr(response, "status_code", 0) or 0) != 200:
                        raise RuntimeError(
                            "HTTP %s"
                            % getattr(response, "status_code", "?")
                        )
                    data = response.json() or {}
                    required = (
                        ("Filme", "MovieCount"),
                        ("Serien", "SeriesCount"),
                        ("Episoden", "EpisodeCount"),
                    )
                    missing = [
                        field
                        for unused_label, field in required
                        if data.get(field) is None
                    ]
                    if missing:
                        raise RuntimeError(
                            "fehlende Felder: %s" % ",".join(missing)
                        )
                    elapsed_ms = (
                        _embyflow_v26_mono() - started
                    ) * 1000.0
                    for label, field in required:
                        store_count(label, data.get(field), elapsed_ms)
                    _embyflow_v26_log(
                        "CORE ms=%.1f movies=%s series=%s episodes=%s"
                        % (
                            elapsed_ms,
                            data.get("MovieCount"),
                            data.get("SeriesCount"),
                            data.get("EpisodeCount"),
                        )
                    )
                except Exception as error:
                    elapsed_ms = (
                        _embyflow_v26_mono() - started
                    ) * 1000.0
                    store_error("Kernzähler", error, elapsed_ms)
                    _embyflow_v26_log(
                        "CORE_ERROR ms=%.1f error=%s"
                        % (elapsed_ms, str(error))
                    )

            def fetch_filtered_count(label, include_types, genre):
                started = _embyflow_v26_mono()
                try:
                    response = embyflow_http_get(
                        server + "/Users/%s/Items" % user_id,
                        headers=headers,
                        params={
                            "Recursive": "true",
                            "IncludeItemTypes": include_types,
                            "Genres": genre,
                            "Limit": "0",
                        },
                        timeout=8,
                        verify=True,
                    )
                    if int(getattr(response, "status_code", 0) or 0) != 200:
                        raise RuntimeError(
                            "HTTP %s"
                            % getattr(response, "status_code", "?")
                        )
                    data = response.json() or {}
                    if data.get("TotalRecordCount") is None:
                        raise RuntimeError("TotalRecordCount fehlt")
                    elapsed_ms = (
                        _embyflow_v26_mono() - started
                    ) * 1000.0
                    store_count(
                        label,
                        data.get("TotalRecordCount"),
                        elapsed_ms,
                    )
                    _embyflow_v26_log(
                        "%s ms=%.1f count=%s"
                        % (
                            label,
                            elapsed_ms,
                            data.get("TotalRecordCount"),
                        )
                    )
                except Exception as error:
                    elapsed_ms = (
                        _embyflow_v26_mono() - started
                    ) * 1000.0
                    store_error(label, error, elapsed_ms)
                    _embyflow_v26_log(
                        "%s_ERROR ms=%.1f error=%s"
                        % (label, elapsed_ms, str(error))
                    )

            def run_parallel(callables):
                if _embyflow_v26_threading is None:
                    for function, args in callables:
                        function(*args)
                    return

                workers = []
                for index, pair in enumerate(callables):
                    function, args = pair
                    worker = _embyflow_v26_threading.Thread(
                        target=function,
                        args=args,
                        name="EmbyFlowSyncV26_%d" % index,
                    )
                    worker.daemon = True
                    worker.start()
                    workers.append(worker)

                for worker in workers:
                    worker.join()

            # Drei echte Server-Abfragen gleichzeitig:
            # 1x Core Counts + 2x gefilterte Documentary-Zähler.
            run_parallel((
                (fetch_core_counts, ()),
                (fetch_filtered_count, ("Doku", "Movie", "Documentary")),
                (fetch_filtered_count, ("Doku-Serien", "Series", "Documentary")),
            ))

            # Kompatibilitäts-Fallback, falls /Items/Counts auf einem älteren
            # Emby-Server fehlt. Nur die fehlenden Kernzähler werden angefragt.
            missing_core = [
                pair
                for pair in (
                    ("Filme", "Movie"),
                    ("Serien", "Series"),
                    ("Episoden", "Episode"),
                )
                if pair[0] not in fresh_counts
            ]

            if missing_core:
                def fetch_core_fallback(label, include_types):
                    started = _embyflow_v26_mono()
                    try:
                        response = embyflow_http_get(
                            server + "/Users/%s/Items" % user_id,
                            headers=headers,
                            params={
                                "Recursive": "true",
                                "IncludeItemTypes": include_types,
                                "Limit": "0",
                            },
                            timeout=8,
                            verify=True,
                        )
                        if int(getattr(response, "status_code", 0) or 0) != 200:
                            raise RuntimeError(
                                "HTTP %s"
                                % getattr(response, "status_code", "?")
                            )
                        data = response.json() or {}
                        if data.get("TotalRecordCount") is None:
                            raise RuntimeError("TotalRecordCount fehlt")
                        elapsed_ms = (
                            _embyflow_v26_mono() - started
                        ) * 1000.0
                        store_count(
                            label,
                            data.get("TotalRecordCount"),
                            elapsed_ms,
                        )
                        _embyflow_v26_log(
                            "FALLBACK_%s ms=%.1f count=%s"
                            % (
                                label,
                                elapsed_ms,
                                data.get("TotalRecordCount"),
                            )
                        )
                    except Exception as error:
                        elapsed_ms = (
                            _embyflow_v26_mono() - started
                        ) * 1000.0
                        store_error(label, error, elapsed_ms)
                        _embyflow_v26_log(
                            "FALLBACK_%s_ERROR ms=%.1f error=%s"
                            % (label, elapsed_ms, str(error))
                        )

                run_parallel(tuple(
                    (fetch_core_fallback, pair)
                    for pair in missing_core
                ))

            counts = {}
            cached_used = []
            missing = []
            for label in (
                "Filme",
                "Serien",
                "Episoden",
                "Doku",
                "Doku-Serien",
            ):
                if label in fresh_counts:
                    counts[label] = fresh_counts[label]
                elif label in cached_counts:
                    try:
                        counts[label] = max(
                            0,
                            int(cached_counts.get(label) or 0)
                        )
                        cached_used.append(label)
                    except Exception:
                        missing.append(label)
                else:
                    missing.append(label)

            if missing:
                raise RuntimeError(
                    "Zähler fehlen: %s" % ", ".join(missing)
                )

            sync_text = time.strftime("%H:%M")
            sync_timestamp = int(time.time())
            username = EMBY_USERNAME or "User"

            write_json_file(
                CACHE_DIR + "/library_counts.json",
                {
                    "counts": counts,
                    "last_sync": sync_text,
                    "last_sync_ts": sync_timestamp,
                }
            )
            write_json_file(
                CACHE_DIR + "/server_status.json",
                {
                    "state": "verbunden",
                    "online": "Online",
                    "server": server,
                    "username": username,
                    "last_sync": sync_text,
                }
            )

            total_ms = (
                _embyflow_v26_mono() - total_started
            ) * 1000.0
            result.update({
                "success": True,
                "counts": counts,
                "username": username,
                "server": server,
                "last_sync": sync_text,
            })

            _embyflow_v26_log(
                "DONE total_ms=%.1f fresh=%d cached=%d errors=%d counts=%s"
                % (
                    total_ms,
                    len(fresh_counts),
                    len(cached_used),
                    len(errors),
                    repr(counts),
                )
            )

            monitor = globals().get("_embyflow_v19_emit")
            if callable(monitor):
                try:
                    monitor(
                        "V26_SYNC_DONE",
                        "ms=%.1f fresh=%d cached=%d"
                        % (
                            total_ms,
                            len(fresh_counts),
                            len(cached_used),
                        )
                    )
                except Exception:
                    pass

        except Exception as error:
            result["error"] = str(error)
            total_ms = (
                _embyflow_v26_mono() - total_started
            ) * 1000.0
            _embyflow_v26_log(
                "ERROR total_ms=%.1f error=%s"
                % (total_ms, str(error))
            )
            try:
                with open(
                    "/tmp/embyflow_startup_sync_error.log",
                    "a"
                ) as log:
                    log.write("V26 %s\n" % str(error))
            except Exception:
                pass
        finally:
            self._startup_sync_worker_result = result
            self._startup_sync_worker_done = True
            self._startup_sync_worker_running = False

    try:
        if _embyflow_v26_threading is None:
            startup_sync_worker()
        else:
            worker = _embyflow_v26_threading.Thread(
                target=startup_sync_worker,
                name="EmbyFlowStartupSyncV26"
            )
            worker.daemon = True
            worker.start()
    except Exception as error:
        self._startup_sync_worker_error = str(error)
        self._startup_sync_worker_done = True
        self._startup_sync_worker_running = False


# V20 startet über self.run_startup_library_sync; deshalb genügt der späte,
# eindeutige Klassen-Override und wir müssen keinen bestehenden Block verändern.
EmbyFlowE2Screen.run_startup_library_sync = (
    _embyflow_v26_run_startup_library_sync
)
# EMBYFLOW_SERVER_SYNC_PARALLEL_V26_END

# EMBYFLOW_EXIT_STOPPED_V11_3_START
# EXIT freezes the active PlaySessionId/payload before self.close() and the
# existing V27 background thread performs the Stopped POST directly.
# No nested async reporter; ActiveEncoding cleanup cannot suppress Stopped.
# EMBYFLOW_EXIT_STOPPED_V11_3_END

# EMBYFLOW_PLAYER_EXIT_DIRECT_SWITCH_V27_START
# V27: Player-Rückkehr ohne separates stopService -> playService-Doppelkommando.
# Der alte Exit-Pfad stoppt den Emby-Dienst zunächst explizit und startet kurz
# danach den vorherigen Dienst. Auf manchen ServiceApp/GStreamer-Kombinationen
# kann genau dieses synchrone stopService() den Enigma2-GUI-Thread lange blockieren.
# V27 verwendet bei vorhandenem vorherigem Dienst stattdessen EINEN direkten
# playService()-Wechsel. Die Emby-Stopped-Meldung bleibt im Hintergrundthread.
# Messlog: /tmp/embyflow_player_exit_v27.log
try:
    _embyflow_v27_mono = time.monotonic
except Exception:
    _embyflow_v27_mono = time.time

EMBYFLOW_V27_EXIT_LOG = "/tmp/embyflow_player_exit_v27.log"


def _embyflow_v27_exit_log(message, reset=False):
    try:
        with open(EMBYFLOW_V27_EXIT_LOG, "w" if reset else "a") as handle:
            handle.write(
                "%s | %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_v27_leave_player(self):
    global EMBYFLOW_PLAYER_EXIT_TIMERS

    if getattr(self, "closed", False):
        return

    total_started = _embyflow_v27_mono()
    _embyflow_v27_exit_log(
        "EXIT_START title=%s"
        % str(getattr(self, "title_text", "") or ""),
        reset=True,
    )

    self.closed = True

    try:
        self.stop_player_timers()
    except Exception:
        for timer_name in (
            "hide_timer",
            "start_timer",
            "audio_timer",
            "subtitle_timer",
            "progress_timer",
            "ui_timer",
            "seek_fallback_timer",
            "initial_big_seek_timer",
            "resume_timer",
            "tile_animation_timer",
        ):
            try:
                getattr(self, timer_name).stop()
            except Exception:
                pass

    try:
        stop_position = int(self.current_position_ticks() or 0)
    except Exception:
        stop_position = 0

    last_service = getattr(self, "last_service", None)
    session = self.session
    # EMBYFLOW_ADMIN_SERVER_SAFETY_V1
    stop_play_session_id = str(
        getattr(self, "play_session_id", "") or ""
    )

    # EMBYFLOW_EXIT_STOPPED_V11_3
    # Freeze EVERYTHING needed for /Sessions/Playing/Stopped before self.close().
    # The screen may mutate player state while closing; the exit report must
    # always refer to the exact PlaySessionId that was active at EXIT_START.
    try:
        stop_server = (
            (getattr(self, "playback_info", None) or {}).get("server")
            or EMBY_SERVER.rstrip("/")
        )
    except Exception:
        stop_server = EMBY_SERVER.rstrip("/")
    try:
        stop_token = (
            (getattr(self, "playback_info", None) or {}).get("token")
            or ""
        )
    except Exception:
        stop_token = ""
    try:
        stop_payload = dict(self.emby_report_payload(stop_position) or {})
    except Exception:
        stop_payload = {}
    if stop_payload:
        stop_payload["PlaySessionId"] = stop_play_session_id
        stop_payload["PositionTicks"] = int(stop_position or 0)
        stop_payload["IsPaused"] = True
        stop_payload["PlaybackRate"] = 1

    try:
        stop_resume_info = dict(getattr(self, "playback_info", None) or {})
    except Exception:
        stop_resume_info = {}
    try:
        stop_duration_ticks = int(getattr(self, "duration_ticks", 0) or 0)
    except Exception:
        stop_duration_ticks = 0
    stop_title = str(getattr(self, "title_text", "") or "")
    stop_item_id = str(getattr(self, "item_id", "") or "")

    # Oberfläche zuerst freigeben.
    try:
        self.close()
    except Exception as error:
        _embyflow_v27_exit_log("CLOSE_ERROR error=%s" % str(error))

    _embyflow_v27_exit_log(
        "SCREEN_CLOSED ms=%.1f last_service=%d pos=%s"
        % (
            (_embyflow_v27_mono() - total_started) * 1000.0,
            int(last_service is not None),
            stop_position,
        )
    )

    # Emby-Stopmeldung niemals im GUI-Thread senden.
    try:
        import threading as _embyflow_v27_threading

        def report_stopped_async():
            started = _embyflow_v27_mono()
            stopped_status = "SKIP"
            cleanup_status = "SKIP"

            # EMBYFLOW_EXIT_STOPPED_V11_3
            # This function already runs outside the GUI thread. Therefore do
            # the actual HTTP POST HERE instead of calling the generic async
            # reporter and spawning a second nested daemon thread.
            try:
                try:
                    save_embyflow_local_resume(
                        stop_resume_info,
                        stop_position,
                        stop_duration_ticks,
                        stop_title,
                        stop_item_id,
                    )
                except Exception as error:
                    _embyflow_v27_exit_log(
                        "LOCAL_RESUME_ERROR error=%s" % str(error)
                    )

                if (
                    requests
                    and stop_server
                    and stop_token
                    and stop_payload
                    and stop_play_session_id
                ):
                    stopped_url = (
                        stop_server
                        + "/emby/Sessions/Playing/Stopped?reqformat=json"
                    )
                    stopped_response = embyflow_http_post(
                        stopped_url,
                        headers={
                            "X-Emby-Token": stop_token,
                            "X-Emby-Authorization": AUTH_HEADER,
                        },
                        json=dict(stop_payload),
                        timeout=5,
                        verify=True,
                    )
                    stopped_status = str(
                        getattr(stopped_response, "status_code", "?")
                    )
                    stopped_body = ""
                    try:
                        if int(
                            getattr(stopped_response, "status_code", 0) or 0
                        ) >= 400:
                            stopped_body = str(
                                getattr(stopped_response, "text", "") or ""
                            )[:220]
                    except Exception:
                        stopped_body = ""

                    try:
                        with embyflow_open_log(
                            "/tmp/embyflow_playback_report.log",
                            "a",
                        ) as f:
                            f.write(
                                "%s Stopped status=%s pos=%s session=%s title=%s body=%s\n"
                                % (
                                    time.strftime("%H:%M:%S"),
                                    stopped_status,
                                    stop_position,
                                    stop_play_session_id,
                                    stop_title,
                                    stopped_body,
                                )
                            )
                    except Exception:
                        pass
                else:
                    _embyflow_v27_exit_log(
                        "STOPPED_SKIP server=%d token=%d payload=%d session=%d"
                        % (
                            int(bool(stop_server)),
                            int(bool(stop_token)),
                            int(bool(stop_payload)),
                            int(bool(stop_play_session_id)),
                        )
                    )
            except Exception as error:
                stopped_status = "ERROR"
                _embyflow_v27_exit_log(
                    "STOPPED_ERROR error=%s" % str(error)
                )

            # ActiveEncoding cleanup is independent from the Stopped report.
            # A cleanup failure must never suppress /Sessions/Playing/Stopped.
            try:
                self.cancel_active_encoding(stop_play_session_id)
                cleanup_status = "DONE"
            except Exception as error:
                cleanup_status = "ERROR"
                _embyflow_v27_exit_log(
                    "CLEANUP_ERROR error=%s" % str(error)
                )

            _embyflow_v27_exit_log(
                "REPORT_DONE ms=%.1f stopped=%s cleanup=%s session=%s"
                % (
                    (_embyflow_v27_mono() - started) * 1000.0,
                    stopped_status,
                    cleanup_status,
                    stop_play_session_id,
                )
            )

        report_thread = _embyflow_v27_threading.Thread(
            target=report_stopped_async,
            name="EmbyFlowStoppedV27",
        )
        report_thread.daemon = True
        report_thread.start()
    except Exception as error:
        _embyflow_v27_exit_log("REPORT_THREAD_ERROR error=%s" % str(error))

    # Kurze Entkopplung vom EXIT-Tastendruck. Bei vorhandenem vorherigem Dienst
    # KEIN separates stopService(): playService übernimmt den Dienstwechsel selbst.
    exit_timer = eTimer()

    def restore_previous_service_v27():
        started = _embyflow_v27_mono()
        _embyflow_v27_exit_log(
            "RESTORE_START last_service=%d" % int(last_service is not None)
        )

        try:
            if last_service is not None:
                session.nav.playService(last_service)
                _embyflow_v27_exit_log(
                    "DIRECT_PLAY_DONE ms=%.1f"
                    % ((_embyflow_v27_mono() - started) * 1000.0)
                )
            else:
                # Ohne vorherigen Dienst muss der Emby-Stream trotzdem beendet werden.
                session.nav.stopService()
                _embyflow_v27_exit_log(
                    "STOP_ONLY_DONE ms=%.1f"
                    % ((_embyflow_v27_mono() - started) * 1000.0)
                )
        except Exception as error:
            _embyflow_v27_exit_log(
                "RESTORE_ERROR ms=%.1f error=%s"
                % (
                    (_embyflow_v27_mono() - started) * 1000.0,
                    str(error),
                )
            )
        finally:
            try:
                EMBYFLOW_PLAYER_EXIT_TIMERS.remove(exit_timer)
            except Exception:
                pass

    try:
        exit_timer.callback.append(restore_previous_service_v27)
    except Exception:
        try:
            exit_timer.timeout.connect(restore_previous_service_v27)
        except Exception:
            restore_previous_service_v27()
            return

    EMBYFLOW_PLAYER_EXIT_TIMERS.append(exit_timer)

    try:
        exit_timer.start(120, True)
    except Exception:
        restore_previous_service_v27()


EmbyFlowMoviePlayer.leave_player = _embyflow_v27_leave_player
# EMBYFLOW_PLAYER_EXIT_DIRECT_SWITCH_V27_END

# EMBYFLOW_NEW_COUNTS_ASYNC_V28_START
# V28: Neuerscheinungen-Zähler werden erst NACH dem Öffnen des Kino-Menüs
# asynchron geladen. Der Homescreen-/Startup-Sync V26 bleibt unangetastet.
# Gezählt werden echte DateCreated-Einträge seit dem letzten Öffnen der
# jeweiligen Neu-Kategorie. Zwei schlanke, parallele Streams (Movie/Series)
# reichen aus; Doku/Doku-Serie werden aus Genres derselben Treffer abgeleitet.
# Messlog: /tmp/embyflow_new_counts_v28.log
EMBYFLOW_V28_NEW_COUNT_LOG = "/tmp/embyflow_new_counts_v28.log"
EMBYFLOW_V28_PAGE_SIZE = 200
EMBYFLOW_V28_MAX_PAGES = 50

try:
    _embyflow_v28_mono = time.monotonic
except Exception:
    _embyflow_v28_mono = time.time


_EMBYFLOW_V28_CINEMA_INIT = EmbyFlowCinemaNewScreen.__init__
_EMBYFLOW_V28_CINEMA_REFRESH = EmbyFlowCinemaNewScreen.refresh_cinema


def _embyflow_v28_log(message, reset=False):
    try:
        with open(
            EMBYFLOW_V28_NEW_COUNT_LOG,
            "w" if reset else "a"
        ) as handle:
            handle.write(
                "%s | %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_v28_local_timestamp_epoch(value):
    try:
        value = str(value or "").strip()
        if not value:
            return 0.0
        return float(
            time.mktime(
                time.strptime(
                    value,
                    "%Y-%m-%dT%H:%M:%S"
                )
            )
        )
    except Exception:
        return 0.0


def _embyflow_v28_emby_timestamp_epoch(value):
    """Emby DateCreated (normalerweise UTC/Z) robust in Unixzeit wandeln."""
    try:
        value = str(value or "").strip()
        if not value:
            return 0.0

        import datetime as _v28_datetime

        normalized = value
        if normalized.endswith("Z"):
            normalized = normalized[:-1] + "+00:00"

        try:
            parsed = _v28_datetime.datetime.fromisoformat(normalized)
            if parsed.tzinfo is not None:
                return float(parsed.timestamp())
            return float(time.mktime(parsed.timetuple())) + (
                float(parsed.microsecond) / 1000000.0
            )
        except Exception:
            pass

        plain = value.rstrip("Z").split(".", 1)[0]
        if value.endswith("Z"):
            import calendar as _v28_calendar
            return float(
                _v28_calendar.timegm(
                    time.strptime(
                        plain,
                        "%Y-%m-%dT%H:%M:%S"
                    )
                )
            )

        return float(
            time.mktime(
                time.strptime(
                    plain,
                    "%Y-%m-%dT%H:%M:%S"
                )
            )
        )
    except Exception:
        return 0.0


def _embyflow_v28_content_key(item, include_type):
    try:
        import re as _v28_re

        item_type = str(
            (item or {}).get("Type")
            or include_type
            or ""
        ).strip().lower()

        title_key = _v28_re.sub(
            r"[^a-z0-9]+",
            "",
            str(
                (item or {}).get("Name")
                or ""
            ).strip().lower()
        )

        year_key = str(
            (item or {}).get("ProductionYear")
            or ""
        ).strip()

        if title_key:
            return (
                item_type,
                title_key,
                year_key,
            )

        return (
            item_type,
            str((item or {}).get("Id") or ""),
            year_key,
        )
    except Exception:
        return (
            str(include_type or "").lower(),
            str((item or {}).get("Id") or ""),
            "",
        )


def _embyflow_v28_is_documentary(item):
    try:
        aliases = set((
            "documentary",
            "dokumentation",
            "doku",
        ))
        genres = (item or {}).get("Genres") or []
        if isinstance(genres, (str, bytes)):
            genres = [genres]

        for genre in genres:
            if str(genre or "").strip().casefold() in aliases:
                return True
    except Exception:
        pass
    return False


def _embyflow_v28_fetch_recent_type(
    server,
    token,
    user_id,
    include_type,
    earliest_epoch
):
    """Lädt nur so viele neueste Einträge, bis der älteste relevante Cutoff erreicht ist."""
    result = []
    seen_content = set()
    pages = 0
    truncated = False

    if float(earliest_epoch or 0) <= 0:
        return result, pages, truncated

    start_index = 0

    while pages < int(EMBYFLOW_V28_MAX_PAGES):
        params = {
            "Recursive": "true",
            "IncludeItemTypes": str(include_type),
            "SortBy": "DateCreated",
            "SortOrder": "Descending",
            "StartIndex": str(start_index),
            "Limit": str(EMBYFLOW_V28_PAGE_SIZE),
            "Fields": "Genres,ProductionYear,DateCreated",
        }

        response = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers={
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            },
            params=params,
            timeout=10,
            verify=True,
        )

        status = int(
            getattr(response, "status_code", 500)
            or 500
        )
        if status >= 400:
            raise RuntimeError(
                "%s HTTP %s" % (
                    include_type,
                    status,
                )
            )

        payload = response.json() or {}
        raw_items = payload.get("Items") or []
        pages += 1

        if not raw_items:
            break

        oldest_epoch = None

        for item in raw_items:
            created_epoch = _embyflow_v28_emby_timestamp_epoch(
                item.get("DateCreated")
                or item.get("date_created")
            )

            if created_epoch <= 0:
                continue

            if oldest_epoch is None or created_epoch < oldest_epoch:
                oldest_epoch = created_epoch

            if created_epoch <= float(earliest_epoch):
                continue

            content_key = _embyflow_v28_content_key(
                item,
                include_type
            )
            if content_key in seen_content:
                continue

            seen_content.add(content_key)
            result.append({
                "epoch": created_epoch,
                "documentary": _embyflow_v28_is_documentary(item),
            })

        # Durch absteigende DateCreated-Sortierung ist ab hier nichts Neueres
        # mehr zu erwarten, sobald der älteste Datensatz den Cutoff erreicht.
        if (
            oldest_epoch is not None
            and oldest_epoch <= float(earliest_epoch)
        ):
            break

        if len(raw_items) < int(EMBYFLOW_V28_PAGE_SIZE):
            break

        start_index += len(raw_items)

    if pages >= int(EMBYFLOW_V28_MAX_PAGES):
        # Nur als Diagnose: UI bleibt nutzbar, aber extrem alte Zeitfenster
        # könnten mehr als MAX_PAGES neue Titel enthalten.
        try:
            if result:
                minimum_loaded = min(
                    float(row.get("epoch") or 0)
                    for row in result
                )
                if minimum_loaded > float(earliest_epoch):
                    truncated = True
        except Exception:
            pass

    return result, pages, truncated


def _embyflow_v28_cutoff_snapshot(entries):
    result = {}

    for entry in list(entries or []):
        try:
            label = str(
                entry[0]
                if len(entry) > 0
                else ""
            )
            timestamp = str(
                entry[2]
                if len(entry) > 2
                else ""
            )
            result[label] = _embyflow_v28_local_timestamp_epoch(
                timestamp
            )
        except Exception:
            pass

    return result


def _embyflow_v28_count_after(rows, cutoff, documentary_only=False):
    if float(cutoff or 0) <= 0:
        return None

    count = 0
    for row in rows or []:
        try:
            if float(row.get("epoch") or 0) <= float(cutoff):
                continue
            if documentary_only and not bool(row.get("documentary")):
                continue
            count += 1
        except Exception:
            pass

    return count


def _embyflow_v28_load_counts_worker(owner, cutoffs):
    total_started = _embyflow_v28_mono()
    _embyflow_v28_log(
        "START cutoffs=%s" % repr(cutoffs),
        reset=True,
    )

    try:
        auth_started = _embyflow_v28_mono()
        server, token, user_id = get_emby_auth()
        _embyflow_v28_log(
            "AUTH ms=%.1f token=%d user=%d"
            % (
                (_embyflow_v28_mono() - auth_started) * 1000.0,
                int(bool(token)),
                int(bool(user_id)),
            )
        )

        if not server or not token or not user_id:
            raise RuntimeError("Emby-Authentifizierung fehlt")

        movie_labels = (
            "Alles neu",
            "Neue Filme",
            "Neue Dokus",
        )
        series_labels = (
            "Alles neu",
            "Neue Serien",
            "Neue Doku-Serien",
        )

        movie_cutoffs = [
            float(cutoffs.get(label) or 0)
            for label in movie_labels
            if float(cutoffs.get(label) or 0) > 0
        ]
        series_cutoffs = [
            float(cutoffs.get(label) or 0)
            for label in series_labels
            if float(cutoffs.get(label) or 0) > 0
        ]

        movie_earliest = min(movie_cutoffs) if movie_cutoffs else 0.0
        series_earliest = min(series_cutoffs) if series_cutoffs else 0.0

        fetched = {
            "Movie": ([], 0, False),
            "Series": ([], 0, False),
        }
        errors = {}
        metrics = {}

        import threading as _v28_threading
        workers = []

        def fetch_one(include_type, earliest):
            started = _embyflow_v28_mono()
            try:
                fetched[include_type] = (
                    _embyflow_v28_fetch_recent_type(
                        server,
                        token,
                        user_id,
                        include_type,
                        earliest,
                    )
                )
            except Exception as error:
                errors[include_type] = str(error)
                fetched[include_type] = ([], 0, False)
            finally:
                metrics[include_type] = (
                    (_embyflow_v28_mono() - started) * 1000.0
                )

        if movie_earliest > 0:
            worker = _v28_threading.Thread(
                target=fetch_one,
                args=("Movie", movie_earliest),
                name="EmbyFlowNewCountMovieV28",
            )
            worker.daemon = True
            worker.start()
            workers.append(worker)

        if series_earliest > 0:
            worker = _v28_threading.Thread(
                target=fetch_one,
                args=("Series", series_earliest),
                name="EmbyFlowNewCountSeriesV28",
            )
            worker.daemon = True
            worker.start()
            workers.append(worker)

        # Join ausschließlich in diesem Hintergrundthread, niemals im GUI-Thread.
        for worker in workers:
            worker.join()

        movie_rows, movie_pages, movie_truncated = fetched["Movie"]
        series_rows, series_pages, series_truncated = fetched["Series"]

        _embyflow_v28_log(
            "MOVIE ms=%.1f pages=%s rows=%s truncated=%d error=%s"
            % (
                float(metrics.get("Movie") or 0.0),
                movie_pages,
                len(movie_rows),
                int(bool(movie_truncated)),
                str(errors.get("Movie") or "-"),
            )
        )
        _embyflow_v28_log(
            "SERIES ms=%.1f pages=%s rows=%s truncated=%d error=%s"
            % (
                float(metrics.get("Series") or 0.0),
                series_pages,
                len(series_rows),
                int(bool(series_truncated)),
                str(errors.get("Series") or "-"),
            )
        )

        counts = {}

        if "Movie" not in errors:
            value = _embyflow_v28_count_after(
                movie_rows,
                cutoffs.get("Neue Filme")
            )
            if value is not None:
                counts["Neue Filme"] = value

            value = _embyflow_v28_count_after(
                movie_rows,
                cutoffs.get("Neue Dokus"),
                True,
            )
            if value is not None:
                counts["Neue Dokus"] = value

        if "Series" not in errors:
            value = _embyflow_v28_count_after(
                series_rows,
                cutoffs.get("Neue Serien")
            )
            if value is not None:
                counts["Neue Serien"] = value

            value = _embyflow_v28_count_after(
                series_rows,
                cutoffs.get("Neue Doku-Serien"),
                True,
            )
            if value is not None:
                counts["Neue Doku-Serien"] = value

        all_cutoff = float(cutoffs.get("Alles neu") or 0)
        if (
            all_cutoff > 0
            and "Movie" not in errors
            and "Series" not in errors
        ):
            movie_all = _embyflow_v28_count_after(
                movie_rows,
                all_cutoff
            )
            series_all = _embyflow_v28_count_after(
                series_rows,
                all_cutoff
            )
            counts["Alles neu"] = int(movie_all or 0) + int(series_all or 0)

        owner.embyflow_v28_counts_ready = counts

        _embyflow_v28_log(
            "DONE total_ms=%.1f counts=%s errors=%s"
            % (
                (_embyflow_v28_mono() - total_started) * 1000.0,
                repr(counts),
                repr(errors),
            )
        )

    except Exception as error:
        owner.embyflow_v28_counts_ready = {}
        _embyflow_v28_log(
            "ERROR total_ms=%.1f error=%s"
            % (
                (_embyflow_v28_mono() - total_started) * 1000.0,
                str(error),
            )
        )


def _embyflow_v28_start_new_counts(self):
    try:
        if getattr(self, "embyflow_v28_counts_closed", False):
            return
        if getattr(self, "embyflow_v28_counts_running", False):
            return

        cutoffs = _embyflow_v28_cutoff_snapshot(
            getattr(self, "entries", [])
        )

        # Ohne je geöffnete Kategorie gibt es noch keinen sinnvollen Bezugspunkt.
        if not any(float(value or 0) > 0 for value in cutoffs.values()):
            self.embyflow_v28_new_counts = {}
            return

        self.embyflow_v28_counts_running = True
        self.embyflow_v28_counts_ready = None

        import threading as _v28_threading
        worker = _v28_threading.Thread(
            target=_embyflow_v28_load_counts_worker,
            args=(self, cutoffs),
            name="EmbyFlowNewCountsV28",
        )
        worker.daemon = True
        worker.start()

        self.embyflow_v28_counts_apply_timer.start(
            120,
            True
        )

    except Exception as error:
        self.embyflow_v28_counts_running = False
        _embyflow_v28_log(
            "START_ERROR error=%s" % str(error)
        )


def _embyflow_v28_apply_new_counts(self):
    try:
        if getattr(self, "embyflow_v28_counts_closed", False):
            self.embyflow_v28_counts_running = False
            return

        ready = getattr(
            self,
            "embyflow_v28_counts_ready",
            None
        )

        if ready is None:
            if getattr(self, "embyflow_v28_counts_running", False):
                self.embyflow_v28_counts_apply_timer.start(
                    120,
                    True
                )
            return

        self.embyflow_v28_counts_ready = None
        self.embyflow_v28_counts_running = False
        self.embyflow_v28_new_counts = (
            ready if isinstance(ready, dict) else {}
        )

        self.refresh_cinema()

        _embyflow_v28_log(
            "APPLY counts=%s"
            % repr(self.embyflow_v28_new_counts)
        )

    except Exception as error:
        self.embyflow_v28_counts_running = False
        _embyflow_v28_log(
            "APPLY_ERROR error=%s" % str(error)
        )


def _embyflow_v28_cleanup_new_counts(self):
    self.embyflow_v28_counts_closed = True
    try:
        self.embyflow_v28_counts_apply_timer.stop()
    except Exception:
        pass


def _embyflow_v28_cinema_init(self, *args, **kwargs):
    _EMBYFLOW_V28_CINEMA_INIT(self, *args, **kwargs)

    self.embyflow_v28_new_counts = {}
    self.embyflow_v28_counts_ready = None
    self.embyflow_v28_counts_running = False
    self.embyflow_v28_counts_closed = False
    self.embyflow_v28_counts_apply_timer = eTimer()

    try:
        self.embyflow_v28_counts_apply_timer.callback.append(
            self.embyflow_v28_apply_new_counts
        )
    except Exception:
        try:
            self.embyflow_v28_counts_apply_connection = (
                self.embyflow_v28_counts_apply_timer.timeout.connect(
                    self.embyflow_v28_apply_new_counts
                )
            )
        except Exception:
            self.embyflow_v28_counts_apply_connection = None

    self.onLayoutFinish.append(
        self.embyflow_v28_start_new_counts
    )
    self.onClose.append(
        self.embyflow_v28_cleanup_new_counts
    )


def _embyflow_v28_cinema_refresh(self):
    _EMBYFLOW_V28_CINEMA_REFRESH(self)

    counts = getattr(
        self,
        "embyflow_v28_new_counts",
        {}
    )
    if not isinstance(counts, dict):
        return

    for row_index in range(min(5, len(getattr(self, "entries", []) or []))):
        try:
            entry = self.entries[row_index]
            label = str(
                entry[0]
                if len(entry) > 0
                else ""
            )

            if label not in counts:
                continue

            count = max(
                0,
                int(counts.get(label) or 0)
            )
            timestamp_text = self.entry_timestamp(entry)
            count_text = "+%d neu" % count

            if timestamp_text:
                subtitle = "%s • %s" % (
                    count_text,
                    timestamp_text,
                )
            else:
                subtitle = count_text

            self[
                "cinema_sub%d" % row_index
            ].setText(subtitle)

        except Exception:
            pass


EmbyFlowCinemaNewScreen.__init__ = _embyflow_v28_cinema_init
EmbyFlowCinemaNewScreen.refresh_cinema = _embyflow_v28_cinema_refresh
EmbyFlowCinemaNewScreen.embyflow_v28_start_new_counts = _embyflow_v28_start_new_counts
EmbyFlowCinemaNewScreen.embyflow_v28_apply_new_counts = _embyflow_v28_apply_new_counts
EmbyFlowCinemaNewScreen.embyflow_v28_cleanup_new_counts = _embyflow_v28_cleanup_new_counts
# EMBYFLOW_NEW_COUNTS_ASYNC_V28_END

# EMBYFLOW_LOCAL_MULTI_SOURCE_V16_START
# Multi-Source-Dashboard für USB, HDD und bereits gemountete NAS-/Netzwerkquellen.
# Mounting, Zugangsdaten und Netzwerkfreigaben bleiben Aufgabe des Enigma2-Images;
# EmbyFlow verwaltet nur bereits sichtbare Verzeichnisse.
EMBYFLOW_LOCAL_SOURCES_FILE_V16 = "/etc/enigma2/embyflow_local_sources.json"
EMBYFLOW_LOCAL_SOURCES_STATS_FILE_V16 = "/etc/enigma2/embyflow_local_sources_stats.json"
EMBYFLOW_LOCAL_SOURCE_LOG_V16 = "/tmp/embyflow_local_sources_v16.log"
EMBYFLOW_LOCAL_SOURCE_ASSET_DIR_V16 = os.path.join(PLUGIN_PATH, "assets", "local_sources_v16")
EMBYFLOW_LOCAL_SOURCE_MAX_CARDS_V16 = 5
EMBYFLOW_LOCAL_SOURCE_MAX_SCAN_FILES_V16 = 50000


def _embyflow_v16_log(text):
    try:
        with embyflow_open_log(EMBYFLOW_LOCAL_SOURCE_LOG_V16, "a") as log:
            log.write("%s | %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), str(text)))
    except Exception:
        pass


def _embyflow_v16_source_type_label(mode):
    value = str(mode or "mixed").strip().casefold()
    return {
        "movies": "Filme",
        "series": "Serien",
        "documentary": "Dokumentationen",
        "recordings": "Aufnahmen",
        "mixed": "Gemischt",
    }.get(value, "Gemischt")


def _embyflow_v16_source_type_color(mode):
    value = str(mode or "mixed").strip().casefold()
    return {
        "movies": "#2B8CFF",
        "series": "#22CED2",
        "documentary": "#F2C94C",
        "recordings": "#AEB8C5",
        "mixed": "#A05BF5",
    }.get(value, "#A05BF5")


def _embyflow_v16_icon_name(source):
    source = source if isinstance(source, dict) else {}
    name = str(source.get("name") or "").casefold()
    path = str(source.get("path") or "").casefold()
    mode = str(source.get("mode") or "mixed").casefold()
    if "kinder" in name or "kids" in name:
        return "kids.png"
    if mode == "series" or "/net/" in path or "/autofs/" in path or "nas" in name:
        return "nas.png"
    if mode == "documentary":
        return "doc.png"
    if mode == "recordings":
        return "tv.png"
    if mode == "movies":
        return "folder.png"
    return "drive.png"


def _embyflow_v16_default_sources():
    candidates = []
    defaults = (
        ("Meine Filme", "/media/usb/Filme", "movies"),
        ("Meine Serien", "/media/usb/Serien", "series"),
        ("USB-Festplatte", "/media/usb", "mixed"),
        ("Aufnahmen", "/media/hdd/movie", "recordings"),
    )
    for name, path, mode in defaults:
        try:
            if os.path.isdir(path):
                candidates.append({
                    "id": "src_%s" % uuid4().hex[:12],
                    "name": name,
                    "path": os.path.realpath(path),
                    "mode": mode,
                    "enabled": True,
                })
        except Exception:
            pass
    return candidates


def _embyflow_v16_load_sources():
    try:
        if os.path.isfile(EMBYFLOW_LOCAL_SOURCES_FILE_V16):
            data = read_json_file(EMBYFLOW_LOCAL_SOURCES_FILE_V16, {}) or {}
            sources = data.get("sources") or []
            result = []
            for raw in sources:
                if not isinstance(raw, dict):
                    continue
                path = str(raw.get("path") or "").strip()
                if not path:
                    continue
                result.append({
                    "id": str(raw.get("id") or ("src_%s" % uuid4().hex[:12])),
                    "name": str(raw.get("name") or os.path.basename(path.rstrip("/")) or "Medienquelle"),
                    "path": os.path.realpath(path),
                    "mode": str(raw.get("mode") or "mixed").strip().casefold(),
                    "enabled": bool(raw.get("enabled", True)),
                })
            return result
    except Exception as error:
        _embyflow_v16_log("LOAD_ERROR %s" % str(error))

    sources = _embyflow_v16_default_sources()
    try:
        _embyflow_v16_save_sources(sources)
    except Exception:
        pass
    return sources


def _embyflow_v16_save_sources(sources):
    clean = []
    for raw in list(sources or []):
        if not isinstance(raw, dict):
            continue
        path = str(raw.get("path") or "").strip()
        if not path:
            continue
        clean.append({
            "id": str(raw.get("id") or ("src_%s" % uuid4().hex[:12])),
            "name": str(raw.get("name") or os.path.basename(path.rstrip("/")) or "Medienquelle"),
            "path": os.path.realpath(path),
            "mode": str(raw.get("mode") or "mixed").strip().casefold(),
            "enabled": bool(raw.get("enabled", True)),
        })
    write_json_file(EMBYFLOW_LOCAL_SOURCES_FILE_V16, {
        "version": 1,
        "sources": clean,
    })
    return clean


def _embyflow_v16_decode_mount_path(value):
    return str(value or "").replace("\\040", " ").replace("\\011", "\t").replace("\\134", "\\")


def _embyflow_v16_detect_mounts():
    result = []
    seen = set()
    pseudo_fs = set((
        "proc", "sysfs", "tmpfs", "devtmpfs", "devpts", "cgroup", "cgroup2",
        "overlay", "squashfs", "debugfs", "securityfs", "pstore", "tracefs",
        "fusectl", "mqueue", "hugetlbfs", "rpc_pipefs",
    ))

    try:
        with open("/proc/mounts", "r") as handle:
            lines = handle.readlines()
    except Exception:
        lines = []

    for line in lines:
        try:
            parts = line.split()
            if len(parts) < 3:
                continue
            device = _embyflow_v16_decode_mount_path(parts[0])
            path = os.path.realpath(_embyflow_v16_decode_mount_path(parts[1]))
            fstype = str(parts[2] or "").casefold()
            if fstype in pseudo_fs:
                continue
            if path == "/" or path.startswith("/proc") or path.startswith("/sys") or path.startswith("/dev"):
                continue
            if not (path.startswith("/media/") or path.startswith("/mnt/") or path.startswith("/run/media/")):
                continue
            if path in seen:
                continue
            seen.add(path)
            label = os.path.basename(path.rstrip("/")) or path
            if fstype in ("cifs", "nfs", "nfs4"):
                kind = "Netzwerk"
            elif path.startswith("/media/hdd"):
                kind = "Festplatte"
            elif path.startswith("/media/usb") or path.startswith("/run/media"):
                kind = "USB/Laufwerk"
            else:
                kind = "Mount"
            result.append({
                "path": path,
                "label": "%s · %s" % (label, kind),
                "device": device,
                "fstype": fstype,
            })
        except Exception:
            continue

    for path, label in (
        ("/media/usb", "USB-Festplatte · /media/usb"),
        ("/media/hdd", "Festplatte · /media/hdd"),
        ("/media/net", "Netzwerk · /media/net"),
        ("/media/autofs", "AutoFS · /media/autofs"),
        ("/mnt", "Mounts · /mnt"),
    ):
        try:
            real = os.path.realpath(path)
            if real not in seen and os.path.isdir(real):
                seen.add(real)
                result.append({"path": real, "label": label, "device": "", "fstype": ""})
        except Exception:
            pass

    result.sort(key=lambda entry: str(entry.get("label") or "").casefold())
    return result


def _embyflow_v16_source_is_inside(root_path, candidate_path):
    try:
        root = os.path.realpath(str(root_path or ""))
        candidate = os.path.realpath(str(candidate_path or ""))
        return candidate == root or candidate.startswith(root.rstrip("/") + "/")
    except Exception:
        return False


