class EmbyFlowLocalFolderBrowserV16(Screen):
    VISIBLE_ROWS = 11

    skin = scale_skin(
        '''
        <screen name="EmbyFlowLocalFolderBrowserV16" position="0,0" size="1920,1080"
                flags="wfNoBorder" backgroundColor="#081827">
            <eLabel position="0,0" size="1920,1080" backgroundColor="#081827" />
            <eLabel position="0,0" size="1920,4" backgroundColor="#1689FF" />
            <eLabel text="EmbyFlow" position="110,42" size="360,50" font="Regular;36"
                    foregroundColor="#F4F7FB" backgroundColor="#081827" transparent="1" />
            <eLabel text="Ordner auswählen" position="110,112" size="900,58" font="Bold;44"
                    foregroundColor="#F4F7FB" backgroundColor="#081827" transparent="1" />
            <widget name="path" position="110,175" size="1640,38" font="Regular;22"
                    foregroundColor="#AEB8C5" backgroundColor="#081827" transparent="1" />
            <widget name="focus" position="245,240" size="1410,54" zPosition="1"
                    backgroundColor="#15385D" transparent="0" cornerRadius="8"
                    widgetBorderWidth="2" widgetBorderColor="#1689FF" />
        '''
        + _EMBYFLOW_V16_FOLDER_ROWS_SKIN
        + '''
            <widget name="status" position="110,915" size="1500,32" font="Regular;21"
                    foregroundColor="#8090A4" backgroundColor="#081827" transparent="1" />
            <eLabel position="110,990" size="18,18" backgroundColor="red" />
            <eLabel text="Zurück" position="140,980" size="120,34" font="Regular;22"
                    foregroundColor="#F2F5F8" backgroundColor="#081827" transparent="1" />
            <eLabel position="300,990" size="18,18" backgroundColor="green" />
            <eLabel text="Diesen Ordner verwenden" position="330,980" size="300,34" font="Regular;22"
                    foregroundColor="#F2F5F8" backgroundColor="#081827" transparent="1" />
            <eLabel position="690,990" size="18,18" backgroundColor="blue" />
            <eLabel text="Neu laden" position="720,980" size="160,34" font="Regular;22"
                    foregroundColor="#F2F5F8" backgroundColor="#081827" transparent="1" />
            <eLabel text="OK  Öffnen" position="1580,980" size="220,34" font="Regular;22"
                    foregroundColor="#F2F5F8" backgroundColor="#081827" transparent="1" halign="right" />
        </screen>
        '''
    )

    def __init__(self, session, root_path):
        Screen.__init__(self, session)
        self.root_path = os.path.realpath(str(root_path or "/"))
        self.current_path = self.root_path
        self.entries = []
        self.index = 0
        self.offset = 0
        self.scan_result = None
        self.scan_running = False
        self.closed_browser_v16 = False
        self.scan_generation = 0
        self["path"] = Label(self.current_path)
        self["focus"] = Label(" ")
        self["status"] = Label("")
        for index in range(self.VISIBLE_ROWS):
            self["dir%d" % index] = Label("")
        self["actions"] = ActionMap(
            ["OkCancelActions", "DirectionActions", "ColorActions"],
            {
                "ok": self.open_selected,
                "cancel": self.close_cancel,
                "red": self.close_cancel,
                "green": self.choose_current,
                "blue": self.reload,
                "up": self.move_up,
                "down": self.move_down,
                "left": self.page_up,
                "right": self.page_down,
            },
            -1,
        )
        self.apply_timer = eTimer()
        try:
            self.apply_timer.callback.append(self.apply_scan)
        except Exception:
            try:
                self.apply_connection = self.apply_timer.timeout.connect(self.apply_scan)
            except Exception:
                self.apply_connection = None
        self.onLayoutFinish.append(self.reload)
        self.onClose.append(self.cleanup)

    def cleanup(self):
        self.closed_browser_v16 = True
        try:
            self.apply_timer.stop()
        except Exception:
            pass

    def close_cancel(self):
        self.close(None)

    def choose_current(self):
        self.close(self.current_path)

    def reload(self):
        if self.scan_running:
            return
        self.scan_running = True
        self.scan_generation += 1
        generation = self.scan_generation
        path = self.current_path
        self["status"].setText("Ordner werden geladen …")
        import threading as _v16_threading

        def worker():
            result = []
            error = ""
            try:
                with os.scandir(path) as iterator:
                    for entry in iterator:
                        try:
                            if entry.name.startswith("."):
                                continue
                            if entry.is_dir(follow_symlinks=False):
                                full = os.path.realpath(entry.path)
                                if _embyflow_v16_source_is_inside(self.root_path, full):
                                    result.append((entry.name, full))
                        except Exception:
                            continue
                result.sort(key=lambda item: item[0].casefold())
            except Exception as exc:
                error = str(exc)
            self.scan_result = (generation, result, error)

        thread = _v16_threading.Thread(target=worker, name="EmbyFlowFolderV16")
        thread.daemon = True
        thread.start()
        self.apply_timer.start(100, True)

    def apply_scan(self):
        if self.closed_browser_v16:
            return
        ready = self.scan_result
        if ready is None:
            if self.scan_running:
                self.apply_timer.start(100, True)
            return
        self.scan_result = None
        generation, result, error = ready
        if generation != self.scan_generation:
            self.apply_timer.start(1, True)
            return
        self.scan_running = False
        self.entries = list(result or [])
        self.index = min(self.index, max(0, len(self.entries) - 1))
        self.offset = min(self.offset, max(0, len(self.entries) - self.VISIBLE_ROWS))
        if error:
            self["status"].setText("Fehler: %s" % error)
        else:
            self["status"].setText("%d Unterordner · Grün übernimmt den aktuellen Ordner" % len(self.entries))
        self.refresh()

    def refresh(self):
        self["path"].setText(self.current_path)
        for row in range(self.VISIBLE_ROWS):
            pos = self.offset + row
            text = ""
            if pos < len(self.entries):
                text = self.entries[pos][0]
            self["dir%d" % row].setText(text)
        visible = self.index - self.offset
        try:
            self["focus"].instance.move(EFP(245, 240 + visible * 58))
        except Exception:
            pass

    def move_up(self):
        if not self.entries:
            return
        self.index = max(0, self.index - 1)
        if self.index < self.offset:
            self.offset = self.index
        self.refresh()

    def move_down(self):
        if not self.entries:
            return
        self.index = min(len(self.entries) - 1, self.index + 1)
        if self.index >= self.offset + self.VISIBLE_ROWS:
            self.offset = self.index - self.VISIBLE_ROWS + 1
        self.refresh()

    def page_up(self):
        if not self.entries:
            return
        self.index = max(0, self.index - self.VISIBLE_ROWS)
        self.offset = max(0, min(self.index, max(0, len(self.entries) - self.VISIBLE_ROWS)))
        self.refresh()

    def page_down(self):
        if not self.entries:
            return
        self.index = min(len(self.entries) - 1, self.index + self.VISIBLE_ROWS)
        self.offset = max(0, min(self.index, max(0, len(self.entries) - self.VISIBLE_ROWS)))
        self.refresh()

    def open_selected(self):
        if not self.entries or self.index >= len(self.entries):
            return
        path = self.entries[self.index][1]
        if not _embyflow_v16_source_is_inside(self.root_path, path):
            return
        self.current_path = path
        self.entries = []
        self.index = 0
        self.offset = 0
        self.refresh()
        self.reload()


