class EmbyFlowTextInputScreenV19(Screen):
    skin = scale_skin(_embyflow_v19_keyboard_skin())

    def __init__(self, session, title="Eingabe", text="", masked=False):
        Screen.__init__(self, session)
        self.title_text = str(title or "Eingabe")
        self.value = str(text or "")
        self.masked = bool(masked)
        self.uppercase = False
        self.row = 0
        self.col = 0
        self.closed_input_v19 = False

        self["headline"] = Label(self.title_text)
        self["subtitle"] = Label(self._subtitle_for_title())
        self["input"] = Label("")
        self["counter"] = Label("")
        self["key_focus"] = Label(" ")
        self["help1"] = Label("Pfeiltasten\nZeichen auswählen")
        self["help2"] = Label("OK\nAusgewähltes Zeichen einfügen")
        self["help3"] = Label("Grün übernehmen\nGelb letztes Zeichen löschen")
        self["tip"] = Label(self._tip_for_title())

        total_keys = len(_EMBYFLOW_V19_KEY_ROWS_BASE) * _EMBYFLOW_V19_KEY_COLS
        for index in range(total_keys):
            self["key%d" % index] = Label("")

        actions = {
            "cancel": self.cancel_input,
            "red": self.cancel_input,
            "green": self.accept_input,
            "yellow": self.backspace,
            "blue": self.toggle_case,
            "ok": self.press_key,
            "left": self.move_left,
            "right": self.move_right,
            "up": self.move_up,
            "down": self.move_down,
        }
        for number in range(10):
            actions[str(number)] = self._number_action(str(number))

        self["actions"] = ActionMap(
            ["OkCancelActions", "DirectionActions", "ColorActions", "NumberActions"],
            actions,
            -1,
        )
        self.onLayoutFinish.append(self.refresh_all)

    def _number_action(self, value):
        return lambda: self.insert_text(value)

    def _subtitle_for_title(self):
        low = self.title_text.casefold()
        if "nas-adresse" in low or "hostname" in low:
            return "IP-Adresse oder Hostname des NAS eingeben"
        if "freigabe" in low or "export" in low:
            return "SMB-Freigabe oder NFS-Exportpfad eingeben"
        if "passwort" in low:
            return "Passwort eingeben – die Zeichen werden nicht im Klartext angezeigt"
        if "benutzer" in low:
            return "Benutzername für die SMB/CIFS-Freigabe eingeben"
        if "pfad" in low:
            return "Pfad der Medienquelle eingeben"
        if "name" in low:
            return "Anzeigenamen für die Medienquelle eingeben"
        return "Text mit der Fernbedienung eingeben"

    def _tip_for_title(self):
        low = self.title_text.casefold()
        if "nas-adresse" in low or "hostname" in low:
            return "Beispiel: 192.168.1.100 oder diskstation.local"
        if "freigabe" in low:
            return "SMB: z. B. Filme · NFS: z. B. /volume1/Filme"
        if "pfad" in low:
            return "Beispiel: /media/net/NAS/Filme"
        if "passwort" in low:
            return "Das Passwort bleibt intern unverändert; die Anzeige ist maskiert."
        return "Blau wechselt zwischen Groß- und Kleinschreibung."

    def current_keys(self):
        result = []
        for base_row in _EMBYFLOW_V19_KEY_ROWS_BASE:
            row = []
            for key in base_row:
                value = key
                if self.uppercase and len(value) == 1 and value.isalpha():
                    value = value.upper()
                row.append(value)
            result.append(tuple(row))
        return tuple(result)

    def refresh_all(self):
        self.refresh_keys()
        self.refresh_input()
        self.refresh_focus()

    def refresh_keys(self):
        keys = self.current_keys()
        index = 0
        for row in keys:
            for key in row:
                self["key%d" % index].setText(key)
                index += 1

    def refresh_input(self):
        shown = ("*" * len(self.value)) if self.masked else self.value
        max_chars = 58
        if len(shown) > max_chars:
            shown = "…" + shown[-(max_chars - 1):]
        self["input"].setText(shown or " ")
        self["counter"].setText("%d Zeichen" % len(self.value))

    def refresh_focus(self):
        try:
            x = _EMBYFLOW_V19_KEY_X + self.col * (_EMBYFLOW_V19_KEY_W + _EMBYFLOW_V19_KEY_GAP_X)
            y = _EMBYFLOW_V19_KEY_Y + self.row * (_EMBYFLOW_V19_KEY_H + _EMBYFLOW_V19_KEY_GAP_Y)
            self["key_focus"].instance.move(EFP(x, y))
            self["key_focus"].instance.resize(EFS(_EMBYFLOW_V19_KEY_W, _EMBYFLOW_V19_KEY_H))
            self["key_focus"].show()
            self["key_focus"].instance.show()
        except Exception:
            pass

    def move_left(self):
        self.col = (self.col - 1) % _EMBYFLOW_V19_KEY_COLS
        self.refresh_focus()

    def move_right(self):
        self.col = (self.col + 1) % _EMBYFLOW_V19_KEY_COLS
        self.refresh_focus()

    def move_up(self):
        self.row = (self.row - 1) % len(_EMBYFLOW_V19_KEY_ROWS_BASE)
        self.refresh_focus()

    def move_down(self):
        self.row = (self.row + 1) % len(_EMBYFLOW_V19_KEY_ROWS_BASE)
        self.refresh_focus()

    def press_key(self):
        try:
            key = self.current_keys()[self.row][self.col]
        except Exception:
            return
        if key == "LEER":
            key = " "
        self.insert_text(key)

    def insert_text(self, text):
        text = str(text or "")
        if not text:
            return
        if len(self.value) >= 255:
            return
        self.value += text
        self.refresh_input()

    def backspace(self):
        if self.value:
            self.value = self.value[:-1]
            self.refresh_input()

    def toggle_case(self):
        self.uppercase = not self.uppercase
        self.refresh_keys()

    def accept_input(self):
        if self.closed_input_v19:
            return
        self.closed_input_v19 = True
        self.close(self.value)

    def cancel_input(self):
        if self.closed_input_v19:
            return
        self.closed_input_v19 = True
        self.close(None)


