class EmbyFlowLoginTextInputScreenV21(EmbyFlowTextInputScreenV19):
    skin = scale_skin(_embyflow_v21_login_keyboard_skin())

    def __init__(
        self,
        session,
        title="Emby Benutzername",
        text="",
        masked=False,
        server_label="",
    ):
        self.login_server_label = str(server_label or "Server")
        EmbyFlowTextInputScreenV19.__init__(
            self,
            session,
            title,
            text,
            masked,
        )
        self["login_context"] = Label("")
        self.onLayoutFinish.append(self._refresh_login_context_v21)

    def _refresh_login_context_v21(self):
        try:
            self["login_context"].setText(
                "ANMELDUNG  ·  %s" % self.login_server_label
            )
        except Exception:
            pass

    def _subtitle_for_title(self):
        low = self.title_text.casefold()
        if "passwort" in low:
            return "Passwort für dein Emby-Konto eingeben"
        return "Benutzername für dein Emby-Konto eingeben"

    def _tip_for_title(self):
        low = self.title_text.casefold()
        if "passwort" in low:
            return "Das Passwort wird während der Eingabe maskiert."
        return "Groß- und Kleinschreibung des Benutzernamens beachten."

    def _help_for_title_v19_1(self):
        low = self.title_text.casefold()
        if "passwort" in low:
            return (
                "Passwort deines\nEmby-Kontos.",
                "Die Eingabe wird auf\ndem Bildschirm maskiert.",
                "Grün übernimmt die\nEingabe.",
                "Das Passwort wird hier nicht im Klartext angezeigt.",
            )
        return (
            "Benutzername deines\nEmby-Kontos.",
            "Beispiel\nBenutzername",
            "Grün übernimmt die\nEingabe.",
            "Groß- und Kleinschreibung des Benutzernamens beachten.",
        )

    def refresh_focus(self):
        try:
            x = _EMBYFLOW_V21_LOGIN_KEY_X + self.col * (
                _EMBYFLOW_V21_LOGIN_KEY_W + _EMBYFLOW_V21_LOGIN_KEY_GAP_X
            )
            y = _EMBYFLOW_V21_LOGIN_KEY_Y + self.row * (
                _EMBYFLOW_V21_LOGIN_KEY_H + _EMBYFLOW_V21_LOGIN_KEY_GAP_Y
            )
            self["key_focus"].instance.move(EFP(x, y))
            self["key_focus"].instance.resize(
                EFS(_EMBYFLOW_V21_LOGIN_KEY_W, _EMBYFLOW_V21_LOGIN_KEY_H)
            )
            self["key_focus"].show()
            self["key_focus"].instance.show()
        except Exception:
            pass
# EMBYFLOW_LOGIN_FULLSCREEN_KEYBOARD_V21_END

def _embyflow_v19_nas_submit_if_complete(self):
    try:
        current = self["config"].getCurrent()
        if not current or len(current) < 2:
            return
        item = current[1]
        if isinstance(item, ConfigSelection):
            self.keyRight()
            return
        if isinstance(item, (ConfigText, ConfigPassword)):
            self._vkb_item_v18 = item
            self.session.openWithCallback(
                self._vkb_done_v18,
                EmbyFlowTextInputScreenV19,
                str(current[0] or "Eingabe"),
                str(getattr(item, "value", "") or ""),
                isinstance(item, ConfigPassword),
            )
    except Exception:
        pass


def _embyflow_v19_open_manual_path(self):
    self.session.openWithCallback(
        self.manual_path_callback,
        EmbyFlowTextInputScreenV19,
        "Pfad der Medienquelle",
        str(self.manual_value or "/media/"),
        False,
    )


def _embyflow_v19_finalize_edit_current(self):
    try:
        current = self["config"].getCurrent()
        if not current or len(current) < 2:
            return
        item = current[1]
        if isinstance(item, ConfigSelection):
            self.keyRight()
            return
        if isinstance(item, (ConfigText, ConfigPassword)):
            self._vkb_item_v18 = item
            self.session.openWithCallback(
                self._vkb_done_v18,
                EmbyFlowTextInputScreenV19,
                str(current[0] or "Eingabe"),
                str(getattr(item, "value", "") or ""),
                isinstance(item, ConfigPassword),
            )
    except Exception:
        pass


EmbyFlowNasSetupScreenV18.submit_if_complete = _embyflow_v19_nas_submit_if_complete
EmbyFlowLocalAddSourceScreenV18.open_manual_path = _embyflow_v19_open_manual_path
EmbyFlowLocalSourceFinalizeScreenV18.edit_current = _embyflow_v19_finalize_edit_current
