# EMBYFLOW_LOCAL_INPUT_HELP_V19_1_START
# Kontextabhängige Eingabehilfe für die EmbyFlow-Vollbildtastatur.
# Setzt dynamische Texte bewusst in refresh_all(), damit sie erst nach
# aufgebautem Screen/Widget-Layout geschrieben werden.

def _embyflow_v19_1_help_for_title(self):
    low = str(getattr(self, "title_text", "") or "").casefold()

    if "nas-adresse" in low or "hostname" in low:
        return (
            "Hier kommt die Adresse\ndeines NAS hinein.",
            "IP-Adresse\n192.168.1.100",
            "oder Hostname\ndiskstation.local",
            "Nur IP oder Hostname eingeben – kein smb:// davor.",
        )

    if "freigabe" in low or "export" in low:
        return (
            "Name der SMB-Freigabe\noder des NFS-Exports.",
            "SMB/CIFS\nFilme",
            "NFS\n/volume1/Filme",
            "Bei SMB normalerweise keinen führenden / verwenden.",
        )

    if "benutzer" in low:
        return (
            "Benutzerkonto für die\nSMB/CIFS-Freigabe.",
            "Beispiel\nmediauser",
            "Bei einer Gastfreigabe\nkann das Feld leer bleiben.",
            "Groß- und Kleinschreibung des Benutzernamens beachten.",
        )

    if "passwort" in low:
        return (
            "Passwort des gewählten\nSMB-Benutzers.",
            "Die Eingabe wird auf\ndem Bildschirm maskiert.",
            "Für NFS wird hier\nkein Passwort benötigt.",
            "Das Passwort erscheint während der Eingabe nicht im Klartext.",
        )

    if "pfad" in low:
        return (
            "Lokaler Pfad oder bereits\neingebundener Mount.",
            "USB-Beispiel\n/media/usb/Filme",
            "NAS-Beispiel\n/media/net/NAS/Filme",
            "Der Pfad muss auf der Box erreichbar sein.",
        )

    if "name" in low:
        return (
            "Dieser Name erscheint\nunter Eigene Medien.",
            "Beispiel\nMeine Filme",
            "oder\nWohnzimmer-NAS Serien",
            "Nur der Anzeigename wird geändert – nicht der Ordnerpfad.",
        )

    return (
        "Pfeiltasten\nZeichen auswählen",
        "OK\nZeichen einfügen",
        "Grün übernehmen\nGelb letztes Zeichen löschen",
        "Blau wechselt zwischen Groß- und Kleinschreibung.",
    )


def _embyflow_v19_1_refresh_all(self):
    # Dynamische Labels erst nach dem Layout-Aufbau setzen. Das verhindert,
    # dass Skin-/Image-Varianten initiale Label-Texte verschlucken.
    try:
        self["headline"].setText(str(getattr(self, "title_text", "") or "Eingabe"))
    except Exception:
        pass
    try:
        self["subtitle"].setText(self._subtitle_for_title())
    except Exception:
        pass

    try:
        help1, help2, help3, tip = self._help_for_title_v19_1()
        self["help1"].setText(help1)
        self["help2"].setText(help2)
        self["help3"].setText(help3)
        self["tip"].setText(tip)
    except Exception:
        pass

    self.refresh_keys()
    self.refresh_input()
    self.refresh_focus()


EmbyFlowTextInputScreenV19._help_for_title_v19_1 = _embyflow_v19_1_help_for_title
EmbyFlowTextInputScreenV19.refresh_all = _embyflow_v19_1_refresh_all
