class EmbyFlowNasSetupScreenV19_6(Screen):

    skin = _embyflow_v19_6_nas_skin()

    ROW_Y = (250, 346, 442, 538, 634)

    ROW_LABELS = (
        "NAS-Adresse / Hostname",
        "Protokoll",
        "Freigabe / Export",
        "Benutzer (SMB)",
        "Passwort (SMB)",
    )

    def __init__(self, session, host="", protocol="cifs"):
        Screen.__init__(self, session)

        protocol = str(protocol or "cifs").casefold()
        if protocol not in ("cifs", "nfs"):
            protocol = "cifs"

        self.form_values = [
            str(host or ""),
            protocol,
            "",
            "",
            "",
        ]

        self.index = 0
        self.editing_index = None
        self.closed_v19_6 = False

        # EMBYFLOW_NAS_PROTOCOL_AUTO_DETECT_V19_7
        self.protocol_detect_running = False
        self.protocol_detect_result = None
        self.protocol_detect_generation = 0
        self.protocol_detect_timer = eTimer()
        self.protocol_detect_timer_connection = None

        try:
            self.protocol_detect_timer.callback.append(
                self._protocol_detect_poll
            )
        except Exception:
            try:
                self.protocol_detect_timer_connection = (
                    self.protocol_detect_timer.timeout.connect(
                        self._protocol_detect_poll
                    )
                )
            except Exception:
                self.protocol_detect_timer_connection = None

        # V20.4:
        # smbclient bleibt ein externes, optional installiertes Programm.
        self.smb_share_scan_running = False
        self.smb_share_scan_result = None
        self.smb_share_scan_generation = 0

        self.smb_share_scan_timer = eTimer()
        self.smb_share_scan_timer_connection = None

        try:
            self.smb_share_scan_timer.callback.append(
                self._smb_share_scan_poll
            )
        except Exception:
            try:
                self.smb_share_scan_timer_connection = (
                    self.smb_share_scan_timer.timeout.connect(
                        self._smb_share_scan_poll
                    )
                )
            except Exception:
                self.smb_share_scan_timer_connection = None

        self["focus"] = Label(" ")
        self["help_pointer"] = Label("←")

        for idx, text in enumerate(self.ROW_LABELS):
            self["row_label%d" % idx] = Label(text)
            self["row_value%d" % idx] = Label("")
            self["row_arrow%d" % idx] = Label("")

        self["help"] = Label("")
        self["tip"] = Label("")
        self["hint"] = Label(
            "Gelb sucht SMB-Freigaben · Blau erkennt Protokoll · Grün testet · OK bearbeitet"
        )

        self["actions"] = ActionMap(
            [
                "OkCancelActions",
                "DirectionActions",
                "ColorActions",
            ],
            {
                "cancel": self.cancel,
                "red": self.cancel,
                "green": self.submit,
                "yellow": self.discover_smb_shares,
                "blue": self.detect_protocol,
                "ok": self.edit_current,
                "up": self.move_up,
                "down": self.move_down,
                "left": self.key_left,
                "right": self.key_right,
            },
            -1,
        )

        self.onLayoutFinish.append(self.refresh)

    def _protocol_name(self):
        return "NFS" if self.form_values[1] == "nfs" else "SMB/CIFS"

    def _display_value(self, idx):
        value = self.form_values[idx]

        if idx == 1:
            return self._protocol_name()

        if idx in (3, 4) and self.form_values[1] == "nfs":
            return "— nicht benötigt —"

        if idx == 4:
            if value:
                return "*" * len(value)
            return "Optional / Gastzugang"

        if idx == 3 and not value:
            return "Optional / Gastzugang"

        if idx in (0, 2) and not value:
            return "Noch nicht gesetzt"

        return value

    def _action_text(self, idx):
        if idx == 1:
            return "Wechseln"

        if idx in (3, 4) and self.form_values[1] == "nfs":
            return ""

        value = str(self.form_values[idx] or "").strip()

        if value:
            return "Ändern"

        return "Eingeben"

    def _help_text(self):
        idx = self.index

        if idx == 0:
            return (
                "Adresse deines NAS.\n\n"
                "IP-Adresse\n"
                "192.168.1.100\n\n"
                "oder Hostname\n"
                "diskstation.local"
            )

        if idx == 1:
            return (
                "SMB/CIFS\n"
                "Für Windows-/Samba-Freigaben.\n\n"
                "NFS\n"
                "Für NFS-Exports.\n\n"
                "Blau: automatisch erkennen."
            )

        if idx == 2:
            if self.form_values[1] == "nfs":
                return (
                    "NFS-Exportpfad eingeben.\n\n"
                    "Beispiel:\n"
                    "/volume1/Filme"
                )

            return (
                "Name der SMB-Freigabe eingeben.\n\n"
                "Beispiel:\n"
                "Filme"
            )

        if idx == 3:
            return (
                "SMB-Benutzername.\n\n"
                "Leer lassen, wenn die Freigabe "
                "einen Gastzugang erlaubt."
            )

        return (
            "SMB-Passwort.\n\n"
            "Die Eingabe wird in der "
            "EmbyFlow-Tastatur maskiert."
        )

    def _tip_text(self):
        if self.index == 0:
            return "Kein smb:// oder nfs:// voranstellen."

        if self.index == 1:
            return "Bei NFS sind Benutzer und Passwort nicht nötig."

        if self.index == 2:
            return "SMB: Freigabename · NFS: kompletter Exportpfad"

        if self.index in (3, 4):
            return "Nur für SMB/CIFS; bei Gastzugang leer lassen."

        return ""

    def refresh(self):
        for idx in range(5):
            self["row_value%d" % idx].setText(
                self._display_value(idx)
            )
            self["row_arrow%d" % idx].setText(
                self._action_text(idx)
            )

        self["help"].setText(self._help_text())
        self["tip"].setText(self._tip_text())

        try:
            self["focus"].instance.move(
                EFP(220, self.ROW_Y[self.index])
            )
            self["focus"].instance.resize(
                EFS(1110, 80)
            )
            self["focus"].show()
            self["focus"].instance.show()

            self["help_pointer"].instance.move(
                EFP(
                    1365,
                    self.ROW_Y[self.index] + 19
                )
            )
            self["help_pointer"].show()
            self["help_pointer"].instance.show()

        except Exception:
            pass

    def move_up(self):
        self.index = (self.index - 1) % 5
        self.refresh()

    def move_down(self):
        self.index = (self.index + 1) % 5
        self.refresh()

    def _toggle_protocol(self, direction=1):
        if self.form_values[1] == "cifs":
            self.form_values[1] = "nfs"
        else:
            self.form_values[1] = "cifs"

        self["hint"].setText(
            "Protokoll: %s" % self._protocol_name()
        )

        try:
            self["hint"].instance.setForegroundColor(
                parseColor("#91A2B7")
            )
        except Exception:
            pass

        self.refresh()

    def key_left(self):
        if self.index == 1:
            self._toggle_protocol(-1)

    def key_right(self):
        if self.index == 1:
            self._toggle_protocol(1)

    def _protocol_detect_probe(self, host, port):
        sock = None

        try:
            import socket

            addresses = socket.getaddrinfo(
                host,
                int(port),
                0,
                socket.SOCK_STREAM,
            )

            for family, socktype, proto, canonname, sockaddr in addresses:
                try:
                    sock = socket.socket(
                        family,
                        socktype,
                        proto,
                    )
                    sock.settimeout(0.7)

                    if sock.connect_ex(sockaddr) == 0:
                        return True

                except Exception:
                    pass

                finally:
                    try:
                        if sock is not None:
                            sock.close()
                    except Exception:
                        pass

                    sock = None

        except Exception:
            pass

        return False

    def detect_protocol(self):
        if self.protocol_detect_running:
            self["hint"].setText(
                "Protokoll-Erkennung läuft bereits …"
            )
            return

        host = _embyflow_v18_validate_host(
            self.form_values[0]
        )

        if not host:
            self.index = 0
            self["hint"].setText(
                "Bitte zuerst NAS-Adresse oder Hostname eingeben."
            )
            self.refresh()
            return

        self.protocol_detect_generation += 1
        generation = self.protocol_detect_generation

        self.protocol_detect_running = True
        self.protocol_detect_result = None

        self.index = 1
        self["hint"].setText(
            "Suche SMB/CIFS und NFS auf %s …" % host
        )

        try:
            self["hint"].instance.setForegroundColor(
                parseColor("#91A2B7")
            )
        except Exception:
            pass

        self.refresh()

        def worker():
            result = {
                "generation": generation,
                "host": host,
                "smb445": False,
                "smb139": False,
                "nfs2049": False,
                "error": "",
            }

            try:
                result["smb445"] = self._protocol_detect_probe(
                    host,
                    445,
                )

                if not result["smb445"]:
                    result["smb139"] = self._protocol_detect_probe(
                        host,
                        139,
                    )

                result["nfs2049"] = self._protocol_detect_probe(
                    host,
                    2049,
                )

            except Exception as error:
                result["error"] = str(error)

            if (
                not self.closed_v19_6
                and generation == self.protocol_detect_generation
            ):
                self.protocol_detect_result = result

            try:
                with open(
                    "/tmp/embyflow_nas_protocol_detect.log",
                    "a",
                ) as log:
                    log.write(
                        "%s host=%s smb445=%s smb139=%s "
                        "nfs2049=%s error=%s\\n"
                        % (
                            time.strftime("%Y-%m-%d %H:%M:%S"),
                            host,
                            int(bool(result["smb445"])),
                            int(bool(result["smb139"])),
                            int(bool(result["nfs2049"])),
                            str(result["error"] or ""),
                        )
                    )
            except Exception:
                pass

        try:
            import threading

            thread = threading.Thread(
                target=worker,
                name="EmbyFlowNasProtocolDetectV19_7",
            )
            thread.daemon = True
            thread.start()

            self.protocol_detect_timer.start(
                150,
                False,
            )

        except Exception as error:
            self.protocol_detect_running = False
            self["hint"].setText(
                "Automatische Erkennung konnte nicht gestartet werden: %s"
                % str(error)
            )

    def _protocol_detect_poll(self):
        result = self.protocol_detect_result

        if result is None:
            return

        try:
            self.protocol_detect_timer.stop()
        except Exception:
            pass

        self.protocol_detect_result = None
        self.protocol_detect_running = False

        if (
            int(result.get("generation") or 0)
            != self.protocol_detect_generation
        ):
            return

        smb = bool(
            result.get("smb445")
            or result.get("smb139")
        )

        nfs = bool(
            result.get("nfs2049")
        )

        self.index = 1

        if smb and not nfs:
            self.form_values[1] = "cifs"

            self["hint"].setText(
                "Automatisch erkannt: SMB/CIFS"
            )

        elif nfs and not smb:
            self.form_values[1] = "nfs"

            self["hint"].setText(
                "Automatisch erkannt: NFS"
            )

        elif smb and nfs:
            # Beide Dienste laufen. Eine eindeutige automatische
            # Entscheidung wäre hier technisch falsch.
            self["hint"].setText(
                "SMB/CIFS und NFS gefunden · beide Protokolle sind verfügbar"
            )

            try:
                self["hint"].instance.setForegroundColor(
                    parseColor("#FFFFFF")
                )
            except Exception:
                pass

        else:
            self["hint"].setText(
                "Kein SMB/CIFS oder NFS erkannt · NAS und Freigabedienste prüfen"
            )

        self.refresh()

    def _smb_share_hint_color(self, color):
        try:
            self["hint"].instance.setForegroundColor(
                parseColor(color)
            )
        except Exception:
            pass

    @staticmethod
    def _smb_share_parse(output):
        shares = []
        seen = set()

        for raw in str(output or "").splitlines():
            parts = [
                item.strip()
                for item in raw.strip().split("|")
            ]

            # smbclient -g -L:
            # Disk|Freigabename|Kommentar
            if (
                len(parts) < 2
                or parts[0].casefold() != "disk"
            ):
                continue

            share = parts[1].strip()

            if not share:
                continue

            # Technische Standardfreigaben nicht anbieten.
            if share.casefold() in (
                "ipc$",
                "print$",
            ):
                continue

            key = share.casefold()

            if key in seen:
                continue

            seen.add(key)
            shares.append(share)

        shares.sort(
            key=lambda value: value.casefold()
        )

        return shares

    def discover_smb_shares(self):
        if self.smb_share_scan_running:
            self["hint"].setText(
                "SMB-Freigabensuche läuft bereits …"
            )
            return

        if (
            str(
                self.form_values[1] or ""
            ).casefold()
            != "cifs"
        ):
            self.index = 1

            self["hint"].setText(
                "Freigabensuche ist nur für SMB/CIFS verfügbar."
            )

            self._smb_share_hint_color(
                "#F5C542"
            )

            self.refresh()
            return

        host = _embyflow_v18_validate_host(
            self.form_values[0]
        )

        if not host:
            self.index = 0

            self["hint"].setText(
                "Bitte zuerst NAS-Adresse oder Hostname eingeben."
            )

            self._smb_share_hint_color(
                "#F5C542"
            )

            self.refresh()
            return

        try:
            import shutil

            smbclient = shutil.which(
                "smbclient"
            )

        except Exception:
            smbclient = None

        if not smbclient:
            self["hint"].setText(
                "smbclient ist nicht installiert · "
                "Freigabensuche nicht verfügbar"
            )

            self._smb_share_hint_color(
                "#F5C542"
            )

            return

        user = str(
            self.form_values[3] or ""
        )

        password = str(
            self.form_values[4] or ""
        )

        if any(
            char in user + password
            for char in ("\n", "\r")
        ):
            self["hint"].setText(
                "Ungültige Zeilenumbrüche in Zugangsdaten."
            )

            self._smb_share_hint_color(
                "#FF6B6B"
            )

            return

        self.smb_share_scan_generation += 1
        generation = (
            self.smb_share_scan_generation
        )

        self.smb_share_scan_running = True
        self.smb_share_scan_result = None

        self.index = 2

        self["hint"].setText(
            "Suche SMB-Freigaben auf %s …"
            % host
        )

        self._smb_share_hint_color(
            "#91A2B7"
        )

        self.refresh()

        def worker():
            data = {
                "generation": generation,
                "host": host,
                "shares": [],
                "rc": -1,
                "error": "",
                "auth": bool(
                    user or password
                ),
            }

            authfile = None

            try:
                import os
                import subprocess
                import tempfile

                cmd = [
                    smbclient,
                    "-g",
                    "-L",
                    host,
                    "-E",
                    "-d",
                    "0",
                    "-t",
                    "8",
                ]

                if user or password:
                    fd, authfile = (
                        tempfile.mkstemp(
                            prefix=".embyflow_smb_",
                            dir="/tmp",
                            text=True,
                        )
                    )

                    os.fchmod(
                        fd,
                        0o600,
                    )

                    with os.fdopen(
                        fd,
                        "w",
                    ) as credentials:
                        credentials.write(
                            "username = %s\n"
                            % user
                        )

                        credentials.write(
                            "password = %s\n"
                            % password
                        )

                    cmd += [
                        "-A",
                        authfile,
                    ]

                else:
                    # Kein Benutzer/Passwort:
                    # explizit Gastzugriff versuchen.
                    cmd += [
                        "-N",
                    ]

                process = subprocess.Popen(
                    cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                )

                try:
                    stdout_data, stderr_data = (
                        process.communicate(
                            timeout=15
                        )
                    )

                except subprocess.TimeoutExpired:
                    process.kill()
                    process.communicate()

                    raise RuntimeError(
                        "Zeitüberschreitung bei smbclient"
                    )

                data["rc"] = int(
                    process.returncode or 0
                )

                stdout_text = (
                    stdout_data or b""
                ).decode(
                    "utf-8",
                    "replace",
                )

                stderr_text = (
                    stderr_data or b""
                ).decode(
                    "utf-8",
                    "replace",
                )

                data["shares"] = (
                    self._smb_share_parse(
                        stdout_text
                    )
                )

                # Ein smbclient kann nach erfolgreicher
                # Share-Liste noch Fehler beim Workgroup-
                # Browsing melden. Gefundene Disk-Shares
                # haben deshalb Vorrang vor dem Returncode.
                if (
                    not data["shares"]
                    and stderr_text.strip()
                ):
                    lines = [
                        line.strip()
                        for line
                        in stderr_text.splitlines()
                        if line.strip()
                    ]

                    if lines:
                        data["error"] = (
                            lines[-1][:240]
                        )

            except Exception as error:
                data["error"] = (
                    str(error)[:240]
                )

            finally:
                if authfile:
                    try:
                        os.unlink(
                            authfile
                        )
                    except Exception:
                        pass

            if (
                not self.closed_v19_6
                and generation
                == self.smb_share_scan_generation
            ):
                self.smb_share_scan_result = (
                    data
                )

            # Kein Passwort im Log.
            try:
                with open(
                    "/tmp/"
                    "embyflow_smb_share_discovery.log",
                    "a",
                ) as log:
                    log.write(
                        "%s host=%s auth=%s "
                        "rc=%s shares=%s error=%s\n"
                        % (
                            time.strftime(
                                "%Y-%m-%d %H:%M:%S"
                            ),
                            host,
                            int(
                                bool(
                                    data["auth"]
                                )
                            ),
                            data["rc"],
                            len(
                                data["shares"]
                            ),
                            str(
                                data["error"]
                                or ""
                            ).replace(
                                "\n",
                                " ",
                            )[:240],
                        )
                    )

            except Exception:
                pass

        try:
            import threading

            thread = threading.Thread(
                target=worker,
                name=(
                    "EmbyFlowSmbShareDiscoveryV20_4"
                ),
            )

            thread.daemon = True
            thread.start()

            self.smb_share_scan_timer.start(
                150,
                False,
            )

        except Exception as error:
            self.smb_share_scan_running = False

            self["hint"].setText(
                "Freigabensuche konnte nicht "
                "gestartet werden: %s"
                % error
            )

            self._smb_share_hint_color(
                "#FF6B6B"
            )

    def _smb_share_scan_poll(self):
        data = self.smb_share_scan_result

        if data is None:
            return

        try:
            self.smb_share_scan_timer.stop()
        except Exception:
            pass

        self.smb_share_scan_result = None
        self.smb_share_scan_running = False

        if (
            int(
                data.get(
                    "generation"
                ) or 0
            )
            != self.smb_share_scan_generation
        ):
            return

        shares = list(
            data.get(
                "shares"
            ) or []
        )

        if shares:
            self["hint"].setText(
                "%d SMB-Freigabe%s gefunden · auswählen"
                % (
                    len(shares),
                    ""
                    if len(shares) == 1
                    else "n",
                )
            )

            self._smb_share_hint_color(
                "#4AC36B"
            )

            choices = [
                (
                    share,
                    share,
                )
                for share in shares
            ]

            self.session.openWithCallback(
                self._smb_share_choice_done,
                ChoiceBox,
                title=(
                    "SMB-Freigabe auswählen"
                ),
                list=choices,
            )

            return

        if data.get("auth"):
            text = (
                "Keine SMB-Datenfreigaben gefunden · "
                "Zugangsdaten prüfen"
            )

        else:
            text = (
                "Keine SMB-Datenfreigaben per "
                "Gastzugriff gefunden · ggf. "
                "Benutzer/Passwort eintragen"
            )

        error = str(
            data.get(
                "error"
            ) or ""
        ).strip()

        if error:
            text += " · " + error

        self["hint"].setText(
            text[:180]
        )

        self._smb_share_hint_color(
            "#F5C542"
        )

    def _smb_share_choice_done(
        self,
        result=None,
    ):
        if result is None:
            self["hint"].setText(
                "Freigabenauswahl abgebrochen."
            )

            self._smb_share_hint_color(
                "#91A2B7"
            )

            return

        if isinstance(
            result,
            (
                tuple,
                list,
            ),
        ):
            share = (
                result[1]
                if len(result) > 1
                else result[0]
            )
        else:
            share = result

        share = str(
            share or ""
        ).strip()

        if not share:
            return

        self.form_values[1] = "cifs"
        self.form_values[2] = share
        self.index = 2

        self["hint"].setText(
            "SMB-Freigabe übernommen: %s · "
            "Grün zum Verbindungstest"
            % share
        )

        self._smb_share_hint_color(
            "#4AC36B"
        )

        self.refresh()

    def edit_current(self):
        if self.index == 1:
            self._toggle_protocol(1)
            return

        if self.index in (3, 4) and self.form_values[1] == "nfs":
            self["hint"].setText(
                "Bei NFS werden Benutzer und Passwort nicht benötigt."
            )
            return

        self.editing_index = self.index

        self.session.openWithCallback(
            self._field_done,
            EmbyFlowTextInputScreenV19,
            self.ROW_LABELS[self.index],
            str(self.form_values[self.index] or ""),
            self.index == 4,
        )

    def _field_done(self, result=None):
        if result is None:
            return

        idx = self.editing_index
        if idx not in (0, 2, 3, 4):
            return

        self.form_values[idx] = str(result)

        self["hint"].setText(
            "Gespeichert: %s" % self.ROW_LABELS[idx]
        )

        self.refresh()

    def submit(self):
        host = _embyflow_v18_validate_host(
            self.form_values[0]
        )

        protocol = str(
            self.form_values[1] or "cifs"
        ).casefold()

        share = str(
            self.form_values[2] or ""
        ).strip()

        if not host:
            self.index = 0
            self["hint"].setText(
                "Bitte eine gültige NAS-IP oder einen Hostnamen eingeben."
            )
            self.refresh()
            return

        if not share:
            self.index = 2
            self["hint"].setText(
                "Bitte Freigabename (SMB) oder Exportpfad (NFS) eingeben."
            )
            self.refresh()
            return

        if self.closed_v19_6:
            return

        self.closed_v19_6 = True

        self.close(
            {
                "host": host,
                "protocol": protocol,
                "share": share,
                "username": (
                    str(self.form_values[3] or "")
                    if protocol == "cifs"
                    else ""
                ),
                "password": (
                    str(self.form_values[4] or "")
                    if protocol == "cifs"
                    else ""
                ),
            }
        )

    def cancel(self):
        if self.closed_v19_6:
            return

        self.closed_v19_6 = True
        self.protocol_detect_generation += 1
        self.smb_share_scan_generation += 1

        try:
            self.protocol_detect_timer.stop()
        except Exception:
            pass

        try:
            self.smb_share_scan_timer.stop()
        except Exception:
            pass

        self.close(None)


