# EMBYFLOW_RECORDING_PLANNER_V20
# EMBYFLOW_RECORDING_PLANNER_ZLAYER_CALLBACK_V20_1
# EMBYFLOW_RECORDING_EPG_READABILITY_V20_2
# EMBYFLOW_RECORDING_BOUQUET_FOCUS_V20_3
# Native Enigma2-Aufnahmeplanung fuer "Eigene Medien".
# Sender/Bouquets und EPG stammen ausschliesslich aus dem Enigma2-System des Nutzers.
# Die eigentliche Aufnahme wird vom nativen Enigma2 RecordTimer ausgefuehrt.

_EMBYFLOW_V20_BOUQUET_ROWS = 9


def _embyflow_v20_clean_service_name(value):
    text = str(value or "")
    text = text.replace("\x86", "").replace("\x87", "")
    text = re.sub(r"[\x00-\x1f\x7f]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _embyflow_v20_service_key(ref):
    parts = str(ref or "").split(":")
    return ":".join(parts[:11]) if len(parts) >= 11 else str(ref or "")


def _embyflow_v20_service_name(ref, fallback=""):
    try:
        from enigma import eServiceCenter
        sref = eServiceReference(str(ref or ""))
        info = eServiceCenter.getInstance().info(sref)
        if info is not None:
            name = _embyflow_v20_clean_service_name(info.getName(sref))
            if name:
                return name
    except Exception:
        pass
    return _embyflow_v20_clean_service_name(fallback) or "Sender"


def _embyflow_v20_parse_bouquets():
    base = "/etc/enigma2"
    master = os.path.join(base, "bouquets.tv")
    result = []

    try:
        with open(master, "r", encoding="utf-8", errors="replace") as handle:
            lines = handle.readlines()
    except Exception:
        try:
            with open(master, "r") as handle:
                lines = handle.readlines()
        except Exception:
            lines = []

    names = []
    rx = re.compile(r'FROM BOUQUET\s+"([^"]+\.tv)"', re.I)
    for raw in lines:
        match = rx.search(str(raw or ""))
        if not match:
            continue
        filename = os.path.basename(match.group(1))
        if filename not in names:
            names.append(filename)

    for filename in names:
        path = os.path.join(base, filename)
        bouquet_name = filename
        channels = []
        pending = None

        try:
            with open(path, "r", encoding="utf-8", errors="replace") as handle:
                blines = handle.readlines()
        except Exception:
            try:
                with open(path, "r") as handle:
                    blines = handle.readlines()
            except Exception:
                continue

        for raw in blines:
            line = str(raw or "").strip()
            if line.startswith("#NAME "):
                bouquet_name = _embyflow_v20_clean_service_name(line[6:]) or bouquet_name
                continue

            if line.startswith("#SERVICE "):
                service = line[9:].strip()
                pending = None
                if not service or "FROM BOUQUET" in service.upper():
                    continue
                parts = service.split(":")
                if len(parts) > 1 and parts[1] in ("64", "832"):
                    continue
                pending = {"ref": service, "name": ""}
                channels.append(pending)
                continue

            if line.startswith("#DESCRIPTION ") and pending is not None:
                pending["name"] = _embyflow_v20_clean_service_name(line[13:])

        clean_channels = []
        seen = set()
        for channel in channels:
            ref = str(channel.get("ref") or "").strip()
            if not ref:
                continue
            key = _embyflow_v20_service_key(ref)
            if key in seen:
                continue
            seen.add(key)
            channel["name"] = _embyflow_v20_service_name(ref, channel.get("name") or "")
            clean_channels.append(channel)

        if clean_channels:
            result.append({
                "file": filename,
                "name": bouquet_name,
                "channels": clean_channels,
            })

    return result


def _embyflow_v20_record_targets():
    targets = []
    seen = set()

    try:
        sources = _embyflow_v16_load_sources()
    except Exception:
        sources = []

    for source in sources:
        try:
            if str(source.get("mode") or "").casefold() != "recordings":
                continue
            path = os.path.realpath(str(source.get("path") or ""))
            if not path or path in seen:
                continue
            if not os.path.isdir(path):
                continue
            seen.add(path)
            targets.append({
                "name": str(source.get("name") or "Aufnahmen"),
                "path": path,
                "kind": "Eigene Medien",
            })
        except Exception:
            continue

    native = ""
    try:
        from Components.UsageConfig import preferredTimerPath, defaultMoviePath
        native = str(preferredTimerPath() or defaultMoviePath() or "").strip()
    except Exception:
        native = ""

    if not native:
        for candidate in ("/media/hdd/movie", "/media/hdd"):
            if os.path.isdir(candidate):
                native = candidate
                break

    if native:
        try:
            native = os.path.realpath(native)
        except Exception:
            pass
        if native not in seen and os.path.isdir(native):
            targets.append({
                "name": "Standard-Aufnahmeordner",
                "path": native,
                "kind": "Enigma2",
            })

    return targets


def _embyflow_v20_bouquet_skin():
    rows = []
    for idx in range(_EMBYFLOW_V20_BOUQUET_ROWS):
        y = 184 + idx * 76
        rows.append(
            '<widget name="bq_bg%d" position="20,%d" size="290,68" '
            'zPosition="1" backgroundColor="#08131F" transparent="0" />'
            '<widget name="bq_name%d" position="42,%d" size="244,34" '
            'zPosition="3" font="Regular;22" foregroundColor="#F4F7FB" '
            'transparent="1" />'
            '<widget name="bq_count%d" position="42,%d" size="244,26" '
            'zPosition="3" font="Regular;16" foregroundColor="#9CA7B5" '
            'transparent="1" />'
            % (idx, y, idx, y + 7, idx, y + 39)
        )

    # V20.3:
    # Kein blauer Vollhintergrund.
    # Nur ein schmaler Fokusstrich links.
    rows.append(
        '<widget name="bq_focusbar" position="20,184" size="4,68" '
        'zPosition="4" backgroundColor="#1689FF" transparent="0" />'
    )

    return "".join(rows)


