class EmbyFlowRecordingPlannerScreenV20(Screen):
    skin = _EMBYFLOW_V20_RECORDING_SKIN

    def __init__(self, session):
        Screen.__init__(self, session)

        self.bouquets = _embyflow_v20_parse_bouquets()
        self.bouquet_index = 0
        self.bouquet_offset = 0
        self.channel_index = 0
        self.focus_zone = "bouquets"
        self.record_targets = _embyflow_v20_record_targets()
        self.record_target_index = 0

        for idx in range(_EMBYFLOW_V20_BOUQUET_ROWS):
            self["bq_bg%d" % idx] = Label(" ")
            self["bq_name%d" % idx] = Label("")
            self["bq_count%d" % idx] = Label("")

        self["bq_focusbar"] = Label(" ")

        self["channel"] = Label("")
        self["bouquet_title"] = Label("")
        self["event_title"] = Label("")
        self["event_subtitle"] = Label("")
        self["event_time"] = Label("")
        self["event_description"] = Label("")
        self["margin_before"] = Label("")
        self["margin_after"] = Label("")
        self["target_name"] = Label("")
        self["target_path"] = Label("")
        self["status"] = Label("")
        self["epg_hint"] = Label("Links: Bouquets · Blau: Sender wählen · Grün: Aufnahme speichern")

        self.epg_available = False
        self.EPGListClass = None
        self.ServiceReferenceClass = None
        self.RecordTimerEntryClass = None
        self.parseEventFunc = None
        self.TimerEntryClass = None
        self.TimerEditListClass = None
        self.TimerSanityConflictClass = None

        try:
            from Components.EpgList import EPGList, EPG_TYPE_SINGLE
            from ServiceReference import ServiceReference
            self.EPGListClass = EPGList
            self.ServiceReferenceClass = ServiceReference
            self["epg"] = EPGList(
                type=EPG_TYPE_SINGLE,
                selChangedCB=self._event_changed,
                timer=self.session.nav.RecordTimer,
            )
            # V20.2: kompaktere Datums-/Zeitspalten geben dem
            # Sendungstitel deutlich mehr Platz.
            self["epg"].column_weekday = 48
            self["epg"].column_datetime = 200
            self.epg_available = True
        except Exception:
            self["epg"] = Label("")

        try:
            from RecordTimer import RecordTimerEntry, parseEvent
            self.RecordTimerEntryClass = RecordTimerEntry
            self.parseEventFunc = parseEvent
        except Exception:
            pass

        try:
            from Screens.TimerEntry import TimerEntry
            self.TimerEntryClass = TimerEntry
        except Exception:
            pass

        try:
            from Screens.TimerEdit import TimerEditList, TimerSanityConflict
            self.TimerEditListClass = TimerEditList
            self.TimerSanityConflictClass = TimerSanityConflict
        except Exception:
            try:
                from Screens.TimerEdit import TimerEditList
                self.TimerEditListClass = TimerEditList
            except Exception:
                pass

        self["actions"] = ActionMap(
            ["OkCancelActions", "DirectionActions", "ColorActions", "MenuActions"],
            {
                "cancel": self.close,
                "red": self.close,
                "green": self.save_timer_direct,
                "yellow": self.open_timer_list,
                "blue": self.open_channel_choice,
                "menu": self.open_target_choice,
                "ok": self.open_timer_editor,
                "up": self.key_up,
                "down": self.key_down,
                "left": self.key_left,
                "right": self.key_right,
            },
            -1,
        )

        self.onLayoutFinish.append(self._layout_ready)

    def _layout_ready(self):
        if not self.bouquets:
            self["status"].setText(
                "Keine TV-Bouquets gefunden. Bitte zuerst eine Senderliste in Enigma2 einrichten."
            )
            self._refresh_bouquets()
            self._refresh_target()
            return

        self._select_current_service_if_possible()
        self._refresh_bouquets()
        self._refresh_target()
        self._load_channel_epg()

    def _select_current_service_if_possible(self):
        current = ""
        try:
            ref = self.session.nav.getCurrentlyPlayingServiceReference()
            if ref is not None:
                current = _embyflow_v20_service_key(ref.toString())
        except Exception:
            current = ""
        if not current:
            return
        for bidx, bouquet in enumerate(self.bouquets):
            for cidx, channel in enumerate(bouquet.get("channels") or []):
                if _embyflow_v20_service_key(channel.get("ref")) == current:
                    self.bouquet_index = bidx
                    self.channel_index = cidx
                    return

    def _current_bouquet(self):
        if not self.bouquets:
            return None
        self.bouquet_index = max(0, min(self.bouquet_index, len(self.bouquets) - 1))
        return self.bouquets[self.bouquet_index]

    def _current_channel(self):
        bouquet = self._current_bouquet()
        if not bouquet:
            return None
        channels = list(bouquet.get("channels") or [])
        if not channels:
            return None
        self.channel_index = max(0, min(self.channel_index, len(channels) - 1))
        return channels[self.channel_index]

    def _refresh_bouquets(self):
        count = len(self.bouquets)
        if count:
            if self.bouquet_index < self.bouquet_offset:
                self.bouquet_offset = self.bouquet_index
            if self.bouquet_index >= self.bouquet_offset + _EMBYFLOW_V20_BOUQUET_ROWS:
                self.bouquet_offset = self.bouquet_index - _EMBYFLOW_V20_BOUQUET_ROWS + 1
            self.bouquet_offset = max(
                0,
                min(self.bouquet_offset, max(0, count - _EMBYFLOW_V20_BOUQUET_ROWS)),
            )

        for slot in range(_EMBYFLOW_V20_BOUQUET_ROWS):
            idx = self.bouquet_offset + slot
            name = ""
            count_text = ""
            selected = False
            if 0 <= idx < count:
                bouquet = self.bouquets[idx]
                name = str(bouquet.get("name") or "Bouquet")
                channel_count = len(bouquet.get("channels") or [])
                count_text = "%d Sender" % channel_count
                selected = idx == self.bouquet_index and self.focus_zone == "bouquets"

            self["bq_name%d" % slot].setText(name)
            self["bq_count%d" % slot].setText(count_text)

            try:
                # V20.3:
                # Hintergrund bleibt IMMER dunkel.
                # Dadurch entstehen weder blaue Vollflächen noch
                # alte/stale Farbreste hinter den transparenten Labels.
                self["bq_bg%d" % slot].instance.setBackgroundColor(
                    parseColor("#08131F")
                )

                self["bq_name%d" % slot].instance.setForegroundColor(
                    parseColor(
                        "#FFFFFF"
                        if selected
                        else "#F4F7FB"
                    )
                )

                self["bq_count%d" % slot].instance.setForegroundColor(
                    parseColor(
                        "#1689FF"
                        if selected
                        else "#9CA7B5"
                    )
                )

            except Exception:
                pass

        # Einzige Fokusmarkierung:
        # schmaler cyanfarbener Balken links.
        try:
            if self.focus_zone == "bouquets" and count:
                focus_slot = (
                    self.bouquet_index
                    - self.bouquet_offset
                )

                if (
                    0 <= focus_slot
                    < _EMBYFLOW_V20_BOUQUET_ROWS
                ):
                    self["bq_focusbar"].instance.move(
                        EFP(
                            20,
                            184 + focus_slot * 76
                        )
                    )
                else:
                    self["bq_focusbar"].instance.move(
                        EFP(-500, -500)
                    )
            else:
                self["bq_focusbar"].instance.move(
                    EFP(-500, -500)
                )

        except Exception:
            pass

    def _refresh_target(self):
        before = 0
        after = 0
        try:
            before = int(config.recording.margin_before.value or 0)
            after = int(config.recording.margin_after.value or 0)
        except Exception:
            pass
        self["margin_before"].setText("Vorlaufzeit     %d Min." % before)
        self["margin_after"].setText("Nachlaufzeit   %d Min." % after)

        if not self.record_targets:
            self["target_name"].setText("Aufnahmeziel: nicht verfügbar")
            self["target_path"].setText("Bitte einen Aufnahmeordner in Enigma2 oder 'Eigene Medien' einrichten.")
            return

        self.record_target_index = max(0, min(self.record_target_index, len(self.record_targets) - 1))
        target = self.record_targets[self.record_target_index]
        self["target_name"].setText("Aufnahmeziel: %s" % str(target.get("name") or "Aufnahmen"))
        self["target_path"].setText(str(target.get("path") or ""))

    def _load_channel_epg(self):
        bouquet = self._current_bouquet()
        channel = self._current_channel()

        if bouquet:
            self["bouquet_title"].setText(str(bouquet.get("name") or ""))
        else:
            self["bouquet_title"].setText("")

        if not channel:
            self["channel"].setText("Kein Sender")
            self["status"].setText("Das ausgewählte Bouquet enthält keine nutzbaren TV-Sender.")
            return

        self["channel"].setText(str(channel.get("name") or "Sender"))

        if not self.epg_available or self.ServiceReferenceClass is None:
            self["status"].setText("Die native Enigma2-EPG-Komponente ist auf diesem Image nicht verfügbar.")
            return

        try:
            service = self.ServiceReferenceClass(eServiceReference(str(channel.get("ref") or "")))
            self["epg"].fillSingleEPG(service)
            self["status"].setText("EPG geladen · Grün programmiert die markierte Sendung.")
            self._event_changed()
        except Exception as error:
            self["status"].setText("EPG konnte nicht geladen werden: %s" % str(error))

    def _event_changed(self):
        event = None
        service = None
        try:
            current = self["epg"].getCurrent()
            if current:
                event = current[0]
                service = current[1] if len(current) > 1 else None
        except Exception:
            pass

        if event is None:
            self["event_title"].setText("Keine EPG-Daten")
            self["event_subtitle"].setText("")
            self["event_time"].setText("")
            self["event_description"].setText(
                "Für diesen Sender liegen aktuell keine EPG-Daten vor."
            )
            return

        try:
            title = str(event.getEventName() or "Sendung")
        except Exception:
            title = "Sendung"
        try:
            short = str(event.getShortDescription() or "")
        except Exception:
            short = ""
        try:
            extended = str(event.getExtendedDescription() or "")
        except Exception:
            extended = ""
        try:
            begin = int(event.getBeginTime() or 0)
            duration = int(event.getDuration() or 0)
        except Exception:
            begin = 0
            duration = 0

        self["event_title"].setText(title)
        self["event_subtitle"].setText(short)
        if begin:
            start = time.strftime("%a %d.%m.%Y  %H:%M", time.localtime(begin))
            end = time.strftime("%H:%M", time.localtime(begin + max(0, duration)))
            self["event_time"].setText(
                "%s - %s   ·   %d Min." % (start, end, max(0, duration // 60))
            )
        else:
            self["event_time"].setText("")

        description = extended or short or "Keine Beschreibung verfügbar."
        self["event_description"].setText(description[:1400])

    def key_up(self):
        if self.focus_zone == "bouquets":
            if self.bouquets:
                self.bouquet_index = (self.bouquet_index - 1) % len(self.bouquets)
                self.channel_index = 0
                self._refresh_bouquets()
                self._load_channel_epg()
            return
        try:
            from enigma import eListbox
            self["epg"].instance.moveSelection(eListbox.moveUp)
        except Exception:
            pass

    def key_down(self):
        if self.focus_zone == "bouquets":
            if self.bouquets:
                self.bouquet_index = (self.bouquet_index + 1) % len(self.bouquets)
                self.channel_index = 0
                self._refresh_bouquets()
                self._load_channel_epg()
            return
        try:
            from enigma import eListbox
            self["epg"].instance.moveSelection(eListbox.moveDown)
        except Exception:
            pass

    def key_left(self):
        self.focus_zone = "bouquets"
        self._refresh_bouquets()

    def key_right(self):
        if self._current_channel() is not None:
            self.focus_zone = "epg"
            self._refresh_bouquets()

    def open_channel_choice(self):
        bouquet = self._current_bouquet()
        if not bouquet:
            return
        channels = list(bouquet.get("channels") or [])
        entries = []
        for idx, channel in enumerate(channels):
            entries.append((
                str(channel.get("name") or "Sender"),
                {"index": idx},
            ))
        if not entries:
            self.session.open(MessageBox, "Dieses Bouquet enthält keine Sender.", MessageBox.TYPE_INFO, timeout=5)
            return
        self.session.openWithCallback(
            self._channel_choice_done,
            EmbyFlowChoiceScreen,
            "Sender wählen · %s" % str(bouquet.get("name") or "Bouquet"),
            entries,
        )

    def _channel_choice_done(self, selection):
        if not selection:
            return
        data = selection[1] if len(selection) > 1 else {}
        if not isinstance(data, dict):
            return
        try:
            self.channel_index = int(data.get("index") or 0)
        except Exception:
            self.channel_index = 0
        self.focus_zone = "epg"
        self._refresh_bouquets()
        self._load_channel_epg()

    def open_target_choice(self):
        self.record_targets = _embyflow_v20_record_targets()
        if not self.record_targets:
            self.session.open(
                MessageBox,
                "Kein erreichbarer Aufnahmeordner gefunden.\n\n"
                "Richte unter 'Eigene Medien' eine Quelle vom Typ 'Aufnahmen' "
                "oder einen normalen Enigma2-Aufnahmeordner ein.",
                MessageBox.TYPE_INFO,
                timeout=8,
            )
            return
        entries = []
        for idx, target in enumerate(self.record_targets):
            label = "%s · %s" % (
                str(target.get("name") or "Aufnahmen"),
                str(target.get("kind") or ""),
            )
            entries.append((label, {"index": idx}))
        self.session.openWithCallback(
            self._target_choice_done,
            EmbyFlowChoiceScreen,
            "Aufnahmeziel wählen",
            entries,
        )

    def _target_choice_done(self, selection):
        if not selection:
            return
        data = selection[1] if len(selection) > 1 else {}
        if not isinstance(data, dict):
            return
        try:
            self.record_target_index = int(data.get("index") or 0)
        except Exception:
            self.record_target_index = 0
        self._refresh_target()

    def _selected_event(self):
        try:
            current = self["epg"].getCurrent()
            if current and current[0] is not None and current[1] is not None:
                return current[0], current[1]
        except Exception:
            pass
        return None, None

    def _selected_target_path(self):
        self.record_targets = _embyflow_v20_record_targets()
        if not self.record_targets:
            return ""
        self.record_target_index = max(0, min(self.record_target_index, len(self.record_targets) - 1))
        return str(self.record_targets[self.record_target_index].get("path") or "")

    def _timer_exists_for_event(self, event, service):
        try:
            eventid = int(event.getEventId() or 0)
            begin = int(event.getBeginTime() or 0)
            end = begin + int(event.getDuration() or 0)
            service_key = _embyflow_v20_service_key(service.ref.toString())
            timers = self.session.nav.RecordTimer.getAllTimersList()
            for timer in timers:
                try:
                    timer_key = _embyflow_v20_service_key(timer.service_ref.ref.toString())
                    if timer_key != service_key:
                        continue
                    if eventid and int(getattr(timer, "eit", 0) or 0) == eventid:
                        return True
                    if begin < int(timer.begin) <= end or int(timer.begin) <= begin <= int(timer.end):
                        return True
                except Exception:
                    continue
        except Exception:
            pass
        return False

    def _make_timer_entry(self):
        event, service = self._selected_event()
        if event is None or service is None:
            self.session.open(MessageBox, "Bitte zuerst eine Sendung auswählen.", MessageBox.TYPE_INFO, timeout=5)
            return None

        if self._timer_exists_for_event(event, service):
            self.session.open(
                MessageBox,
                "Für diese Sendung ist bereits ein Aufnahme-Timer vorhanden.",
                MessageBox.TYPE_INFO,
                timeout=6,
            )
            return None

        target = self._selected_target_path()
        if not target or not os.path.isdir(target):
            self.session.open(
                MessageBox,
                "Das Aufnahmeziel ist aktuell nicht erreichbar.\n\nBitte mit MENU ein anderes Ziel wählen.",
                MessageBox.TYPE_INFO,
                timeout=7,
            )
            return None

        if self.RecordTimerEntryClass is None or self.parseEventFunc is None:
            self.session.open(
                MessageBox,
                "Die native Enigma2-Timerfunktion ist auf diesem Image nicht verfügbar.",
                MessageBox.TYPE_INFO,
                timeout=7,
            )
            return None

        try:
            entry = self.RecordTimerEntryClass(
                service,
                checkOldTimers=True,
                dirname=target,
                *self.parseEventFunc(event)
            )
            return entry
        except Exception as error:
            self.session.open(
                MessageBox,
                "Aufnahme-Timer konnte nicht vorbereitet werden:\n\n%s" % str(error),
                MessageBox.TYPE_INFO,
                timeout=8,
            )
            return None

    def save_timer_direct(self):
        entry = self._make_timer_entry()
        if entry is None:
            return
        self._commit_timer_entry(entry)

    def open_timer_editor(self):
        entry = self._make_timer_entry()
        if entry is None:
            return
        if self.TimerEntryClass is None:
            self._commit_timer_entry(entry)
            return
        try:
            self.session.openWithCallback(
                self._timer_editor_done,
                self.TimerEntryClass,
                entry,
                newEntry=True,
            )
        except Exception:
            try:
                self.session.openWithCallback(
                    self._timer_editor_done,
                    self.TimerEntryClass,
                    entry,
                )
            except Exception as error:
                self.session.open(
                    MessageBox,
                    "Timer-Editor konnte nicht geöffnet werden:\n\n%s" % str(error),
                    MessageBox.TYPE_INFO,
                    timeout=8,
                )

    def _timer_editor_done(self, answer=None):
        try:
            if not answer or not answer[0]:
                return
            entry = answer[1]
        except Exception:
            return
        self._commit_timer_entry(entry)

    def _commit_timer_entry(self, entry):
        try:
            conflicts = self.session.nav.RecordTimer.record(entry)
        except Exception as error:
            self.session.open(
                MessageBox,
                "Aufnahme-Timer konnte nicht gespeichert werden:\n\n%s" % str(error),
                MessageBox.TYPE_INFO,
                timeout=8,
            )
            return

        if conflicts is not None:
            if self.TimerSanityConflictClass is not None:
                try:
                    self.session.openWithCallback(
                        self._timer_editor_done,
                        self.TimerSanityConflictClass,
                        conflicts,
                    )
                    return
                except Exception:
                    pass
            self.session.open(
                MessageBox,
                "Timerkonflikt erkannt. Bitte die Timer-Liste prüfen.",
                MessageBox.TYPE_INFO,
                timeout=7,
            )
            return

        name = str(getattr(entry, "name", "Sendung") or "Sendung")
        self["status"].setText("Aufnahme programmiert: %s" % name)
        self.session.open(
            MessageBox,
            "Aufnahme programmiert:\n\n%s" % name,
            MessageBox.TYPE_INFO,
            timeout=5,
        )
        try:
            self["epg"].l.invalidate()
        except Exception:
            pass

    def open_timer_list(self):
        if self.TimerEditListClass is None:
            self.session.open(
                MessageBox,
                "Die native Enigma2-Timerliste ist auf diesem Image nicht verfügbar.",
                MessageBox.TYPE_INFO,
                timeout=6,
            )
            return
        try:
            self.session.open(self.TimerEditListClass)
        except Exception as error:
            self.session.open(
                MessageBox,
                "Timer-Liste konnte nicht geöffnet werden:\n\n%s" % str(error),
                MessageBox.TYPE_INFO,
                timeout=7,
            )


_EMBYFLOW_V20_OLD_MANAGE_MENU = EmbyFlowLocalSourcesScreenV17.open_manage_menu
_EMBYFLOW_V20_OLD_MANAGE_CALLBACK = EmbyFlowLocalSourcesScreenV17.manage_menu_callback


def _embyflow_v20_open_manage_menu(self):
    entries = [
        ("Aufnahme-Timer anzeigen", {"action": "record_timers"}),
        ("Medienquelle hinzufügen", {"action": "add"}),
    ]
    if self.current_source():
        entries.extend([
            ("Ausgewählte Quelle bearbeiten", {"action": "edit"}),
            ("Ausgewählte Quelle entfernen", {"action": "remove"}),
        ])
    self.session.openWithCallback(
        self.manage_menu_callback,
        EmbyFlowChoiceScreen,
        "Eigene Medien",
        entries,
    )


def _embyflow_v20_manage_menu_callback(self, selection):
    if not selection:
        return
    data = selection[1] if len(selection) > 1 else {}
    action = data.get("action") if isinstance(data, dict) else ""

    if action == "record_epg":
        self.session.open(EmbyFlowRecordingPlannerScreenV20)
        return

    if action == "record_timers":
        try:
            from Screens.TimerEdit import TimerEditList
            self.session.open(TimerEditList)
        except Exception:
            self.session.open(
                MessageBox,
                "Die native Enigma2-Timerliste ist auf diesem Image nicht verfügbar.",
                MessageBox.TYPE_INFO,
                timeout=6,
            )
        return

    _EMBYFLOW_V20_OLD_MANAGE_CALLBACK(self, selection)


EmbyFlowLocalSourcesScreenV17.open_manage_menu = _embyflow_v20_open_manage_menu
EmbyFlowLocalSourcesScreenV17.manage_menu_callback = _embyflow_v20_manage_menu_callback
# EMBYFLOW_RECORDING_PLANNER_V20_END


# EMBYFLOW_RECORDING_CHANNEL_CALLBACK_SAFE_V20_1

def _embyflow_v20_1_channel_choice_done(self, selection):
    log_path = "/tmp/embyflow_recording_v20_1.log"

    try:
        with open(log_path, "a") as log:
            log.write(
                "CHANNEL_CALLBACK selection=%r\n"
                % (selection,)
            )
    except Exception:
        pass

    if not selection:
        try:
            self["status"].setText(
                "Keine Senderauswahl übernommen."
            )
        except Exception:
            pass
        return

    data = None

    try:
        if isinstance(selection, dict):
            data = selection
        elif (
            isinstance(selection, (tuple, list))
            and len(selection) > 1
        ):
            data = selection[1]
    except Exception:
        data = None

    if not isinstance(data, dict):
        try:
            self["status"].setText(
                "Senderauswahl konnte nicht gelesen werden."
            )
        except Exception:
            pass
        return

    try:
        index = int(data.get("index", 0) or 0)
    except Exception:
        index = 0

    try:
        bouquet = self._current_bouquet()
        channels = list(
            (bouquet or {}).get("channels") or []
        )

        if not channels:
            self["status"].setText(
                "Dieses Bouquet enthält keine Sender."
            )
            return

        self.channel_index = max(
            0,
            min(index, len(channels) - 1)
        )

        self.focus_zone = "epg"
        self._refresh_bouquets()

        channel = self._current_channel()

        self["bouquet_title"].setText(
            str((bouquet or {}).get("name") or "")
        )

        self["channel"].setText(
            str((channel or {}).get("name") or "Sender")
        )

        self["status"].setText(
            "Sender übernommen · EPG wird geladen …"
        )

        try:
            with open(log_path, "a") as log:
                log.write(
                    "CHANNEL_APPLY "
                    "bouquet=%r "
                    "index=%d "
                    "channel=%r "
                    "ref=%r "
                    "epg_available=%r\n"
                    % (
                        (bouquet or {}).get("name"),
                        self.channel_index,
                        (channel or {}).get("name"),
                        (channel or {}).get("ref"),
                        getattr(
                            self,
                            "epg_available",
                            None
                        ),
                    )
                )
        except Exception:
            pass

        self._load_channel_epg()

    except Exception as error:
        try:
            self["status"].setText(
                "Sender übernommen, aber EPG-Fehler: %s"
                % str(error)
            )
        except Exception:
            pass

        try:
            with open(log_path, "a") as log:
                log.write(
                    "CHANNEL_ERROR %s\n"
                    % str(error)
                )
        except Exception:
            pass


EmbyFlowRecordingPlannerScreenV20._channel_choice_done = (
    _embyflow_v20_1_channel_choice_done
)


