def _embyflow_own_media_v23_is_menu(self):
    try:
        title = str(
            getattr(self, "title_text", "")
            or ""
        ).strip().casefold()

        if title != "eigene medien":
            return False

        labels = set()

        for entry in getattr(self, "entries", []) or []:
            try:
                labels.add(
                    str(entry[0] or "").strip()
                )
            except Exception:
                pass

        required = {
            "Aufnahme-Timer anzeigen",
            "Medienquelle hinzufügen",
            "Ausgewählte Quelle bearbeiten",
            "Ausgewählte Quelle entfernen",
        }

        return required.issubset(labels)

    except Exception:
        return False


