def _embyflow_own_media_v23_init(self, session, title, entries):
    _EMBYFLOW_OWN_MEDIA_V23_ORIGINAL_INIT(
        self,
        session,
        title,
        entries,
    )

    if not _embyflow_own_media_v23_is_menu(self):
        return

    # Nur dieses eine Menu bekommt den Spezial-Skin.
    self.skin = _EMBYFLOW_OWN_MEDIA_V23_SKIN

    self["own_badge0"] = Label("EPG")
    self["own_badge1"] = Label("TMR")
    self["own_badge2"] = Label("+")
    self["own_badge3"] = Label("EDIT")
    self["own_badge4"] = Label("DEL")

    self["own_info_bg"] = Label(" ")
    self["own_info_badge"] = Label("EPG")
    self["own_info_title"] = Label("")
    self["own_info_description"] = Label("")

    self["own_quick_bg"] = Label(" ")
    self["own_quick_title"] = Label("ⓘ  Schnellinfo")
    self["own_quick_text"] = Label("")

    self["own_hint_bg"] = Label(" ")
    self["own_hint_title"] = Label("Hinweis")
    self["own_hint_text"] = Label("")

    self.page_size = 16


def _embyflow_own_media_v23_info(text, timestamp):
    last_used = embyflow_format_choice_last_opened(
        timestamp
    )

    data = {
        "Sendung aufnehmen (EPG)": (
            "EPG",
            "Sendung aufnehmen\n(EPG)",
            "Zeigt die geplanten und laufenden "
            "Aufnahmetimer der Box. Hier können "
            "bestehende Timer kontrolliert und "
            "verwaltet werden.",
            "Letzte Nutzung: %s" % last_used,
            "Die Timer werden nativ von Enigma2 "
            "verwaltet.",
        ),

        "Medienquelle hinzufügen": (
            "+",
            "Medienquelle\nhinzufügen",
            "Fügen Sie lokale oder Netzwerkmedien "
            "hinzu. Unterstützt werden eingerichtete "
            "USB-, Festplatten-, SMB- und "
            "NFS-Quellen.",
            "Letzte Nutzung: %s" % last_used,
            "Jeder Benutzer verwendet ausschließlich "
            "seine eigenen Speicherorte.",
        ),

        "Ausgewählte Quelle bearbeiten": (
            "EDIT",
            "Quelle\nbearbeiten",
            "Ändern Sie Name, Typ oder Verbindung "
            "der aktuell ausgewählten Medienquelle.",
            "Letzte Nutzung: %s" % last_used,
            "Die vorhandenen Mediendateien werden "
            "dabei nicht verändert.",
        ),

        "Ausgewählte Quelle entfernen": (
            "DEL",
            "Quelle\nentfernen",
            "Entfernt die ausgewählte Quelle aus "
            "EmbyFlow. Die Dateien auf dem "
            "Speichermedium selbst bleiben erhalten.",
            "Letzte Nutzung: %s" % last_used,
            "Vor dem Entfernen erfolgt weiterhin "
            "eine Sicherheitsabfrage.",
        ),
    }

    return data.get(
        text,
        (
            "INFO",
            text,
            "",
            "Letzte Nutzung: %s" % last_used,
            "",
        )
    )


def _embyflow_own_media_v23_refresh(self):
    _EMBYFLOW_OWN_MEDIA_V23_ORIGINAL_REFRESH(self)

    if not _embyflow_own_media_v23_is_menu(self):
        return

    visible = self.visible_entries()

    try:
        self["choice_hero_background"].hide()
    except Exception:
        pass

    # Alte Such-Infoelemente sicher unsichtbar.
    for name in (
        "choice_info_bg",
        "choice_info_accent",
        "choice_info_title",
        "choice_info_intro",
        "choice_info_count_label",
        "choice_info_count",
        "choice_info_latest_label",
        "choice_info_latest",
        "choice_info_hint",
    ):
        try:
            self[name].hide()
        except Exception:
            pass

    y_values = (
        220,
        348,
        476,
        604,
        732,
    )

    try:
        from enigma import gFont
    except Exception:
        gFont = None

    selected_slot = max(
        0,
        min(
            int(getattr(self, "index", 0)),
            4,
        )
    )

    for slot in range(5):
        text = ""
        timestamp = ""

        if slot < len(visible):
            try:
                text = str(
                    visible[slot][0]
                    or ""
                )
            except Exception:
                text = ""

            try:
                if len(visible[slot]) > 2:
                    timestamp = str(
                        visible[slot][2]
                        or ""
                    )
            except Exception:
                timestamp = ""

        selected = bool(text) and slot == selected_slot

        try:
            self["row%d" % slot].setText(text)
        except Exception:
            pass

        try:
            if text:
                self[
                    "choice_sub%d" % slot
                ].setText(
                    embyflow_format_choice_last_opened(
                        timestamp
                    )
                )
                self[
                    "choice_status%d" % slot
                ].setText("›")
            else:
                self[
                    "choice_sub%d" % slot
                ].setText("")
                self[
                    "choice_status%d" % slot
                ].setText("")
        except Exception:
            pass

        try:
            card = self[
                "choice_card%d" % slot
            ]

            card.instance.setBackgroundColor(
                parseColor(
                    "#142338"
                    if selected
                    else "#111923"
                )
            )

            if text:
                card.show()
                card.instance.show()
            else:
                card.hide()
        except Exception:
            pass

        try:
            row = self[
                "row%d" % slot
            ].instance

            row.move(
                EFP(
                    274,
                    y_values[slot] + 34,
                )
            )

            row.resize(
                EFS(
                    560,
                    48,
                )
            )

            row.setForegroundColor(
                parseColor(
                    "#FFFFFF"
                    if selected
                    else "#D7DEE8"
                )
            )

            if gFont is not None:
                row.setFont(
                    gFont(
                        "Bold",
                        30 if selected else 29,
                    )
                )
        except Exception:
            pass

        try:
            sub = self[
                "choice_sub%d" % slot
            ].instance

            sub.move(
                EFP(
                    842,
                    y_values[slot] + 38,
                )
            )

            sub.resize(
                EFS(
                    300,
                    38,
                )
            )

            sub.setForegroundColor(
                parseColor(
                    "#C8D2DF"
                    if selected
                    else "#7F8996"
                )
            )

            if text:
                self[
                    "choice_sub%d" % slot
                ].show()
        except Exception:
            pass

        try:
            arrow = self[
                "choice_status%d" % slot
            ].instance

            arrow.move(
                EFP(
                    1170,
                    y_values[slot] + 32,
                )
            )

            arrow.resize(
                EFS(
                    44,
                    48,
                )
            )

            arrow.setForegroundColor(
                parseColor(
                    "#1689FF"
                    if selected
                    else "#697583"
                )
            )

            if text:
                self[
                    "choice_status%d" % slot
                ].show()
        except Exception:
            pass

    # Fokusrahmen.
    if visible:
        focus_y = y_values[selected_slot]

        try:
            self["focus_bg"].instance.move(
                EFP(140, focus_y)
            )
            self["focus_bg"].instance.resize(
                EFS(1110, 116)
            )
            self["focus_bg"].instance.setBackgroundColor(
                parseColor("#102A49")
            )
            self["focus_bg"].show()
            self["focus_bg"].instance.show()
        except Exception:
            pass

        try:
            self["focus_bar"].instance.move(
                EFP(140, focus_y)
            )
            self["focus_bar"].instance.resize(
                EFS(5, 116)
            )
            self["focus_bar"].instance.setBackgroundColor(
                parseColor("#1689FF")
            )
            self["focus_bar"].show()
            self["focus_bar"].instance.show()
        except Exception:
            pass

    # Dynamisches rechtes Panel.
    current_text = ""
    current_timestamp = ""

    if (
        selected_slot >= 0
        and selected_slot < len(visible)
    ):
        try:
            current_text = str(
                visible[selected_slot][0]
                or ""
            )
        except Exception:
            pass

        try:
            if len(visible[selected_slot]) > 2:
                current_timestamp = str(
                    visible[selected_slot][2]
                    or ""
                )
        except Exception:
            pass

    (
        badge,
        panel_title,
        description,
        quick_text,
        hint_text,
    ) = _embyflow_own_media_v23_info(
        current_text,
        current_timestamp,
    )

    try:
        self["own_info_badge"].setText(badge)
        self["own_info_title"].setText(panel_title)
        self["own_info_description"].setText(description)
        self["own_quick_text"].setText(quick_text)
        self["own_hint_text"].setText(hint_text)
    except Exception:
        pass


EmbyFlowChoiceScreen.__init__ = (
    _embyflow_own_media_v23_init
)

EmbyFlowChoiceScreen.refresh = (
    _embyflow_own_media_v23_refresh
)

EmbyFlowChoiceScreen.is_own_media_v23_menu = (
    _embyflow_own_media_v23_is_menu
)

