# ============================================================
# EMBYFLOW_SENDER_CARDS_V23_1
#
# Nur fuer:
#   Sender waehlen · <Bouquet>
#
# - 2 x 8 kompakte Senderkarten
# - blauer Fokus wie Eigene Medien V23
# - Bouquet separat unter der Ueberschrift
# - "Noch nie geoeffnet" wird nicht angezeigt
# - aktuelle EPG-Sendung wird aus dem Enigma2-EPG-Cache gelesen
# ============================================================

import re as _embyflow_sender_v231_re
import time as _embyflow_sender_v231_time


_EMBYFLOW_SENDER_V231_PREVIOUS_INIT = (
    EmbyFlowChoiceScreen.__init__
)

_EMBYFLOW_SENDER_V231_PREVIOUS_REFRESH = (
    EmbyFlowChoiceScreen.refresh
)


def _embyflow_sender_v231_is_menu(self):
    try:
        title = str(
            getattr(self, "title_text", "")
            or ""
        ).strip().casefold()

        return (
            title.startswith("sender wählen")
            or title.startswith("sender waehlen")
        )

    except Exception:
        return False


def _embyflow_sender_v231_bouquet(self):
    try:
        title = str(
            getattr(self, "title_text", "")
            or ""
        ).strip()

        for separator in ("·", "•", " – ", " - "):
            if separator in title:
                left, right = title.split(
                    separator,
                    1,
                )

                if (
                    left.strip().casefold()
                    in (
                        "sender wählen",
                        "sender waehlen",
                    )
                ):
                    return right.strip()

        return ""

    except Exception:
        return ""


def _embyflow_sender_v231_find_ref(value, depth=0):
    if depth > 5:
        return ""

    if value is None:
        return ""

    try:
        if isinstance(value, str):
            candidate = value.strip()

            if _embyflow_sender_v231_re.match(
                r"^\d+:\d+:\d+:[0-9A-Fa-f]+:",
                candidate,
            ):
                return candidate

            return ""
    except Exception:
        pass

    try:
        method = getattr(
            value,
            "toString",
            None,
        )

        if callable(method):
            candidate = str(
                method()
                or ""
            ).strip()

            if _embyflow_sender_v231_re.match(
                r"^\d+:\d+:\d+:[0-9A-Fa-f]+:",
                candidate,
            ):
                return candidate
    except Exception:
        pass

    if isinstance(value, dict):
        preferred = (
            "service_ref",
            "serviceRef",
            "serviceref",
            "service_reference",
            "reference",
            "ref",
            "service",
        )

        for key in preferred:
            if key not in value:
                continue

            result = _embyflow_sender_v231_find_ref(
                value.get(key),
                depth + 1,
            )

            if result:
                return result

        for nested in value.values():
            result = _embyflow_sender_v231_find_ref(
                nested,
                depth + 1,
            )

            if result:
                return result

    elif isinstance(value, (tuple, list)):
        for nested in value:
            result = _embyflow_sender_v231_find_ref(
                nested,
                depth + 1,
            )

            if result:
                return result

    return ""


def _embyflow_sender_v231_epg(entry):
    try:
        entry_data = (
            entry[1]
            if len(entry) > 1
            else None
        )

        service_ref = (
            _embyflow_sender_v231_find_ref(
                entry_data
            )
        )

        if not service_ref:
            return (
                "Sender auswählen",
                "",
            )

        from enigma import (
            eEPGCache,
            eServiceReference,
        )

        cache = eEPGCache.getInstance()

        if cache is None:
            return (
                "Sender auswählen",
                "",
            )

        reference = eServiceReference(
            service_ref
        )

        event = cache.lookupEventTime(
            reference,
            -1,
            0,
        )

        if event is None:
            return (
                "Kein EPG verfügbar",
                "",
            )

        event_name = str(
            event.getEventName()
            or ""
        ).strip()

        if not event_name:
            event_name = "Kein EPG verfügbar"

        try:
            begin = int(
                event.getBeginTime()
                or 0
            )

            time_text = (
                _embyflow_sender_v231_time.strftime(
                    "%H:%M",
                    _embyflow_sender_v231_time.localtime(
                        begin
                    ),
                )
                if begin > 0
                else ""
            )

        except Exception:
            time_text = ""

        return (
            event_name,
            time_text,
        )

    except Exception:
        return (
            "Sender auswählen",
            "",
        )


