def _embyflow_sender_v2311_open_channel_choice(self):
    bouquet = self._current_bouquet()

    if not bouquet:
        return

    channels = list(
        bouquet.get("channels")
        or []
    )

    entries = []

    for idx, channel in enumerate(channels):
        try:
            sender_name = str(
                channel.get("name")
                or "Sender"
            )
        except Exception:
            sender_name = "Sender"

        data = {
            "index": idx,
        }

        # Den kompletten Senderdatensatz mitgeben.
        # Damit bleiben wir unabhängig davon, wie der
        # Bouquet-Parser die ServiceRef intern benennt.
        if isinstance(channel, dict):
            data["channel"] = dict(channel)

        # Zusätzlich ServiceRef direkt vorbereiten.
        try:
            service_ref = (
                _embyflow_sender_v231_find_ref(
                    channel
                )
            )

            if service_ref:
                data["service_ref"] = (
                    service_ref
                )

        except Exception:
            pass

        entries.append(
            (
                sender_name,
                data,
            )
        )

    if not entries:
        self.session.open(
            MessageBox,
            "Dieses Bouquet enthält keine Sender.",
            MessageBox.TYPE_INFO,
            timeout=5,
        )
        return

    self.session.openWithCallback(
        self._channel_choice_done,
        EmbyFlowChoiceScreen,
        "Sender wählen · %s"
        % str(
            bouquet.get("name")
            or "Bouquet"
        ),
        entries,
    )


