# ============================================================
# EMBYFLOW_CUSTOM_EPG_REMOVED_V1
# Eigener Sender-EPG, EPG-Manager, externe Engine,
# Dashboards und Multi-Source-Import wurden entfernt.


# EMBYFLOW_LOCAL_ALL_MEDIA_TILE_V1_START
#
# Virtuelle Kachel "Alle Medien":
# - wird NICHT in /etc/enigma2/embyflow_local_sources.json gespeichert
# - liegt logisch hinter den echten Quellen
# - benutzt den bereits vorhandenen 5. Kartenplatz, wenn er frei ist
# - bei mehr als 4 echten Quellen bleibt sie am Ende der horizontalen Liste erreichbar
# - "Quellen verwalten" zeigt weiterhin ausschliesslich echte Quellen
# - beim Oeffnen werden die vorhandenen Quellen im Worker zusammengefuehrt
#
# Ueberlappende Quellen (z. B. /media/usb plus /media/usb/Filme) werden
# entdoppelt: die spezifischere Quelle gewinnt fuer diesen Unterbaum.

EMBYFLOW_LOCAL_ALL_MEDIA_ID_V1 = "__embyflow_all_media_v1__"

_EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_REFRESH_V1 = EmbyFlowLocalSourcesScreenV17.refresh
_EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_MOVE_LEFT_V1 = EmbyFlowLocalSourcesScreenV17.move_left
_EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_MOVE_RIGHT_V1 = EmbyFlowLocalSourcesScreenV17.move_right
_EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_MOVE_DOWN_V1 = EmbyFlowLocalSourcesScreenV17.move_down
_EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_OPEN_V1 = EmbyFlowLocalSourcesScreenV17.open_selected


def _embyflow_local_all_media_virtual_source_v1(screen):
    count = len(list(getattr(screen, "sources", []) or []))
    return {
        "id": EMBYFLOW_LOCAL_ALL_MEDIA_ID_V1,
        "name": "Alle Medien",
        "path": "%d Quelle%s" % (count, "" if count == 1 else "n"),
        "mode": "mixed",
        "enabled": True,
    }


def _embyflow_local_all_media_selected_v1(screen):
    real_sources = list(getattr(screen, "sources", []) or [])
    return bool(
        real_sources
        and int(getattr(screen, "selected_index", 0) or 0) == len(real_sources)
    )


def _embyflow_local_all_media_is_within_v1(path, root):
    try:
        path_real = os.path.realpath(str(path or ""))
        root_real = os.path.realpath(str(root or "")).rstrip(os.sep)
        if not path_real or not root_real:
            return False
        return path_real == root_real or path_real.startswith(root_real + os.sep)
    except Exception:
        return False


def _embyflow_local_all_media_common_root_v1(sources):
    roots = []
    for source in list(sources or []):
        try:
            path = os.path.realpath(str((source or {}).get("path") or ""))
            if path:
                roots.append(path)
        except Exception:
            pass

    if not roots:
        return "/media"

    try:
        common = os.path.commonpath(roots)
    except Exception:
        common = "/media"

    common = os.path.realpath(str(common or "/media"))
    if common == "/":
        # Die vorkonfigurierten Eigenen Medien liegen normalerweise unter /media.
        # / als Playback-Root ist unnoetig breit; /media ist der sichere Fallback.
        if all(_embyflow_local_all_media_is_within_v1(root, "/media") for root in roots):
            common = "/media"
    return common


class EmbyFlowAllMediaLibraryScreenV1(EmbyFlowLocalLibraryScreenV3):
    def __init__(self, session, sources):
        self.all_media_sources_v1 = [
            dict(source)
            for source in list(sources or [])
            if isinstance(source, dict)
        ]
        self.all_media_source_count_v1 = len(self.all_media_sources_v1)
        root = _embyflow_local_all_media_common_root_v1(
            self.all_media_sources_v1
        )
        EmbyFlowLocalLibraryScreenV3.__init__(
            self,
            session,
            root,
            "all",
            "Alle Medien",
        )

    def update_header(self):
        count = len(list(getattr(self, "entries", []) or []))
        source_count = int(
            getattr(self, "all_media_source_count_v1", 0) or 0
        )
        self["subtitle"].setText(
            "%d Einträge aus %d Quelle%s"
            % (
                count,
                source_count,
                "" if source_count == 1 else "n",
            )
        )

    def start_scan(self):
        if self.scan_loading:
            return

        sources = [
            dict(source)
            for source in list(
                getattr(self, "all_media_sources_v1", []) or []
            )
            if isinstance(source, dict)
        ]

        if not sources:
            self.entries = []
            self["status"].setText("Keine Medienquelle eingerichtet")
            self.update_header()
            self.refresh()
            return

        self.scan_generation += 1
        generation = self.scan_generation
        self.scan_result = None
        self.scan_loading = True
        self["status"].setText("Alle Medien werden eingelesen …")

        import threading as _all_media_threading_v1

        def worker():
            try:
                prepared = []
                for source in sources:
                    root = os.path.realpath(
                        str(source.get("path") or "")
                    )
                    if not root or not os.path.isdir(root):
                        continue
                    prepared.append((source, root))

                combined = []
                seen_movie_paths = set()
                seen_series_episode_paths = set()

                for source, root in prepared:
                    mode = str(
                        source.get("mode") or "mixed"
                    ).strip().casefold()
                    source_name = str(
                        source.get("name") or "Medienquelle"
                    )

                    # Wenn eine spezifischere konfigurierte Quelle unterhalb
                    # dieser Quelle liegt, wird dieser Unterbaum in der
                    # breiteren Quelle ausgeblendet. So erscheint z. B.
                    # /media/usb/Serien nicht noch einmal ueber /media/usb.
                    child_roots = []
                    for other_source, other_root in prepared:
                        if other_root == root:
                            continue
                        if _embyflow_local_all_media_is_within_v1(
                            other_root, root
                        ):
                            child_roots.append(other_root)

                    scan_mode = "series" if mode == "series" else "movies"
                    entries = list(
                        embyflow_local_v3_scan(root, scan_mode) or []
                    )

                    for raw in entries:
                        if not isinstance(raw, dict):
                            continue
                        entry = dict(raw)
                        entry_path = os.path.realpath(
                            str(entry.get("path") or "")
                        )

                        if child_roots and any(
                            _embyflow_local_all_media_is_within_v1(
                                entry_path, child
                            )
                            for child in child_roots
                        ):
                            continue

                        if entry.get("kind") == "series":
                            episodes = []
                            for episode_raw in list(
                                entry.get("episodes") or []
                            ):
                                if not isinstance(episode_raw, dict):
                                    continue
                                episode = dict(episode_raw)
                                episode_path = os.path.realpath(
                                    str(episode.get("path") or "")
                                )
                                if episode_path in seen_series_episode_paths:
                                    continue
                                seen_series_episode_paths.add(episode_path)
                                meta = str(episode.get("meta") or "")
                                episode["meta"] = (
                                    source_name
                                    + (" · " + meta if meta else "")
                                )
                                episodes.append(episode)

                            if not episodes:
                                continue

                            entry["episodes"] = episodes
                            entry["path"] = str(
                                episodes[0].get("path")
                                or entry.get("path")
                                or ""
                            )
                            entry["mtime"] = max(
                                [
                                    float(ep.get("mtime") or 0.0)
                                    for ep in episodes
                                ]
                                or [0.0]
                            )
                            entry["meta"] = "%s · %d Episode%s" % (
                                source_name,
                                len(episodes),
                                "" if len(episodes) == 1 else "n",
                            )
                            combined.append(entry)
                            continue

                        if not entry_path:
                            continue
                        if entry_path in seen_movie_paths:
                            continue
                        seen_movie_paths.add(entry_path)

                        if mode == "recordings":
                            # Dadurch zeigt die vorhandene Bibliothekskarte
                            # den Badge AUFNAHME statt FILM.
                            entry["kind"] = "episode"

                        old_meta = str(entry.get("meta") or "")
                        entry["meta"] = (
                            source_name
                            + (" · " + old_meta if old_meta else "")
                        )
                        combined.append(entry)

                combined.sort(
                    key=lambda item: (
                        -float((item or {}).get("mtime") or 0.0),
                        str((item or {}).get("title") or "").casefold(),
                    )
                )

                result = {
                    "ok": True,
                    "entries": combined,
                    "generation": generation,
                }
            except Exception as error:
                result = {
                    "ok": False,
                    "entries": [],
                    "generation": generation,
                    "error": str(error),
                }

            if (
                not self.closed_local_library_v3
                and generation == self.scan_generation
            ):
                self.scan_result = result

        thread = _all_media_threading_v1.Thread(
            target=worker,
            name="EmbyFlowAllMediaScanV1",
        )
        thread.daemon = True
        thread.start()
        self.scan_timer.start(100, False)


def _embyflow_local_all_media_refresh_v1(screen):
    real_sources = list(getattr(screen, "sources", []) or [])

    if not real_sources:
        return _EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_REFRESH_V1(screen)

    virtual = _embyflow_local_all_media_virtual_source_v1(screen)
    virtual_index = len(real_sources)
    source_status = getattr(screen, "source_status", None)
    had_virtual_status = (
        isinstance(source_status, dict)
        and EMBYFLOW_LOCAL_ALL_MEDIA_ID_V1 in source_status
    )
    old_virtual_status = (
        source_status.get(EMBYFLOW_LOCAL_ALL_MEDIA_ID_V1)
        if had_virtual_status
        else None
    )

    try:
        # Nur waehrend des Renderns anhaengen. Die persistente Quellenliste
        # und alle Scanner sehen weiterhin ausschliesslich echte Quellen.
        screen.sources = real_sources + [virtual]
        if isinstance(screen.source_status, dict):
            screen.source_status[EMBYFLOW_LOCAL_ALL_MEDIA_ID_V1] = True

        _EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_REFRESH_V1(screen)

        slot = virtual_index - int(getattr(screen, "card_offset", 0) or 0)
        if 0 <= slot < 5:
            screen["card_name%d" % slot].setText("Alle Medien")
            screen["card_type%d" % slot].setText("Übersicht")
            screen["card_path%d" % slot].setText(
                "%d Quelle%s"
                % (
                    len(real_sources),
                    "" if len(real_sources) == 1 else "n",
                )
            )
            screen["card_state%d" % slot].setText("Bereit")

            try:
                screen._set_text_color(
                    "card_type%d" % slot,
                    "#A05BF5",
                )
                screen._set_text_color(
                    "card_state%d" % slot,
                    "#53D769",
                )
            except Exception:
                pass

            # "Alle Medien" ist eine Funktion, keine verwaltbare Quelle.
            # Darum bleibt die korrespondierende Zeile rechts leer.
            for widget_name in (
                "mgr_name%d" % slot,
                "mgr_path%d" % slot,
                "mgr_type%d" % slot,
                "mgr_state%d" % slot,
            ):
                try:
                    screen[widget_name].setText("")
                except Exception:
                    pass
            try:
                screen["mgr_icon%d" % slot].hide()
                if screen["mgr_icon%d" % slot].instance:
                    screen["mgr_icon%d" % slot].instance.hide()
                screen._set_bg_color(
                    "mgr_bg%d" % slot,
                    "#0A1C30",
                )
            except Exception:
                pass

        if _embyflow_local_all_media_selected_v1(screen):
            screen["manager_hint"].setText(
                "Alle Medien · %d Quelle%s"
                % (
                    len(real_sources),
                    "" if len(real_sources) == 1 else "n",
                )
            )
            screen["status"].setText(
                "OK öffnet alle eingerichteten Medienquellen gemeinsam."
            )
        else:
            selected = int(
                getattr(screen, "selected_index", 0) or 0
            )
            if 0 <= selected < len(real_sources):
                screen["manager_hint"].setText(
                    "Quelle %d von %d"
                    % (selected + 1, len(real_sources))
                )

    finally:
        screen.sources = real_sources
        if isinstance(getattr(screen, "source_status", None), dict):
            if had_virtual_status:
                screen.source_status[
                    EMBYFLOW_LOCAL_ALL_MEDIA_ID_V1
                ] = old_virtual_status
            else:
                screen.source_status.pop(
                    EMBYFLOW_LOCAL_ALL_MEDIA_ID_V1,
                    None,
                )


def _embyflow_local_all_media_move_left_v1(screen):
    zone = str(
        getattr(screen, "focus_zone_v17", "cards") or "cards"
    )
    real_sources = list(getattr(screen, "sources", []) or [])

    if zone == "cards" and real_sources:
        total = len(real_sources) + 1
        current = int(
            getattr(screen, "selected_index", 0) or 0
        )
        screen.selected_index = (current - 1) % total
        screen.refresh()
        return

    return _EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_MOVE_LEFT_V1(screen)


def _embyflow_local_all_media_move_right_v1(screen):
    zone = str(
        getattr(screen, "focus_zone_v17", "cards") or "cards"
    )
    real_sources = list(getattr(screen, "sources", []) or [])

    if zone == "cards" and real_sources:
        total = len(real_sources) + 1
        current = int(
            getattr(screen, "selected_index", 0) or 0
        )
        screen.selected_index = (current + 1) % total
        screen.refresh()
        return

    return _EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_MOVE_RIGHT_V1(screen)


def _embyflow_local_all_media_move_down_v1(screen):
    # Die virtuelle Uebersicht darf nicht in "Quelle bearbeiten/entfernen"
    # wechseln, weil sie keine persistente Quelle ist.
    if _embyflow_local_all_media_selected_v1(screen):
        screen.refresh()
        return

    return _EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_MOVE_DOWN_V1(screen)


def _embyflow_local_all_media_open_v1(screen):
    zone = str(
        getattr(screen, "focus_zone_v17", "cards") or "cards"
    )

    if zone == "cards" and _embyflow_local_all_media_selected_v1(screen):
        snapshot = [
            dict(source)
            for source in list(getattr(screen, "sources", []) or [])
            if isinstance(source, dict)
        ]
        screen.session.open(
            EmbyFlowAllMediaLibraryScreenV1,
            snapshot,
        )
        return

    return _EMBYFLOW_LOCAL_ALL_MEDIA_ORIG_OPEN_V1(screen)


EmbyFlowLocalSourcesScreenV17.refresh = _embyflow_local_all_media_refresh_v1
EmbyFlowLocalSourcesScreenV17.move_left = _embyflow_local_all_media_move_left_v1
EmbyFlowLocalSourcesScreenV17.move_right = _embyflow_local_all_media_move_right_v1
EmbyFlowLocalSourcesScreenV17.move_down = _embyflow_local_all_media_move_down_v1
EmbyFlowLocalSourcesScreenV17.open_selected = _embyflow_local_all_media_open_v1

# EMBYFLOW_LOCAL_ALL_MEDIA_TILE_V1_END

# EMBYFLOW_RECORDINGS_BRIDGE_V1_START
#
# RC2.1 enthält bereits:
# - Enigma2 .meta/.eit/.cuts Parser
# - Senderauflösung über ServiceRef
# - Aufnahme-Detailansicht
# - Vorschaubilder über den V10-Thumbnailpfad
# - Live-Aufnahme-Markierung
#
# Es fehlte nur die direkte Verdrahtung:
# Quelle mode="recordings" -> EmbyFlowLocalEpisodesScreenV7.
#
# Dieser Patch hängt sich bewusst AN die aktuell registrierte
# EmbyFlowLocalSourcesScreenV17.open_selected()-Methode, damit spätere/unsere
# vorhandenen Erweiterungen (z.B. "Alle Medien") erhalten bleiben.

EMBYFLOW_RECORDINGS_BRIDGE_LOG_V1 = "/tmp/embyflow_recordings_bridge_v1.log"

_EMBYFLOW_RECORDINGS_BRIDGE_ORIGINAL_OPEN_SELECTED_V1 = (
    EmbyFlowLocalSourcesScreenV17.open_selected
)


def _embyflow_recordings_bridge_log_v1(message):
    try:
        with embyflow_open_log(
            EMBYFLOW_RECORDINGS_BRIDGE_LOG_V1,
            "a",
        ) as handle:
            handle.write(
                "%s | %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_recordings_bridge_raw_entries_v1(root_path):
    root = os.path.realpath(str(root_path or ""))
    result = []

    if not root or not os.path.isdir(root):
        return result

    try:
        for item in list(
            embyflow_local_v3_video_files(root)
            or []
        ):
            if not isinstance(item, dict):
                continue

            path = os.path.realpath(
                str(item.get("path") or "")
            )

            if not path or not os.path.isfile(path):
                continue

            entry = dict(item)
            entry["path"] = path
            result.append(entry)

    except Exception as error:
        _embyflow_recordings_bridge_log_v1(
            "SCAN_ERROR root=%s error=%s"
            % (root, str(error))
        )

    result.sort(
        key=lambda entry: (
            -float(entry.get("mtime") or 0.0),
            str(entry.get("path") or "").casefold(),
        )
    )

    return result


class EmbyFlowRecordingsScreenV1(
    EmbyFlowLocalEpisodesScreenV7
):
    # Das bestehende V10/V17-Aufnahmelayout bleibt die Basis.
    # Nur die statische Serien-Beschriftung wird für diesen generischen
    # Aufnahmeordner passend benannt.
    try:
        skin = str(
            EmbyFlowLocalEpisodesScreenV7.skin
            or ""
        ).replace(
            'text="Lokales Serienposter"',
            'text="Aufnahme-Vorschau"',
        ).replace(
            'text="Serienposter"',
            'text="Aufnahme-Vorschau"',
        )
    except Exception:
        skin = EmbyFlowLocalEpisodesScreenV7.skin

    def __init__(
        self,
        session,
        root_path,
        title="Aufnahmen",
    ):
        self.recordings_bridge_root_v1 = (
            os.path.realpath(
                str(root_path or "/media/hdd/movie")
            )
        )

        raw_entries = (
            _embyflow_recordings_bridge_raw_entries_v1(
                self.recordings_bridge_root_v1
            )
        )

        _embyflow_recordings_bridge_log_v1(
            "OPEN root=%s entries=%d ffmpeg=%s"
            % (
                self.recordings_bridge_root_v1,
                len(raw_entries),
                "yes"
                if os.path.isfile("/usr/bin/ffmpeg")
                else "no",
            )
        )

        EmbyFlowLocalEpisodesScreenV7.__init__(
            self,
            session,
            self.recordings_bridge_root_v1,
            str(title or "Aufnahmen"),
            raw_entries,
            "",
        )

        # Bei generischen Aufnahmen ist "SERIE" im Detail-Fallback falsch.
        try:
            self["detail_poster_fallback"].setText(
                "AUFNAHME"
            )
        except Exception:
            pass

    def reload(self):
        if getattr(self, "loading", False):
            return

        self.raw_entries = (
            _embyflow_recordings_bridge_raw_entries_v1(
                self.recordings_bridge_root_v1
            )
        )

        _embyflow_recordings_bridge_log_v1(
            "RELOAD root=%s entries=%d"
            % (
                self.recordings_bridge_root_v1,
                len(self.raw_entries),
            )
        )

        self.start_load(
            preserve_selection=True
        )


def _embyflow_recordings_bridge_open_selected_v1(
    screen
):
    try:
        zone = str(
            getattr(
                screen,
                "focus_zone_v17",
                "cards",
            )
            or "cards"
        )

        if zone == "cards":
            source = screen.current_source()

            if isinstance(source, dict):
                mode = str(
                    source.get("mode")
                    or ""
                ).strip().casefold()

                if mode == "recordings":
                    source_id = str(
                        source.get("id")
                        or ""
                    )

                    # Gleicher Erreichbarkeitscheck wie im V16-Basiscode.
                    if (
                        source_id
                        and getattr(
                            screen,
                            "source_status",
                            {},
                        ).get(source_id)
                        is not True
                    ):
                        screen.session.open(
                            MessageBox,
                            (
                                "Die Medienquelle ist aktuell "
                                "nicht erreichbar:\n\n%s"
                            )
                            % str(
                                source.get("path")
                                or ""
                            ),
                            MessageBox.TYPE_INFO,
                            timeout=6,
                        )
                        return

                    path = os.path.realpath(
                        str(
                            source.get("path")
                            or "/media/hdd/movie"
                        )
                    )
                    name = str(
                        source.get("name")
                        or "Aufnahmen"
                    )

                    screen.session.open(
                        EmbyFlowRecordingsScreenV1,
                        path,
                        name,
                    )
                    return

    except Exception as error:
        _embyflow_recordings_bridge_log_v1(
            "OPEN_BRIDGE_ERROR %s"
            % str(error)
        )

    # Alle anderen Quellen und unsere sonstigen Erweiterungen unverändert.
    return (
        _EMBYFLOW_RECORDINGS_BRIDGE_ORIGINAL_OPEN_SELECTED_V1(
            screen
        )
    )


EmbyFlowLocalSourcesScreenV17.open_selected = (
    _embyflow_recordings_bridge_open_selected_v1
)


# Optional: Falls unsere virtuelle "Alle Medien"-Kachel bereits installiert ist,
# werden Aufnahmen dort ebenfalls mit .meta/.eit angereichert.
# Die Kachel bleibt weiterhin die einfache Sammelansicht; der vollständige
# Detail-/Thumbnail-Workflow liegt in der echten Quelle "Aufnahmen".
if "EmbyFlowAllMediaLibraryScreenV1" in globals():
    try:
        _EMBYFLOW_RECORDINGS_BRIDGE_ALL_MEDIA_POLL_V1 = (
            EmbyFlowAllMediaLibraryScreenV1.poll_scan
        )

        def _embyflow_recordings_bridge_all_media_poll_v1(
            screen
        ):
            had_result = (
                getattr(screen, "scan_result", None)
                is not None
            )

            result = (
                _EMBYFLOW_RECORDINGS_BRIDGE_ALL_MEDIA_POLL_V1(
                    screen
                )
            )

            if (
                not had_result
                or getattr(
                    screen,
                    "scan_loading",
                    False,
                )
            ):
                return result

            try:
                resume_map = (
                    load_embyflow_local_resume()
                )
            except Exception:
                resume_map = {}

            changed = False
            enriched = []

            for raw in list(
                getattr(screen, "entries", [])
                or []
            ):
                if not isinstance(raw, dict):
                    enriched.append(raw)
                    continue

                entry = dict(raw)

                if (
                    str(
                        entry.get("kind")
                        or ""
                    ).casefold()
                    == "episode"
                ):
                    try:
                        prepared = (
                            embyflow_local_v7_prepare_episode(
                                entry,
                                "Aufnahmen",
                                resume_map,
                            )
                        )

                        sender = (
                            embyflow_local_v12_recording_source(
                                prepared
                            )
                        )

                        entry.update(prepared)
                        entry["kind"] = "episode"
                        entry["title"] = str(
                            prepared.get(
                                "display_title"
                            )
                            or entry.get("title")
                            or "Aufnahme"
                        )

                        meta_parts = []

                        if (
                            sender
                            and sender != "Unbekannt"
                        ):
                            meta_parts.append(sender)

                        date_text = str(
                            prepared.get("date_text")
                            or ""
                        )
                        if date_text:
                            meta_parts.append(date_text)

                        size_text = str(
                            prepared.get("size_text")
                            or ""
                        )
                        if size_text:
                            meta_parts.append(size_text)

                        entry["meta"] = (
                            " · ".join(meta_parts)
                        )

                        try:
                            cached_thumb = (
                                embyflow_local_v10_cached_thumb(
                                    prepared
                                )
                            )
                            if cached_thumb:
                                entry["poster"] = (
                                    cached_thumb
                                )
                        except Exception:
                            pass

                        changed = True

                    except Exception:
                        pass

                enriched.append(entry)

            if changed:
                screen.entries = enriched
                screen.refresh()

            return result

        EmbyFlowAllMediaLibraryScreenV1.poll_scan = (
            _embyflow_recordings_bridge_all_media_poll_v1
        )

    except Exception as error:
        _embyflow_recordings_bridge_log_v1(
            "ALL_MEDIA_HOOK_ERROR %s"
            % str(error)
        )

# EMBYFLOW_RECORDINGS_BRIDGE_V1_END

# EMBYFLOW_RECORDINGS_BRIDGE_V2_START
#
# V2 ersetzt nur den Eintritt in die Aufnahmequelle.
#
# Ursache V1:
# session.open(EmbyFlowRecordingsScreenV1, ...) lag in einem grossen try/except.
# Falls die eigene V1-Unterklasse beim Konstruieren scheiterte, fiel der Code
# anschliessend unbemerkt auf den alten Originalpfad zurueck -> Filmansicht.
#
# V2:
# - benutzt DIREKT die bereits bewaehrte EmbyFlowLocalEpisodesScreenV7
# - kein eigener Skin / keine eigene Unterklasse
# - kein stiller Fallback auf "movies"
# - schreibt einen simplen /tmp-Log mit Python built-in open()
# - Blau liest /media/hdd/movie wirklich neu ein
# - .meta/.eit/.cuts + V10/V12/V17 bleiben dadurch voll aktiv

EMBYFLOW_RECORDINGS_BRIDGE_LOG_V2 = (
    "/tmp/embyflow_recordings_bridge_v2.log"
)

_EMBYFLOW_RECORDINGS_BRIDGE_V2_PREVIOUS_OPEN = (
    EmbyFlowLocalSourcesScreenV17.open_selected
)

_EMBYFLOW_RECORDINGS_BRIDGE_V2_ORIGINAL_EPISODE_RELOAD = (
    EmbyFlowLocalEpisodesScreenV7.reload
)


def _embyflow_recordings_bridge_log_v2(message):
    try:
        with open(
            EMBYFLOW_RECORDINGS_BRIDGE_LOG_V2,
            "a",
            encoding="utf-8",
        ) as handle:
            handle.write(
                "%s | %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_recordings_bridge_scan_v2(root_path):
    root = os.path.realpath(
        str(root_path or "/media/hdd/movie")
    )
    values = []

    if not os.path.isdir(root):
        return values

    for raw in list(
        embyflow_local_v3_video_files(root)
        or []
    ):
        if not isinstance(raw, dict):
            continue

        path = os.path.realpath(
            str(raw.get("path") or "")
        )

        if not path or not os.path.isfile(path):
            continue

        item = dict(raw)
        item["path"] = path
        values.append(item)

    values.sort(
        key=lambda entry: (
            -float(entry.get("mtime") or 0.0),
            str(entry.get("path") or "").casefold(),
        )
    )

    return values


def _embyflow_recordings_bridge_episode_reload_v2(screen):
    root = str(
        getattr(
            screen,
            "embyflow_recordings_bridge_root_v2",
            "",
        )
        or ""
    )

    if not root:
        return (
            _EMBYFLOW_RECORDINGS_BRIDGE_V2_ORIGINAL_EPISODE_RELOAD(
                screen
            )
        )

    if getattr(screen, "loading", False):
        return

    try:
        selected = screen.selected_entry() or {}
        selected_path = str(
            selected.get("path") or ""
        )
    except Exception:
        selected_path = ""

    try:
        screen.raw_entries = (
            _embyflow_recordings_bridge_scan_v2(root)
        )

        _embyflow_recordings_bridge_log_v2(
            "RELOAD root=%s entries=%d"
            % (
                root,
                len(screen.raw_entries),
            )
        )

        screen.start_load(
            preserve_selection=bool(selected_path)
        )

    except Exception as error:
        _embyflow_recordings_bridge_log_v2(
            "RELOAD_ERROR root=%s error=%r"
            % (
                root,
                error,
            )
        )

        try:
            screen.session.open(
                MessageBox,
                (
                    "Aufnahmen konnten nicht neu "
                    "eingelesen werden:\n\n%s"
                )
                % str(error),
                MessageBox.TYPE_ERROR,
                timeout=8,
            )
        except Exception:
            pass


def _embyflow_recordings_bridge_open_v2(screen):
    zone = str(
        getattr(
            screen,
            "focus_zone_v17",
            "cards",
        )
        or "cards"
    )

    source = None
    mode = ""

    if zone == "cards":
        try:
            source = screen.current_source()
        except Exception:
            source = None

        if isinstance(source, dict):
            mode = str(
                source.get("mode")
                or ""
            ).strip().casefold()

    _embyflow_recordings_bridge_log_v2(
        "CLICK zone=%s mode=%s name=%s path=%s"
        % (
            zone,
            mode,
            str(
                (source or {}).get("name")
                if isinstance(source, dict)
                else ""
            ),
            str(
                (source or {}).get("path")
                if isinstance(source, dict)
                else ""
            ),
        )
    )

    if zone != "cards" or mode != "recordings":
        return (
            _EMBYFLOW_RECORDINGS_BRIDGE_V2_PREVIOUS_OPEN(
                screen
            )
        )

    path = os.path.realpath(
        str(
            source.get("path")
            or "/media/hdd/movie"
        )
    )
    name = str(
        source.get("name")
        or "Aufnahmen"
    )

    if not os.path.isdir(path):
        _embyflow_recordings_bridge_log_v2(
            "OPEN_BLOCKED path_missing=%s"
            % path
        )

        screen.session.open(
            MessageBox,
            (
                "Der Aufnahmeordner ist nicht "
                "verfügbar:\n\n%s"
            )
            % path,
            MessageBox.TYPE_ERROR,
            timeout=7,
        )
        return

    try:
        raw_entries = (
            _embyflow_recordings_bridge_scan_v2(path)
        )
    except Exception as error:
        _embyflow_recordings_bridge_log_v2(
            "SCAN_ERROR path=%s error=%r"
            % (
                path,
                error,
            )
        )
        raw_entries = []

    _embyflow_recordings_bridge_log_v2(
        "OPEN_TRY path=%s entries=%d ffmpeg=%s"
        % (
            path,
            len(raw_entries),
            "yes"
            if os.path.isfile("/usr/bin/ffmpeg")
            else "no",
        )
    )

    try:
        # WICHTIG:
        # Keine eigene Unterklasse. Direkt die existierende Aufnahmeansicht,
        # die bereits META/EIT/CUTS, V10-Thumbnails, V12-Sender und V17-Live
        # besitzt.
        dialog = screen.session.open(
            EmbyFlowLocalEpisodesScreenV7,
            path,
            name,
            raw_entries,
            "",
        )

        try:
            dialog.embyflow_recordings_bridge_root_v2 = path
        except Exception:
            pass

        try:
            dialog["detail_poster_fallback"].setText(
                "AUFNAHME"
            )
        except Exception:
            pass

        _embyflow_recordings_bridge_log_v2(
            "OPEN_OK path=%s entries=%d"
            % (
                path,
                len(raw_entries),
            )
        )
        return

    except Exception as error:
        # V2 faellt absichtlich NICHT auf die Filmansicht zurueck.
        # So wird ein echter Fehler sichtbar und kann nicht mehr kaschiert werden.
        _embyflow_recordings_bridge_log_v2(
            "OPEN_ERROR path=%s error=%r"
            % (
                path,
                error,
            )
        )

        try:
            screen.session.open(
                MessageBox,
                (
                    "Die Aufnahmeansicht konnte "
                    "nicht geöffnet werden:\n\n%s"
                    "\n\nDetails: %s"
                )
                % (
                    path,
                    str(error),
                ),
                MessageBox.TYPE_ERROR,
                timeout=10,
            )
        except Exception:
            pass

        return


EmbyFlowLocalEpisodesScreenV7.reload = (
    _embyflow_recordings_bridge_episode_reload_v2
)

EmbyFlowLocalSourcesScreenV17.open_selected = (
    _embyflow_recordings_bridge_open_v2
)

# EMBYFLOW_RECORDINGS_BRIDGE_V2_END

# EMBYFLOW_RECORDINGS_BRIDGE_V3_START
#
# Ursache auf der Testbox:
# - Quelle "Aufnahmen" zeigte auf /media/hdd/movie
# - dieser Ordner existiert, ist aber leer
# - reale Enigma2-Aufnahmen liegen z.B. in:
#     /media/usb/Filme
#     /media/usb/Serien/...
#
# V3 macht "Aufnahmen" deshalb zu einer logischen Sammelansicht:
# - scannt alle aktiv konfigurierten lokalen Medienwurzeln
# - reduziert ueberlappende Wurzeln (z.B. /media/usb deckt Filme/Serien ab)
# - nimmt NUR echte Enigma2-Aufnahmen mit .meta/.eit bzw.
#   klassischem Enigma2-Aufnahmedateinamen
# - dedupliziert identische Dateien
# - setzt einen gemeinsamen sicheren Playback-Root
# - Blau scannt dieselben Wurzeln erneut

EMBYFLOW_RECORDINGS_BRIDGE_LOG_V3 = (
    "/tmp/embyflow_recordings_bridge_v3.log"
)

_EMBYFLOW_RECORDINGS_BRIDGE_V3_PREVIOUS_OPEN = (
    EmbyFlowLocalSourcesScreenV17.open_selected
)

_EMBYFLOW_RECORDINGS_BRIDGE_V3_PREVIOUS_RELOAD = (
    EmbyFlowLocalEpisodesScreenV7.reload
)


def _embyflow_recordings_bridge_log_v3(message):
    try:
        with open(
            EMBYFLOW_RECORDINGS_BRIDGE_LOG_V3,
            "a",
            encoding="utf-8",
        ) as handle:
            handle.write(
                "%s | %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_recordings_bridge_within_v3(path, root):
    try:
        p = os.path.realpath(str(path or ""))
        r = os.path.realpath(str(root or "")).rstrip(os.sep)
        return bool(
            p
            and r
            and (
                p == r
                or p.startswith(r + os.sep)
            )
        )
    except Exception:
        return False


def _embyflow_recordings_bridge_roots_v3(source=None):
    roots = []

    def add(path):
        try:
            real = os.path.realpath(str(path or ""))
        except Exception:
            return
        if (
            real
            and os.path.isdir(real)
            and real not in roots
        ):
            roots.append(real)

    # Der konfigurierte Aufnahmeweg bleibt Kandidat, falls er spaeter
    # tatsaechlich benutzt wird.
    if isinstance(source, dict):
        add(source.get("path"))

    try:
        sources = list(
            _embyflow_v16_load_sources()
            or []
        )
    except Exception:
        sources = []

    for item in sources:
        if not isinstance(item, dict):
            continue
        if item.get("enabled", True) is False:
            continue
        mode = str(
            item.get("mode") or ""
        ).strip().casefold()
        if mode == "recordings":
            continue
        add(item.get("path"))

    # Breitere Roots gewinnen. Beispiel:
    # /media/usb deckt /media/usb/Filme und /media/usb/Serien bereits ab.
    ordered = sorted(
        roots,
        key=lambda value: (
            value.count(os.sep),
            len(value),
            value.casefold(),
        ),
    )
    reduced = []

    for root in ordered:
        if any(
            _embyflow_recordings_bridge_within_v3(
                root,
                existing,
            )
            for existing in reduced
        ):
            continue
        reduced.append(root)

    return reduced


def _embyflow_recordings_bridge_is_recording_v3(path):
    file_path = os.path.realpath(
        str(path or "")
    )

    if not file_path or not os.path.isfile(file_path):
        return False

    # Enigma2 legt bei normalen Aufnahmen typischerweise .meta an:
    # <aufnahme>.ts.meta
    for candidate in (
        file_path + ".meta",
        os.path.splitext(file_path)[0] + ".meta",
    ):
        if os.path.isfile(candidate):
            return True

    # EIT kann je nach Image als <stem>.eit oder <video>.eit vorkommen.
    try:
        for candidate in (
            embyflow_local_v7_eit_candidates(file_path)
            or []
        ):
            if os.path.isfile(candidate):
                return True
    except Exception:
        pass

    # Letzter Fallback fuer laufende/ungewoehnliche Aufnahmen:
    # YYYYMMDD HHMM - Sender - Titel.ext
    try:
        name = os.path.basename(file_path)
        if re.match(
            r"^\d{8}\s+\d{4}\s*-\s*.+?\s*-\s*.+\.[^.]+$",
            name,
        ):
            return True
    except Exception:
        pass

    return False


def _embyflow_recordings_bridge_scan_roots_v3(roots):
    result = []
    seen = set()
    scanned_videos = 0

    for root in list(roots or []):
        if not os.path.isdir(root):
            continue

        try:
            files = list(
                embyflow_local_v3_video_files(root)
                or []
            )
        except Exception as error:
            _embyflow_recordings_bridge_log_v3(
                "ROOT_SCAN_ERROR root=%s error=%r"
                % (
                    root,
                    error,
                )
            )
            continue

        scanned_videos += len(files)

        for raw in files:
            if not isinstance(raw, dict):
                continue

            path = os.path.realpath(
                str(raw.get("path") or "")
            )

            if (
                not path
                or path in seen
                or not _embyflow_recordings_bridge_is_recording_v3(
                    path
                )
            ):
                continue

            seen.add(path)
            entry = dict(raw)
            entry["path"] = path
            entry["recording_root"] = root
            result.append(entry)

    result.sort(
        key=lambda entry: (
            -float(entry.get("mtime") or 0.0),
            str(entry.get("path") or "").casefold(),
        )
    )

    _embyflow_recordings_bridge_log_v3(
        "SCAN roots=%d videos=%d recordings=%d"
        % (
            len(list(roots or [])),
            scanned_videos,
            len(result),
        )
    )

    return result


def _embyflow_recordings_bridge_playback_root_v3(
    entries,
    roots,
):
    candidates = []

    for entry in list(entries or []):
        if not isinstance(entry, dict):
            continue
        path = os.path.realpath(
            str(entry.get("path") or "")
        )
        if path:
            candidates.append(
                os.path.dirname(path)
            )

    if not candidates:
        candidates = [
            os.path.realpath(str(root or ""))
            for root in list(roots or [])
            if root
        ]

    if not candidates:
        return "/media"

    try:
        common = os.path.commonpath(candidates)
    except Exception:
        common = "/media"

    common = os.path.realpath(
        str(common or "/media")
    )

    # Niemals / als lokalen Playback-Root benutzen.
    if common == "/":
        common = "/media"

    return common


def _embyflow_recordings_bridge_reload_v3(screen):
    roots = list(
        getattr(
            screen,
            "embyflow_recording_roots_v3",
            [],
        )
        or []
    )

    if not roots:
        return (
            _EMBYFLOW_RECORDINGS_BRIDGE_V3_PREVIOUS_RELOAD(
                screen
            )
        )

    if getattr(screen, "loading", False):
        return

    try:
        screen.raw_entries = (
            _embyflow_recordings_bridge_scan_roots_v3(
                roots
            )
        )

        _embyflow_recordings_bridge_log_v3(
            "RELOAD recordings=%d"
            % len(screen.raw_entries)
        )

        screen.start_load(
            preserve_selection=True
        )

    except Exception as error:
        _embyflow_recordings_bridge_log_v3(
            "RELOAD_ERROR error=%r"
            % error
        )

        try:
            screen.session.open(
                MessageBox,
                (
                    "Aufnahmen konnten nicht "
                    "neu eingelesen werden:\n\n%s"
                )
                % str(error),
                MessageBox.TYPE_ERROR,
                timeout=8,
            )
        except Exception:
            pass


def _embyflow_recordings_bridge_open_v3(screen):
    zone = str(
        getattr(
            screen,
            "focus_zone_v17",
            "cards",
        )
        or "cards"
    )

    source = None
    mode = ""

    if zone == "cards":
        try:
            source = screen.current_source()
        except Exception:
            source = None

        if isinstance(source, dict):
            mode = str(
                source.get("mode") or ""
            ).strip().casefold()

    if zone != "cards" or mode != "recordings":
        return (
            _EMBYFLOW_RECORDINGS_BRIDGE_V3_PREVIOUS_OPEN(
                screen
            )
        )

    name = str(
        source.get("name")
        or "Aufnahmen"
    )

    roots = (
        _embyflow_recordings_bridge_roots_v3(
            source
        )
    )
    entries = (
        _embyflow_recordings_bridge_scan_roots_v3(
            roots
        )
    )
    playback_root = (
        _embyflow_recordings_bridge_playback_root_v3(
            entries,
            roots,
        )
    )

    _embyflow_recordings_bridge_log_v3(
        "OPEN name=%s roots=%s playback_root=%s recordings=%d ffmpeg=%s"
        % (
            name,
            repr(roots),
            playback_root,
            len(entries),
            "yes"
            if os.path.isfile("/usr/bin/ffmpeg")
            else "no",
        )
    )

    try:
        dialog = screen.session.open(
            EmbyFlowLocalEpisodesScreenV7,
            playback_root,
            name,
            entries,
            "",
        )

        try:
            dialog.embyflow_recording_roots_v3 = list(
                roots
            )
        except Exception:
            pass

        # Der komplette Metadaten-/Thumbnailpfad wird von der vorhandenen
        # Aufnahmeansicht ausgefuehrt. Keine Filmansicht als Fallback.
        return

    except Exception as error:
        _embyflow_recordings_bridge_log_v3(
            "OPEN_ERROR error=%r"
            % error
        )

        try:
            screen.session.open(
                MessageBox,
                (
                    "Die Aufnahmeansicht konnte "
                    "nicht geöffnet werden:\n\n%s"
                )
                % str(error),
                MessageBox.TYPE_ERROR,
                timeout=10,
            )
        except Exception:
            pass

        return


EmbyFlowLocalEpisodesScreenV7.reload = (
    _embyflow_recordings_bridge_reload_v3
)

EmbyFlowLocalSourcesScreenV17.open_selected = (
    _embyflow_recordings_bridge_open_v3
)

# EMBYFLOW_RECORDINGS_BRIDGE_V3_END

# EMBYFLOW_RECORDING_TITLE_CLIPFIX_V1

# EMBYFLOW_RECORDING_PIPE_SANITIZER_V1_START
#
# Manche DVB-EIT-Kurztexte enthalten z.B.:
#   "Tatort: Borowski und das ewige Meer || Deutschland ..."
#
# V7 verwendet einen vom Eventnamen abweichenden Kurztext als display_title.
# Dadurch landet der technische/inhaltliche Zusatz hinter "||" auf der Karte.
#
# Release-sicherer Fix:
# - nur display_title anfassen
# - nur bei ZWEI ODER MEHR ASCII-Pipes
# - alles links von || bleibt erhalten
# - Sender, EIT/META, Beschreibung, Genre, Laufzeit, Playback,
#   Thumbnail und Fortschritt bleiben unveraendert.

_EMBYFLOW_RECORDING_PIPE_SANITIZER_ORIGINAL_PREPARE_V1 = (
    embyflow_local_v7_prepare_episode
)


def _embyflow_recording_pipe_sanitize_title_v1(value):
    try:
        text = str(value or "")
        if not text:
            return text

        match = re.search(r"\s*\|{2,}\s*", text)
        if not match:
            return text

        cleaned = text[:match.start()].strip()
        return cleaned or text

    except Exception:
        return str(value or "")


def _embyflow_recording_pipe_prepare_v1(
    raw_entry,
    series_title,
    resume_map,
):
    entry = _EMBYFLOW_RECORDING_PIPE_SANITIZER_ORIGINAL_PREPARE_V1(
        raw_entry,
        series_title,
        resume_map,
    )

    if not isinstance(entry, dict):
        return entry

    original_title = str(
        entry.get("display_title") or ""
    )
    cleaned_title = (
        _embyflow_recording_pipe_sanitize_title_v1(
            original_title
        )
    )

    if cleaned_title != original_title:
        entry["display_title"] = cleaned_title

    return entry


embyflow_local_v7_prepare_episode = (
    _embyflow_recording_pipe_prepare_v1
)

# EMBYFLOW_RECORDING_PIPE_SANITIZER_V1_END

# EMBYFLOW_RECORDING_EIT_BOXSEPARATOR_V1_START
#
# Reales DVB-EIT-Beispiel:
# event_name:
#   Tatort: Borowski und das ewige Meer
# short_text:
#   Tatort: Borowski und das ewige Meer ║ Deutschland ║ 2024 ║ 12
#
# Der sichtbare Kartentitel soll in diesem Fall der event_name bleiben.
#
# Sicherheitsregel:
# - nur wenn display_title das Zeichen ║ (U+2551) enthält
# - UND der Teil links vom ersten ║ exakt series_name/event_name entspricht
# - dann wird nur display_title auf den sauberen Eventnamen gesetzt
# - sonst KEINE Änderung

_EMBYFLOW_RECORDING_EIT_BOXSEPARATOR_PREPARE_V1 = (
    embyflow_local_v7_prepare_episode
)


def _embyflow_recording_eit_boxseparator_prepare_v1(
    raw_entry,
    series_title,
    resume_map,
):
    entry = _EMBYFLOW_RECORDING_EIT_BOXSEPARATOR_PREPARE_V1(
        raw_entry,
        series_title,
        resume_map,
    )

    if not isinstance(entry, dict):
        return entry

    display_title = str(
        entry.get("display_title") or ""
    ).strip()

    event_name = str(
        entry.get("series_name") or ""
    ).strip()

    if "║" not in display_title or not event_name:
        return entry

    left = display_title.split("║", 1)[0].strip()

    if (
        left
        and left.casefold() == event_name.casefold()
    ):
        entry["display_title"] = event_name

    return entry


embyflow_local_v7_prepare_episode = (
    _embyflow_recording_eit_boxseparator_prepare_v1
)

# EMBYFLOW_RECORDING_EIT_BOXSEPARATOR_V1_END

