_EMBYFLOW_TATORT_DETAILPOSTER_PREV_UPDATE_DETAIL_V1 = (
    EmbyFlowLocalEpisodesScreenV7.update_detail
)


def _embyflow_tatort_detailposter_selected_v1(owner):
    try:
        entry = owner.selected_entry()
        if not isinstance(entry, dict):
            return False

        title = str(
            entry.get("display_title")
            or entry.get("title")
            or ""
        ).strip().casefold()

        if title == EMBYFLOW_TATORT_DETAILPOSTER_TITLE_V1:
            return True

        path = str(entry.get("path") or "").casefold()
        return (
            "tatort" in path
            and "borowski" in path
            and "ewige meer" in path
        )

    except Exception:
        return False


def _embyflow_tatort_detailposter_apply_v1(owner):
    if not _embyflow_tatort_detailposter_selected_v1(owner):
        return

    path = EMBYFLOW_TATORT_DETAILPOSTER_V1

    if (
        not os.path.isfile(path)
        or os.path.getsize(path) <= 500
    ):
        return

    try:
        owner["detail_poster_fallback"].hide()
        owner["detail_poster"].show()
    except Exception:
        return

    try:
        embyflow_decode_image_to_widget(
            owner,
            "detail_poster",
            path,
            180,
            270,
            token="recording-detail-tatort-borowski-v1",
            is_current=lambda: (
                not getattr(owner, "closed_v7", False)
                and _embyflow_tatort_detailposter_selected_v1(owner)
            ),
        )
    except Exception:
        pass


def _embyflow_tatort_detailposter_refresh_v1(owner):
    result = _EMBYFLOW_TATORT_DETAILPOSTER_PREV_REFRESH_V1(
        owner
    )
    _embyflow_tatort_detailposter_apply_v1(owner)
    return result


def _embyflow_tatort_detailposter_update_detail_v1(owner):
    result = (
        _EMBYFLOW_TATORT_DETAILPOSTER_PREV_UPDATE_DETAIL_V1(
            owner
        )
    )
    _embyflow_tatort_detailposter_apply_v1(owner)
    return result


