# EMBYFLOW_RECORDING_CINEMATIC_ALIGN_V3

# EMBYFLOW_RECORDING_MOVIE_REMOTE_POSTER_V1_START
_EMBYFLOW_MOVIE_REMOTE_V1_ORIGINAL_DOWNLOAD = (
    embyflow_local_v4_download_poster
)
_EMBYFLOW_MOVIE_REMOTE_V1_ORIGINAL_MISSING_PATH = (
    embyflow_local_v4_missing_path
)
_EMBYFLOW_MOVIE_REMOTE_V1_ORIGINAL_WRITE_SOURCE = (
    _cinematic_v1_write_source
)
_EMBYFLOW_MOVIE_REMOTE_V1_PROVIDER_BY_POSTER = {}


def _embyflow_movie_remote_v1_log(message):
    try:
        with open(
            "/tmp/embyflow_movie_remote_poster_v1.log",
            "a",
            encoding="utf-8",
        ) as handle:
            handle.write(
                "%s | %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_movie_remote_v1_provider_label(value):
    raw = str(value or "").strip()
    folded = raw.casefold()

    if (
        "themoviedb" in folded
        or "movie db" in folded
        or "moviedb" in folded
        or "tmdb" in folded
    ):
        return "TMDb"

    if (
        "open movie database" in folded
        or "omdb" in folded
    ):
        return "OMDb"

    return raw or "Emby Remote"


def embyflow_local_v4_missing_path(mode, title):
    # Neue Versionskennung nur fuer Filme:
    # alte negative Movie-Caches blockieren den neuen Remote-Fallback nicht.
    path = _EMBYFLOW_MOVIE_REMOTE_V1_ORIGINAL_MISSING_PATH(
        mode,
        title,
    )

    if str(mode or "") == "movies":
        return path + ".remotev1"

    return path


def _embyflow_movie_remote_v1_roots(server):
    root = str(server or "").rstrip("/")
    roots = []

    if root:
        roots.append(root)

    if root and not root.lower().endswith("/emby"):
        roots.append(root + "/emby")

    return roots


def _embyflow_movie_remote_v1_score(title, item):
    best = -1

    for candidate in (
        str(item.get("Name") or "").strip(),
        str(item.get("OriginalTitle") or "").strip(),
    ):
        if not candidate:
            continue

        try:
            score = embyflow_local_v4_candidate_score(
                title,
                {
                    "Name": candidate,
                    "ImageTags": {},
                },
            )
        except Exception:
            score = -1

        best = max(best, int(score or -1))

    return best


def _embyflow_movie_remote_v1_search(
    session,
    server,
    token,
    title,
):
    headers = {
        "X-Emby-Token": str(token or ""),
        "X-Emby-Authorization": AUTH_HEADER,
        "Accept-Encoding": "identity",
        "Content-Type": "application/json",
    }

    payload = {
        "SearchInfo": {
            "Name": str(title or "").strip(),
            "MetadataLanguage": "de",
            "MetadataCountryCode": "DE",
            "ProviderIds": {},
            "IsAutomated": True,
        },
        "IncludeDisabledProviders": True,
    }

    all_results = []

    for root in _embyflow_movie_remote_v1_roots(server):
        try:
            response = session.post(
                root + "/Items/RemoteSearch/Movie",
                headers=headers,
                json=payload,
                timeout=(5, 30),
                verify=True,
            )

            _embyflow_movie_remote_v1_log(
                "SEARCH root=%s title=%s http=%s"
                % (
                    root,
                    title,
                    response.status_code,
                )
            )

            if int(response.status_code or 0) != 200:
                continue

            data = response.json()

            if isinstance(data, list):
                all_results.extend(data)

        except Exception as error:
            _embyflow_movie_remote_v1_log(
                "SEARCH_ERROR root=%s title=%s error=%s"
                % (
                    root,
                    title,
                    error,
                )
            )

    candidates = []

    for index, item in enumerate(all_results):
        if not isinstance(item, dict):
            continue

        image_url = str(
            item.get("ImageUrl") or ""
        ).strip()

        if not image_url:
            continue

        score = _embyflow_movie_remote_v1_score(
            title,
            item,
        )

        candidates.append(
            (
                score,
                -index,
                item,
            )
        )

        _embyflow_movie_remote_v1_log(
            "CANDIDATE title=%s name=%s original=%s year=%s "
            "provider=%s score=%s image=yes"
            % (
                title,
                item.get("Name"),
                item.get("OriginalTitle"),
                item.get("ProductionYear"),
                item.get("SearchProviderName"),
                score,
            )
        )

    if not candidates:
        return None

    candidates.sort(
        key=lambda row: (row[0], row[1]),
        reverse=True,
    )

    best_score, _order, best = candidates[0]

    # Bei genau einem Remote-Treffer darf Emby selbst die Relevanz liefern.
    # Bei mehreren Treffern verlangen wir weiterhin eine brauchbare
    # Titeluebereinstimmung, damit kein falsches Poster genommen wird.
    if (
        int(best_score) < 70
        and len(candidates) != 1
    ):
        _embyflow_movie_remote_v1_log(
            "REJECT title=%s best_score=%s candidates=%s"
            % (
                title,
                best_score,
                len(candidates),
            )
        )
        return None

    return best


def _embyflow_movie_remote_v1_fetch_image(
    session,
    server,
    token,
    item,
    cache_path,
):
    image_url = str(
        item.get("ImageUrl") or ""
    ).strip()
    provider_raw = str(
        item.get("SearchProviderName") or ""
    ).strip()

    if not image_url:
        return "", ""

    headers = {
        "X-Emby-Token": str(token or ""),
        "X-Emby-Authorization": AUTH_HEADER,
        "Accept-Encoding": "identity",
    }

    temporary = cache_path + ".remote.download"

    try:
        ensure_dir(
            os.path.dirname(cache_path)
        )
    except Exception:
        pass

    for root in _embyflow_movie_remote_v1_roots(server):
        try:
            response = session.get(
                root + "/Items/RemoteSearch/Image",
                headers=headers,
                params={
                    "imageUrl": image_url,
                    "ProviderName": provider_raw,
                },
                timeout=(5, 30),
                verify=True,
            )

            content_type = str(
                response.headers.get("Content-Type", "")
                if hasattr(response, "headers")
                else ""
            )

            _embyflow_movie_remote_v1_log(
                "IMAGE root=%s provider=%s http=%s type=%s bytes=%s"
                % (
                    root,
                    provider_raw,
                    response.status_code,
                    content_type,
                    len(response.content or b""),
                )
            )

            if (
                int(response.status_code or 0) != 200
                or not response.content
                or len(response.content) <= 500
                or (
                    content_type
                    and not content_type.startswith("image/")
                )
            ):
                continue

            with open(temporary, "wb") as handle:
                handle.write(response.content)
                handle.flush()

                try:
                    os.fsync(handle.fileno())
                except Exception:
                    pass

            if not embyflow_local_v4_file_valid(temporary):
                try:
                    os.remove(temporary)
                except Exception:
                    pass
                continue

            try:
                os.replace(
                    temporary,
                    cache_path,
                )
            except AttributeError:
                try:
                    os.remove(cache_path)
                except Exception:
                    pass
                os.rename(
                    temporary,
                    cache_path,
                )

            try:
                embyflow_local_v5_normalize_poster(
                    cache_path
                )
            except Exception:
                pass

            try:
                embyflow_touch_cache_file(
                    cache_path,
                    0,
                )
                embyflow_request_cache_tune(
                    "recording-movie-remote-v1"
                )
            except Exception:
                pass

            provider = (
                _embyflow_movie_remote_v1_provider_label(
                    provider_raw
                )
            )

            _EMBYFLOW_MOVIE_REMOTE_V1_PROVIDER_BY_POSTER[
                cache_path
            ] = provider

            return cache_path, provider

        except Exception as error:
            _embyflow_movie_remote_v1_log(
                "IMAGE_ERROR root=%s provider=%s error=%s"
                % (
                    root,
                    provider_raw,
                    error,
                )
            )

        finally:
            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except Exception:
                pass

    return "", ""


def embyflow_local_v4_download_poster(
    session,
    server,
    token,
    user_id,
    mode,
    title,
):
    # Bestehendes Verhalten zuerst unangetastet lassen:
    # Emby-Library und bei Serien weiterhin TVmaze.
    result = _EMBYFLOW_MOVIE_REMOTE_V1_ORIGINAL_DOWNLOAD(
        session,
        server,
        token,
        user_id,
        mode,
        title,
    )

    if result or str(mode or "") != "movies":
        return result

    missing_path = embyflow_local_v4_missing_path(
        mode,
        title,
    )
    cache_path = embyflow_local_v4_cache_path(
        mode,
        title,
    )

    # Der bisherige Downloader hat bei keinem Library-Treffer bereits
    # negativ gecacht. Jetzt kommt fuer Filme noch die Remote-Suche.
    embyflow_clear_negative_cache(
        missing_path
    )

    remote = _embyflow_movie_remote_v1_search(
        session,
        server,
        token,
        title,
    )

    if not remote:
        embyflow_mark_negative_cache(
            missing_path,
            "no-emby-library-or-remote-movie-poster",
        )
        _embyflow_movie_remote_v1_log(
            "RESULT title=%s poster=no"
            % title
        )
        return ""

    poster, provider = (
        _embyflow_movie_remote_v1_fetch_image(
            session,
            server,
            token,
            remote,
            cache_path,
        )
    )

    if poster:
        embyflow_clear_negative_cache(
            missing_path
        )
        _embyflow_movie_remote_v1_log(
            "RESULT title=%s poster=yes provider=%s name=%s"
            % (
                title,
                provider,
                remote.get("Name"),
            )
        )
        return poster

    embyflow_mark_negative_cache(
        missing_path,
        "remote-movie-image-download-failed",
    )
    _embyflow_movie_remote_v1_log(
        "RESULT title=%s poster=no image-download-failed"
        % title
    )
    return ""


def _cinematic_v1_write_source(
    poster_path,
    provider,
):
    # Der Cinematic-V1-Worker kennt den neuen Film-Fallback noch nicht
    # und wuerde sonst pauschal "Emby" speichern.
    path = str(poster_path or "")
    remote_provider = (
        _EMBYFLOW_MOVIE_REMOTE_V1_PROVIDER_BY_POSTER.get(
            path
        )
    )

    return _EMBYFLOW_MOVIE_REMOTE_V1_ORIGINAL_WRITE_SOURCE(
        poster_path,
        remote_provider or provider,
    )


