def embyflow_local_v4_missing_path(mode, title):
    path = _EMBYFLOW_MOVIE_REMOTE_V2_PREV_MISSING_PATH(
        mode,
        title,
    )

    if str(mode or "") == "movies":
        return path + ".directv2"

    return path


def _embyflow_movie_remote_v2_direct_image(
    session,
    image_url,
    provider_raw,
    cache_path,
):
    url = str(image_url or "").strip()

    if not url.lower().startswith("https://"):
        _embyflow_movie_remote_v1_log(
            "DIRECT_SKIP non-https url=%s" % url
        )
        return "", ""

    provider = (
        _embyflow_movie_remote_v1_provider_label(
            provider_raw
        )
    )

    temporary = cache_path + ".direct.download"

    try:
        ensure_dir(os.path.dirname(cache_path))
    except Exception:
        pass

    try:
        response = session.get(
            url,
            headers={
                "User-Agent":
                    "EmbyFlowE2-RecordingMoviePoster/2",
                "Accept":
                    "image/avif,image/webp,image/apng,image/*,*/*;q=0.8",
                "Accept-Encoding": "identity",
            },
            timeout=(5, 30),
            verify=True,
            allow_redirects=True,
        )

        content_type = str(
            response.headers.get("Content-Type", "")
            if hasattr(response, "headers")
            else ""
        )

        _embyflow_movie_remote_v1_log(
            "DIRECT_IMAGE provider=%s http=%s type=%s bytes=%s"
            % (
                provider_raw,
                response.status_code,
                content_type,
                len(response.content or b""),
            )
        )

        if (
            int(response.status_code or 0) != 200
            or not response.content
            or len(response.content) <= 500
            or (
                content_type
                and not content_type.startswith("image/")
            )
        ):
            return "", ""

        with open(temporary, "wb") as handle:
            handle.write(response.content)
            handle.flush()

            try:
                os.fsync(handle.fileno())
            except Exception:
                pass

        if not embyflow_local_v4_file_valid(temporary):
            return "", ""

        try:
            os.replace(temporary, cache_path)
        except AttributeError:
            try:
                os.remove(cache_path)
            except Exception:
                pass
            os.rename(temporary, cache_path)

        try:
            embyflow_local_v5_normalize_poster(
                cache_path
            )
        except Exception:
            pass

        try:
            embyflow_touch_cache_file(
                cache_path,
                0,
            )
            embyflow_request_cache_tune(
                "recording-movie-remote-v2"
            )
        except Exception:
            pass

        _EMBYFLOW_MOVIE_REMOTE_V1_PROVIDER_BY_POSTER[
            cache_path
        ] = provider

        _embyflow_movie_remote_v1_log(
            "DIRECT_OK provider=%s poster=%s"
            % (
                provider,
                cache_path,
            )
        )

        return cache_path, provider

    except Exception as error:
        _embyflow_movie_remote_v1_log(
            "DIRECT_ERROR provider=%s error=%s"
            % (
                provider_raw,
                error,
            )
        )

        return "", ""

    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_movie_remote_v1_fetch_image(
    session,
    server,
    token,
    item,
    cache_path,
):
    poster, provider = (
        _EMBYFLOW_MOVIE_REMOTE_V2_PREV_FETCH_IMAGE(
            session,
            server,
            token,
            item,
            cache_path,
        )
    )

    if poster:
        return poster, provider

    image_url = str(
        item.get("ImageUrl") or ""
    ).strip()

    provider_raw = str(
        item.get("SearchProviderName") or ""
    ).strip()

    _embyflow_movie_remote_v1_log(
        "PROXY_FAILED -> DIRECT title=%s provider=%s"
        % (
            item.get("Name"),
            provider_raw,
        )
    )

    return _embyflow_movie_remote_v2_direct_image(
        session,
        image_url,
        provider_raw,
        cache_path,
    )


