# EMBYFLOW_RECORDING_CATEGORY_FILTER_V1_START
# Aufnahme-Kategorien zusätzlich zu den bisherigen Sehstatus-Filtern.

EMBYFLOW_RECORDING_FILTERS_V1 = (
    ("all", "Alle"),
    ("movie", "Filme"),
    ("series", "Serien"),
    ("documentary", "Dokumentationen"),
    ("show", "Shows / Unterhaltung"),
    ("news", "Nachrichten"),
    ("sport", "Sport"),
    ("other", "Sonstiges"),
    ("unseen", "Ungesehen"),
    ("started", "Angefangen"),
    ("seen", "Gesehen"),
)


def _embyflow_recording_filter_text_v1(entry):
    data = entry if isinstance(entry, dict) else {}

    values = (
        data.get("display_title"),
        data.get("series_name"),
        data.get("genre"),
        data.get("tags"),
        data.get("description"),
        os.path.basename(str(data.get("path") or "")),
    )

    return " ".join(
        str(value or "") for value in values
    ).casefold()


def _embyflow_recording_has_word_v1(text, words):
    normalized = re.sub(
        r"[^a-z0-9äöüß]+",
        " ",
        str(text or "").casefold(),
    )

    padded = " " + " ".join(normalized.split()) + " "

    return any(
        (" " + word + " ") in padded
        for word in words
    )


def embyflow_recording_category_v1(entry):
    data = entry if isinstance(entry, dict) else {}
    text = _embyflow_recording_filter_text_v1(data)

    title = str(
        data.get("display_title") or ""
    ).strip().casefold()

    series_name = str(
        data.get("series_name") or ""
    ).strip().casefold()

    runtime = int(
        data.get("runtime_seconds") or 0
    )

    categories = (
        (
            "documentary",
            (
                "doku",
                "dokumentation",
                "dokumentarfilm",
                "reportage",
                "terra x",
                "planet wissen",
            ),
        ),
        (
            "news",
            (
                "nachrichten",
                "tagesschau",
                "tagesthemen",
                "heute journal",
                "newstime",
                "rtl aktuell",
                "news",
            ),
        ),
        (
            "sport",
            (
                "sport",
                "fußball",
                "fussball",
                "bundesliga",
                "champions league",
                "tennis",
                "formel 1",
                "handball",
                "basketball",
                "eishockey",
                "boxen",
            ),
        ),
        (
            "show",
            (
                "show",
                "quiz",
                "talkshow",
                "casting",
                "reality",
                "unterhaltung",
                "magazin",
                "comedy",
                "late night",
            ),
        ),
    )

    for category, words in categories:
        if _embyflow_recording_has_word_v1(
            text,
            words,
        ):
            return category

    series_patterns = (
        r"\bs\d{1,2}\s*[/._-]?\s*e\d{1,4}\b",
        r"\b\d{1,2}\.\s*staffel\b",
        r"\b(staffel|folge|episode)\s*\d+\b",
        r"\b\d{4}\s*/\s*e\d+\b",
    )

    if any(
        re.search(pattern, text, re.I)
        for pattern in series_patterns
    ):
        return "series"

    if (
        title
        and series_name
        and title != series_name
        and series_name not in ("aufnahme", "aufnahmen")
        and len(series_name) >= 4
        and runtime > 0
        and runtime < 75 * 60
    ):
        return "series"

    if _embyflow_recording_has_word_v1(
        text,
        (
            "serie",
            "krimiserie",
            "action serie",
            "actionserie",
            "sitcom",
            "soap",
            "telenovela",
        ),
    ):
        return "series"

    if _embyflow_recording_has_word_v1(
        text,
        (
            "film",
            "spielfilm",
            "fernsehfilm",
            "kinofilm",
            "tv film",
            "thriller",
            "krimi",
            "komödie",
            "komoedie",
            "drama",
        ),
    ):
        return "movie"

    if runtime >= 70 * 60:
        return "movie"

    return "other"


def _embyflow_recording_current_filter_v1(self):
    index = int(
        getattr(self, "filter_index", 0) or 0
    )

    return EMBYFLOW_RECORDING_FILTERS_V1[
        index % len(EMBYFLOW_RECORDING_FILTERS_V1)
    ]


def _embyflow_recording_apply_view_v1(
    self,
    selected_path="",
):
    filter_key, _filter_label = (
        self.current_filter()
    )

    sort_key, _sort_label = (
        self.current_sort()
    )

    status_filters = (
        "unseen",
        "started",
        "seen",
    )

    values = []

    for source in self.all_entries:
        entry = dict(source or {})

        if filter_key in status_filters:
            if (
                str(entry.get("state") or "")
                != filter_key
            ):
                continue

        elif filter_key != "all":
            if (
                embyflow_recording_category_v1(entry)
                != filter_key
            ):
                continue

        values.append(entry)

    if sort_key == "date_asc":
        values.sort(
            key=lambda entry: (
                float(entry.get("mtime") or 0.0),
                str(
                    entry.get("display_title") or ""
                ).casefold(),
            )
        )

    elif sort_key == "size_desc":
        values.sort(
            key=lambda entry: (
                -int(entry.get("size") or 0),
                -float(entry.get("mtime") or 0.0),
            )
        )

    else:
        values.sort(
            key=lambda entry: (
                -float(entry.get("mtime") or 0.0),
                str(
                    entry.get("display_title") or ""
                ).casefold(),
            )
        )

    self.entries = values
    self.selected_index = 0

    if selected_path:
        for index, entry in enumerate(
            self.entries
        ):
            if (
                str(entry.get("path") or "")
                == selected_path
            ):
                self.selected_index = index
                break

    self.update_header()
    self.refresh()


def _embyflow_recording_cycle_filter_v1(self):
    self.filter_index = (
        int(getattr(self, "filter_index", 0) or 0)
        + 1
    ) % len(
        EMBYFLOW_RECORDING_FILTERS_V1
    )

    self.apply_view()


EmbyFlowLocalEpisodesScreenV7.current_filter = (
    _embyflow_recording_current_filter_v1
)

EmbyFlowLocalEpisodesScreenV7.apply_view = (
    _embyflow_recording_apply_view_v1
)

EmbyFlowLocalEpisodesScreenV7.cycle_filter = (
    _embyflow_recording_cycle_filter_v1
)

