def _embyflow_attribution_provider_v1(value):
    raw = " ".join(
        str(value or "").split()
    ).strip()
    folded = raw.casefold()

    # Diese älteren Sammelwerte enthalten keinen nachweisbaren
    # Einzelanbieter und dürfen daher nicht genauer ausgegeben werden.
    if folded in (
        "emby",
        "emby remote",
        "emby / tvmaze",
    ):
        return (
            "Emby-Bibliothek · Anbieter nicht gemeldet"
        )

    if folded in (
        "lokal",
        "local",
        "manuell",
    ):
        return "Lokale Datei"

    aliases = (
        (
            (
                "themoviedb",
                "movie db",
                "moviedb",
                "tmdb",
            ),
            "TMDb",
        ),
        (
            (
                "thetvdb",
                "tv db",
                "tvdb",
            ),
            "TheTVDB",
        ),
        (
            (
                "fanart.tv",
                "fanart tv",
                "fanarttv",
            ),
            "Fanart.tv",
        ),
        (
            (
                "open movie database",
                "omdb",
            ),
            "OMDb",
        ),
        (
            (
                "tvmaze",
                "tv maze",
            ),
            "TVmaze",
        ),
    )

    for needles, label in aliases:
        if any(
            needle in folded
            for needle in needles
        ):
            return label

    # Unbekannte installierte Emby-Anbieter behalten ihren echten,
    # vom Server gelieferten Namen. Es wird nichts geraten.
    return raw or "Anbieter nicht gemeldet"


