def _embyflow_player_picon_norm_v1(value):
    return "".join(
        character
        for character in str(value or "").casefold()
        if character.isalnum()
    )


def _embyflow_player_picon_names_v1(
    service_reference
):
    raw = str(
        service_reference or ""
    ).strip()

    names = []

    if raw:
        parts = raw.split(":")

        for length in (10, 11):
            candidate = "_".join(
                parts[:length]
            ).strip("_")

            if candidate:
                names.append(
                    candidate + ".png"
                )

        candidate = (
            raw.rstrip(":")
            .replace(":", "_")
        )

        if candidate:
            names.append(
                candidate + ".png"
            )

    result = []
    seen = set()

    for name in names:
        key = name.casefold()

        if key not in seen:
            seen.add(key)
            result.append(name)

    return result


def _embyflow_player_find_picon_v1(
    service_reference,
    service_name,
):
    roots = (
        "/usr/share/enigma2/picon",
        "/usr/local/share/enigma2/picon",
        "/etc/enigma2/picon",
        "/media/hdd/picon",
        "/media/usb/picon",
        "/picon",
    )

    reference_names = (
        _embyflow_player_picon_names_v1(
            service_reference
        )
    )

    # Exakte Zuordnung über die Service-Referenz.
    for root in roots:
        for name in reference_names:
            candidate = os.path.join(
                root,
                name,
            )

            if (
                os.path.isfile(candidate)
                and os.path.getsize(candidate) > 500
            ):
                return candidate

    # Rückfall über den lesbaren Sendernamen.
    wanted = _embyflow_player_picon_norm_v1(
        service_name
    )

    without_hd = (
        wanted[:-2]
        if wanted.endswith("hd")
        else wanted
    )

    alternatives = set(
        filter(
            None,
            (
                wanted,
                without_hd,
                wanted.replace("uhd", ""),
            ),
        )
    )

    if not alternatives:
        return ""

    for root in roots:
        if not os.path.isdir(root):
            continue

        try:
            for name in os.listdir(root):
                if not name.lower().endswith(".png"):
                    continue

                stem = os.path.splitext(name)[0]

                if (
                    _embyflow_player_picon_norm_v1(stem)
                    not in alternatives
                ):
                    continue

                candidate = os.path.join(
                    root,
                    name,
                )

                if (
                    os.path.isfile(candidate)
                    and os.path.getsize(candidate) > 500
                ):
                    return candidate

        except Exception:
            pass

    return ""


# EMBYFLOW_PLAYER_PICON_BLEND_V1_START
def _embyflow_player_prepare_picon_v1(path):
    """
    Beschneidet transparente Außenränder und setzt die verbleibende
    Leinwand auf die exakte OSD-Farbe. Dadurch kann Enigma2 transparente
    Piconbereiche nicht mehr als schwarze Balken darstellen.
    Das Original-Picon wird niemals verändert.
    """
    source_path = str(path or "")

    if (
        not source_path
        or not os.path.isfile(source_path)
    ):
        return source_path

    try:
        import hashlib
        from PIL import Image

        stat = os.stat(source_path)
        signature = "%s|%s|%s" % (
            source_path,
            int(stat.st_mtime),
            int(stat.st_size),
        )
        digest = hashlib.sha1(
            signature.encode("utf-8", "replace")
        ).hexdigest()

        cache_dir = "/tmp/embyflow_player_picons_v1"

        if not os.path.isdir(cache_dir):
            os.makedirs(cache_dir)

        target_path = os.path.join(
            cache_dir,
            digest + ".png",
        )

        if (
            os.path.isfile(target_path)
            and os.path.getsize(target_path) > 100
        ):
            return target_path

        image = Image.open(source_path).convert("RGBA")
        alpha = image.getchannel("A")
        bounds = alpha.getbbox()

        if bounds:
            image = image.crop(bounds)

        target_width = 220
        target_height = 140
        padding_x = 4
        padding_y = 4

        available_width = target_width - (padding_x * 2)
        available_height = target_height - (padding_y * 2)

        if image.width <= 0 or image.height <= 0:
            return source_path

        factor = min(
            float(available_width) / float(image.width),
            float(available_height) / float(image.height),
        )

        new_width = max(
            1,
            int(round(image.width * factor)),
        )
        new_height = max(
            1,
            int(round(image.height * factor)),
        )

        try:
            resampling = Image.Resampling.LANCZOS
        except Exception:
            resampling = Image.LANCZOS

        image = image.resize(
            (new_width, new_height),
            resampling,
        )

        # Exakte Farbe des Player-OSD: #151311
        canvas = Image.new(
            "RGBA",
            (target_width, target_height),
            (21, 19, 17, 255),
        )

        position = (
            (target_width - new_width) // 2,
            (target_height - new_height) // 2,
        )

        canvas.alpha_composite(
            image,
            dest=position,
        )

        temporary = target_path + ".tmp.png"
        canvas.save(
            temporary,
            "PNG",
            optimize=True,
        )
        os.replace(temporary, target_path)

        return target_path

    except Exception:
        return source_path
# EMBYFLOW_PLAYER_PICON_BLEND_V1_END


def _embyflow_player_try_picon_v1(self):
    if getattr(
        self,
        "embyflow_player_picon_attempted_v1",
        False,
    ):
        return False

    self.embyflow_player_picon_attempted_v1 = True

    path = _embyflow_player_find_picon_v1(
        getattr(
            self,
            "embyflow_recording_service_reference_v1",
            "",
        ),
        getattr(
            self,
            "embyflow_recording_service_name_v1",
            "",
        ),
    )

    if not path:
        try:
            self["player_poster"].hide()
        except Exception:
            pass

        return False

    # EMBYFLOW_PLAYER_SEPARATE_PICON_LOADER_V1
    path = _embyflow_player_prepare_picon_v1(path)
    self.player_picon_ready_path_v1 = path
    self.player_poster_failed = False

    try:
        self["player_poster"].hide()
    except Exception:
        pass

    try:
        with embyflow_open_log(
            "/tmp/embyflow_player_picon_v1.log",
            "a",
        ) as log:
            log.write(
                "%s sender=%s picon=%s\n"
                % (
                    time.strftime(
                        "%Y-%m-%d %H:%M:%S"
                    ),
                    getattr(
                        self,
                        "embyflow_recording_service_name_v1",
                        "",
                    ),
                    path,
                )
            )
    except Exception:
        pass

    accepted = embyflow_decode_image_to_widget(
        self,
        "player_picon",
        path,
        sx(110),
        sy(70),
        token="player-picon-v1",
        is_current=lambda: (
            not getattr(
                self,
                "player_poster_closed",
                False,
            )
            and str(path) == str(
                getattr(
                    self,
                    "player_picon_ready_path_v1",
                    "",
                )
            )
        ),
    )

    if accepted:
        self.player_picon_loaded_path_v1 = path

        if getattr(self, "overlay_visible", False):
            try:
                self["player_picon"].show()
            except Exception:
                pass

    return bool(accepted)


def _embyflow_player_load_date_picon_v1(
    self
):
    source_id = self.player_poster_source_id()

    result = (
        _EMBYFLOW_PLAYER_DATE_PICON_PREV_LOAD(
            self
        )
    )

    # Lokale Aufnahme ohne verwendbare Emby-ID:
    # sofort das Senderlogo versuchen.
    if not source_id:
        _embyflow_player_try_picon_v1(
            self
        )

    return result


def _embyflow_player_poll_date_picon_v1(
    self
):
    result = (
        _EMBYFLOW_PLAYER_DATE_PICON_PREV_POLL(
            self
        )
    )

    # Emby-Poster fehlgeschlagen:
    # Senderlogo als Rückfall verwenden.
    if (
        getattr(
            self,
            "player_poster_failed",
            False,
        )
        or getattr(
            self,
            "player_poster_poll_count",
            0,
        ) >= 60
    ):
        _embyflow_player_try_picon_v1(
            self
        )

    return result


