# EMBYFLOW_INTRO_CREDITS_MARKERS_V17_5_START
# Original EmbyFlow implementation.
# Uses Emby's hidden Chapter marker metadata (IntroStart, IntroEnd, CreditsStart)
# but no EmbyDream/murxer code, skin, geometry, widget names or assets.

EMBYFLOW_MARKER_AUTONEXT_COUNTDOWN_V17_5 = 10
EMBYFLOW_INTRO_MIN_REMAINING_SECONDS_V17_5 = 5


def _embyflow_marker_v17_5_format_ticks(ticks):
    try:
        total = max(0, int(ticks or 0)) // 10000000
    except Exception:
        total = 0

    hours = total // 3600
    minutes = (total % 3600) // 60
    seconds = total % 60

    if hours:
        return "%d:%02d:%02d" % (
            hours,
            minutes,
            seconds,
        )

    return "%d:%02d" % (
        minutes,
        seconds,
    )


def _embyflow_marker_v17_5_log(message):
    try:
        with open(
            "/tmp/embyflow_intro_credits_v17_5.log",
            "a",
            encoding="utf-8",
        ) as handle:
            handle.write(
                "%s %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


