    def __init__(
        self,
        session,
        player,
        intro_start_ticks,
        intro_end_ticks,
    ):
        Screen.__init__(self, session)

        self.player = player

        try:
            self.intro_start_ticks = max(
                0,
                int(intro_start_ticks or 0),
            )
        except Exception:
            self.intro_start_ticks = 0

        try:
            self.intro_end_ticks = max(
                self.intro_start_ticks,
                int(intro_end_ticks or 0),
            )
        except Exception:
            self.intro_end_ticks = self.intro_start_ticks

        self["frame_top"] = Label(" ")
        self["frame_right"] = Label(" ")
        self["frame_bottom"] = Label(" ")
        self["frame_left"] = Label(" ")

        self["brand"] = Label("EMBY FLOW  •  INTRO")
        self["question"] = Label("Intro überspringen?")
        self["time_start"] = Label(
            _embyflow_marker_v17_5_format_ticks(
                self.intro_start_ticks
            )
        )
        self["arrow"] = Label("→")
        self["time_end"] = Label(
            _embyflow_marker_v17_5_format_ticks(
                self.intro_end_ticks
            )
        )
        self["progress_bg"] = Label(" ")
        self["progress_fill"] = Label(" ")
        self["position_text"] = Label("")
        self["help"] = Label(
            "Du befindest dich im Intro.\n"
            "Direkt zum Ende des Intros springen?"
        )
        self["ok_button"] = Label("OK  ÜBERSPRINGEN")
        self["back_button"] = Label("ROT / ZURÜCK  WEITERSEHEN")

        self["actions"] = ActionMap(
            [
                "OkCancelActions",
                "ColorActions",
            ],
            {
                "ok": self._skip,
                "cancel": self._stay,
                "red": self._stay,
                "blue": self._stay,
            },
            -10,
        )

        self._timer = eTimer()

        try:
            self._timer.callback.append(
                self._refresh
            )
        except Exception:
            try:
                self._timer.timeout.connect(
                    self._refresh
                )
            except Exception:
                pass

        self.onLayoutFinish.append(
            self._layout_ready
        )

        try:
            self.onClose.append(
                self._cleanup
            )
        except Exception:
            pass

    def _layout_ready(self):
        self._refresh()

        try:
            self._timer.start(
                500,
                False,
            )
        except Exception:
            pass

    def _cleanup(self):
        try:
            self._timer.stop()
        except Exception:
            pass

    def _refresh(self):
        try:
            current = int(
                self.player.current_position_ticks()
                or 0
            )
        except Exception:
            current = 0

        if (
            self.intro_end_ticks > 0
            and current >= self.intro_end_ticks
        ):
            self.close("expired")
            return

        span = max(
            1,
            self.intro_end_ticks
            - self.intro_start_ticks,
        )

        progress = max(
            0,
            min(
                span,
                current
                - self.intro_start_ticks,
            ),
        )

        fraction = min(
            1.0,
            max(
                0.0,
                float(progress)
                / float(span),
            ),
        )

        width = max(
            1,
            int(
                round(
                    480.0
                    * fraction
                )
            ),
        )

        try:
            instance = getattr(
                self["progress_fill"],
                "instance",
                None,
            )

            if instance is not None:
                instance.resize(
                    eSize(
                        width,
                        8,
                    )
                )
        except Exception:
            pass

        self["position_text"].setText(
            "Aktuell  %s"
            % _embyflow_marker_v17_5_format_ticks(
                current
            )
        )

    def _skip(self):
        self.close("skip")

    def _stay(self):
        self.close("stay")


