# EMBYFLOW_CHAPTER_PREVIEW_PREWARM_V17_5_3_START
#
# Performance-only change for chapter thumbnails.
#
# Problem proven from the existing implementation:
# - Missing chapter thumbnails are generated one-by-one.
# - Each ffmpeg attempt may wait up to 20 seconds and can retry at
#   several offsets for black frames.
# - Therefore a first visit to a title can leave the carousel visibly
#   filling in for too long.
#
# V17.5.3 keeps the same image-generation/cache format and starts a
# low-priority single-worker prewarm shortly after playback begins.
# The active chapter and its neighbors are generated first; the rest
# follows only while the chapter menu is closed.
#
# No seek, stream-timebase, subtitle, resume, intro or AutoNext logic
# is changed.

try:
    import threading as _embyflow_chapter_prewarm_threading_v17_5_3
    _EMBYFLOW_CHAPTER_PREWARM_LOCK_V17_5_3 = (
        _embyflow_chapter_prewarm_threading_v17_5_3.RLock()
    )
except Exception:
    _embyflow_chapter_prewarm_threading_v17_5_3 = None
    _EMBYFLOW_CHAPTER_PREWARM_LOCK_V17_5_3 = None


_EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_PLAYER_INIT_V17_5_3 = (
    EmbyFlowMoviePlayer.__init__
)
_EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_OPEN_V17_5_3 = (
    EmbyFlowMoviePlayer.open_chapter_navigation
)
_EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_CLEANUP_V17_5_3 = (
    EmbyFlowChapterNavigator._cleanup
)
_EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_OBTAIN_V17_5_3 = (
    EmbyFlowChapterNavigator._obtain_preview
)
_EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_REFRESH_V17_5_3 = (
    EmbyFlowChapterNavigator._refresh_carousel_v17
)
_EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_POLL_V17_5_3 = (
    EmbyFlowChapterNavigator._poll_async_v17
)


def _embyflow_chapter_prewarm_log_v17_5_3(message):
    try:
        with embyflow_open_log(
            "/tmp/embyflow_chapter_prewarm_error.log",
            "a",
            encoding="utf-8",
        ) as log:
            log.write(
                "%s %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_chapter_obtain_locked_v17_5_3(
    self,
    chapter,
    path,
):
    lock = _EMBYFLOW_CHAPTER_PREWARM_LOCK_V17_5_3

    if lock is None:
        return _EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_OBTAIN_V17_5_3(
            self,
            chapter,
            path,
        )

    with lock:
        return _EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_OBTAIN_V17_5_3(
            self,
            chapter,
            path,
        )


class _EmbyFlowChapterPrewarmProxyV17_5_3(object):
    """Plain worker helper: reuses preview methods without allocating a Screen."""

    # Important: EmbyFlowChapterNavigator ultimately derives from Enigma2 Screen.
    # object.__new__(ScreenSubclass) is unsafe on the real box.  The background
    # prewarmer needs only these preview helpers, not a GUI Screen instance.
    _cache_path = EmbyFlowChapterNavigator._cache_path
    _preview_file_valid = EmbyFlowChapterNavigator._preview_file_valid

    # Keep the V17.5.3 single-ffmpeg lock for background/menu coordination.
    _obtain_preview = _embyflow_chapter_obtain_locked_v17_5_3

    _download_preview = EmbyFlowChapterNavigator._download_preview
    _generate_preview_frame = EmbyFlowChapterNavigator._generate_preview_frame
    _preview_atomic_replace = EmbyFlowChapterNavigator._preview_atomic_replace

    # V11.6 safe-preview helpers used by the locked obtain method.
    _preview_v6_log = EmbyFlowChapterNavigator._preview_v6_log
    _preview_v6_native_item_marker = EmbyFlowChapterNavigator._preview_v6_native_item_marker
    _preview_v6_native_chapter_marker = EmbyFlowChapterNavigator._preview_v6_native_chapter_marker
    _preview_v6_direct_marker = EmbyFlowChapterNavigator._preview_v6_direct_marker
    _preview_v6_placeholder_path = EmbyFlowChapterNavigator._preview_v6_placeholder_path
    _preview_v6_make_placeholder = EmbyFlowChapterNavigator._preview_v6_make_placeholder
    _preview_v6_source_is_safe = EmbyFlowChapterNavigator._preview_v6_source_is_safe
    _preview_v6_safe_direct_source = EmbyFlowChapterNavigator._preview_v6_safe_direct_source
    _preview_v6_run_ffmpeg_direct = EmbyFlowChapterNavigator._preview_v6_run_ffmpeg_direct
    _generate_preview_frame_safe_direct_v11_6 = (
        EmbyFlowChapterNavigator._generate_preview_frame_safe_direct_v11_6
    )

    _preview_auth_context_v3 = EmbyFlowChapterNavigator._preview_auth_context_v3
    _preview_v5_error = EmbyFlowChapterNavigator._preview_v5_error
    _preview_v5_black_frame = EmbyFlowChapterNavigator._preview_v5_black_frame
    _preview_v5_offsets = EmbyFlowChapterNavigator._preview_v5_offsets
    _preview_v5_transcode_url = EmbyFlowChapterNavigator._preview_v5_transcode_url
    _preview_v5_run_ffmpeg = EmbyFlowChapterNavigator._preview_v5_run_ffmpeg


def _embyflow_chapter_priority_order_v17_5_3(
    player,
    chapters,
):
    chapters = list(chapters or [])

    if not chapters:
        return []

    try:
        current = int(
            player.current_position_ticks()
            or 0
        )
    except Exception:
        current = 0

    active = 0

    for index, chapter in enumerate(chapters):
        try:
            if int(
                chapter.get("StartPositionTicks")
                or 0
            ) <= current:
                active = index
            else:
                break
        except Exception:
            pass

    order = []

    # First paint priority: selected/current card and its visible neighbors.
    for offset in (0, -1, 1, -2, 2):
        index = active + offset

        if (
            0 <= index < len(chapters)
            and index not in order
        ):
            order.append(index)

    # Then fill the remaining title cache in normal chapter order.
    for index in range(len(chapters)):
        if index not in order:
            order.append(index)

    # Avoid an unbounded background job on unusually chapter-heavy media.
    return order[:24]


def _embyflow_chapter_prewarm_worker_v17_5_3(
    player,
    serial,
    delay_seconds,
):
    try:
        time.sleep(
            max(
                0.0,
                float(delay_seconds or 0.0),
            )
        )

        if int(serial) != int(
            getattr(
                player,
                "_embyflow_chapter_prewarm_serial_v17_5_3",
                -1,
            )
        ):
            return

        if getattr(
            player,
            "_embyflow_chapter_prewarm_stop_v17_5_3",
            False,
        ):
            return

        chapters = []

        try:
            chapters = list(
                player.embyflow_extract_local_chapters()
                or []
            )
        except Exception:
            chapters = []

        if not chapters:
            try:
                chapters = list(
                    player.embyflow_fetch_chapters_remote()
                    or []
                )
            except Exception:
                chapters = []

        if not chapters:
            _embyflow_chapter_prewarm_log_v17_5_3(
                "PREWARM_SKIP item=%s reason=no_chapters"
                % str(
                    getattr(
                        player,
                        "item_id",
                        "",
                    )
                    or "-"
                )
            )
            return

        helper = _EmbyFlowChapterPrewarmProxyV17_5_3()
        helper.player = player
        helper.chapters = chapters
        helper._closing = False
        helper._preview_process = None

        # V11.6 mass-user safety:
        # Background prewarm may only consume native chapter JPEGs for chapters
        # that already advertise ImageTag. It never blind-probes missing tags,
        # never opens a Static=true video stream and never starts local ffmpeg.
        helper._embyflow_preview_background_prewarm_v11_6 = True

        order = _embyflow_chapter_priority_order_v17_5_3(
            player,
            chapters,
        )

        made = 0
        cached = 0

        for chapter_index in order:
            if int(serial) != int(
                getattr(
                    player,
                    "_embyflow_chapter_prewarm_serial_v17_5_3",
                    -1,
                )
            ):
                break

            if getattr(
                player,
                "_embyflow_chapter_prewarm_stop_v17_5_3",
                False,
            ):
                break

            # User-facing carousel always wins over background cache work.
            # V17.5.3.2 pauses the worker while the menu is open and then
            # resumes the same queue after the menu closes.  This avoids the
            # old behavior where opening the chapter screen permanently
            # stopped the rest of the title prewarm.
            if getattr(
                player,
                "_embyflow_chapter_menu_open_v17_5_3",
                False,
            ):
                _embyflow_chapter_prewarm_log_v17_5_3(
                    "PREWARM_PAUSE item=%s reason=chapter_menu"
                    % str(
                        getattr(
                            player,
                            "item_id",
                            "",
                        )
                        or "-"
                    )
                )

                while getattr(
                    player,
                    "_embyflow_chapter_menu_open_v17_5_3",
                    False,
                ):
                    if int(serial) != int(
                        getattr(
                            player,
                            "_embyflow_chapter_prewarm_serial_v17_5_3",
                            -1,
                        )
                    ):
                        break

                    if getattr(
                        player,
                        "_embyflow_chapter_prewarm_stop_v17_5_3",
                        False,
                    ):
                        break

                    time.sleep(0.10)

                if int(serial) != int(
                    getattr(
                        player,
                        "_embyflow_chapter_prewarm_serial_v17_5_3",
                        -1,
                    )
                ):
                    break

                if getattr(
                    player,
                    "_embyflow_chapter_prewarm_stop_v17_5_3",
                    False,
                ):
                    break

                _embyflow_chapter_prewarm_log_v17_5_3(
                    "PREWARM_RESUME item=%s reason=chapter_menu_closed"
                    % str(
                        getattr(
                            player,
                            "item_id",
                            "",
                        )
                        or "-"
                    )
                )

            chapter = chapters[chapter_index]
            path = helper._cache_path(chapter)

            if helper._preview_file_valid(path):
                cached += 1
                continue

            started = time.monotonic()

            result = helper._obtain_preview(
                chapter,
                path,
            )

            elapsed = max(
                0.0,
                time.monotonic() - started,
            )

            if (
                result
                and helper._preview_file_valid(result)
            ):
                made += 1
                _embyflow_chapter_prewarm_log_v17_5_3(
                    "PREWARM_OK item=%s chapter=%s seconds=%.3f"
                    % (
                        str(
                            getattr(
                                player,
                                "item_id",
                                "",
                            )
                            or "-"
                        ),
                        chapter_index + 1,
                        elapsed,
                    )
                )
            else:
                _embyflow_chapter_prewarm_log_v17_5_3(
                    "PREWARM_FAIL item=%s chapter=%s seconds=%.3f"
                    % (
                        str(
                            getattr(
                                player,
                                "item_id",
                                "",
                            )
                            or "-"
                        ),
                        chapter_index + 1,
                        elapsed,
                    )
                )

            # Give playback/server a small gap between thumbnail jobs.
            time.sleep(0.20)

        _embyflow_chapter_prewarm_log_v17_5_3(
            "PREWARM_DONE item=%s generated=%s cached=%s total=%s"
            % (
                str(
                    getattr(
                        player,
                        "item_id",
                        "",
                    )
                    or "-"
                ),
                made,
                cached,
                len(order),
            )
        )

    except Exception as error:
        _embyflow_chapter_prewarm_log_v17_5_3(
            "PREWARM_ERROR item=%s type=%s message=%s"
            % (
                str(
                    getattr(
                        player,
                        "item_id",
                        "",
                    )
                    or "-"
                ),
                type(error).__name__,
                str(error).replace(
                    "\n",
                    " ",
                )[:240],
            )
        )
    finally:
        try:
            if int(serial) == int(
                getattr(
                    player,
                    "_embyflow_chapter_prewarm_serial_v17_5_3",
                    -1,
                )
            ):
                player._embyflow_chapter_prewarm_running_v17_5_3 = False
        except Exception:
            pass


def _embyflow_chapter_start_prewarm_v17_5_3(
    player,
    delay_seconds=5.0,
):
    if (
        _embyflow_chapter_prewarm_threading_v17_5_3
        is None
    ):
        return

    if getattr(
        player,
        "_embyflow_chapter_prewarm_running_v17_5_3",
        False,
    ):
        return

    if getattr(
        player,
        "_embyflow_chapter_prewarm_stop_v17_5_3",
        False,
    ):
        return

    player._embyflow_chapter_prewarm_serial_v17_5_3 = int(
        getattr(
            player,
            "_embyflow_chapter_prewarm_serial_v17_5_3",
            0,
        )
        or 0
    ) + 1

    serial = int(
        player._embyflow_chapter_prewarm_serial_v17_5_3
    )

    player._embyflow_chapter_prewarm_running_v17_5_3 = True

    try:
        worker = (
            _embyflow_chapter_prewarm_threading_v17_5_3.Thread(
                target=_embyflow_chapter_prewarm_worker_v17_5_3,
                args=(
                    player,
                    serial,
                    delay_seconds,
                ),
                name="EmbyFlowChapterPrewarmV17_5_3",
            )
        )
        worker.daemon = True
        worker.start()
    except Exception:
        player._embyflow_chapter_prewarm_running_v17_5_3 = False


def _embyflow_chapter_player_init_v17_5_3(
    self,
    *args,
    **kwargs
):
    _EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_PLAYER_INIT_V17_5_3(
        self,
        *args,
        **kwargs
    )

    self._embyflow_chapter_prewarm_serial_v17_5_3 = 0
    self._embyflow_chapter_prewarm_running_v17_5_3 = False
    self._embyflow_chapter_prewarm_stop_v17_5_3 = False
    self._embyflow_chapter_menu_open_v17_5_3 = False

    # V17.5.3.2: start almost immediately.  The worker is still
    # single-threaded and coordinated with the chapter menu lock.
    _embyflow_chapter_start_prewarm_v17_5_3(
        self,
        1.0,
    )


def _embyflow_chapter_open_v17_5_3(
    self,
):
    self._embyflow_chapter_menu_open_v17_5_3 = True
    return _EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_OPEN_V17_5_3(
        self
    )


def _embyflow_chapter_cleanup_v17_5_3(
    self,
):
    try:
        player = getattr(
            self,
            "player",
            None,
        )

        if player is not None:
            player._embyflow_chapter_menu_open_v17_5_3 = False
    except Exception:
        pass

    return _EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_CLEANUP_V17_5_3(
        self
    )


def _embyflow_chapter_visible_ready_v17_5_3(
    self,
):
    if not getattr(
        self,
        "chapters",
        None,
    ):
        return False

    found = 0

    for slot in range(5):
        chapter_index = self._slot_chapter_index_v17(
            slot
        )

        if chapter_index is None:
            continue

        found += 1
        chapter = self.chapters[chapter_index]
        path = self._cache_path(chapter)

        if not self._preview_file_valid(path):
            return False

    return found > 0


def _embyflow_chapter_refresh_v17_5_3(
    self,
):
    result = _EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_REFRESH_V17_5_3(
        self
    )

    if _embyflow_chapter_visible_ready_v17_5_3(
        self
    ):
        try:
            self["status_text"].setText("")
        except Exception:
            pass

    return result


def _embyflow_chapter_poll_v17_5_3(
    self,
):
    result = _EMBYFLOW_CHAPTER_PREWARM_ORIGINAL_POLL_V17_5_3(
        self
    )

    if _embyflow_chapter_visible_ready_v17_5_3(
        self
    ):
        try:
            self["status_text"].setText("")
        except Exception:
            pass

    return result


