        self["badge_4k"].setText(str(badges.get("resolution") or "VIDEO"))
        self["badge_hdr"].setText(str(badges.get("hdr") or "SDR"))
        self["badge_audio"].setText(str(badges.get("audio") or "AUDIO"))

