#
# V2 target approved by user:
#   MENU -> one compact overlay with exactly two neighbouring cards:
#     7. QUALITÄT & VERSIONEN  |  8. STATS FOR NERDS
#   no INFO key required, no separate Stats screen.
#   Quality/version is interactive; stats are live/read-only.
#   A quality/version change resumes at the current movie position by a
#   delayed native Enigma2 seek after the replacement service is ready.
# ============================================================================



# ============================================================================
# EMBYFLOW_OPTIONAL_EXTEPLAYER3_ENGINE_V11_4_START
#
# Optional backend below the existing EmbyFlowMoviePlayer:
#   AUTO                -> 4097 (unchanged safe default)
#   ENIGMA2 / 4097      -> force 4097
#   EXTEPLAYER3 / 5002  -> force 5002 when ServiceApp + exteplayer3 exist
#
# The EmbyFlow player UI remains in charge of overlay, subtitles, chapters,
# seek/resume, V11.2 Session Guard and V11.3 Stopped handling.
# ============================================================================

EMBYFLOW_ENGINE_OPTIONS_V11_4 = (
    ("AUTOMATISCH", "auto"),
    ("ENIGMA2 / 4097", "e2"),
    ("EXTEPLAYER3 / 5002", "ext"),
)


def _embyflow_engine_v11_4_exteplayer3_available():
    """Local capability check only: no network and no shell command."""
    try:
        binary_ok = any(
            os.path.exists(path)
            for path in (
                "/usr/bin/exteplayer3",
                "/usr/bin/Exteplayer3",
                "/usr/bin/extEplayer3",
            )
        )
        serviceapp_ok = os.path.isdir(
            "/usr/lib/enigma2/python/Plugins/SystemPlugins/ServiceApp"
        )
        return bool(binary_ok and serviceapp_ok)
    except Exception:
        return False


def _embyflow_engine_v11_4_mode(player=None, requested_mode=None):
    mode = str(
        requested_mode
        if requested_mode is not None
        else getattr(player, "embyflow_engine_mode_v11_4", "auto")
    ).strip().lower()
    if mode not in ("auto", "e2", "ext"):
        mode = "auto"
    return mode


def _embyflow_engine_v11_4_service_type(player=None, requested_mode=None):
    mode = _embyflow_engine_v11_4_mode(player, requested_mode)
    if mode == "ext" and _embyflow_engine_v11_4_exteplayer3_available():
        return 5002
    # AUTO remains the currently proven backend for mass deployment.
    return STREAM_SERVICE_TYPE


def _embyflow_engine_v11_4_log(player, event, requested_mode=None, extra=""):
    try:
        mode = _embyflow_engine_v11_4_mode(player, requested_mode)
        service_type = _embyflow_engine_v11_4_service_type(
            player,
            requested_mode,
        )
        with embyflow_open_log("/tmp/embyflow_engine_v11_4.log", "a") as log:
            log.write(
                "%s event=%s mode=%s service_type=%s ext_available=%s "
                "session=%s title=%s extra=%s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(event),
                    mode,
                    service_type,
                    int(bool(_embyflow_engine_v11_4_exteplayer3_available())),
                    str(getattr(player, "play_session_id", "") or ""),
                    str(getattr(player, "title_text", "") or ""),
                    str(extra or "").replace("\n", " ")[:240],
                )
            )
    except Exception:
        pass


