def _embyflow_qs_v2_2_compact_version_name(value, index=0):
    text = str(value or "").strip()
    if not text:
        return "Version %d" % (int(index) + 1)

    # Typical Emby source names can contain the movie title and year before the
    # actual edition/release description, e.g.
    #   Mutiny - (2026) - WEBDL-1080p - h264 AAC
    # In the compact card the useful differentiator is the tail.
    parts = [part.strip() for part in text.split(" - ") if part.strip()]
    if len(parts) >= 3:
        second = parts[1].strip()
        if (
            len(second) in (4, 6)
            and second.strip("()[]{}").isdigit()
        ):
            text = " - ".join(parts[2:])

    if len(text) > 38:
        text = text[:35] + "…"
    return text


_EMBYFLOW_QS_V2_2_OLD_SOURCE_PRIMARY = _embyflow_qs_v1_source_primary


def _embyflow_qs_v1_source_primary(source, index):
    raw = _EMBYFLOW_QS_V2_2_OLD_SOURCE_PRIMARY(source, index)
    return _embyflow_qs_v2_2_compact_version_name(raw, index)



def _embyflow_qs_v1_device_name():
    candidates = []
    for path in (
        "/proc/stb/info/vumodel",
        "/proc/stb/info/model",
        "/proc/stb/info/boxtype",
        "/proc/stb/info/brand",
    ):
        try:
            with open(path, "r") as handle:
                value = handle.read().strip()
            if value and value not in candidates:
                candidates.append(value)
        except Exception:
            pass

    mapping = {
        "duo4kse": "VU+ Duo 4K SE",
        "vuduo4kse": "VU+ Duo 4K SE",
        "vuplusduo4kse": "VU+ Duo 4K SE",
        "duo4k": "VU+ Duo 4K",
        "vuduo4k": "VU+ Duo 4K",
        "vuplusduo4k": "VU+ Duo 4K",
        "ultimo4k": "VU+ Ultimo 4K",
        "vuultimo4k": "VU+ Ultimo 4K",
        "uno4kse": "VU+ Uno 4K SE",
        "vuuno4kse": "VU+ Uno 4K SE",
        "uno4k": "VU+ Uno 4K",
        "vuuno4k": "VU+ Uno 4K",
        "zero4k": "VU+ Zero 4K",
        "vuzero4k": "VU+ Zero 4K",
        "solo4k": "VU+ Solo 4K",
        "vusolo4k": "VU+ Solo 4K",
    }

    # Do not stop at the first proc value: some OpenATV images expose a generic
    # compatibility boxtype (e.g. dm8000) even though model/vumodel is correct.
    for value in candidates:
        key = re.sub(r"[^a-z0-9]+", "", str(value).lower())
        if key in mapping:
            return mapping[key]

    for value in candidates:
        key = re.sub(r"[^a-z0-9]+", "", str(value).lower())
        if key and key not in ("dm8000", "dreambox", "unknown"):
            return str(value)

    return "Enigma2"



def _embyflow_qs_v1_server_name(player):
    now = time.time()
    cached = str(
        getattr(player, "_embyflow_qs_v2_2_server_name", "") or ""
    ).strip()
    cached_ts = float(
        getattr(player, "_embyflow_qs_v2_2_server_name_ts", 0.0) or 0.0
    )
    if cached and now - cached_ts < 300.0:
        return cached

    playback_info = getattr(player, "playback_info", None) or {}
    server = str(
        playback_info.get("server")
        or EMBY_AUTH_CACHE.get("server")
        or EMBY_SERVER
        or ""
    ).rstrip("/")

    display = ""
    if server:
        try:
            info = embyflow_cached_get_json(
                server + "/System/Info/Public",
                headers={"X-Emby-Authorization": AUTH_HEADER},
                ttl=300,
                timeout=3,
                verify=True,
                cache_key="quality-stats-server-name",
            ) or {}
            display = str(
                info.get("ServerName")
                or info.get("Name")
                or ""
            ).strip()
        except Exception:
            display = ""

    if not display and server:
        try:
            try:
                from urllib.parse import urlparse
            except Exception:
                from urlparse import urlparse
            parsed = urlparse(server)
            display = str(parsed.hostname or parsed.netloc or server).strip()
        except Exception:
            display = server

    if not display:
        display = "Unbekannt"

    try:
        player._embyflow_qs_v2_2_server_name = display
        player._embyflow_qs_v2_2_server_name_ts = now
    except Exception:
        pass

    return display


# The compact screen uses these helpers dynamically through
# embyflow_stats_snapshot_v1()/version_entries, so no player or playback hooks
# are replaced here.
# EMBYFLOW_QUALITY_VERSION_STATS_V2_2_DISPLAYFIX_RELEASE
# EMBYFLOW_QUALITY_VERSION_STATS_V2_2_DISPLAYFIX_END


# ============================================================================
# EMBYFLOW_ADMIN_SESSION_GUARD_V11_2_START
# Central invariant: Progress for a new PlaySessionId is blocked until a
# successful Playing 2xx for that exact session has been confirmed.
# Reports are serialized in a background worker; GUI remains non-blocking.
# EMBYFLOW_ADMIN_SESSION_GUARD_V11_2_END

# EMBYFLOW_ADMIN_SESSION_PLAYING_V11_1_START
# New PlaySessionIds created by replacement/seek paths now send a Playing
# report immediately after successful service replacement, before Progress.
# Existing V3 async sender remains in use, so GUI stays non-blocking.
# EMBYFLOW_ADMIN_SESSION_PLAYING_V11_1_END

# EMBYFLOW_QUALITY_STALL_GUARD_V3_0_START
# 01.09.2026
# Real-box diagnosis on OpenATV 7.6:
# - a quality/HLS replacement can accept seekTo() (result 0) and immediately
#   report the requested native position, but the native playback clock may then
#   remain frozen at exactly that position.
# - synchronous Emby progress POSTs can time out repeatedly and must never block
#   the Enigma2 GUI thread.
#
# V3.0 therefore adds two narrow safeguards without changing the player skin,
# subtitle/chapter UI, stream codec policy or normal Direct resume:
#   1) Progress/Playing/Stopped reports are sent asynchronously. Concurrent
#      Progress reports are coalesced while one request is in flight.
#   2) After a successful native resume on a quality-transcoding HLS stream, a
#      one-shot watchdog verifies that the native clock is actually advancing.
#      If it is stuck, the same HLS quality is restarted once with the absolute
#      StartTimeTicks so the server performs the resume instead of Enigma2.
# ============================================================================


def _embyflow_v30_log(message):
    try:
        with embyflow_open_log("/tmp/embyflow_quality_stallguard_v3.log", "a") as handle:
            handle.write('%s %s\n' % (time.strftime('%H:%M:%S'), str(message or '')))
    except Exception:
        pass


def _embyflow_v30_send_report_async(self, endpoint, position_ticks=0):
    """
    Non-blocking playback reporter.

    V11.2 SESSION GUARD:
    A Progress report is never allowed to be the first successful report for a
    new PlaySessionId. If that session has not yet received a successful
    /Sessions/Playing (2xx), this worker sends Playing first and only then sends
    Progress. This is centralized here so no seek/restart path can bypass it.
    """
    try:
        if not requests:
            return

        server = (getattr(self, 'playback_info', None) or {}).get('server') or EMBY_SERVER.rstrip('/')
        token = (getattr(self, 'playback_info', None) or {}).get('token') or ''
        payload = self.emby_report_payload(position_ticks)
        if not server or not token or not payload:
            return

        endpoint = str(endpoint or '')
        session_id = str(payload.get('PlaySessionId') or getattr(self, 'play_session_id', '') or '')
        title = str(getattr(self, 'title_text', '') or '')

        if endpoint == 'Playing':
            url = server + '/emby/Sessions/Playing?reqformat=json'
        elif endpoint == 'Progress':
            url = server + '/emby/Sessions/Playing/Progress?reqformat=json'
            payload['EventName'] = 'Pause' if bool(getattr(self, 'paused', False)) else 'TimeUpdate'
        elif endpoint == 'Stopped':
            url = server + '/emby/Sessions/Playing/Stopped?reqformat=json'
            payload['IsPaused'] = True
            payload['PlaybackRate'] = 1
        else:
            url = server + '/emby/Sessions/Playing/' + endpoint + '?reqformat=json'

        headers = {
            'X-Emby-Token': token,
            'X-Emby-Authorization': AUTH_HEADER,
        }
        payload_copy = dict(payload)

        import threading as _embyflow_v30_threading

        # Per-player state, created lazily. All network work stays off the GUI.
        if not hasattr(self, '_embyflow_v112_report_lock'):
            self._embyflow_v112_report_lock = _embyflow_v30_threading.Lock()
        if not hasattr(self, '_embyflow_v112_announced_sessions'):
            self._embyflow_v112_announced_sessions = set()
        if not hasattr(self, '_embyflow_v112_progress_inflight'):
            self._embyflow_v112_progress_inflight = set()

        # Keep at most one Progress request per PlaySessionId in flight.
        if endpoint == 'Progress' and session_id:
            try:
                if session_id in self._embyflow_v112_progress_inflight:
                    return
                self._embyflow_v112_progress_inflight.add(session_id)
            except Exception:
                pass

        def _log_report(kind, response, pos, sid, body=''):
            try:
                with embyflow_open_log('/tmp/embyflow_playback_report.log', 'a') as f:
                    f.write('%s %s status=%s pos=%s session=%s title=%s body=%s\n' % (
                        time.strftime('%H:%M:%S'),
                        kind,
                        getattr(response, 'status_code', '?'),
                        pos,
                        sid,
                        title,
                        body,
                    ))
            except Exception:
                pass

        def _post_report(target_url, target_payload, kind, pos, sid):
            r = embyflow_http_post(
                target_url,
                headers=headers,
                json=target_payload,
                timeout=5,
                verify=True,
            )
            body = ''
            try:
                if getattr(r, 'status_code', 0) >= 400:
                    body = getattr(r, 'text', '')[:220]
            except Exception:
                body = ''
            _log_report(kind, r, pos, sid, body)
            return r

        def worker():
            try:
                # Serialize report order in background. This guarantees that
                # auto-Playing cannot be overtaken by Progress for the same
                # replacement session.
                with self._embyflow_v112_report_lock:
                    announced = self._embyflow_v112_announced_sessions

                    if endpoint == 'Playing':
                        # Explicit Playing may race with a Progress-triggered
                        # auto-Playing. Do not double-register the same session.
                        if session_id and session_id in announced:
                            return
                        r = _post_report(
                            server + '/emby/Sessions/Playing?reqformat=json',
                            payload_copy,
                            'Playing',
                            position_ticks,
                            session_id,
                        )
                        if session_id and 200 <= int(getattr(r, 'status_code', 0) or 0) < 300:
                            announced.add(session_id)
                        return

                    if endpoint == 'Progress':
                        # Central invariant: no Progress before a confirmed
                        # Playing for this exact PlaySessionId.
                        if session_id and session_id not in announced:
                            playing_payload = dict(payload_copy)
                            playing_payload.pop('EventName', None)

                            r_play = _post_report(
                                server + '/emby/Sessions/Playing?reqformat=json',
                                playing_payload,
                                'Playing',
                                position_ticks,
                                session_id,
                            )

                            ok = 200 <= int(getattr(r_play, 'status_code', 0) or 0) < 300

                            # A seek's playService() can return a fraction before
                            # Emby has created the replacement session. Retry
                            # once, still in this background worker, before
                            # allowing Progress through.
                            if not ok:
                                try:
                                    time.sleep(0.30)
                                except Exception:
                                    pass
                                r_play = _post_report(
                                    server + '/emby/Sessions/Playing?reqformat=json',
                                    playing_payload,
                                    'Playing',
                                    position_ticks,
                                    session_id,
                                )
                                ok = 200 <= int(getattr(r_play, 'status_code', 0) or 0) < 300

                            if ok:
                                announced.add(session_id)
                            else:
                                # Do not lie to Emby with Progress for a session
                                # that has not been registered. The next timer
                                # Progress will retry the Playing handshake.
                                try:
                                    with embyflow_open_log('/tmp/embyflow_session_guard_v11_2.log', 'a') as f:
                                        f.write('%s BLOCK_PROGRESS session=%s title=%s pos=%s\n' % (
                                            time.strftime('%H:%M:%S'),
                                            session_id,
                                            title,
                                            position_ticks,
                                        ))
                                except Exception:
                                    pass
                                return

                        _post_report(
                            server + '/emby/Sessions/Playing/Progress?reqformat=json',
                            payload_copy,
                            'Progress',
                            position_ticks,
                            session_id,
                        )
                        return

                    # Stopped / other reports are serialized with the same lock.
                    r = _post_report(
                        url,
                        payload_copy,
                        endpoint,
                        position_ticks,
                        session_id,
                    )

                    if endpoint == 'Stopped' and session_id:
                        try:
                            if 200 <= int(getattr(r, 'status_code', 0) or 0) < 300:
                                announced.discard(session_id)
                        except Exception:
                            pass

            except Exception as error:
                try:
                    with embyflow_open_log('/tmp/embyflow_playback_report_error.log', 'a') as f:
                        f.write('%s %s\n' % (endpoint, str(error)))
                except Exception:
                    pass
            finally:
                if endpoint == 'Progress' and session_id:
                    try:
                        self._embyflow_v112_progress_inflight.discard(session_id)
                    except Exception:
                        pass

        thread = _embyflow_v30_threading.Thread(
            target=worker,
            name='EmbyFlowPlaybackReportV112-%s' % endpoint,
        )
        thread.daemon = True
        thread.start()

    except Exception as error:
        if str(endpoint) == 'Progress':
            try:
                sid = str(getattr(self, 'play_session_id', '') or '')
                if sid and hasattr(self, '_embyflow_v112_progress_inflight'):
                    self._embyflow_v112_progress_inflight.discard(sid)
            except Exception:
                pass
        try:
            with embyflow_open_log('/tmp/embyflow_playback_report_error.log', 'a') as f:
                f.write('%s async-setup %s\n' % (endpoint, str(error)))
        except Exception:
            pass


# The existing progress/start/stop wrappers call this method dynamically, so a
# single method replacement makes all report paths non-blocking.
EmbyFlowMoviePlayer.send_emby_playback_report = _embyflow_v30_send_report_async


def _embyflow_v30_cancel_stall_watchdog(self):
    try:
        timer = getattr(self, '_embyflow_v30_stall_timer', None)
        if timer is not None:
            timer.stop()
    except Exception:
        pass
    self._embyflow_v30_stall_target = None


def _embyflow_v30_stall_check(self):
    target_ticks = getattr(self, '_embyflow_v30_stall_target', None)
    if target_ticks is None:
        return

    target_ticks = max(0, int(target_ticks or 0))
    item_id = str(getattr(self, '_embyflow_v30_stall_item', '') or '')
    quality_mode = str(getattr(self, '_embyflow_v30_stall_quality', '') or '')

    # The user may have left the player or switched content/quality again.
    if item_id and item_id != str(getattr(self, 'item_id', '') or ''):
        _embyflow_v30_cancel_stall_watchdog(self)
        return
    if str(getattr(self, 'embyflow_playback_mode', '') or '') != 'quality-transcoding':
        _embyflow_v30_cancel_stall_watchdog(self)
        return
    if quality_mode and quality_mode != str(getattr(self, 'embyflow_quality_mode_v1', '') or ''):
        _embyflow_v30_cancel_stall_watchdog(self)
        return

    try:
        native_ticks = self.native_position_ticks()
    except Exception:
        native_ticks = None

    # At least ~1.5 seconds of real native clock movement after the resume means
    # the service is alive. Do not touch a healthy quality switch.
    if native_ticks is not None and int(native_ticks) >= target_ticks + 15000000:
        _embyflow_v30_log(
            'OK item=%s quality=%s target=%s native=%s advance=%s' % (
                item_id, quality_mode, target_ticks, int(native_ticks),
                int(native_ticks) - target_ticks,
            )
        )
        _embyflow_v30_cancel_stall_watchdog(self)
        return

    if bool(getattr(self, '_embyflow_v30_stall_fallback_used', False)):
        _embyflow_v30_log(
            'STILL_STALLED item=%s quality=%s target=%s native=%s fallback=already-used' % (
                item_id, quality_mode, target_ticks, str(native_ticks),
            )
        )
        _embyflow_v30_cancel_stall_watchdog(self)
        return

    # One-shot fallback: rebuild the *same* HLS quality, but this time let Emby
    # start the stream at the absolute movie position. No receiver seek follows.
    self._embyflow_v30_stall_fallback_used = True
    _embyflow_v30_log(
        'STALL item=%s quality=%s target=%s native=%s action=server-resume' % (
            item_id, quality_mode, target_ticks, str(native_ticks),
        )
    )

    try:
        source = _embyflow_qs_v1_current_source(self)
        if not source:
            raise RuntimeError('MediaSource nicht verfügbar')

        new_url, new_session_id, playback_mode = _embyflow_qs_v1_build_stream(
            self,
            quality_mode,
            source,
            target_ticks,
        )
        if playback_mode != 'quality-transcoding':
            raise RuntimeError('Fallback ergab unerwarteten Modus %s' % playback_mode)

        new_ref = eServiceReference(
            _embyflow_engine_v11_4_service_type(self),
            0,
            new_url,
        )
        try:
            with embyflow_open_log("/tmp/embyflow_universal_ref_trace.log", "a") as _urt:
                _urt.write("%s site=stallguard_fallback url=%s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), embyflow_sanitize_url_for_log(str(new_ref.getPath() if hasattr(new_ref, "getPath") else ""))))
        except Exception:
            pass
        new_ref.setName(self.title_text)

        # EMBYFLOW_ADMIN_SERVER_SAFETY_V1
        old_play_session_id = str(
            getattr(self, "play_session_id", "") or ""
        )
        self.play_session_id = new_session_id
        self.stream_url = new_url
        self.ref = new_ref
        self.embyflow_playback_mode = playback_mode
        try:
            self.playback_info['url'] = new_url
            self.playback_info['play_session_id'] = new_session_id
            self.playback_info['playback_mode'] = playback_mode
        except Exception:
            pass

        # Server-side HLS resume becomes the absolute content-clock base.
        self.embyflow_v10_stream_base_ticks = int(target_ticks)
        self.embyflow_v10_stream_started_monotonic = None
        self.embyflow_v10_stream_confirmed_playing = False
        self.embyflow_v10_stream_time_mode = None
        self.embyflow_v10_clock_wait_logged = False
        self.pending_seek_started_ticks = None
        self.pending_seek_target_ticks = None
        self.initial_big_seek_target_ticks = None
        self.seek_has_been_used = True
        self.synthetic_position_ticks = int(target_ticks)
        try:
            self.embyflow_v10_stream_restart_issued_monotonic = time.monotonic()
        except Exception:
            self.embyflow_v10_stream_restart_issued_monotonic = None
        try:
            self.play_started_ts = int(time.time()) - int(target_ticks // 10000000)
        except Exception:
            pass

        self._embyflow_stream_replacement_in_progress = True
        try:
            self.cancel_active_encoding(old_play_session_id)
            self.session.nav.playService(new_ref)
        finally:
            self._embyflow_stream_replacement_in_progress = False

        try:
            self.audio_retry_count = 0
            self.audio_timer.start(1200, True)
        except Exception:
            pass

        # EMBYFLOW_ADMIN_SESSION_PLAYING_V11_1_STALL
        try:
            self.send_emby_playback_report('Playing', target_ticks)
        except Exception:
            pass

        try:
            self.send_emby_playback_report('Progress', target_ticks)
        except Exception:
            pass

        _embyflow_v30_log(
            'FALLBACK_STARTED item=%s quality=%s session=%s url=%s' % (
                item_id, quality_mode, new_session_id,
                embyflow_sanitize_url_for_log(new_url),
            )
        )

        # Verify the fallback exactly once as well. We never loop/restart again.
        self._embyflow_v30_stall_target = target_ticks
        try:
            self._embyflow_v30_stall_timer.start(7000, True)
        except Exception:
            pass

    except Exception as error:
        _embyflow_v30_log(
            'FALLBACK_ERROR item=%s quality=%s error=%s' % (
                item_id, quality_mode, str(error),
            )
        )
        _embyflow_v30_cancel_stall_watchdog(self)


def _embyflow_v30_schedule_stall_watchdog(self, target_ticks):
    target_ticks = max(0, int(target_ticks or 0))
    if target_ticks <= 0:
        return

    self._embyflow_v30_stall_target = target_ticks
    self._embyflow_v30_stall_item = str(getattr(self, 'item_id', '') or '')
    self._embyflow_v30_stall_quality = str(getattr(self, 'embyflow_quality_mode_v1', '') or '')
    self._embyflow_v30_stall_fallback_used = False

    if not hasattr(self, '_embyflow_v30_stall_timer'):
        self._embyflow_v30_stall_timer = eTimer()
        try:
            self._embyflow_v30_stall_timer.callback.append(
                lambda: _embyflow_v30_stall_check(self)
            )
        except Exception:
            try:
                self._embyflow_v30_stall_timer.timeout.connect(
                    lambda: _embyflow_v30_stall_check(self)
                )
            except Exception:
                pass

    try:
        self._embyflow_v30_stall_timer.stop()
    except Exception:
        pass
    try:
        self._embyflow_v30_stall_timer.start(6000, True)
        _embyflow_v30_log(
            'WATCH item=%s quality=%s target=%s delay_ms=6000' % (
                self._embyflow_v30_stall_item,
                self._embyflow_v30_stall_quality,
                target_ticks,
            )
        )
    except Exception as error:
        _embyflow_v30_log('WATCH_ERROR %s' % str(error))


_EMBYFLOW_V30_ORIGINAL_RESUME_FINALIZE = _embyflow_qs_v2_resume_finalize


def _embyflow_v30_resume_finalize(self, target_ticks):
    _EMBYFLOW_V30_ORIGINAL_RESUME_FINALIZE(self, target_ticks)
    try:
        if (
            int(target_ticks or 0) > 0
            and str(getattr(self, 'embyflow_playback_mode', '') or '') == 'quality-transcoding'
        ):
            _embyflow_v30_schedule_stall_watchdog(self, target_ticks)
    except Exception as error:
        _embyflow_v30_log('FINALIZE_WATCH_ERROR %s' % str(error))


# _embyflow_qs_v2_resume_tick resolves this global at runtime.
_embyflow_qs_v2_resume_finalize = _embyflow_v30_resume_finalize

