def _embyflow_v8_refresh_server_cards(self):
    _EMBYFLOW_V8_PREV_REFRESH_CARDS(self)
    try:
        card_index = self.focus if self.focus in (0, 1, 2, 3) else self.selected_server_index
        x, y = self.SERVER_CARD_POSITIONS[card_index]
        self["server_focus_border"].instance.move(EFP(x, y))
        self["server_focus_border"].instance.resize(EFS(348, 236))
        self["server_focus_inner"].instance.move(EFP(x + 6, y + 6))
        self["server_focus_inner"].instance.resize(EFS(336, 224))
    except Exception:
        pass

EmbyFlowConnectionWizard._refresh_server_cards = _embyflow_v8_refresh_server_cards


def _embyflow_v8_focus_target(self):
    if self.focus == 4:
        return (515, 498)
    if self.focus == 5:
        return (515, 568)
    if self.focus == 6:
        return (515, 620)
    return (515, 668)

EmbyFlowConnectionWizard._focus_target = _embyflow_v8_focus_target
