_EMBYFLOW_V9_ASSET_DIR = "/tmp/embyflow_v9_assets"
_EMBYFLOW_V9_ASSETS = {
    'v9_bg.png': '',
    'v9_focus_card.png': '',
    'v9_focus_input.png': '',
    'v9_focus_save.png': '',
    'v9_focus_login.png': '',
    'v9_checkbox_on.png': '',
    'v9_checkbox_off.png': 'iVBORw0KGgoAAAANSUhEUgAAABoAAAAaCAYAAACpSkzOAAAAXklEQVR4nGNgGAVkAkZsgsrPXvynxNC7UhIY5jJR2xJcZjBiU/BYQ+8bJRbJ3rjExcCA6jMMH9EKjFo0atGoRaMWjVo0FC3CqAmpUfExMGDWshg+wlYNU2rJKKAIAAD/1hgmm/OhxwAAAABJRU5ErkJggg==',
}

def _embyflow_v9_install_assets():
    try:
        import base64 as _v9_base64
        if not os.path.isdir(_EMBYFLOW_V9_ASSET_DIR):
            os.makedirs(_EMBYFLOW_V9_ASSET_DIR)
        for _name, _payload in _EMBYFLOW_V9_ASSETS.items():
            _path = os.path.join(_EMBYFLOW_V9_ASSET_DIR, _name)
            _raw = _v9_base64.b64decode(_payload)
            try:
                _same = os.path.exists(_path) and os.path.getsize(_path) == len(_raw)
            except Exception:
                _same = False
            if not _same:
                with open(_path, "wb") as _fh:
                    _fh.write(_raw)
        return True
    except Exception as _error:
        try:
            with open("/tmp/embyflow_v9_asset_error.log", "a") as _fh:
                _fh.write(str(_error) + "\n")
        except Exception:
            pass
        return False

_EMBYFLOW_V9_ASSETS_READY = _embyflow_v9_install_assets()

