def _embyflow_v11_refresh_focus_marker(self):
    # V11: exactly one visible yellow arrow for the current login control.
    for _name in ("v9_focus_input","v9_focus_save","v9_focus_login"):
        try:
            self[_name].hide()
        except Exception:
            pass
    try:
        if self.focus < 4:
            self["focus_marker"].hide()
            return
        _positions = {
            4: (515, 500),  # username
            5: (515, 595),  # password
            6: (515, 670),  # save password
            7: (515, 743),  # login
            8: (940, 743),  # manual / advanced
        }
        _x, _y = _positions.get(self.focus, (515, 500))
        self["focus_marker"].setText(">")
        self["focus_marker"].instance.move(EFP(_x, _y))
        self["focus_marker"].instance.resize(EFS(30, 42))
        self["focus_marker"].show()
    except Exception:
        pass
EmbyFlowConnectionWizard._refresh_focus_marker = _embyflow_v11_refresh_focus_marker

