# EMBYFLOW_ADMIN_SAFETY_V11_7_1_EMBY_THUMBNAILSET_CANONICAL_START
#
# Chapter-preview architecture switch:
# - normal user path consumes Emby's already-prepared Video Preview Thumbnails;
# - exactly one read-only ThumbnailSet lookup is performed per chapter screen;
# - only the selected chapter requests an image; neighbours stay cache-only;
# - native tagged Chapter artwork is the secondary server-side fallback;
# - receiver ffmpeg and server-transcode frame extraction are NOT part of the
#   normal V11.7 chapter-preview path;
# - old V17.5.3 background chapter prewarm is disabled to avoid unsolicited
#   server requests while a movie is merely playing.
#
# All server interaction introduced here is GET-only.

EMBYFLOW_V11_7_TRICKPLAY_SET_WIDTH = 400
EMBYFLOW_V11_7_TRICKPLAY_SET_TIMEOUT = 2.5
EMBYFLOW_V11_7_TRICKPLAY_IMAGE_TIMEOUT = 3.0

# Defense in depth: V11.7 does not use local ffmpeg for chapter frames.
EMBYFLOW_ALLOW_SAFE_DIRECT_CHAPTER_FRAME_FALLBACK = False


def _embyflow_v11_7_thumbnailset(self):
    """Load Emby's prepared trickplay index once for this chapter screen."""
    if bool(
        getattr(
            self,
            "_embyflow_v11_7_thumbnailset_loaded",
            False,
        )
    ):
        return list(
            getattr(
                self,
                "_embyflow_v11_7_thumbnailset_entries",
                [],
            )
            or []
        )

    # Mark before I/O. A failed/empty lookup is not retried repeatedly while
    # the user navigates the same chapter screen.
    self._embyflow_v11_7_thumbnailset_loaded = True
    self._embyflow_v11_7_thumbnailset_entries = []
    self._embyflow_v11_7_thumbnailset_aspect = 0.0

    # V11.7 deliberately performs no background preview traffic.
    if bool(
        getattr(
            self,
            "_embyflow_preview_background_prewarm_v11_6",
            False,
        )
    ):
        return []

    if not requests:
        return []

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(
        getattr(
            self.player,
            "item_id",
            "",
        )
        or ""
    ).strip()
    media_source_id = str(
        getattr(
            self.player,
            "media_source_id",
            "",
        )
        or ""
    ).strip()

    if not server or not token or not item_id:
        return []

    url = "%s/Items/%s/ThumbnailSet" % (
        str(server).rstrip("/"),
        item_id,
    )
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
    }
    # V11.7.1 controlled DEV test: ask for the title-level prepared preview
    # index without constraining it to the player's MediaSourceId. Emby clients
    # in the field use several valid request shapes; after V11.7 returned an
    # empty set with MediaSourceId on this server, this is deliberately the
    # single alternate shape we test. Width=400 matches Emby Web usage.
    params = {
        "Width": str(EMBYFLOW_V11_7_TRICKPLAY_SET_WIDTH),
    }

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_TRICKPLAY_SET_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_1_thumbnailset_http_error",
                item=item_id,
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return []

    status = int(
        getattr(
            response,
            "status_code",
            0,
        )
        or 0
    )
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_1_thumbnailset_miss",
                item=item_id,
                status=status,
            )
        except Exception:
            pass
        return []

    try:
        payload = response.json()
    except Exception:
        try:
            raw = getattr(response, "content", b"") or b""
            if not isinstance(raw, str):
                raw = raw.decode("utf-8", "replace")
            payload = json.loads(raw)
        except Exception as error:
            try:
                self._preview_v6_log(
                    "v11_7_1_thumbnailset_invalid_json",
                    item=item_id,
                    status=status,
                    error_type=type(error).__name__,
                )
            except Exception:
                pass
            payload = {}

    if not isinstance(payload, dict):
        try:
            self._preview_v6_log(
                "v11_7_1_thumbnailset_invalid_payload",
                item=item_id,
                status=status,
                payload_type=type(payload).__name__,
            )
        except Exception:
            pass
        return []

    try:
        self._embyflow_v11_7_thumbnailset_aspect = float(
            payload.get("AspectRatio")
            or 0.0
        )
    except Exception:
        self._embyflow_v11_7_thumbnailset_aspect = 0.0

    entries = []
    for raw_entry in list(payload.get("Thumbnails") or []):
        if not isinstance(raw_entry, dict):
            continue
        try:
            position_ticks = int(
                raw_entry.get("PositionTicks")
                or 0
            )
        except Exception:
            continue
        if position_ticks < 0:
            continue
        entries.append({
            "PositionTicks": position_ticks,
            "ImageTag": str(
                raw_entry.get("ImageTag")
                or ""
            ).strip(),
        })

    entries.sort(
        key=lambda entry: int(
            entry.get("PositionTicks")
            or 0
        )
    )
    self._embyflow_v11_7_thumbnailset_entries = entries

    try:
        self._preview_v6_log(
            "v11_7_1_thumbnailset_ok" if entries else "v11_7_1_thumbnailset_empty",
            item=item_id,
            count=len(entries),
            player_has_media_source=int(bool(media_source_id)),
            thumbnailset_query="width_only",
        )
    except Exception:
        pass

    return list(entries)


def _embyflow_v11_7_nearest_thumbnail(self, chapter):
    entries = _embyflow_v11_7_thumbnailset(self)
    if not entries:
        return None

    try:
        target_ticks = max(
            0,
            int(
                chapter.get("StartPositionTicks")
                or 0
            ),
        )
    except Exception:
        target_ticks = 0

    # Nearest prepared preview. For an exact tie prefer the image at/after the
    # chapter boundary, reducing the chance of showing the previous scene.
    try:
        return min(
            entries,
            key=lambda entry: (
                abs(
                    int(entry.get("PositionTicks") or 0)
                    - target_ticks
                ),
                0
                if int(entry.get("PositionTicks") or 0)
                >= target_ticks
                else 1,
            ),
        )
    except Exception:
        return None


def _embyflow_v11_7_download_trickplay(self, chapter, path):
    if not path or not requests:
        return ""

    if bool(
        getattr(
            self,
            "_embyflow_preview_background_prewarm_v11_6",
            False,
        )
    ):
        return ""

    thumbnail = _embyflow_v11_7_nearest_thumbnail(
        self,
        chapter,
    )
    if not isinstance(thumbnail, dict):
        return ""

    try:
        position_ticks = max(
            0,
            int(
                thumbnail.get("PositionTicks")
                or 0
            ),
        )
    except Exception:
        return ""

    image_tag = str(
        thumbnail.get("ImageTag")
        or ""
    ).strip()

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(
        getattr(
            self.player,
            "item_id",
            "",
        )
        or ""
    ).strip()
    media_source_id = str(
        getattr(
            self.player,
            "media_source_id",
            "",
        )
        or ""
    ).strip()

    if not server or not token or not item_id:
        return ""

    url = "%s/Items/%s/Images/Thumbnail" % (
        str(server).rstrip("/"),
        item_id,
    )
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
    }
    params = {
        "MaxWidth": str(EMBYFLOW_V11_7_TRICKPLAY_SET_WIDTH),
        "Quality": "86",
        "PositionTicks": str(position_ticks),
    }
    if image_tag:
        params["Tag"] = image_tag
    if media_source_id:
        params["MediaSourceId"] = media_source_id

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_TRICKPLAY_IMAGE_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_1_trickplay_http_error",
                item=item_id,
                chapter=str(
                    chapter.get("_embyflow_image_index")
                    or 0
                ),
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return ""

    status = int(
        getattr(
            response,
            "status_code",
            0,
        )
        or 0
    )
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_1_trickplay_miss",
                item=item_id,
                chapter=str(
                    chapter.get("_embyflow_image_index")
                    or 0
                ),
                status=status,
            )
        except Exception:
            pass
        return ""

    content = getattr(
        response,
        "content",
        b"",
    ) or b""
    content_type = str(
        response.headers.get(
            "Content-Type",
            "",
        )
        if hasattr(response, "headers")
        else ""
    )

    if (
        len(content) <= 500
        or (
            content_type
            and not content_type.startswith("image/")
        )
    ):
        try:
            self._preview_v6_log(
                "v11_7_1_trickplay_invalid_image",
                item=item_id,
                chapter=str(chapter.get("_embyflow_image_index") or 0),
                status=status,
                bytes=len(content),
                content_type=content_type[:80],
            )
        except Exception:
            pass
        return ""

    temporary = path + ".trickplay_v11_7.tmp"
    try:
        with open(temporary, "wb") as handle:
            handle.write(content)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass

        self._preview_atomic_replace(
            temporary,
            path,
        )

        if self._preview_file_valid(path):
            try:
                self._preview_v6_log(
                    "v11_7_1_trickplay_ok",
                    item=item_id,
                    chapter=str(
                        chapter.get("_embyflow_image_index")
                        or 0
                    ),
                    position_ticks=position_ticks,
                    bytes=len(content),
                )
            except Exception:
                pass
            return path
        return ""
    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_v11_7_obtain_preview(self, chapter, path):
    """V11.7 normal path: cache -> Emby trickplay -> tagged Chapter -> placeholder."""
    if not path:
        return ""

    if self._preview_file_valid(path):
        return path

    # No V11.7 preview generation or download runs as playback background work.
    if bool(
        getattr(
            self,
            "_embyflow_preview_background_prewarm_v11_6",
            False,
        )
    ):
        return ""

    trickplay = _embyflow_v11_7_download_trickplay(
        self,
        chapter,
        path,
    )
    if self._preview_file_valid(trickplay):
        return trickplay

    # Secondary server-prepared source only when Emby explicitly advertises a
    # native chapter ImageTag. V11.7 does not blind-probe untagged chapters.
    if str(chapter.get("ImageTag") or "").strip():
        native = self._download_preview(
            chapter,
            path,
            allow_untagged=False,
        )
        if self._preview_file_valid(native):
            return native

    # Final fallback is purely local and creates no server request.
    return self._preview_v6_make_placeholder(
        chapter
    )


def _embyflow_v11_7_no_background_prewarm(
    player,
    delay_seconds=5.0,
):
    # Intentional no-op. Prepared Emby trickplay assets are consumed on demand
    # by the visible chapter screen instead of generating/fetching a title-wide
    # cache during playback.
    return None


# The V17.5.3 player-init wrapper resolves this global at runtime, so replacing
# it here prevents the old prewarm thread from starting for future players.
_embyflow_chapter_start_prewarm_v17_5_3 = (
    _embyflow_v11_7_no_background_prewarm
)

# Final method precedence: bypass the V17.5.3 locked wrapper that captured the
# old V11.6 ffmpeg-capable obtain method.
EmbyFlowChapterNavigator._obtain_preview = (
    _embyflow_v11_7_obtain_preview
)

# Expose helpers on the class for diagnostics/unit-style offline inspection.
EmbyFlowChapterNavigator._thumbnailset_v11_7 = (
    _embyflow_v11_7_thumbnailset
)
EmbyFlowChapterNavigator._nearest_thumbnail_v11_7 = (
    _embyflow_v11_7_nearest_thumbnail
)
EmbyFlowChapterNavigator._download_trickplay_v11_7 = (
    _embyflow_v11_7_download_trickplay
)

# EMBYFLOW_ADMIN_SAFETY_V11_7_1_EMBY_THUMBNAILSET_CANONICAL_DEVLIVE_RELEASE
# GET 1: /Items/{itemId}/ThumbnailSet?Width=400  (no MediaSourceId)
# GET 2: /Items/{itemId}/Images/Thumbnail?PositionTicks=...&MaxWidth=400...
# No POST/DELETE. No StartTimeTicks. No new PlaySessionId. No video stream open.
# No receiver ffmpeg. No background chapter prewarm.
# EMBYFLOW_ADMIN_SAFETY_V11_7_1_EMBY_THUMBNAILSET_CANONICAL_DEVLIVE_END

# EMBYFLOW_ADMIN_SAFETY_V11_7_2_SERVER_ASSETS_START
# Solution path: prepared Emby assets only.
# 1) local cache
# 2) prepared ThumbnailSet/Images/Thumbnail (V11.7.1)
# 3) native Emby Chapter image, including one untagged foreground probe
# 4) local visual placeholder
# No ffmpeg, no video stream open, no POST/DELETE, no background prewarm.

EMBYFLOW_V11_7_2_NATIVE_WIDTH = 400
EMBYFLOW_V11_7_2_NATIVE_HEIGHT = 225
EMBYFLOW_V11_7_2_NATIVE_TIMEOUT = 1.5


def _embyflow_v11_7_2_download_native_chapter(self, chapter, path):
    if not path or not requests:
        return ""

    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""

    try:
        image_index = int(chapter.get("_embyflow_image_index") or 0)
    except Exception:
        image_index = 0

    attempted = getattr(self, "_embyflow_v11_7_2_native_attempted", None)
    if not isinstance(attempted, set):
        attempted = set()
        self._embyflow_v11_7_2_native_attempted = attempted
    if image_index in attempted:
        return ""
    attempted.add(image_index)

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(getattr(self.player, "item_id", "") or "").strip()
    if not server or not token or not item_id:
        return ""

    image_tag = str(chapter.get("ImageTag") or "").strip()
    url = "%s/Items/%s/Images/Chapter/%d" % (
        str(server).rstrip("/"),
        item_id,
        image_index,
    )
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
    }
    params = {
        "MaxWidth": str(EMBYFLOW_V11_7_2_NATIVE_WIDTH),
        "MaxHeight": str(EMBYFLOW_V11_7_2_NATIVE_HEIGHT),
        "Quality": "86",
    }
    if image_tag:
        params["Tag"] = image_tag

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_2_NATIVE_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_2_native_http_error",
                item=item_id,
                chapter=image_index,
                tagged=int(bool(image_tag)),
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return ""

    status = int(getattr(response, "status_code", 0) or 0)
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_2_native_miss",
                item=item_id,
                chapter=image_index,
                tagged=int(bool(image_tag)),
                status=status,
            )
        except Exception:
            pass
        return ""

    content = getattr(response, "content", b"") or b""
    content_type = str(
        response.headers.get("Content-Type", "")
        if hasattr(response, "headers") else ""
    )
    if len(content) <= 500 or (content_type and not content_type.startswith("image/")):
        try:
            self._preview_v6_log(
                "v11_7_2_native_invalid",
                item=item_id,
                chapter=image_index,
                bytes=len(content),
                content_type=content_type[:80],
            )
        except Exception:
            pass
        return ""

    temporary = path + ".native.v11_7_2.tmp"
    try:
        with open(temporary, "wb") as handle:
            handle.write(content)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass

        self._preview_atomic_replace(temporary, path)
        if self._preview_file_valid(path):
            try:
                self._preview_v6_log(
                    "v11_7_2_native_ok",
                    item=item_id,
                    chapter=image_index,
                    tagged=int(bool(image_tag)),
                    bytes=len(content),
                )
            except Exception:
                pass
            return path
        return ""
    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_v11_7_2_obtain_preview(self, chapter, path):
    if not path:
        return ""

    if self._preview_file_valid(path):
        return path

    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""

    # First use Emby's VPT/ThumbnailSet when it exists.
    trickplay = _embyflow_v11_7_download_trickplay(self, chapter, path)
    if self._preview_file_valid(trickplay):
        return trickplay

    # If the server has no VPT set, use Emby's native Chapter image endpoint.
    # This is a documented image type and does not decode the movie on the box.
    native = _embyflow_v11_7_2_download_native_chapter(self, chapter, path)
    if self._preview_file_valid(native):
        return native

    return self._preview_v6_make_placeholder(chapter)


_EMBYFLOW_V11_7_2_POLL_ORIGINAL = EmbyFlowChapterNavigator._poll_async_v17


def _embyflow_v11_7_2_poll(self):
    result = _EMBYFLOW_V11_7_2_POLL_ORIGINAL(self)
    try:
        if (
            not bool(getattr(self, "_carousel_busy", False))
            and not list(getattr(self, "_carousel_queue", []) or [])
            and str(self["status_text"].getText() or "") == "Kapitelbild wird vorbereitet …"
        ):
            self["status_text"].setText("")
    except Exception:
        pass
    return result


EmbyFlowChapterNavigator._obtain_preview = _embyflow_v11_7_2_obtain_preview
EmbyFlowChapterNavigator._download_native_chapter_v11_7_2 = _embyflow_v11_7_2_download_native_chapter
EmbyFlowChapterNavigator._poll_async_v17 = _embyflow_v11_7_2_poll

# EMBYFLOW_ADMIN_SAFETY_V11_7_2_SERVER_ASSETS_DEVLIVE_RELEASE
# GET path A: /Items/{itemId}/ThumbnailSet?Width=400
# GET path B: /Items/{itemId}/Images/Thumbnail?PositionTicks=... (only when A has entries)
# GET path C: /Items/{itemId}/Images/Chapter/{index}?MaxWidth=400&MaxHeight=225 (fallback)
# No api_key in query string; token stays in request headers.
# No ffmpeg. No video stream open. No POST/DELETE. No background prewarm.
# EMBYFLOW_ADMIN_SAFETY_V11_7_2_SERVER_ASSETS_END


# EMBYFLOW_ADMIN_SAFETY_V11_7_3_NATIVE_CHAPTER_EXACT_START
# Exact Emby-style native chapter asset path observed in Emby clients/server logs:
# - enrich missing chapter ImageTag once via Fields=Chapters;
# - GET /Items/{itemId}/Images/Chapter/{index}
#   ?maxWidth=400&tag=...&mediaSourceId=...&quality=90
# - no ffmpeg, no movie seek, no POST/DELETE, no retry cascade.

EMBYFLOW_V11_7_3_NATIVE_WIDTH = 400
EMBYFLOW_V11_7_3_METADATA_TIMEOUT = 2.5
EMBYFLOW_V11_7_3_IMAGE_TIMEOUT = 3.0


def _embyflow_v11_7_3_chapter_asset_map(self):
    cached = getattr(self, "_embyflow_v11_7_3_asset_map", None)
    if isinstance(cached, dict):
        return cached

    # Mark as loaded before I/O so an error is not retried for every key press.
    self._embyflow_v11_7_3_asset_map = {}

    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return {}
    if not requests:
        return {}

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(getattr(self.player, "item_id", "") or "").strip()
    info = getattr(self.player, "playback_info", None) or {}
    user_id = str(info.get("user_id") or "").strip()

    if not server or not token or not item_id:
        return {}

    if user_id:
        url = "%s/Users/%s/Items/%s" % (
            str(server).rstrip("/"),
            user_id,
            item_id,
        )
        endpoint = "user_item"
    else:
        url = "%s/Items/%s" % (
            str(server).rstrip("/"),
            item_id,
        )
        endpoint = "item"

    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
    }

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params={"Fields": "Chapters"},
            timeout=EMBYFLOW_V11_7_3_METADATA_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_3_chaptermeta_http_error",
                item=item_id,
                endpoint=endpoint,
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return {}

    status = int(getattr(response, "status_code", 0) or 0)
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_3_chaptermeta_miss",
                item=item_id,
                endpoint=endpoint,
                status=status,
            )
        except Exception:
            pass
        return {}

    try:
        data = response.json() or {}
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_3_chaptermeta_invalid_json",
                item=item_id,
                endpoint=endpoint,
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return {}

    raw_chapters = list(data.get("Chapters") or data.get("chapters") or [])
    assets = {}
    tagged = 0
    for raw_index, raw in enumerate(raw_chapters):
        if not isinstance(raw, dict):
            continue
        marker_type = str(raw.get("MarkerType") or "").strip().lower()
        if marker_type and marker_type != "chapter":
            continue
        try:
            ticks = max(0, int(raw.get("StartPositionTicks") or 0))
        except Exception:
            continue
        try:
            image_index = int(raw.get("ChapterIndex"))
        except Exception:
            image_index = raw_index
        tag = str(raw.get("ImageTag") or "").strip()
        if tag:
            tagged += 1
        assets[ticks] = {
            "index": max(0, image_index),
            "tag": tag,
        }

    self._embyflow_v11_7_3_asset_map = assets
    try:
        self._preview_v6_log(
            "v11_7_3_chaptermeta_ok",
            item=item_id,
            endpoint=endpoint,
            count=len(assets),
            tagged=tagged,
        )
    except Exception:
        pass
    return assets


def _embyflow_v11_7_3_resolve_native_asset(self, chapter):
    try:
        ticks = max(0, int(chapter.get("StartPositionTicks") or 0))
    except Exception:
        ticks = 0

    try:
        image_index = max(0, int(chapter.get("_embyflow_image_index") or 0))
    except Exception:
        image_index = 0
    tag = str(chapter.get("ImageTag") or "").strip()

    # If local chapter metadata already advertises an image, trust it.
    if tag:
        return image_index, tag

    assets = _embyflow_v11_7_3_chapter_asset_map(self)
    asset = assets.get(ticks) if isinstance(assets, dict) else None
    if isinstance(asset, dict):
        try:
            image_index = max(0, int(asset.get("index") or 0))
        except Exception:
            pass
        tag = str(asset.get("tag") or "").strip()
        try:
            chapter["_embyflow_image_index"] = image_index
            if tag:
                chapter["ImageTag"] = tag
        except Exception:
            pass

    return image_index, tag


def _embyflow_v11_7_3_download_native_chapter(self, chapter, path):
    if not path or not requests:
        return ""
    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""

    try:
        image_index, image_tag = _embyflow_v11_7_3_resolve_native_asset(self, chapter)
    except Exception:
        image_index, image_tag = 0, ""

    attempted = getattr(self, "_embyflow_v11_7_3_native_attempted", None)
    if not isinstance(attempted, set):
        attempted = set()
        self._embyflow_v11_7_3_native_attempted = attempted

    attempt_key = (int(image_index), str(image_tag or ""))
    if attempt_key in attempted:
        return ""
    attempted.add(attempt_key)

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(getattr(self.player, "item_id", "") or "").strip()
    media_source_id = str(getattr(self.player, "media_source_id", "") or "").strip()
    if not media_source_id:
        try:
            media_source_id = str((getattr(self.player, "playback_info", None) or {}).get("media_source_id") or "").strip()
        except Exception:
            media_source_id = ""

    if not server or not token or not item_id:
        return ""

    url = "%s/Items/%s/Images/Chapter/%d" % (
        str(server).rstrip("/"),
        item_id,
        int(image_index),
    )
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
    }
    params = {
        "maxWidth": str(EMBYFLOW_V11_7_3_NATIVE_WIDTH),
        "quality": "90",
    }
    if image_tag:
        params["tag"] = image_tag
    if media_source_id:
        params["mediaSourceId"] = media_source_id

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_3_IMAGE_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_3_native_http_error",
                item=item_id,
                chapter=int(image_index),
                tagged=int(bool(image_tag)),
                has_media_source=int(bool(media_source_id)),
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return ""

    status = int(getattr(response, "status_code", 0) or 0)
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_3_native_miss",
                item=item_id,
                chapter=int(image_index),
                tagged=int(bool(image_tag)),
                has_media_source=int(bool(media_source_id)),
                status=status,
            )
        except Exception:
            pass
        return ""

    content = getattr(response, "content", b"") or b""
    content_type = str(
        response.headers.get("Content-Type", "")
        if hasattr(response, "headers") else ""
    )
    if len(content) <= 500 or (content_type and not content_type.startswith("image/")):
        try:
            self._preview_v6_log(
                "v11_7_3_native_invalid",
                item=item_id,
                chapter=int(image_index),
                bytes=len(content),
                content_type=content_type[:80],
            )
        except Exception:
            pass
        return ""

    temporary = path + ".native.v11_7_3.tmp"
    try:
        with open(temporary, "wb") as handle:
            handle.write(content)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass

        self._preview_atomic_replace(temporary, path)
        if self._preview_file_valid(path):
            try:
                self._preview_v6_log(
                    "v11_7_3_native_ok",
                    item=item_id,
                    chapter=int(image_index),
                    tagged=int(bool(image_tag)),
                    has_media_source=int(bool(media_source_id)),
                    bytes=len(content),
                )
            except Exception:
                pass
            return path
        return ""
    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_v11_7_3_obtain_preview(self, chapter, path):
    if not path:
        return ""
    if self._preview_file_valid(path):
        return path
    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""

    # Prepared VPT remains first choice when the server has it.
    trickplay = _embyflow_v11_7_download_trickplay(self, chapter, path)
    if self._preview_file_valid(trickplay):
        return trickplay

    # Exact native chapter-image request used by Emby clients.
    native = _embyflow_v11_7_3_download_native_chapter(self, chapter, path)
    if self._preview_file_valid(native):
        return native

    return self._preview_v6_make_placeholder(chapter)


EmbyFlowChapterNavigator._obtain_preview = _embyflow_v11_7_3_obtain_preview
EmbyFlowChapterNavigator._chapter_asset_map_v11_7_3 = _embyflow_v11_7_3_chapter_asset_map
EmbyFlowChapterNavigator._download_native_chapter_v11_7_3 = _embyflow_v11_7_3_download_native_chapter

# EMBYFLOW_ADMIN_SAFETY_V11_7_3_NATIVE_CHAPTER_EXACT_DEVLIVE_RELEASE
# Native request now mirrors Emby client/server log shape:
# /Items/{itemId}/Images/Chapter/{index}?maxWidth=400&tag=...&mediaSourceId=...&quality=90
# Missing ImageTag is enriched once from Fields=Chapters using header auth only.
# No api_key query parameter in V11.7.3 requests.
# No ffmpeg. No video stream open. No POST/DELETE. No background prewarm.
# EMBYFLOW_ADMIN_SAFETY_V11_7_3_NATIVE_CHAPTER_EXACT_END


# EMBYFLOW_ADMIN_SAFETY_V11_7_4_NATIVE_CHAPTER_TIMEOUTFIX_START
# Verified fix after DEV-LIVE: V11.7.3 aborted valid Emby chapter image GETs after 3.0 s.
# Emby server logs show native /Images/Chapter/{index} requests can legitimately take ~9.5 s.
# V11.7.4 therefore:
# - uses native prepared Chapter images FIRST for chapter navigation;
# - forces JPEG output for Enigma2 compatibility;
# - allows one native GET up to 15 s in the worker thread (GUI stays responsive);
# - only falls back to ThumbnailSet when no native chapter image is obtained;
# - no ffmpeg, no video seek, no POST/DELETE, no retry cascade.

EMBYFLOW_V11_7_4_NATIVE_WIDTH = 400
EMBYFLOW_V11_7_4_IMAGE_TIMEOUT = 15.0
EMBYFLOW_V11_7_4_METADATA_TIMEOUT = 8.0

# Let the existing chapter-metadata enrichment wait long enough as well.
EMBYFLOW_V11_7_3_METADATA_TIMEOUT = EMBYFLOW_V11_7_4_METADATA_TIMEOUT


def _embyflow_v11_7_4_download_native_chapter(self, chapter, path):
    if not path or not requests:
        return ""
    # Prepared Emby chapter JPEGs are safe to prewarm: this performs only a
    # read-only image GET and never opens/decodes the video stream.

    try:
        image_index, image_tag = _embyflow_v11_7_3_resolve_native_asset(self, chapter)
    except Exception:
        try:
            image_index = max(0, int(chapter.get("_embyflow_image_index") or 0))
        except Exception:
            image_index = 0
        image_tag = str(chapter.get("ImageTag") or "").strip()

    attempted = getattr(self, "_embyflow_v11_7_4_native_attempted", None)
    if not isinstance(attempted, set):
        attempted = set()
        self._embyflow_v11_7_4_native_attempted = attempted
    attempt_key = (int(image_index), str(image_tag or ""))
    if attempt_key in attempted:
        return ""
    attempted.add(attempt_key)

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(getattr(self.player, "item_id", "") or "").strip()
    media_source_id = str(getattr(self.player, "media_source_id", "") or "").strip()
    if not media_source_id:
        try:
            media_source_id = str((getattr(self.player, "playback_info", None) or {}).get("media_source_id") or "").strip()
        except Exception:
            media_source_id = ""

    if not server or not token or not item_id:
        return ""

    url = "%s/Items/%s/Images/Chapter/%d" % (
        str(server).rstrip("/"), item_id, int(image_index)
    )
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
        "Accept": "image/jpeg,image/png,*/*;q=0.8",
    }
    params = {
        "maxWidth": str(EMBYFLOW_V11_7_4_NATIVE_WIDTH),
        "quality": "90",
        "format": "jpg",
    }
    if image_tag:
        params["tag"] = image_tag
    if media_source_id:
        params["mediaSourceId"] = media_source_id

    started = time.time()
    try:
        self._preview_v6_log(
            "v11_7_4_native_start",
            item=item_id,
            chapter=int(image_index),
            tagged=int(bool(image_tag)),
            has_media_source=int(bool(media_source_id)),
            timeout_s=int(EMBYFLOW_V11_7_4_IMAGE_TIMEOUT),
        )
    except Exception:
        pass

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_4_IMAGE_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        elapsed_ms = int(max(0.0, time.time() - started) * 1000.0)
        try:
            self._preview_v6_log(
                "v11_7_4_native_http_error",
                item=item_id,
                chapter=int(image_index),
                tagged=int(bool(image_tag)),
                has_media_source=int(bool(media_source_id)),
                elapsed_ms=elapsed_ms,
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return ""

    elapsed_ms = int(max(0.0, time.time() - started) * 1000.0)
    status = int(getattr(response, "status_code", 0) or 0)
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_4_native_miss",
                item=item_id,
                chapter=int(image_index),
                tagged=int(bool(image_tag)),
                has_media_source=int(bool(media_source_id)),
                elapsed_ms=elapsed_ms,
                status=status,
            )
        except Exception:
            pass
        return ""

    content = getattr(response, "content", b"") or b""
    content_type = str(
        response.headers.get("Content-Type", "")
        if hasattr(response, "headers") else ""
    )
    # Accept JPEG/PNG signatures; format=jpg should normally produce JPEG.
    is_jpeg = content.startswith(b"\xff\xd8")
    is_png = content.startswith(b"\x89PNG\r\n\x1a\n")
    if len(content) <= 500 or not (is_jpeg or is_png):
        try:
            self._preview_v6_log(
                "v11_7_4_native_invalid",
                item=item_id,
                chapter=int(image_index),
                bytes=len(content),
                content_type=content_type[:80],
                elapsed_ms=elapsed_ms,
            )
        except Exception:
            pass
        return ""

    temporary = path + ".native.v11_7_4.tmp"
    try:
        with open(temporary, "wb") as handle:
            handle.write(content)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass
        self._preview_atomic_replace(temporary, path)
        if self._preview_file_valid(path):
            try:
                self._preview_v6_log(
                    "v11_7_4_native_ok",
                    item=item_id,
                    chapter=int(image_index),
                    tagged=int(bool(image_tag)),
                    has_media_source=int(bool(media_source_id)),
                    bytes=len(content),
                    elapsed_ms=elapsed_ms,
                )
            except Exception:
                pass
            return path
        return ""
    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_v11_7_4_obtain_preview(self, chapter, path):
    if not path:
        return ""
    if self._preview_file_valid(path):
        return path
    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""

    # For this chapter screen, use Emby's already-generated 5-minute chapter
    # screenshots directly. This is the same server asset class EmbyDream exposes.
    native = _embyflow_v11_7_4_download_native_chapter(self, chapter, path)
    if self._preview_file_valid(native):
        return native

    # Optional prepared VPT fallback for servers/libraries that actually have it.
    trickplay = _embyflow_v11_7_download_trickplay(self, chapter, path)
    if self._preview_file_valid(trickplay):
        return trickplay

    return self._preview_v6_make_placeholder(chapter)


EmbyFlowChapterNavigator._obtain_preview = _embyflow_v11_7_4_obtain_preview
EmbyFlowChapterNavigator._download_native_chapter_v11_7_4 = _embyflow_v11_7_4_download_native_chapter

# EMBYFLOW_ADMIN_SAFETY_V11_7_4_NATIVE_CHAPTER_TIMEOUTFIX_DEVLIVE_RELEASE
# Native chapter GET: one request, maxWidth=400, format=jpg, timeout=15 s.
# Native Chapter image is tried before ThumbnailSet for chapter navigation.
# No ffmpeg. No stream seek. No POST/DELETE. No retry cascade.
# EMBYFLOW_ADMIN_SAFETY_V11_7_4_NATIVE_CHAPTER_TIMEOUTFIX_END


# V11.7.4 Apple/EmbyDream-style prewarm: fetch only the current chapter and
# the four visible neighbours after playback starts. The existing prewarm
# thread begins after ~1 s, so the chapter menu normally hits local cache.
def _embyflow_chapter_priority_order_v17_5_3(player, chapters):
    chapters = list(chapters or [])
    if not chapters:
        return []
    try:
        current = int(player.current_position_ticks() or 0)
    except Exception:
        current = 0
    active = 0
    for index, chapter in enumerate(chapters):
        try:
            if int(chapter.get("StartPositionTicks") or 0) <= current:
                active = index
            else:
                break
        except Exception:
            pass
    order = []
    for offset in (0, -1, 1, -2, 2):
        index = active + offset
        if 0 <= index < len(chapters) and index not in order:
            order.append(index)
    return order


def _embyflow_v11_7_4_prewarm_obtain(self, chapter, path):
    if not path:
        return ""
    if self._preview_file_valid(path):
        return path
    # Native server chapter screenshot only. No ThumbnailSet fallback here,
    # no placeholder and no ffmpeg during background prewarm.
    return _embyflow_v11_7_4_download_native_chapter(self, chapter, path)


# Make the already-existing player prewarm worker use V11.7.4's prepared
# server-image path instead of the old V11.6 ffmpeg/native-probe path.
_EmbyFlowChapterPrewarmProxyV17_5_3._obtain_preview = _embyflow_v11_7_4_prewarm_obtain

# EMBYFLOW_ADMIN_SAFETY_V11_7_4_PREWARM_VISIBLE5


# EMBYFLOW_ADMIN_SAFETY_V11_7_5_ITEMSERVICE_CHAPTERS_PREWARM_FIX_START
# Fixes two concrete V11.7.4 defects:
# 1) chapter image metadata was enriched through /Users/{user}/Items/{id};
#    Emby's documented ItemService form for Chapters is /Items?Fields=Chapters&Ids={id}.
# 2) V11.7 had globally replaced the V17.5.3 prewarm starter with a no-op;
#    V11.7.4 changed the worker but never restored the starter, so prewarm never ran.
# V11.7.5 mirrors the proven Emby Web/iOS chapter image flow:
#   GET /Items?Recursive=true&Fields=Chapters&Ids={itemId}
#   GET /Items/{itemId}/Images/Chapter/{index}?maxWidth=400&tag=...&quality=90
# Only read-only GETs; no ffmpeg, no stream seek, no POST/DELETE.

EMBYFLOW_V11_7_5_NATIVE_WIDTH = 400
EMBYFLOW_V11_7_5_METADATA_TIMEOUT = 8.0
EMBYFLOW_V11_7_5_IMAGE_TIMEOUT = 15.0


def _embyflow_v11_7_5_chapter_asset_map(self):
    cached = getattr(self, "_embyflow_v11_7_5_asset_map", None)
    if isinstance(cached, dict):
        return cached

    # One metadata request per helper/screen. Mark before I/O to prevent a
    # per-keypress retry storm if the server returns an error.
    self._embyflow_v11_7_5_asset_map = {}

    if not requests:
        return {}

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(getattr(self.player, "item_id", "") or "").strip()
    if not server or not token or not item_id:
        return {}

    url = "%s/Items" % str(server).rstrip("/")
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
    }
    params = {
        "Recursive": "true",
        "Fields": "Chapters",
        "Ids": item_id,
        "Limit": "1",
    }

    started = time.time()
    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_5_METADATA_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_5_chaptermeta_http_error",
                item=item_id,
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return {}

    status = int(getattr(response, "status_code", 0) or 0)
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_5_chaptermeta_miss",
                item=item_id,
                status=status,
            )
        except Exception:
            pass
        return {}

    try:
        data = response.json() or {}
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_5_chaptermeta_invalid_json",
                item=item_id,
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return {}

    items = list(data.get("Items") or data.get("items") or [])
    item = items[0] if items and isinstance(items[0], dict) else {}
    raw_chapters = list(item.get("Chapters") or item.get("chapters") or [])

    assets = {}
    tagged = 0
    for raw_index, raw in enumerate(raw_chapters):
        if not isinstance(raw, dict):
            continue
        marker_type = str(raw.get("MarkerType") or "").strip().lower()
        if marker_type and marker_type != "chapter":
            continue
        try:
            ticks = max(0, int(raw.get("StartPositionTicks") or 0))
        except Exception:
            continue
        try:
            image_index = int(raw.get("ChapterIndex"))
        except Exception:
            image_index = raw_index
        image_index = max(0, image_index)
        tag = str(raw.get("ImageTag") or "").strip()
        if tag:
            tagged += 1
        assets[ticks] = {
            "index": image_index,
            "tag": tag,
        }

    self._embyflow_v11_7_5_asset_map = assets
    elapsed_ms = int(max(0.0, time.time() - started) * 1000.0)
    try:
        self._preview_v6_log(
            "v11_7_5_chaptermeta_ok",
            item=item_id,
            count=len(assets),
            tagged=tagged,
            elapsed_ms=elapsed_ms,
        )
    except Exception:
        pass
    return assets


# The existing resolver calls this global by name. Point it at the correct
# ItemService implementation so foreground and prewarm share the same mapping.
_embyflow_v11_7_3_chapter_asset_map = _embyflow_v11_7_5_chapter_asset_map
EmbyFlowChapterNavigator._chapter_asset_map_v11_7_5 = _embyflow_v11_7_5_chapter_asset_map


def _embyflow_v11_7_5_download_native_chapter(self, chapter, path):
    if not path or not requests:
        return ""

    try:
        image_index, image_tag = _embyflow_v11_7_3_resolve_native_asset(self, chapter)
    except Exception:
        try:
            image_index = max(0, int(chapter.get("_embyflow_image_index") or 0))
        except Exception:
            image_index = 0
        image_tag = str(chapter.get("ImageTag") or "").strip()

    # Do not blind-probe. Emby chapter screenshots are advertised with ImageTag.
    if not image_tag:
        try:
            self._preview_v6_log(
                "v11_7_5_native_skip_no_tag",
                item=str(getattr(self.player, "item_id", "") or ""),
                chapter=int(image_index),
            )
        except Exception:
            pass
        return ""

    attempted = getattr(self, "_embyflow_v11_7_5_native_attempted", None)
    if not isinstance(attempted, set):
        attempted = set()
        self._embyflow_v11_7_5_native_attempted = attempted
    attempt_key = (int(image_index), str(image_tag))
    if attempt_key in attempted:
        return ""
    attempted.add(attempt_key)

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(getattr(self.player, "item_id", "") or "").strip()
    if not server or not token or not item_id:
        return ""

    # Proven Emby Web/iOS form. Intentionally no MediaSourceId: the chapter
    # image is item-scoped and this avoids binding the request to a stale or
    # differently-named playback source.
    url = "%s/Items/%s/Images/Chapter/%d" % (
        str(server).rstrip("/"),
        item_id,
        int(image_index),
    )
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
        "Accept": "image/jpeg,image/png,*/*;q=0.8",
    }
    params = {
        "maxWidth": str(EMBYFLOW_V11_7_5_NATIVE_WIDTH),
        "tag": image_tag,
        "quality": "90",
    }

    started = time.time()
    try:
        self._preview_v6_log(
            "v11_7_5_native_start",
            item=item_id,
            chapter=int(image_index),
            tagged=1,
            timeout_s=int(EMBYFLOW_V11_7_5_IMAGE_TIMEOUT),
        )
    except Exception:
        pass

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_5_IMAGE_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        elapsed_ms = int(max(0.0, time.time() - started) * 1000.0)
        try:
            self._preview_v6_log(
                "v11_7_5_native_http_error",
                item=item_id,
                chapter=int(image_index),
                elapsed_ms=elapsed_ms,
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return ""

    elapsed_ms = int(max(0.0, time.time() - started) * 1000.0)
    status = int(getattr(response, "status_code", 0) or 0)
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_5_native_miss",
                item=item_id,
                chapter=int(image_index),
                elapsed_ms=elapsed_ms,
                status=status,
            )
        except Exception:
            pass
        return ""

    content = getattr(response, "content", b"") or b""
    content_type = str(
        response.headers.get("Content-Type", "")
        if hasattr(response, "headers") else ""
    )
    is_jpeg = content.startswith(b"\xff\xd8")
    is_png = content.startswith(b"\x89PNG\r\n\x1a\n")
    if len(content) <= 500 or not (is_jpeg or is_png):
        try:
            self._preview_v6_log(
                "v11_7_5_native_invalid",
                item=item_id,
                chapter=int(image_index),
                bytes=len(content),
                content_type=content_type[:80],
                elapsed_ms=elapsed_ms,
            )
        except Exception:
            pass
        return ""

    temporary = path + ".native.v11_7_5.tmp"
    try:
        with open(temporary, "wb") as handle:
            handle.write(content)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass
        self._preview_atomic_replace(temporary, path)
        if self._preview_file_valid(path):
            try:
                self._preview_v6_log(
                    "v11_7_5_native_ok",
                    item=item_id,
                    chapter=int(image_index),
                    bytes=len(content),
                    elapsed_ms=elapsed_ms,
                )
            except Exception:
                pass
            return path
        return ""
    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_v11_7_5_obtain_preview(self, chapter, path):
    if not path:
        return ""
    if self._preview_file_valid(path):
        return path

    # Primary path: Emby's already-generated chapter screenshots. This mirrors
    # the server-side asset flow used by Emby clients and EmbyDream-style scene
    # chapter displays; no receiver-side video decoding is involved.
    native = _embyflow_v11_7_5_download_native_chapter(self, chapter, path)
    if self._preview_file_valid(native):
        return native

    # Background prewarm must never cache a placeholder as if it were a real
    # chapter screenshot. Foreground may show the local placeholder.
    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""

    # Do not waste a second request on this server's known-empty ThumbnailSet.
    return self._preview_v6_make_placeholder(chapter)


