def _embyflow_v11_7_5_start_prewarm(player, delay_seconds=1.0):
    # V11.7 replaced this starter with a no-op. Restore the original worker
    # semantics, while V11.7.4's priority function limits the queue to visible 5.
    if _embyflow_chapter_prewarm_threading_v17_5_3 is None:
        return
    if getattr(player, "_embyflow_chapter_prewarm_running_v17_5_3", False):
        return
    if getattr(player, "_embyflow_chapter_prewarm_stop_v17_5_3", False):
        return

    player._embyflow_chapter_prewarm_serial_v17_5_3 = int(
        getattr(player, "_embyflow_chapter_prewarm_serial_v17_5_3", 0) or 0
    ) + 1
    serial = int(player._embyflow_chapter_prewarm_serial_v17_5_3)
    player._embyflow_chapter_prewarm_running_v17_5_3 = True

    try:
        worker = _embyflow_chapter_prewarm_threading_v17_5_3.Thread(
            target=_embyflow_chapter_prewarm_worker_v17_5_3,
            args=(player, serial, delay_seconds),
            name="EmbyFlowChapterPrewarmV11_7_5",
        )
        worker.daemon = True
        worker.start()
    except Exception:
        player._embyflow_chapter_prewarm_running_v17_5_3 = False


# Player-init wrapper resolves this name at runtime. This restores the worker
# that V11.7 accidentally disabled.
_embyflow_chapter_start_prewarm_v17_5_3 = _embyflow_v11_7_5_start_prewarm

