    def __init__(self, session):
        Screen.__init__(self, session)
        self.setTitle("EmbyFlow Update")

        self["state_title"] = Label("Update prüfen")
        self["update_status"] = Label("Bereit zur Update-Prüfung")
        self["update_installed"] = Label(
            _embyflow_update_display_version(PLUGIN_VERSION)
        )
        self["update_available"] = Label("–")
        self["update_channel"] = Label(str(EMBYFLOW_UPDATE_CHANNEL).lower())
        self["update_last_checked"] = Label("Noch nie")
        self["update_last_installed"] = Label("Unbekannt")
        self["content_title"] = Label("Änderungen:")
        self["update_changelog"] = Label("Noch nicht geprüft.")
        self["update_scroll_thumb"] = Label("")
        self["update_scroll_hint"] = Label("")
        self._changelog_pages = ["Noch nicht geprüft."]
        self._changelog_page = 0
        self["update_steps"] = Label(
            "○ Manifest laden\n\n"
            "○ SHA256 prüfen\n\n"
            "○ Backup vorbereiten\n\n"
            "○ Python-Dateien prüfen\n\n"
            "○ Dateien aktualisieren"
        )
        self["key_green"] = Label("PRÜFEN")

        self._busy = False
        self._worker_done = False
        self._worker_result = None
        self._worker_kind = ""
        self._manifest = None
        self._update_available_flag = False
        self._installable = False
        self._installed_success = False

        self._poll_timer = eTimer()
        try:
            self._poll_timer.callback.append(self._poll_worker)
        except Exception:
            try:
                self._poll_timer.timeout.connect(self._poll_worker)
            except Exception:
                pass

        self["actions"] = ActionMap(
            ["OkCancelActions", "ColorActions", "DirectionActions"],
            {
                "cancel": self.close,
                "red": self.close,
                "ok": self.green_pressed,
                "green": self.green_pressed,
                "blue": self.check_updates,
                "up": self.changelog_page_up,
                "down": self.changelog_page_down,
            },
            -1,
        )

        self._refresh_update_timestamps()
        self.onLayoutFinish.append(self.check_updates)

    def _refresh_update_timestamps(self):
        state = _embyflow_update_load_state()
        checked_ts = int(state.get("last_checked_ts") or 0)
        installed_ts = int(state.get("last_installed_ts") or 0)
        if installed_ts <= 0:
            installed_ts = _embyflow_update_install_time_fallback()
        self["update_last_checked"].setText(
            _embyflow_update_timestamp_text(checked_ts)
        )
        self["update_last_installed"].setText(
            _embyflow_update_timestamp_text(installed_ts)
        )

    def _render_changelog_page(self):
        pages = list(getattr(self, "_changelog_pages", []) or [])
        if not pages:
            pages = [""]
        total = len(pages)
        page = max(
            0,
            min(
                int(getattr(self, "_changelog_page", 0) or 0),
                total - 1,
            ),
        )
        self._changelog_page = page
        self["update_changelog"].setText(pages[page])

        try:
            self["update_scroll_hint"].setText(
                "%d/%d" % (page + 1, total)
                if total > 1 else ""
            )
        except Exception:
            pass

        try:
            track_y = 562
            track_h = 145
            if total <= 1:
                thumb_h = track_h
                thumb_y = track_y
            else:
                thumb_h = max(28, int(track_h / total))
                travel = max(0, track_h - thumb_h)
                thumb_y = track_y + int(
                    (travel * page) / max(1, total - 1)
                )

            self["update_scroll_thumb"].instance.move(
                EFP(1023, thumb_y)
            )
            self["update_scroll_thumb"].instance.resize(
                EFS(10, thumb_h)
            )
            self["update_scroll_thumb"].show()
        except Exception:
            pass

    def changelog_page_up(self):
        try:
            if int(getattr(self, "_changelog_page", 0) or 0) > 0:
                self._changelog_page -= 1
                self._render_changelog_page()
        except Exception:
            pass

    def changelog_page_down(self):
        try:
            pages = list(getattr(self, "_changelog_pages", []) or [])
            if int(getattr(self, "_changelog_page", 0) or 0) < len(pages) - 1:
                self._changelog_page += 1
                self._render_changelog_page()
        except Exception:
            pass

    def _set_changelog_static(self, value):
        self._changelog_pages = [str(value or "")]
        self._changelog_page = 0
        self._render_changelog_page()

    def _set_changelog(self, items):
        import textwrap

        values = [
            str(value or "").strip()
            for value in list(items or [])[:12]
            if str(value or "").strip()
        ]
        if not values:
            self._set_changelog_static(
                "Keine Änderungsnotizen angegeben."
            )
            return

        lines = []
        for value in values:
            wrapped = textwrap.wrap(
                value,
                width=49,
                break_long_words=False,
                break_on_hyphens=False,
            ) or [value]

            lines.append("• " + wrapped[0])
            for continuation in wrapped[1:]:
                lines.append("  " + continuation)

        # 5 lines fit comfortably into the 145px field at Regular;21.
        page_size = 5
        self._changelog_pages = [
            "\n".join(lines[index:index + page_size])
            for index in range(0, len(lines), page_size)
        ] or [""]

        self._changelog_page = 0
        self._render_changelog_page()

    def _start_worker(self, kind, worker):
        if self._busy:
            return
        self._busy = True
        self._worker_done = False
        self._worker_result = None
        self._worker_kind = str(kind or "")

        try:
            import threading

            def run():
                try:
                    value = worker()
                    self._worker_result = {"ok": True, "value": value}
                except Exception as error:
                    self._worker_result = {"ok": False, "error": str(error)}
                    try:
                        with embyflow_open_log(
                            "/tmp/embyflow_updater_error.log",
                            "a",
                        ) as log:
                            log.write(
                                "%s kind=%s error=%s\n"
                                % (
                                    time.strftime("%Y-%m-%d %H:%M:%S"),
                                    self._worker_kind,
                                    str(error),
                                )
                            )
                    except Exception:
                        pass
                finally:
                    self._worker_done = True

            thread = threading.Thread(
                target=run,
                name="EmbyFlowUpdaterV1",
            )
            thread.daemon = True
            thread.start()
            self._poll_timer.start(150, False)
        except Exception as error:
            self._busy = False
            self._worker_done = True
            self._worker_result = {"ok": False, "error": str(error)}
            self._poll_worker()

    def check_updates(self):
        if self._busy:
            return
        self._installed_success = False
        self._manifest = None
        self._update_available_flag = False
        self._installable = False
        self["state_title"].setText("Update prüfen")
        self["update_status"].setText("Suche auf GitHub nach Updates …")
        self["update_available"].setText("Wird geprüft …")
        self["update_channel"].setText(str(EMBYFLOW_UPDATE_CHANNEL).lower())
        self["content_title"].setText("Änderungen:")
        self._set_changelog_static("Manifest wird geladen …")
        self["update_steps"].setText(
            "○ Manifest laden\n\n"
            "○ SHA256 prüfen\n\n"
            "○ Backup vorbereiten\n\n"
            "○ Python-Dateien prüfen\n\n"
            "○ Dateien aktualisieren"
        )
        self["key_green"].setText("PRÜFUNG LÄUFT")
        self._start_worker("check", _embyflow_update_fetch_manifest)

    def _poll_worker(self):
        if not self._worker_done:
            return
        try:
            self._poll_timer.stop()
        except Exception:
            pass

        self._busy = False
        result = self._worker_result or {"ok": False, "error": "Keine Antwort"}
        kind = self._worker_kind

        if not result.get("ok"):
            self["state_title"].setText(
                "Prüfung fehlgeschlagen" if kind == "check" else "Update fehlgeschlagen"
            )
            self["update_status"].setText(
                "Update-Prüfung fehlgeschlagen" if kind == "check" else "Update fehlgeschlagen"
            )
            self["update_available"].setText("–")
            self["key_green"].setText("ERNEUT PRÜFEN")
            error_text = str(result.get("error") or "Unbekannter Fehler")
            self["content_title"].setText("Fehlerbehandlung:")
            self._set_changelog_static(error_text[:420])
            self["update_steps"].setText(
                "✗ Vorgang abgebrochen\n\n"
                "✓ Vorhandene Installation geschützt\n\n"
                "✓ Keine Konfiguration verändert"
            )
            return

        value = result.get("value") or {}
        if kind == "check":
            self._apply_manifest(value)
        elif kind == "install":
            self._apply_install_success(value)

    def _apply_manifest(self, manifest):
        self._manifest = dict(manifest or {})
        try:
            _embyflow_update_mark_checked(self._manifest)
        except Exception:
            pass
        self._refresh_update_timestamps()
        remote_build = int(self._manifest.get("build") or 0)
        remote_version = str(self._manifest.get("version") or "–")
        self._update_available_flag = remote_build > int(PLUGIN_UPDATE_BUILD)
        self._installable = bool(self._manifest.get("installable"))

        if remote_build < int(PLUGIN_UPDATE_BUILD):
            self["update_available"].setText("Kein neueres Update")
            self["content_title"].setText("Änderungen dieses Builds:")
            local_notes = [
                part.strip()
                for part in str(PLUGIN_UPDATE_CHANGELOG or "").split("|")
                if part.strip()
            ]
            self._set_changelog(local_notes)
        else:
            self["update_available"].setText(
                _embyflow_update_display_version(remote_version)
            )
            self["content_title"].setText("Änderungen:")
            self._set_changelog(self._manifest.get("changelog"))

        self["update_channel"].setText(
            str(self._manifest.get("channel") or EMBYFLOW_UPDATE_CHANNEL).lower()
        )

        security = [
            "✓ HTTPS-Manifest",
            "✓ Build geprüft",
        ]
        if str(self._manifest.get("sha256") or "").strip():
            security.append("✓ SHA256 vorhanden")
        else:
            security.append("✗ SHA256 fehlt")
        if self._installable:
            security.extend([
                "✓ Update-Datei erlaubt",
                "✓ Backup vor Installation",
            ])
        else:
            security.extend([
                "○ Update-Datei noch gesperrt",
                "✓ Installation bleibt geschützt",
            ])
        self["update_steps"].setText("\n\n".join(security))

        if not self._update_available_flag:
            self["state_title"].setText("Aktuell")
            if remote_build < int(PLUGIN_UPDATE_BUILD):
                self["update_status"].setText(
                    "✓ Du hast bereits eine neuere Version installiert."
                )
            else:
                self["update_status"].setText(
                    "✓ EmbyFlow E2 ist aktuell."
                )
            self["key_green"].setText("ERNEUT PRÜFEN")
            return

        if not self._installable:
            self["state_title"].setText("Update gefunden")
            self["update_status"].setText(
                "Update gefunden · Testmanifest ist noch nicht installierbar"
            )
            self["key_green"].setText("ERNEUT PRÜFEN")
            notes = list(self._manifest.get("changelog") or [])[:5]
            notes.append("Installation gesperrt: Phase 1 akzeptiert nur eine .py-Datei.")
            self._set_changelog(notes)
            return

        self["state_title"].setText("Update gefunden")
        self["update_status"].setText("Update verfügbar und installierbar")
        self["key_green"].setText("UPDATE INSTALLIEREN")

    def green_pressed(self):
        if self._busy:
            return
        if self._installed_success:
            self.restart_gui()
            return
        if self._update_available_flag and self._installable and self._manifest:
            try:
                self.session.openWithCallback(
                    self._install_confirmed,
                    MessageBox,
                    "EmbyFlow Update wirklich installieren?\n\n%s\n\n"
                    "Vor dem Austausch werden SHA256 und Python-Syntax geprüft."
                    % str(self._manifest.get("version") or "Update"),
                    MessageBox.TYPE_YESNO,
                )
            except Exception:
                self._install_confirmed(True)
            return
        self.check_updates()

    def _install_confirmed(self, answer):
        if not answer or self._busy or not self._manifest:
            return
        manifest = dict(self._manifest)
        self["state_title"].setText("Update wird installiert")
        self["update_status"].setText("Bitte warten …")
        self["content_title"].setText("Änderungen:")
        self["key_green"].setText("INSTALLATION LÄUFT")
        self["update_steps"].setText(
            "○ Download …\n\n"
            "○ SHA256 prüfen …\n\n"
            "○ Backup erstellen …\n\n"
            "○ Python-Dateien prüfen …\n\n"
            "○ Dateien aktualisieren …"
        )
        self._start_worker(
            "install",
            lambda: _embyflow_update_install_plugin(manifest),
        )

    def _apply_install_success(self, result):
        self._installed_success = True
        self._refresh_update_timestamps()
        version = str(result.get("version") or "Update")
        self["state_title"].setText("Update erfolgreich")
        self["update_status"].setText("✓ Update erfolgreich installiert · GUI-Neustart erforderlich")
        self["update_available"].setText(version)
        self["content_title"].setText("Abgeschlossen:")
        self._set_changelog_static(
            "EmbyFlow E2 wurde erfolgreich aktualisiert.\n\n"
            "Die neue Version wird nach dem GUI-Neustart aktiv."
        )
        self["key_green"].setText("GUI NEU STARTEN")
        self["update_steps"].setText(
            "✓ Download\n\n"
            "✓ SHA256 geprüft\n\n"
            "✓ Backup erstellt\n\n"
            "✓ Python-Dateien geprüft\n\n"
            "✓ Dateien aktualisiert"
        )

    def restart_gui(self):
        try:
            from Screens.Standby import TryQuitMainloop
            self.session.open(TryQuitMainloop, 3)
        except Exception as error:
            try:
                self.session.open(
                    MessageBox,
                    "Update ist installiert.\n\n"
                    "Der automatische GUI-Neustart konnte nicht geöffnet werden:\n%s\n\n"
                    "Bitte die Enigma2-GUI manuell neu starten." % str(error),
                    MessageBox.TYPE_INFO,
                    timeout=12,
                )
            except Exception:
                pass


