EmbyFlowConnectionWizard.skin = scale_skin(_embyflow_login_reference_v13_skin())
EmbyFlowConnectionWizard.SERVER_CARD_POSITIONS = (
    (420, 290),
    (420, 370),
    (420, 450),
    (420, 530),
)

# Letzte UI-Prioritaet: die vier Server als vertikale Zeilen darstellen.
def _embyflow_login_reference_v13_refresh_cards(self):
    try:
        self["v9_focus_card"].hide()
    except Exception:
        pass

    for index in range(4):
        try:
            value = str(self.server_slots[index] or "").strip()
        except Exception:
            value = ""
        state = self.server_runtime_states.get(index)
        selected = index == self.selected_server_index

        if state == "online":
            state_text = "ONLINE"
        elif state == "error":
            state_text = "FEHLER"
        elif value:
            state_text = "BEREIT"
        else:
            state_text = "LEER"
        if selected and value:
            state_text = "✓ " + state_text

        try:
            self["server_name%d" % index].setText("Server %d" % (index + 1))
            self["server_brand%d" % index].setText(value or "Nicht eingerichtet")
            self["server_state%d" % index].setText(state_text)
            self["server_icon%d" % index].setText("")
        except Exception:
            pass

    try:
        idx = self.focus if self.focus in (0, 1, 2, 3) else self.selected_server_index
        x, y = self.SERVER_CARD_POSITIONS[idx]
        self["server_focus_border"].instance.move(EFP(x, y))
        self["server_focus_border"].instance.resize(EFS(1080, 64))
        self["server_focus_inner"].instance.move(EFP(x + 4, y + 4))
        self["server_focus_inner"].instance.resize(EFS(1072, 56))
        self["server_focus_border"].show()
        self["server_focus_inner"].show()
    except Exception:
        pass

    try:
        if not self.server:
            status = "Kein Server ausgewählt · OK zum Einrichten"
        elif self.connection_ok:
            status = "● Verbindung OK · %s" % (self.server_name or self._selected_server_label())
        else:
            status = "● Bereit · GRÜN prüft die Verbindung"
        self["server_status"].setText(status)
    except Exception:
        pass

EmbyFlowConnectionWizard._refresh_server_cards = _embyflow_login_reference_v13_refresh_cards


def _embyflow_login_reference_v13_focus_marker(self):
    for _name in ("v9_focus_input", "v9_focus_save", "v9_focus_login", "save_checkbox"):
        try:
            self[_name].hide()
        except Exception:
            pass
    try:
        if self.focus < 4:
            self["focus_marker"].hide()
            return
        positions = {
            4: (615, 649),
            5: (615, 719),
            6: (615, 785),
            7: (405, 850),
            8: (955, 850),
        }
        x, y = positions.get(self.focus, (615, 649))
        self["focus_marker"].setText(">")
        self["focus_marker"].instance.move(EFP(x, y))
        self["focus_marker"].instance.resize(EFS(28, 34))
        self["focus_marker"].show()
    except Exception:
        pass

EmbyFlowConnectionWizard._refresh_focus_marker = _embyflow_login_reference_v13_focus_marker

_EMBYFLOW_LOGIN_REFERENCE_V13_PREV_REFRESH = EmbyFlowConnectionWizard.refresh_all

def _embyflow_login_reference_v13_refresh_all(self):
    _EMBYFLOW_LOGIN_REFERENCE_V13_PREV_REFRESH(self)
    try:
        self["username_value"].setText(self.username or "Benutzername eingeben")
    except Exception:
        pass
    try:
        self["password_value"].setText("•" * len(self.password) if self.password else "Passwort eingeben")
    except Exception:
        pass
    try:
        self["save_password"].setText("[X] Zugangsdaten speichern" if self.save_password_enabled else "[ ] Zugangsdaten speichern")
    except Exception:
        pass
    try:
        self["login_button"].setText("ANMELDEN")
    except Exception:
        pass
    _embyflow_login_reference_v13_focus_marker(self)

EmbyFlowConnectionWizard.refresh_all = _embyflow_login_reference_v13_refresh_all
